[53] = {name = "Удар в спину", additional_info = "{Энергия: 60} {Дистанция ближнего боя}\nМгновенное действие\n[q]Удар в спину, наносящий цели 150% урона оружия и дополнительно 15 ед. урона. Для удара нужно находиться за спиной цели и держать кинжал в правой руке. Длина серии приемов увеличивается на 1."},
[56] = {name = "Оглушение", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Оглушение цели на 3 сек."},
[65] = {name = "Ускорение", additional_info = "Мана: 14\nМгновенное действие\n[q]Повышение скорости атаки на 2%. Время действия – 30 сек."},
[66] = {name = "Малая невидимость", additional_info = "Мана: 110\nПрименение: 3 сек\n[q]Заклинатель становится невидимым на 2 мин. Однако заклинание нестабильно и может перестать действовать раньше времени."},
[67] = {name = "Подтверждение", additional_info = nil},
[71] = {name = "Оборонительная стойка", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\n[q]Переход в оборонительную стойку. При этом получаемый урон уменьшается на 10%, а наносимый урон - на 10%. Увеличение создаваемой угрозы."},
[72] = {name = "Удар щитом", additional_info = "{Ярость: 10} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 12 сек}\nТребуется: Боевая стойка, Оборонительная стойка\n[q]Бьет цель щитом, нанося 6 ед. урона, прерывая применение заклинания и не позволяя применять заклинания той же школы в течение 6 сек."},
[75] = {name = "Автоматическая стрельба", additional_info = "Радиус действия: 8 - 35 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Автоматическая стрельба по цели, действующая до отмены."},
[77] = {name = "Черепаший панцирь", additional_info = nil},
[78] = {name = "Удар героя", additional_info = "{Ярость: 15} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 11 ед. и сильно повышающая ваш уровень угрозы."},
[81] = {name = "Уклонение", additional_info = "[q]Дает шанс уклониться от атаки противника в ближнем бою."},
[84] = {name = "Низкий запас здоровья", additional_info = nil},
[89] = {name = "Увечье", additional_info = "{Мана: 210} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Наносит цели увечье, снижая ее скорость передвижения на 40% и увеличивая время между ее атаками ближнего боя на 45% и атаками дальнего боя на 45%. Время действия – 20 сек."},
[91] = {name = "Варварский штурм", additional_info = "Следующая атака"},
[96] = {name = "Расчленение", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение цели в следующей ближней атаке открытой раны при увеличенном на 100 ед. уроне."},
[99] = {name = "Устрашающий рев", additional_info = "Ярость: 10\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Друид издает устрашающий рев, снижающий силу атаки в ближнем бою находящихся рядом противников на 40. Время действия – 30 сек."},
[100] = {name = "Рывок", additional_info = "Радиус действия: 8 - 25 м\n{Мгновенное действие} {Восстановление: 15 сек}\nТребуется: Боевая стойка\n[q]Бросается к противнику, оглушая его на 1 сек и получая 9 ед. ярости. Не действует во время боя."},
[101] = {name = "Подножка", additional_info = "{Энергия: 15} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 5 сек}\n[q]Ставит подножку противнику, нанося 10 урона и сбивая его с ног на 3 сек. Длина серии приемов увеличивается на 1. Может применяться только к гуманоидам."},
[107] = {name = "Блок", additional_info = "Требуется: Щит\n[q]Дает шанс заблокировать атаку противника в ближнем или дальнем бою."},
[111] = {name = "Шаг времени", additional_info = "Мгновенное действие"},
[113] = {name = "Ледяные оковы", additional_info = "{Мана: 20} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Сковывание противника ледяными цепями, не позволяющими ему двигаться с места в течение 15 сек."},
[116] = {name = "Ледяная стрела", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]В противника летит ледяная стрела, наносящая от [18 * ( 1 ) ] до [20 * ( 1 ) ] ед. урона от магии льда и снижающая скорость передвижения на 40% на 5 сек."},
[118] = {name = "Превращение", additional_info = "{Мана: 60} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Превращает противника в овцу, которая бродит вокруг в течение 20 сек. Овца не может атаковать и применять заклинания, но быстро восполняет здоровье и ману. Урон снимает эффект. Одновременно действует только на одну цель. Действует только на животных, гуманоидов и зверьков."},
[120] = {name = "Конус холода", additional_info = "Мана: 210\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Противники, находящиеся в конусе поражения перед заклинателем, получают от [98 * ( 1 ) ] до [108 * ( 1 ) ] ед. урона от магии льда и замедляются на 50% на 8 сек."},
[122] = {name = "Кольцо льда", additional_info = "Мана: 55\n{Мгновенное действие} {Восстановление: 25 сек}\n[q]Поражает ближайших противников, нанося от [19 * ( 1 ) ] до [21 * ( 1 ) ] ед. урона от магии льда и примораживая их к месту максимум на 8 сек. Нанесенный урон может прервать действие."},
[126] = {name = "Око Килрогга", additional_info = "Мана: 100 Неограниченное расстояние\nПрименение: 5 сек\n[q]Призыв Ока Килрогга, через которое заклинатель может взирать на мир. Око быстро двигается, но очень хрупко."},
[128] = {name = "Камень чар", additional_info = "Мгновенное действие\n[q]Снимает с заклинателя все магические эффекты и поглощает 400 ед. магического урона в течение 1 мин."},
[130] = {name = "Замедленное падение", additional_info = "Мана: 40\nМгновенное действие\nИнгредиенты:\nЛегкое перышко\n[q]Замедление скорости падения на 30 сек."},
[131] = {name = "Подводное дыхание", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nМгновенное действие\nИнгредиенты:\nБлестящая рыбья чешуя\n[q]Позволяет цели дышать под водой в течение 10 мин."},
[132] = {name = "Обнаружение обычной невидимости", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nМгновенное действие\n[q]Придание способности видеть сквозь эффект \"Простая невидимость\" для дружественной цели в течение 10 мин."},
[133] = {name = "Огненный шар", additional_info = "{Мана: 30} {Радиус действия: 35 м}\nПрименение: 1.5 сек\n[q]Бросок огненного шара, который наносит 16 в 25 ед. урона от огня единовременно и 2 ед. урона от огня в течение 4 сек."},
[134] = {name = "Огненный щит", additional_info = "Радиус действия: 30 м\n{Применение: 1 сек} {Восстановление: 15 сек}\n[q]Окружение союзника щитом пламени, который наносит 9 ед. урона от огня ближайшим противникам раз в 3 сек. Время действия – 1 мин."},
[136] = {name = "Лечение питомца", additional_info = "{Мана: 50} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]При поддержании восполняет вашему питомцу 20 ед. здоровья в секунду. Время действия – 5 сек."},
[139] = {name = "Обновление", additional_info = "{Мана: 30} {Радиус действия: 40 м}\nМгновенное действие\n[q]Излечение цели на 45 ед. в течение 15 сек."},
[143] = {name = "Огненный шар", additional_info = "{Мана: 45} {Радиус действия: 35 м}\nПрименение: 2 сек\n[q]Бросок огненного шара, который наносит 34 в 49 ед. урона от огня единовременно и 3 ед. урона от огня в течение 6 сек."},
[145] = {name = "Огненный шар", additional_info = "{Мана: 65} {Радиус действия: 35 м}\nПрименение: 2.5 сек\n[q]Бросок огненного шара, который наносит 57 в 77 ед. урона от огня единовременно и 6 ед. урона от огня в течение 6 сек."},
[168] = {name = "Морозный доспех", additional_info = "Мана: 60\nМгновенное действие\n[q]Усиливает броню на 30. Может снизить скорость передвижения атакующих противников на 30% и увеличить интервал между их атаками на 25% на 5 сек. Одновременно может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[172] = {name = "Порча", additional_info = "{Мана: 35} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Порча цели с нанесением ей 40 ед. урона от темной магии за 12 сек."},
[184] = {name = "Огненный щит II", additional_info = "Радиус действия: 30 м\n{Применение: 1 сек} {Восстановление: 15 сек}\n[q]Окружение союзника щитом пламени, который наносит 17 ед. урона от огня находящимся рядом противникам раз в 3 сек. Время действия – 1 мин."},
