[285] = {name = "Удар героя", additional_info = "{Ярость: 15} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 32 ед. и сильно повышающая ваш уровень угрозы."},
[302] = {name = "Варварский штурм II", additional_info = "Мгновенное действие"},
[324] = {name = "Щит молний", additional_info = "Мана: 45\nМгновенное действие\n[q]Окружение заклинателя 3 шаровыми молниями:шаровыми молниями. Раз в несколько секунд одна из оставшихся шаровых молний поражает противника, атакующего заклинателя любым видом атаки, нанося ему 13 ед. урона от сил природы. Время действия – 10 мин.\n(Восстановление: 3.5с)"},
[325] = {name = "Щит молний", additional_info = "Мана: 80\nМгновенное действие\n[q]Окружение заклинателя 3 шаровыми молниями:шаровыми молниями. Раз в несколько секунд одна из оставшихся шаровых молний поражает противника, атакующего заклинателя любым видом атаки, нанося ему 29 ед. урона от сил природы. Время действия – 10 мин.\n(Восстановление: 3.5с)"},
[331] = {name = "Волна исцеления", additional_info = "{Мана: 25} {Радиус действия: 40 м}\nПрименение: 1.5 сек\n[q]Исцеление дружественной цели на 36 в 47 ед."},
[332] = {name = "Волна исцеления", additional_info = "{Мана: 45} {Радиус действия: 40 м}\nПрименение: 2 сек\n[q]Исцеление дружественной цели на 69 в 83 ед."},
[339] = {name = "Гнев деревьев", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Оплетение цели корнями, удерживающими ее на месте и наносящими 20 ед. урона от сил природы в течение 12 сек. Нанесение стороннего урона может прервать действие. Используется только вне помещений."},
[348] = {name = "Жертвенный огонь", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Наносит противнику [ 11 * ( ( ( 1 ) ) ) ] ед. урона от огня сразу и еще 20 ед. урона от огня за 15 сек."},
[355] = {name = "Провокация", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Оборонительная стойка\n[q]Провоцирует противника, чтобы он атаковал вас. Если вы уже деретесь с этим противником, провокация не сработает."},
[370] = {name = "Развеяние магии", additional_info = "{10% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Развеивает 1 эффект с враждебной цели."},
[379] = {name = "Щит земли", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Защищает цель земляным щитом, который может уменьшить время, теряемое из-за получения урона при произнесении и поддержании заклинаний. Кроме того, атаки исцеляют защищенного персонажа, но этот эффект срабатывает не чаще, чем раз в несколько секунд. Количество зарядов ограничено. Щит Земли можно наложить только на одну цель единовременно и каждая цель может быть защищена только одним заклинанием категории \"Щит стихий\"."},
[403] = {name = "Молния", additional_info = "{Мана: 15} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Удар молнии по цели с нанесением 15 в 17 ед. урона от сил природы."},
[408] = {name = "Удар по почкам", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 20 сек}\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, оглушающий цель. Время оглушения зависит от длины серии:\n 1 прием: 1 секунда\n 2 приема: 2 секунды\n 3 приема: 3 секунды\n 4 приема: 4 секунды\n 5 приемов: 5 секунд"},
[409] = {name = "Тенекожа", additional_info = "Мгновенное действие"},
[410] = {name = "Тенекожа II", additional_info = "Мгновенное действие"},
[411] = {name = "Тенекожа III", additional_info = "Мгновенное действие"},
[421] = {name = "Цепная молния", additional_info = "{Мана: 280} {Радиус действия: 30 м}\n{Применение: 2.5 сек} {Восстановление: 6 сек}\n[q]Поражает противника молнией, нанося 200 в 227 ед. урона от сил природы. Затем молния переходит на других находящихся рядом противников. Каждый переход уменьшает урон на 30% . Максимум целей – 3."},
[427] = {name = "Телепорт в Монастырь", additional_info = "Применение: 2 сек\n[q]Телепортация в Монастырь!"},
