[581] = {name = "Снежный волк", additional_info = "Применение: 3 сек\n[q]Призыв и освобождение ездового снежного волка."},
[585] = {name = "Кара", additional_info = "{Мана: 20} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Карает противника и наносит 15 в 20 ед. урона светлой магии."},
[586] = {name = "Уход в тень", additional_info = "Мана: 40\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Вы исчезаете из виду, в результате чего противники не могут атаковать вас в течение 10 сек."},
[587] = {name = "Сотворение пищи", additional_info = "Мана: 60\nПрименение: 3 сек\n[q]Создает 20 кекса:кексов, чтобы обеспечить мага и его союзников едой.\n\n Сотворенные предметы исчезают, если выйти из игры более чем на 15 минут."},
[588] = {name = "Внутренний огонь", additional_info = "Мана: 30\nМгновенное действие\n[q]Наполняет заклинателя святой энергией, которая усиливает его броню на 315 ед. Каждая успешная атака против жреца снимает один заряд заклинания. Заклинание действуте 10 мин. или пока не будут сняты 20 зарядов."},
[589] = {name = "Слово Тьмы: Боль", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nМгновенное действие\n[q]Слово Тьмы, наносящее 30 ед. урона от темной магии за 18 сек."},
[591] = {name = "Кара", additional_info = "{Мана: 30} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Карает противника и наносит 28 в 34 ед. урона светлой магии."},
[592] = {name = "Слово силы: Щит", additional_info = "{Мана: 80} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 4 сек}\n[q]Создает из частички души члена группы щит, способный поглотить 94 урона. Щит держится 30 сек. Пока заклинатель защищен щитом, применение заклинаний не может быть прервано. Повторно наложить щит можно только через 15 сек."},
[594] = {name = "Слово Тьмы: Боль", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nМгновенное действие\n[q]Слово Тьмы, наносящее 66 ед. урона от темной магии за 18 сек."},
[595] = {name = "Молитва Обороны", additional_info = "Мана: 15\n{Мгновенное действие} {Восстановление: 10 мин}\n[q]Усиление брони всей группы до тех пор, пока эффект не исчезнет или жрец не перестанет читать молитву."},
[596] = {name = "Молитва исцеления", additional_info = "Мана: 410\nПрименение: 3 сек\n[q]Исцеление силой молитвы участников группы в радиусе 30 м. на 312 в 333 ед."},
[597] = {name = "Сотворение пищи", additional_info = "Мана: 105\nПрименение: 3 сек\n[q]Создает 20 ломтя:ломтей хлеба, чтобы обеспечить мага и его союзников едой.\n\n Сотворенные предметы исчезают, если выйти из игры более чем на 15 минут."},
[598] = {name = "Кара", additional_info = "{Мана: 60} {Радиус действия: 30 м}\nПрименение: 2.5 сек\n[q]Карает противника и наносит 58 в 67 ед. урона светлой магии."},
[600] = {name = "Слово силы: Щит", additional_info = "{Мана: 130} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 4 сек}\n[q]Создает из частички души члена группы щит, способный поглотить 166 урона. Щит держится 30 сек. Пока заклинатель защищен щитом, применение заклинаний не может быть прервано. Повторно наложить щит можно только через 15 сек."},
[601] = {name = "Мастер мечей", additional_info = "[q]Увеличение рейтинга атаки одноручными мечами на 3 ед."},
[602] = {name = "Внутренний огонь", additional_info = "Мана: 105\nМгновенное действие\n[q]Наполняет заклинателя святой энергией, которая усиливает его броню на 720 ед. Каждая успешная атака против жреца снимает один заряд заклинания. Заклинание действуте 10 мин. или пока не будут сняты 20 зарядов."},
[603] = {name = "Проклятие рока", additional_info = "{Мана: 300} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Нанесение 3200 ед. урона от темной магии в течение 1 мин. В случае смерти жертвы от этого урона существует вероятность призыва Привратника Скверны. На игроков воздействовать нельзя."},
[604] = {name = "Ослабление магии", additional_info = "{Мана: 100} {Радиус действия: 30 м}\nМгновенное действие\n[q]Ослабление магии, направленной на конкретного участника группы. Урон, наносимый ему заклинаниями, снижается на 10 ед., а воздействие целительных заклинаний – на 20. Время действия – 10 мин."},
[605] = {name = "Контроль над разумом", additional_info = "{Мана: 350} {Радиус действия: 20 м}\nПрименение: 3 сек\n[q]Позволяет управлять гуманоидом не выше 44 уровня, но увеличивает время между его атаками на 25%. Время действия – 1 мин."},
[606] = {name = "Гниение разума", additional_info = "{Мана: 240} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Похищение у цели 2160 ед. маны за 30 сек."},
[607] = {name = "Создание камня огня", additional_info = nil},
