[633] = {name = "Возложение рук", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 1 час}\n[q]Исцеляет дружественную цель на величину, равную максимальному запасу здоровья паладина. При использовании паладин расходует всю свою ману."},
[635] = {name = "Свет небес", additional_info = "{Мана: 35} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Исцеляет дружественную цель на 42 в 51 ед. здоровья."},
[639] = {name = "Свет небес", additional_info = "{Мана: 60} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Исцеляет дружественную цель на 81 в 96 ед. здоровья."},
[642] = {name = "Божественный щит", additional_info = "Мана: 75\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Дает паладину невосприимчивость к урону и заклинаниям, но [ S03 – настройка и отмена пассивных эффектов – паладин : уменьшает наносимый урон на 50% / увеличивает интервалы между атаками на 100%]. Время действия – 10 сек. Цель этого заклинания не может снова получить неуязвимость от \"Божественного щита\", \"Божественной защиты\" и \"Благословения защиты\" в течение 1 мин."},
[643] = {name = "Аура благочестия", additional_info = "Мгновенное действие\n[q]Увеличивает на 275 ед. параметр брони участников группы, находящихся не далее, чем в 30 метрах:метрах. На персонажа может действовать только одна аура от каждого паладина."},
[647] = {name = "Свет небес", additional_info = "{Мана: 110} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Исцеляет дружественную цель на 167 в 196 ед. здоровья."},
