[676] = {name = "Разоружение", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 1 мин}\nТребуется: Оборонительная стойка\n[q]Обезоруживает противника на 10 сек."},
