[686] = {name = "Стрела Тьмы", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nПрименение: 1.7 сек\n[q]Поражение противника теневой стрелой, наносящей 13 в 18 ед. урона от темной магии."},
[687] = {name = "Шкура демона", additional_info = "Мана: 50\nМгновенное действие\n[q]Увеличивает параметр брони персонажа на 40 ед. и восполняет 3 ед. здоровья каждые 5 сек. в течение 30 мин."},
[688] = {name = "Призыв беса", additional_info = "80% от базовой мана\nПрименение: 10 сек\n[q]Призыв беса, повинующегося чернокнижнику."},
[689] = {name = "Похищение жизни", additional_info = "{Мана: 55} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Передача 10 ед. здоровья от цели к заклинателю раз в 1 сек. Время действия – 5 сек."},
[690] = {name = "Огненная стрела II", additional_info = "{Мана: 18} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Нанесение цели 28 в 30 ед. урона от огня."},
[691] = {name = "Призыв охотника Скверны", additional_info = "100% от базовой мана\nПрименение: 10 сек\nИнгредиенты:\nОсколок души\n[q]Призыв Охотника Скверны, повинующегося чернокнижнику."},
[693] = {name = "Создание крошечного камня души", additional_info = "85% от базовой мана\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает слабый камень души. Если персонаж, душа которого заключена в камне, погибнет, он сможет воскреснуть с 400 ед. здоровья и 700 ед. маны.\n\n Созданные предметы исчезают при выходе из игры более чем на 15 мин."},
[694] = {name = "Дразнящий удар", additional_info = "{Ярость: 10} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 2 мин}\nТребуется: Оружие ближнего боя\nТребуется: Боевая стойка\n[q]Провокационный удар, наносящий 22 ед. урона, создающий средний уровень угрозы и вынуждающий цель атаковать вас в течение 6 сек."},
[695] = {name = "Стрела Тьмы", additional_info = "{Мана: 40} {Радиус действия: 30 м}\nПрименение: 2.2 сек\n[q]Поражение противника теневой стрелой, наносящей 26 в 32 ед. урона от темной магии."},
[696] = {name = "Шкура демона", additional_info = "Мана: 120\nМгновенное действие\n[q]Увеличивает параметр брони персонажа на 120 ед. и восполняет 5 ед. здоровья каждые 5 сек. в течение 30 мин."},
[697] = {name = "Призыв демона Бездны", additional_info = "100% от базовой мана\nПрименение: 10 сек\nИнгредиенты:\nОсколок души\n[q]Призыв демона Бездны, повинующегося чернокнижнику."},
[698] = {name = "Ритуал призывания", additional_info = "{Мана: 300} {Радиус действия: 30 м}\nПрименение: 5 сек\nИнгредиенты:\nОсколок души\n[q]Проведение ритуала, призывающего указанного члена группы. Требуется тот, кто будет читать заклинание, и 2 члена группы. Все участники должны находиться вне боя. Щелкнуть правой кнопкой мыши по порталу и не двигаться, пока ритуал не завершится."},
[699] = {name = "Похищение жизни", additional_info = "{Мана: 85} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Передача 17 ед. здоровья от цели к заклинателю раз в 1 сек. Время действия – 5 сек."},
[700] = {name = "Сон", additional_info = "{Мана: 60} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Усыпляет противника на время до 20 сек. Цель проснется при получении урона. Одновременно можно усыпить одну цель."},
[701] = {name = "Огненная стрела", additional_info = "{Мана: 10} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Нанесение цели 19 ед. урона от огня."},
[702] = {name = "Проклятие слабости", additional_info = "{Мана: 20} {Радиус действия: 30 м}\nМгновенное действие\n[q]Снижение наносимого целью урона на 3 ед. на 2 мин. Один чернокнижник может наложить проклятие только на одну цель."},
[703] = {name = "Гаррота", additional_info = "{Энергия: 50} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Незаметность\n[q]Удушающий прием, наносящий противнику 144 ед. урона за 18 сек. Прием увеличивает силу вашей атаки. Для выполнения приема необходимо находиться за спиной цели в состоянии незаметности. Длина серии приемов увеличивается на 1."},
[704] = {name = "Проклятие безрассудства", additional_info = "{Мана: 35} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклятие цели, увеличивающее силу ее атаку ближнего боя на 20 ед., но ослабляющее броню на 140 ед. на 2 мин. Проклятые таким образом противники станут невосприимчивы к страху и ужасу и не убегут с поля боя. Один чернокнижник может наложить проклятье только на одну цель."},
[705] = {name = "Стрела Тьмы", additional_info = "{Мана: 70} {Радиус действия: 30 м}\nПрименение: 2.8 сек\n[q]Поражение противника теневой стрелой, наносящей 52 в 61 ед. урона от темной магии."},
[706] = {name = "Демонический доспех", additional_info = "Мана: 275\nМгновенное действие\n[q]Защита заклинателя, усиливающая его броню на 210, сопротивление темной магии - на 3 и восстанавливающая ему 7 ед. здоровья раз в 5 сек. Время действия – 30 мин."},
[707] = {name = "Жертвенный огонь", additional_info = "{Мана: 45} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Наносит противнику [ 24 * ( ( ( 1 ) ) ) ] ед. урона от огня сразу и еще 40 ед. урона от огня за 15 сек."},
[709] = {name = "Похищение жизни", additional_info = "{Мана: 135} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Передача 29 ед. здоровья от цели к заклинателю раз в 1 сек. Время действия – 5 сек."},
[710] = {name = "Изгнание", additional_info = "{Мана: 100} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Изгнание противника на время до 20 сек. В течение этого времени противник не может участвовать в событиях, однако становится неуязвим. Заклинание можно применять только против одного противника за раз. Действует только на демонов и элементалей."},
[711] = {name = "Адское Пламя", additional_info = "{Мана: 25} {Радиус действия: 30 м}\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Заклинание обжигает всех противников в радиусе 10 метров, нанося им 69 в 78 ед. урона от огня."},
[712] = {name = "Призыв суккуба", additional_info = "100% от базовой мана\nПрименение: 10 сек\nИнгредиенты:\nОсколок души\n[q]Призыв суккуба, повинующегося чернокнижнику."},
[713] = {name = "Призыв инкуба", additional_info = "100% от базовой мана\nПрименение: 10 сек\nИнгредиенты:\nОсколок души\n[q]Призыв инкуба, повинующегося чернокнижнику."},
[714] = {name = "Похищение жизни", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Похищение жизни\" (уровень 1)."},
[719] = {name = "Создание камня души", additional_info = "Применение: 3 сек\n[q]\"Обучение заклинанию \"Создание камня души\"."},
[720] = {name = "Запутывание", additional_info = nil},
[721] = {name = "Стрела Тьмы", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Стрела Тьмы\" (уровень 2)."},
[722] = {name = "Шкура демона", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Шкура демона\" (уровень 2)."},
[724] = {name = "Колодец Света", additional_info = "Мана: 225\n{Применение: 1.5 сек} {Восстановление: 10 мин}\n[q]Создает священный колодец Света. Члены вашей группы или рейда могут испить из него для восстановления 800 ед. здоровья в течение 10 сек. Любой полученный урон снимает данный эффект. Колодец содержит 5 зарядов целительной энергии и существует в течение 3 мин."},
[725] = {name = "Похищение жизни", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Похищение жизни\" (уровень 2)."},
