[735] = {name = "Божественная защита", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Божественная защита\" (уровень 2)."},
[736] = {name = "Похищение жизни", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Похищение жизни\" (уровень 3)."},
[740] = {name = "Спокойствие", additional_info = "Мана: 375\n{Направляемое (Применение:} 10 сек) {Восстановление: 5 мин}\n[q]Восполняет находящимся рядом участникам группы 98 ед. здоровья раз в 2 сек. в течение 10 сек. Требуется поддерживать заклинание."},
[741] = {name = "Дворфийский", additional_info = nil},
[742] = {name = "Распыление", additional_info = "Восстановление: 10 мин\n(Вероятность срабатывания: 35%)"},
[743] = {name = "Слиться с тенью", additional_info = "Мгновенное действие"},
[744] = {name = "Яд", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение урона от сил природы раз в 3 сек. в течение 30 сек."},
[745] = {name = "Сеть", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Набрасывание на противника сети, обездвиживая его на 10 сек."},
[746] = {name = "Первая помощь", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 6 сек)\n[q]Восполнение 66 ед. здоровья в течение 6 сек."},
