[753] = {name = "Огненный посох II", additional_info = "Следующая атака"},
[755] = {name = "Канал здоровья", additional_info = "Здоровье: 11 плюс 5/сек Радиус действия: 20 м\nНаправляемое (Применение: 10 сек)\n[q]Передача питомцу заклинателя 12 ед. здоровья раз в секунду в течение 10 сек., пока заклинатель поддерживает заклинание."},
[758] = {name = "Огневик - постоянное действие", additional_info = "[q]Наложение на основное оружие чар огня, дающих возможность при на каждой атаке причинить дополнительно 25 в 35 ед. урона от огня."},
[759] = {name = "Сотворение агата маны", additional_info = "Мана: 530\nПрименение: 3 сек\n[q]Создает агат маны, который можно использовать для мгновенного восполнения 375 в 425 ед. маны.\n\n Сотворенные предметы исчезают, если выйти из игры более чем на 15 минут."},
[766] = {name = "Элементаль воды", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Дух воды\" (уровень 1)."},
[768] = {name = "Облик кошки", additional_info = "55% от базовой мана\nМгновенное действие\n[q]Преврашение в кошку, что увеличивает силу атаки на величину ловкости плюс 40 ед. В данном облике заклинатель невосприимчив к заклинаниям превращения и может использовать различные способности, свойственные кошке.\n\n При трансформации заклинатель освобождается от действия эффектов превращения и эффектов, снижающих скорость передвижения."},
[769] = {name = "Размах", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Атака 3 находящихся рядом противников, наносящая им 36 ед. урона."},
[770] = {name = "Волшебный огонь", additional_info = "{Мана: 55} {Радиус действия: 30 м}\nМгновенное действие\n[q]Ослабляет броню на 175 ед. на 40 сек. Во время действия заклинания цель не может становиться незаметной или невидимой."},
[772] = {name = "Кровопускание", additional_info = "{Ярость: 10} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Боевая стойка, Оборонительная стойка\n[q]Наносит цели кровоточащую рану, из-за которой она теряет 15 ед. здоровья за 9 сек."},
[774] = {name = "Омоложение", additional_info = "{Мана: 25} {Радиус действия: 40 м}\nМгновенное действие\n[q]Излечение цели на 32 ед. в течение 12 сек."},
[775] = {name = "Древесный облик", additional_info = "20% от базовой мана\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Превращение заклинателя в дерево, что снимает с него все вредноносные физические эффекты и делает невосприимчивым к физическим атакам на 8 сек. Во время действия заклинания он не может атаковать, двигаться или применять заклинания и обладает невосприимчивостью к превращениям.\n\n Перемена облика освобождает заклинателя от сковывающих эффектов (обездвиживания и замораживания)."},
[776] = {name = "Рассеяние чар", additional_info = "{Мана: 24} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 1 сек}\n[q]Заклинание снимает все магические воздействия,оказанные на дружественную цель, и не дает магическим воздействиям поражать цель в течение 5 сек."},
[778] = {name = "Волшебный огонь", additional_info = "{Мана: 75} {Радиус действия: 30 м}\nМгновенное действие\n[q]Ослабляет броню на 285 ед. на 40 сек. Во время действия заклинания цель не может становиться незаметной или невидимой."},
[779] = {name = "Размах", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Атака 3 находящихся рядом противников, наносящая им 18 ед. урона."},
[780] = {name = "Размах", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Атака 3 находящихся рядом противников, наносящая им 25 ед. урона."},
[781] = {name = "Отрыв", additional_info = "{Мана: 50} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 5 сек}\nТребуется: Оружие ближнего боя\n[q]Попытка оторваться от противника, снизив создаваемую угрозу. Прекращение атаки."},
[782] = {name = "Шипы", additional_info = "{Мана: 60} {Радиус действия: 30 м}\nМгновенное действие\n[q]Наделение дружественной цели шипами, которые наносят 6 ед. урона от сил природы атакующим при ударе. Время действия – 10 мин."},
[783] = {name = "Походный облик", additional_info = "20% от базовой мана\nМгновенное действие\n[q]Трансформация в походный облик, что увеличивает скорость передвижения на 40%. В данном облике заклинатель невосприимчив к заклинаниям превращения. Доступно только вне помещений.\n\n При трансформации заклинатель освобождается от эффектов превращения и эффектов, снижающих скорость передвижения."},
[784] = {name = "Волшебный огонь", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Волшебный огонь\" (уровень 1)."},
