[837] = {name = "Ледяная стрела", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nПрименение: 2.2 сек\n[q]В противника летит ледяная стрела, наносящая от [51 * ( 1 ) ] до [57 * ( 1 ) ] ед. урона от магии льда и снижающая скорость передвижения на 40% на 6 сек."},
[838] = {name = "Ледяная стрела", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Ледяная стрела\" (уровень 3)."},
[839] = {name = "Ускорение II", additional_info = "{Мана: 17} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Повышение скорости атаки на 3%. Время действия – 30 сек."},
[842] = {name = "Эфирный облик", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Эфирный облик\" (уровень 2)."},
[844] = {name = "Ледяной доспех", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Ледяной доспех\" (уровень 2)."},
[845] = {name = "Рассекающий удар", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Размашистая атака, наносящая урон от оружия и еще 5 ед. урона цели и ее ближайшему союзнику."},
[846] = {name = "Огненный столб", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Огненный столб\" (уровень 1)"},
