[974] = {name = "Щит земли", additional_info = "{15% от базовой мана} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает цель земляным щитом, который уменьшает время, теряемое из-за получения урона при произнесении и поддержании заклинаний, на 30%. Кроме того, атаки восстанавливают защищенной цели ед. здоровья, но этот эффект срабатывает не чаще, чем раз в несколько секунд. 6 заряда:зарядов. Время действия – 10 мин. Заклинание может одновременно защищать только одну цель, а каждая цель может быть защищена только одним заклинанием категории \"Щит стихий\".\n(Восстановление: 3.5с)"},
[976] = {name = "Защита от темной магии", additional_info = "{Мана: 250} {Радиус действия: 30 м}\nМгновенное действие\n[q]Увеличение сопротивления темной магии у цели на 30 ед. на 10 мин."},
[977] = {name = "Защита от темной магии", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Защита от темной магии\"."},
[979] = {name = "Порча", additional_info = "Применение: 3 сек\n[q]Обучает \"Порче\" (3 - й уровень)."},
[980] = {name = "Проклятие агонии", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклинает цель, вводит ее в состояние агонии и наносит ей в течение 24 сек. постепенно нарастающий урон. Общая величина урона - 84. Каждый чернокнижник может наложить только одно заклинание проклятия на каждую цель."},
[981] = {name = "Проклятие агонии", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Проклятие агонии\" (уровень 1)."},
[982] = {name = "Воскрешение питомца", additional_info = "100% от базовой мана\nПрименение: 10 сек\n[q]Оживляет вашего питомца, возвращая его к жизни с 15% его базового здоровья."},
