[988] = {name = "Рассеивание заклинаний", additional_info = "{18% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Рассеивание магических эффектов с цели, снимающее 2 вредоносных эффекта:вредоносных эффектов с союзника или 2 благотоворных эффекта:благотворных эффектов с противника."},
[989] = {name = "Рассеивание заклинаний", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Рассеивание заклинаний\" (уровень 2)."},
[990] = {name = "Сотворение пищи", additional_info = "Мана: 180\nПрименение: 3 сек\n[q]Создает 20 ломтя:ломтей ржаного хлеба, чтобы обеспечить мага и его союзников едой.\n\n Сотворенные предметы исчезают, если выйти из игры более чем на 15 минут."},
[991] = {name = "Сотворение пищи", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Сотворение пищи\" (уровень 3)."},
