[1005] = {name = "Божественная кара", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Божественная кара\" (уровень 5)"},
[1006] = {name = "Внутренний огонь", additional_info = "Мана: 165\nМгновенное действие\n[q]Наполняет заклинателя святой энергией, которая усиливает его броню на 945 ед. Каждая успешная атака против жреца снимает один заряд заклинания. Заклинание действуте 10 мин. или пока не будут сняты 20 зарядов."},
[1007] = {name = "Внутренний огонь", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Внутренний огонь\" (уровень 3)."},
[1008] = {name = "Усиление магии", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nМгновенное действие\n[q]Усиливает магию, направленную на выбранного участника группы, увеличивая получаемый им магический урон не более чем на 15 ед. и усиливая эффекты лечения на нем не более чем на 30 ед. Время действия – 10 мин."},
[1009] = {name = "Беспощадная взбучка", additional_info = "{Тонус: 45} {Дистанция ближнего боя}\n{Направляемое (Применение:} 5 сек) {Восстановление: 25 сек}\n[q]Избиение противника."},
[1010] = {name = "Проклятие маразма", additional_info = "{Мана: 110} {Радиус действия: 30 м}\nМгновенное действие\n[q]Маразм - уменьшение интеллекта и духа на 6 ед. раз 3 сек., пока обе характеристики не снизятся на 90 ед. Один чернокнижник может наложить проклятие только на одну цель."},
[1011] = {name = "Изгнание нежити", additional_info = "Применение: 3 сек\n[q]Обучение изгнанию нежити (уровень 1)."},
[1012] = {name = "Мастер мечей", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Увеличение рейтинга атаки мечами на 3 ед."},
[1013] = {name = "Сила героя", additional_info = nil},
[1014] = {name = "Проклятие агонии", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклинает цель, вводит ее в состояние агонии и наносит ей в течение 24 сек. постепенно нарастающий урон. Общая величина урона - 180. Каждый чернокнижник может наложить только одно заклинание проклятия на каждую цель."},
[1015] = {name = "Проклятие агонии", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Проклятие агонии\" (уровень 2)."},
[1017] = {name = "Чутье на демонов", additional_info = "Применение: 3 сек\n[q]Обучение способности \"Чутье на демонов\"."},
[1020] = {name = "Божественный щит", additional_info = "Мана: 110\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Дает паладину невосприимчивость к урону и заклинаниям, но [ S03 – настройка и отмена пассивных эффектов – паладин : уменьшает наносимый урон на 50% / увеличивает интервалы между атаками на 100%]. Время действия – 12 сек. Цель этого заклинания не может снова получить неуязвимость от \"Божественного щита\", \"Божественной защиты\" и \"Благословения защиты\" в течение 1 мин."},
[1021] = {name = "Божественный щит", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Божественный щит\" (уровень 2)."},
[1022] = {name = "Благословение защиты", additional_info = "{Мана: 25} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Защита выбранных участников группы от всех физических атак на 6 сек., но в это время они не могут атаковать и использовать физические способности. Каждый паладин единовременно может накладывать на игроков только одно благословение. При использовании данного заклинания цель нельзя снова сделать неуязвимой при помощи заклинаний \"Божественный щит\", \"Божественная защита\", \"Благословение защиты\" в течение 1 мин."},
[1023] = {name = "Печать защиты", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Печать защиты\" (уровень 1)."},
[1025] = {name = "Порча", additional_info = "Применение: 3 сек\n[q]Обучает \"Порче\" (2 - й уровень)."},
[1026] = {name = "Свет небес", additional_info = "{Мана: 190} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Исцеляет дружественную цель на 322 в 368 ед. здоровья."},
[1027] = {name = "Свет небес", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Свет небес\" (уровень 4)."},
[1029] = {name = "Проклятие агонии", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Проклятие агонии\" (уровень 3)."},
[1031] = {name = "Проклятие слабости", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Проклятие слабости\" (уровень 3)."},
[1032] = {name = "Аура благочестия", additional_info = "Мгновенное действие\n[q]Увеличивает на 505 ед. параметр брони участников группы, находящихся не далее, чем в 30 метрах:метрах. На персонажа может действовать только одна аура от каждого паладина."},
[1033] = {name = "Залп огня", additional_info = nil},
[1035] = {name = "Защита от огня", additional_info = nil},
[1037] = {name = "Печать ярости", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Печать ярости\" (уровень 1)."},
[1038] = {name = "Благословение спасения", additional_info = "{8% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Наложение на участников группы благословения, на 5 мин. уменьшающего любую представляемую угрозу на 30%. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[1039] = {name = "Печать спасения", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Печать спасения\" (уровень 1)."},
[1042] = {name = "Свет небес", additional_info = "{Мана: 275} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Исцеляет дружественную цель на 506 в 569 ед. здоровья."},
[1043] = {name = "Свет небес", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Свет небес\" (уровень 5)."},
[1044] = {name = "Благословение свободы", additional_info = "{10% от базовой мана} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 20 сек}\n[q]Наложение на дружественные цели благословения, на 10 сек. дающего невосприимчивость к эффектам замедления движений. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[1045] = {name = "Страх", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Страх\" (уровень 1)."},
[1049] = {name = "Создание камня здоровья", additional_info = "Применение: 3 сек\n[q]Обучение созданию камня здоровья."},
[1050] = {name = "Жертвоприношение", additional_info = "Применение: 1 сек"},
[1053] = {name = "Антимагия", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Антимагия\"."},
[1054] = {name = "Эффект малого камня огня", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наложение на оружие чар огня."},
[1055] = {name = "Глухая оборона", additional_info = nil},
[1056] = {name = "Медленный яд II", additional_info = "Мана: 51\nПрименение: 1 сек"},
[1058] = {name = "Омоложение", additional_info = "{Мана: 40} {Радиус действия: 40 м}\nМгновенное действие\n[q]Излечение цели на 56 ед. в течение 12 сек."},
[1059] = {name = "Омоложение", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Омоложение\" (уровень 2)."},
[1062] = {name = "Гнев деревьев", additional_info = "{Мана: 65} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Оплетение цели корнями, удерживающими ее на месте и наносящими 50 ед. урона от сил природы в течение 15 сек. Нанесение стороннего урона может прервать действие. Используется только вне помещений."},
[1063] = {name = "Гнев деревьев", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Гнев деревьев\" (уровень 2)."},
[1064] = {name = "Цепное исцеление", additional_info = "{Мана: 260} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Восполняет союзнику 332 в 381 ед. здоровья, а затем переходит на соседние цели. Если применить к участнику группы, переходит только на других участников группы. Каждый переход снижает эффективность исцеления до 50% предыдущего исцеления. Максимум целей – 3."},
[1065] = {name = "Деморализующий крик", additional_info = nil},
[1066] = {name = "Водный облик", additional_info = "20% от базовой мана\nМгновенное действие\n[q]Превращение в морского льва, что увеличивает скорость плавания на 50% и позволяет дышать под водой. В данном облике заклинатель невосприимчив к заклинаниям превращения.\n\n При трансформации заклинатель освобождается от действия эффектов превращения и эффектов, снижающих скорость передвижения."},
[1070] = {name = "Волшебный огонь", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Волшебный огонь\" (уровень 3)."},
[1075] = {name = "Шипы", additional_info = "{Мана: 105} {Радиус действия: 30 м}\nМгновенное действие\n[q]Наделение дружественной цели шипами, которые наносят 9 ед. урона от сил природы атакующим при ударе. Время действия – 10 мин."},
[1076] = {name = "Шипы", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Тернии\" (уровень 3)."},
[1079] = {name = "Разорвать", additional_info = "{Энергия: 30} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Завершающий прием, наносящий урон в течение некоторого времени. Урон увеличивается за счет длины серии и силы атаки:\n 1 прием: [ 6 * 1 * (7)] ед. урона за 12 сек.\n 2 приема: [ 6 * 1 * (11)] ед. урона за 12 сек.\n 3 приема: [ 6 * 1 * (15)] ед. урона за 12 сек.\n 4 приема: [ 6 * 1 * (19)] ед. урона за 12 сек.\n 5 приемов: [ 6 * 1 * (23)] ед. урона за 12 сек."},
[1082] = {name = "Когти", additional_info = "{Энергия: 45} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Наносит противнику дополнительно 27 ед. урона. Длина серии приемов увеличивается на 1."},
[1084] = {name = "Огненная стрела III", additional_info = "{Мана: 26} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Нанесение цели 35 в 40 ед. урона от огня."},
[1086] = {name = "Демонический доспех", additional_info = "Мана: 520\nМгновенное действие\n[q]Защита заклинателя, усиливающая его броню на 300, сопротивление темной магии - на 6 и восстанавливающая ему 9 ед. здоровья раз в 5 сек. Время действия – 30 мин."},
[1087] = {name = "Демонический доспех", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Демонический доспех\" (уровень 2)."},
[1088] = {name = "Стрела Тьмы", additional_info = "{Мана: 110} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Поражение противника теневой стрелой, наносящей 92 в 104 ед. урона от темной магии."},
[1089] = {name = "Стрела Тьмы", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Стрела Тьмы\" (уровень 4)."},
[1090] = {name = "Сон", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Усыпляет противника на время до 30 сек. Цель проснется при получении урона. Одновременно можно усыпить одну цель."},
[1091] = {name = "Сон", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Сон\" (уровень 2)."},
[1094] = {name = "Жертвенный огонь", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Наносит противнику [ 53 * ( ( ( 1 ) ) ) ] ед. урона от огня сразу и еще 90 ед. урона от огня за 15 сек."},
[1095] = {name = "Жертвенный огонь", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Жертвенный огонь\" (уровень 3)."},
[1096] = {name = "Огненная стрела IV", additional_info = "{Мана: 34} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Нанесение цели 42 в 49 ед. урона от огня."},
[1098] = {name = "Порабощение демона", additional_info = "{Мана: 300} {Радиус действия: 30 м}\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Порабощение демона уровнем не выше 45. Промежуток между атаками пленного демона увеличивается на 40%, а скорость применения заклинаний уменьшается на 30%. Продолжительность – до 5 мин. При регулярном порабощении одного и того же демона управлять им с каждым разом становится все труднее."},
[1101] = {name = "Канал маны", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Канал маны\"."},
[1105] = {name = "Печать мудрости", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Печать мудрости\" (уровень 3)."},
[1106] = {name = "Стрела Тьмы", additional_info = "{Мана: 160} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Поражение противника теневой стрелой, наносящей 150 в 170 ед. урона от темной магии."},
[1107] = {name = "Порча", additional_info = "Применение: 3 сек\n[q]Обучает \"Порче\" (1 - й уровень)."},
[1108] = {name = "Проклятие слабости", additional_info = "{Мана: 35} {Радиус действия: 30 м}\nМгновенное действие\n[q]Снижение наносимого целью урона на 6 ед. на 2 мин. Один чернокнижник может наложить проклятие только на одну цель."},
[1109] = {name = "Проклятие слабости", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Проклятие слабости\" (уровень 2)."},
[1112] = {name = "Теневая звезда II", additional_info = "Применение: 3 сек"},
[1114] = {name = "Владение уклонением", additional_info = "[q]Повышение вероятности уклонения от удара на 1%."},
[1116] = {name = "Щит Хаоса", additional_info = "Мана: 25 плюс 4/сек."},
[1117] = {name = "Лечение питомца", additional_info = nil},
[1120] = {name = "Похищение души", additional_info = "{Мана: 55} {Радиус действия: 30 м}\nНаправляемое (Применение: 15 сек)\n[q]Похищение души цели, наносящее 55 ед. урона от темной магии за 15 сек. В случае смерти цели, если цель отдает опыт или честь, заклинатель получает осколок души, которые требуются для других заклинаний."},
[1121] = {name = "Запутывание", additional_info = nil},
[1122] = {name = "Инфернал", additional_info = "{100% от базовой мана} {Радиус действия: 30 м}\n{Применение: 2 сек} {Восстановление: 1 час}\nИнгредиенты:\nКамень инфернала\n[q]Призывает метеор из Круговерти Пустоты, который наносит 200 ед. урона от огня и оглушает противников в области действия на 2 сек. Из кратера появляется инфернал, который в течение 5 мин. подчиняется призывателю. Для сохранения контроля после истечения времени инфернала нужно поработить. Действует только вне помещений."},
[1123] = {name = "Ритуал Рока", additional_info = "Применение: 3 сек\n[q]Обучение заклинанию \"Ритуал Рока\"."},
[1124] = {name = "Адское Пламя II", additional_info = "{Мана: 27} {Радиус действия: 30 м}\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Заклинание обжигает всех противников в радиусе 10 метров, нанося им 80 в 91 ед. урона от огня."},
[1126] = {name = "Знак дикой природы", additional_info = "{Мана: 20} {Радиус действия: 30 м}\nМгновенное действие\n[q]Усиление брони дружественной цели на 25 ед. на 30 мин."},
[1127] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 874.8 ед. здоровья за 27 сек. Действие прерывается, если встать с места."},
[1129] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[1130] = {name = "Метка охотника", additional_info = "{Мана: 15} {Радиус действия: 100 м}\nМгновенное действие\n[q]Сила всех атак дальнего боя, направленных против отмеченной охотником цели, повышается на 20. Кроме того, охотник всегда видит отмеченного противника, даже если тот находится в режиме незаметности или невидим, и может следить за ним по мини-карте. Эффект длится 2 мин."},
[1131] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 2148 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[1132] = {name = "Критический удар", additional_info = nil},
[1133] = {name = "Питье", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 1344.6 ед. маны за 27 сек. Действие эффекта прерывается, если персонаж встает с места."},
[1135] = {name = "Питье", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 1992 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
[1137] = {name = "Питье", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 2934 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
[1138] = {name = "Хрустальная защита", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Повышение сопротивления магии льда и темной магии на 10 ед. на 1 мин."},
[1139] = {name = "Ледяной взгляд", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Увеличение времени между атаками противника на 5% на 15 сек."},
[1140] = {name = "Размывание", additional_info = nil},
[1141] = {name = "Аура великолепия", additional_info = nil},
[1142] = {name = "Ледяная стрела", additional_info = nil},
