[2823] = {name = "Смертельный яд", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 36 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 60 раз.\n(Вероятность срабатывания: 30%)"},
[2824] = {name = "Смертельный яд II", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 52 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 75 раз.\n(Вероятность срабатывания: 30%)"},
