[7108] = {name = "Влажная салфетка", additional_info = "Мана: 45\n{Мгновенное действие} {Восстановление: 1 сек}\n[q]Снятие 1 отрицательного эффекта от заклинаний с того, кто воспользуется. Очищение силой лимона."},
