[7137] = {name = "Натиск Тени", additional_info = "Мгновенное действие\n[q]Бросается к противнику, повышая скорость передвижения и урон от первой атаки на 60 ед."},
[7139] = {name = "Поступь Скверны", additional_info = "{Мгновенное действие} {Восстановление: 20 сек}\n[q]Плюс 20 ед. к обычному урону для всех находящихся поблизости противников. Оглушение на 3 сек., увеличение физического урона на 10 ед."},
[7140] = {name = "Выявление слабости", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 25 сек\n[q]Увеличение физического урона, получаемого противником, на 5 ед. на 5 сек."},
