[7279] = {name = "Черная слизь", additional_info = "Дистанция ближнего боя\nПрименение: 3 сек\n[q]Увеличение времени между атаками находящихся поблизости противников на 54%, снижение скорости их передвижения на 30% на 2 мин."},
