[7289] = {name = "Уменьшение", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Понижение силы противника на 1 ед. и выносливости на 1 ед. на 2 мин."},
[7290] = {name = "Вытягивание души", additional_info = "{Мана: 10} {Радиус действия: 10 м}\n{Направляемое (Применение:} 10 сек) {Восстановление: 1 сек}\n[q]Похищение у противника и его ближайшего союзника 10 ед. Здоровья в течение 10 сек. При этом здоровье заклинателя восполняется на величину вплоть до двухкратной от похищенного здоровья."},
[7293] = {name = "Форма зомби", additional_info = nil},
[7294] = {name = "Аура воздаяния", additional_info = "Мгновенное действие\n[q]Нанесение 5 ед. урона от светлой магии любому созданию, которое атакует участника группы, находящегося в радиусе 30 м. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Аура\"."},
[7295] = {name = "Истощение души", additional_info = "Радиус действия: 40 м\nПрименение: 2 сек\n[q]Обездвиживание противника на 10 сек. и похищение у него 35 ед. здоровья, которое передается заклинателю."},
