[7300] = {name = "Морозный доспех", additional_info = "Мана: 110\nМгновенное действие\n[q]Усиливает броню на 110. Может снизить скорость передвижения атакующих противников на 30% и увеличить интервал между их атаками на 25% на 5 сек. Одновременно может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[7301] = {name = "Морозный доспех", additional_info = "Мана: 170\nМгновенное действие\n[q]Усиливает броню на 200. Может снизить скорость передвижения атакующих противников на 30% и увеличить интервал между их атаками на 25% на 5 сек. Одновременно может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[7302] = {name = "Ледяной доспех", additional_info = "Мана: 240\nМгновенное действие\n[q]Усиливает броню на 290 и сопротивление магии льда на 6. Снижает скорость передвижения атакующих противников на 30% и увеличивает интервал между их атаками на 25% на 5 сек. Одновременно может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[7320] = {name = "Ледяной доспех", additional_info = "Мана: 320\nМгновенное действие\n[q]Усиливает броню на 380 и сопротивление магии льда на 9. Снижает скорость передвижения атакующих противников на 30% и увеличивает интервал между их атаками на 25% на 5 сек. Одновременно может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[7321] = {name = "Окоченение", additional_info = nil},
[7322] = {name = "Ледяная стрела", additional_info = "{Мана: 65} {Радиус действия: 30 м}\nПрименение: 2.6 сек\n[q]В противника летит ледяная стрела, наносящая от [74 * ( 1 ) ] до [82 * ( 1 ) ] ед. урона от магии льда и снижающая скорость передвижения на 40% на 7 сек."},
