[7366] = {name = "Стойка берсерка", additional_info = "Мгновенное действие\n[q]Принятие агрессивной боевой стойки, находясь в которой воин разъяряется при нанесении врагу урона. Длительность - 4 мин."},
[7367] = {name = "Заразный укус", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение 15 ед. урона от сил природы раз в 10 сек. Увеличение получаемого физического урона на 5 в течение 3 мин."},
[7369] = {name = "Рассекающий удар", additional_info = "{Ярость: 20} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Размашистая атака, наносящая урон от оружия и еще 10 ед. урона цели и ее ближайшему союзнику."},
[7370] = {name = "Рывок", additional_info = nil},
[7371] = {name = "Рывок", additional_info = "{Тонус: 35} {Радиус действия: 8 - 25 м}\n{Мгновенное действие} {Восстановление: 25 сек}\n[q]Нападение на врага, обездвиживание его на 1 сек и увеличение следующей атаки вепря на 60 ед."},
[7372] = {name = "Подрезать сухожилия", additional_info = "{Ярость: 10} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Боевая стойка, Стойка берсерка\n[q]Калечит противника, нанося 18 ед. урона и снижая скорость передвижения на 45% на 15 сек."},
[7373] = {name = "Подрезать сухожилия", additional_info = "{Ярость: 10} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Боевая стойка, Стойка берсерка\n[q]Калечит противника, нанося 45 ед. урона и снижая скорость передвижения на 50% на 15 сек."},
