[8604] = {name = "Рецепт яйца с травами", additional_info = "Применение: 3 сек\nИнгредиенты:\nНебольшое яйцо , Пряные травы\nЯйцо с травами\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин."},
[8605] = {name = "Рецепт: яйцо с травами", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению яйца с травами."},
[8606] = {name = "Призыв Циклониана", additional_info = "Радиус действия: 100 м\nПрименение: 10 сек\n[q]Призывает Циклониана"},
