[8613] = {name = "Снятие шкур", additional_info = "Радиус действия: 5 м\nПрименение: 2 сек\nИнструменты: Нож для снятия шкур\n[q]Учит снимать шкуры с животных и использовать выкройки, рассчитанные на уровень навыка до 75-го. Для снятия шкур требуется особый нож."},
[8615] = {name = "Снятие шкур (ученик)", additional_info = nil},
[8616] = {name = "Путь берсерка", additional_info = "Неограниченное расстояние\nПрименение: 3 сек\n[q]Изучение способности \"Стойка берсерка\" (уровень 1). Изучение способности \"Перехват\" (уровень 1)."},
[8617] = {name = "Снятие шкур", additional_info = "Радиус действия: 5 м\nПрименение: 2.5 сек\nИнструменты: Нож для снятия шкур\n[q]Навык подмастерья в профеcсии снятия шкур со зверей. Шкуры в дальнейшем используются в кожевничестве. Дает возможность развить навык до уровня 150. Требует наличия ножа для снятия шкур."},
[8618] = {name = "Снятие шкур", additional_info = "Радиус действия: 5 м\nПрименение: 3 сек\nИнструменты: Нож для снятия шкур\n[q]Навык умельца в профессии снятия шкур со зверей. Шкуры в дальнейшем используются в кожевничестве. Дает возможность развить навык до уровня 225. Требует наличия ножа для снятия шкур."},
[8619] = {name = "Снятие шкур (подмастерье)", additional_info = nil},
[8620] = {name = "Снятие шкур (эксперт)", additional_info = nil},
[8621] = {name = "Коварный удар", additional_info = "{Энергия: 45} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мгновенный удар, наносящий 33 ед. урона сверх базового урона оружия. Длина серии приемов увеличивается на 1."},
[8622] = {name = "Коварный удар", additional_info = nil},
[8623] = {name = "Потрошение", additional_info = "{Энергия: 35} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий урон в зависимости от длины серии и силы атаки:\n 1 прием: 60-90 ед. урона\n 2 приема: 105-135 ед. урона\n 3 приема: 150-180 ед. урона\n 4 приема: 195-225 ед. урона\n 5 приемов: 240-270 ед. урона."},
[8624] = {name = "Потрошение", additional_info = "{Энергия: 35} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий урон в зависимости от длины серии и силы атаки:\n 1 прием: 99-143 ед. урона\n 2 приема: 176-220 ед. урона\n 3 приема: 253-297 ед. урона\n 4 приема: 330-374 ед. урона\n 5 приемов: 407-451 ед. урона."},
[8625] = {name = "Потрошение", additional_info = nil},
[8626] = {name = "Потрошение", additional_info = nil},
[8629] = {name = "Парализующий удар", additional_info = "{Энергия: 45} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Оружие ближнего боя\n[q]Удар, наносящий 32 ед. урона и парализующий противника на 4 сек Цель должна быть обращена к вам лицом. После этого удара вы прекращаете автоматическую атаку. Любой урон, нанесенный противнику, выводит его из паралича. Длина серии приемов увеличивается на 1."},
