[9488] = {name = "Огненный шар", additional_info = "{Мана: 45} {Радиус действия: 35 м}\nПрименение: 2 сек\n[q]Наносит противнику урон от огня."},
[9489] = {name = "Создание гадальной чаши", additional_info = "Дистанция ближнего боя\nПрименение: 2.5 сек\nИнструменты: Фиал виденья Талваша\n[q]Создание гадальной чаши, посредством которой можно связаться с Талвашем."},
[9490] = {name = "Устрашающий рев", additional_info = "Ярость: 10\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Друид издает устрашающий рев, снижающий силу атаки в ближнем бою находящихся рядом противников на 75. Время действия – 30 сек."},
[9491] = {name = "Устрашающий рев", additional_info = nil},
[9492] = {name = "Разорвать", additional_info = "{Энергия: 30} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Завершающий прием, наносящий урон в течение некоторого времени. Урон увеличивается за счет длины серии и силы атаки:\n 1 прием: [ 6 * 1 * (11)] ед. урона за 12 сек.\n 2 приема: [ 6 * 1 * (18)] ед. урона за 12 сек.\n 3 приема: [ 6 * 1 * (25)] ед. урона за 12 сек.\n 4 приема: [ 6 * 1 * (32)] ед. урона за 12 сек.\n 5 приемов: [ 6 * 1 * (39)] ед. урона за 12 сек."},
[9493] = {name = "Разорвать", additional_info = "{Энергия: 30} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Завершающий прием, наносящий урон в течение некоторого времени. Урон увеличивается за счет длины серии и силы атаки:\n 1 прием: [ 6 * 1 * (15)] ед. урона за 12 сек.\n 2 приема: [ 6 * 1 * (24)] ед. урона за 12 сек.\n 3 приема: [ 6 * 1 * (33)] ед. урона за 12 сек.\n 4 приема: [ 6 * 1 * (42)] ед. урона за 12 сек.\n 5 приемов: [ 6 * 1 * (51)] ед. урона за 12 сек."},
