[9612] = {name = "Чернильные брызги", additional_info = "Дистанция ближнего боя\nПрименение: 1 сек\n[q]Уменьшение вероятности нанесения урона на 50% на 15 сек."},
[9613] = {name = "Стрела Тьмы", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[9614] = {name = "Маяк Ущелья", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Через 1 мин. 2 миространника из племени Заблудших найдут и атакуют противника. Однако миространники состоят из нестабильных частиц, а потому не способны сохранять материальный облик долее 1 мин."},
