[9616] = {name = "Дикое восстановление", additional_info = "Мана: 65\nПрименение: 3 сек\n[q]Исцеление нанесенного заклинателю вреда на 23 в 37 ед. раз в 2 сек. в течение 20 сек."},
[9617] = {name = "Призрак - визуальный эффект", additional_info = nil},
[9632] = {name = "Шторм клинков", additional_info = "Направляемое (Применение: 9 сек)\n[q]Атака ближайших противников в течение 9 сек. с нанесением стандартоного урона оружия и дополнительно 5 ед. урона раз в 3 сек."},
[9633] = {name = "Вихрь", additional_info = nil},
[9634] = {name = "Облик лютого медведя", additional_info = "55% от базовой мана\nМгновенное действие\n[q]Превращение в лютого медведя, что увеличивает силу атаки на 180 ед., повышает эффективность носимых доспехов на 360%, а максимальный запас здоровья – на 1240 ед. В данном облике заклинатель невосприимчив к заклинаниям превращения и может использовать различные способности, свойственные медведю.\n\n При трансформации заклинатель освобождается от действия эффектов превращения и других эффектов, снижающих скорость передвижения."},
[9635] = {name = "Облик лютого медведя (пассивный эффект)", additional_info = "Требуется: Облик лютого медведя"},
[9636] = {name = "Призыв болотного духа", additional_info = "Применение: 1.5 сек\n[q]Призыв 1 болотного духа для сражения на стороне заклинателя в течение 1 мин."},
[9653] = {name = "Призыв грохотуна из племени Гелкис", additional_info = "Мгновенное действие\n[q]Призыв на помощь заклинателю 1 грохотуна из племени Гелкис для сопровождения заклинателя, пока он их не освободит."},
[9654] = {name = "Скачущая молния", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение молнией, наносящее урон от сил природы противнику и его ближайшему союзнику."},
[9657] = {name = "Панцирь Тени", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\n[q]Усиление защиты на 10 сек."},
[9658] = {name = "Удар пламенем", additional_info = "Радиус действия: 20 м\nПрименение: 2.2 сек\n[q]Нанесение противнику 19 в 21 ед. урона от огня и увеличение полученного противником урона от огня на 20 на 45 сек."},
[9672] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 4 сек."},
[9712] = {name = "Тауматургический канал", additional_info = "Радиус действия: 20 м\nНаправляемое (Применение: 5 сек)\n[q]Наполнение пустого тауматургического сосуда. Используется против Опаленных стражей."},
[9733] = {name = "Злость Арантира", additional_info = "{Мгновенное действие} {Восстановление: 15 сек}\n[q]В течение 4 сек. наносит находящимся рядом противникам урон от оружия плюс 0 ед. раз в 2 сек."},
[9734] = {name = "Божественная кара", additional_info = "{Мана: 75} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Удар по противнику, нанесение урона от светлой магии."},
[9735] = {name = "Особое зрение", additional_info = "Радиус действия: 15 м\nМгновенное действие\n[q]Шаман получает возможность видеть духов стихий."},
