[10011] = {name = "[q3]Порча", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nМифриловый слиток (28), Лимфа нежити (10), Слиток истинного серебра (10), Твердый шлифовальный камень (6), Плотная кожа (6)\n[q3]Гниль\nСтановится персональным при надевании\nДвуручное Древковое\nУрон: 93-141 Скорость 2.70\n(43.33 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Поражение цели с нанесением 50 ед. урона от сил природы и дополнительно 180 ед. урона в течение 1 мин."},
[10012] = {name = "Порча", additional_info = nil},
[10013] = {name = "[q2]Эбеновый нож", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nМифриловый слиток (12), Слиток истинного серебра (6), Звездный рубин (2), Твердый шлифовальный камень , Плотная кожа (2)\n[q2]Эбеновый нож\nСтановится персональным при надевании\nОдноручное Кинжал\nУрон: 32-59 Скорость 1.50\n(30.33 ед. урона в секунду)\n+9 к ловкости\nПрочность: 55 / 55\nТребуется"},
[10014] = {name = "Чертеж: эбеновый нож", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению эбенового ножа."},
[10015] = {name = "[q3]Защитник из истинного серебра", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nМифриловый слиток (30), Слиток истинного серебра (16), Звездный рубин (6), Дыхание ветра (4), Твердый шлифовальный камень (8), Плотная кожа (6)\n[q3]Защитник из истинного серебра\nСтановится персональным при надевании\nДвуручное Меч\nУрон: 108-162 Скорость 3.00\n(45.00 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Защита заклинателя священным щитом."},
