[10953] = {name = "Усмирение", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nМгновенное действие\n[q]Усмирение цели, в результате чего дистанция, на которой она вас атакует, сокращается на 10 метра:метров. Действует только на гуманоидов уровня 70 или ниже. Время действия – 15 сек."},
