[11013] = {name = "Шпион", additional_info = "Мгновенное действие\n[q]Заклинатель получает возможность проиграть анимацию режима незаметности без невидимости."},
[11014] = {name = "Течение Северного источника", additional_info = "{Мана: 265} {Радиус действия: 40 м}\nМгновенное действие\n[q]Исцеление 108 ед. урона у союзника раз в 3 сек. в течение 15 сек."},
[11015] = {name = "Пиявка-кровосос", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Похищение у ближайших врагов 10 ед. здоровья и передача заклинателю количества здоровья в два раза больше украденного."},
[11016] = {name = "Душевный укус", additional_info = "Дистанция ближнего боя\nПрименение: 2 сек\n[q]Похищение у противника 1 ед. здоровья и 1 ед. маны."},
[11017] = {name = "Призыв охотника Скверны из племени Сухокожих", additional_info = "20% от базовой мана\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Призыв на помощь заклинателю 1 охотника Скверны из племени Сухокожих на 4 мин."},
