[11019] = {name = "Взмах крыла", additional_info = "Мгновенное действие\n[q]Поражение противников, находящихся в конусе перед заклинателем. Их отбрасывает назад."},
[11020] = {name = "Обращение в камень", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Оглушение противника при усилении его брони на 30% на 8 сек."},
[11021] = {name = "Огненный плевок", additional_info = "{Мана: 90} {Радиус действия: 10 м}\nПрименение: 3 сек\n[q]Нанесение урона от огня противнику."},
