[11048] = {name = "Постоянная иллюзия - Тирония", additional_info = "Применение: 3 сек\n[q]Наложение постоянного обличья жрицы Тиронии."},
[11067] = {name = "Постоянная иллюзия - Тирион", additional_info = "Применение: 3 сек\n[q]Наложение постоянного обличья Тириона."},
[11068] = {name = "Средоточие Льда", additional_info = "[q]Понижение расхода маны на заклинания магии льда на 1 ед."},
[11069] = {name = "Улучшенный огненный шар", additional_info = "[q]Уменьшает время применения заклинания \"Огненный шар\" на 0.1 секунды."},
[11070] = {name = "Улучшенная ледяная стрела", additional_info = "[q]Снижение времени применения заклинания \"Ледяная стрела\" на 0.1 сек."},
[11071] = {name = "Обморожение", additional_info = "[q]Ваши остужающие эффекты получают 5% шанс заморозить цель на 5 сек."},
[11078] = {name = "Улучшенный огненный взрыв", additional_info = "[q]Уменьшает время востановления заклинания \"Огненный взрыв\" на 0.5 секунды."},
[11080] = {name = "Улучшенный огненный взрыв", additional_info = "[q]Уменьшает время востановления заклинания \"Огненный взрыв\" на 1 секунды."},
[11082] = {name = "Мегавольт", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение урона от сил природы в 5 ед. противникам, находящимся в конусе перед заклинателем."},
[11083] = {name = "Пылающая душа", additional_info = "[q]Прочтение заклинаний огня не будет замедлено при получении урона с вероятностью 35%. Угроза от ваших заклинаний огня уменьшается на 15%."},
[11084] = {name = "Шок", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Мгновенное создание молнии, наносящей 269 в 286 ед. урона от сил природы."},
[11085] = {name = "Цепной удар", additional_info = "Радиус действия: 30 м\nПрименение: 2.5 сек\n[q]Поражение противника молнией, которая перескакивает на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося 162 в 181 ед. урона от сил природы каждому противнику."},
[11086] = {name = "Оберег Зум-Раха", additional_info = "Мгновенное действие\n[q]Создание оберега Зум-Раха, который действует в течение 20 сек. и периодически призывает скелетов Зум-Раха, каждый из которых существует в течение 20 сек."},
[11087] = {name = "Оберег Зум-раха - постоянное действие", additional_info = nil},
[11088] = {name = "Оберег Зум-Раха", additional_info = nil},
[11089] = {name = "Превращение Текала", additional_info = nil},
[11094] = {name = "Улучшенная защита от огня", additional_info = "[q]Защита от огня с вероятностью 10% отражает заклинания школы огня."},
[11095] = {name = "Улучшенный ожог", additional_info = "[q]Повышение до 33% вероятности сделать цель уязвимой для урона от огня при применении на ней заклинания \"Ожог\". В случае успеха цель в течение 30 сек получает на 3% больше урона от огня. Эффект может быть суммирован до 5 раз."},
[11100] = {name = "Метание пламени", additional_info = "[q]Увеличивает дальность применения ваших заклинаний огня на 3 метра:метров."},
[11103] = {name = "Сотрясение", additional_info = "[q]Есть вероятность 2%, что ваши заклинания огня оглушат цель на 2 сек.\n(Вероятность срабатывания: 2%)"},
[11108] = {name = "Улучшенный огненный столб", additional_info = "[q]Повышает вероятность критического удара при применении \"Огненного столба\" на 5%."},
[11113] = {name = "Взрывная волна", additional_info = "Мана: 215\n{Мгновенное действие} {Восстановление: 45 сек}\n[q]От заклинателя расходится волна пламени, нанося всем противникам, захваченным ею, 160 в 192 ед. урона от огня и замедляя их на 6 сек."},
[11115] = {name = "Критическая масса", additional_info = "[q]Повышает вероятность критического удара при применении заклинаний огня на 2%."},
[11119] = {name = "Воспламенение", additional_info = "[q]Критические удары заклинаниями огня воспламеняют цель, нанося ей дополнительно 8% урона от примененного заклинания в течение 4 сек."},
[11120] = {name = "Воспламенение", additional_info = "[q]Критические удары заклинаниями огня воспламеняют цель, нанося ей дополнительно 16% урона от примененного заклинания в течение 4 сек."},
[11124] = {name = "Сила огня", additional_info = "[q]Увеличивает урон от ваших заклинаний огня на 2%."},
[11129] = {name = "Возгорание", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]При использовании каждое атакующее заклинание огня, достигшее цели, увеличивает вероятность нанесения критического урона огнем на 10%. Этот эффект длится, пока 3 заклинания не нанесут:заклинаний не нанесут критический урон."},
[11130] = {name = "Отталкивание", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение плюс 30 ед. к обычному урону находящимся поблизости противникам с отбрасыванием их назад."},
[11131] = {name = "Сосулька", additional_info = "Радиус действия: 60 м\nПрименение: 1.5 сек\n[q]В противника летит ледяная стрела, нанося 360 в 410 ед. урона от магии льда и замедляя скорость его передвижения на 50% в течение 10 сек."},
[11132] = {name = "Изучить орочьи боевые поножи", additional_info = nil},
[11147] = {name = "Благословенная наковальня", additional_info = nil},
[11151] = {name = "Пронзающий лед", additional_info = "[q]Увеличение урона, наносимого вашими ледяными заклинаниями на 2%."},
[11160] = {name = "Направленная сила льда", additional_info = "[q]Снижение расхода маны на заклинания магии льда на 5% и снижение угрозы от них на 10%."},
[11165] = {name = "Улучшенное кольцо льда", additional_info = "[q]Уменьшает время восстановления \"Кольца льда\" на 2 сек."},
[11170] = {name = "Обледенение", additional_info = "[q]Повышает вероятность критического попадания ваших заклинаний в замороженные цели на 10%."},
[11175] = {name = "Вечная мерзлота", additional_info = "[q]Увеличение продолжительности эффектов категории \"Стужа\" на 1 сек. и снижение скорости передвижения противника на 4%."},
[11180] = {name = "Зимняя стужа", additional_info = "[q]Заклинания магии льда с вероятностью 20% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара заклинаний магии льда против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 5 раз.\n(Вероятность срабатывания: 20%)"},
[11185] = {name = "Улучшенная снежная буря", additional_info = "[q]Наделение эффекта заклинания \"Снежная буря\" способностью остужать, что снижает скорость передвижения цели на 30% на 1.50 сек.."},
[11189] = {name = "Защита от льда", additional_info = "[q]Увеличение на 15% эффекта усиления брони заклинаниями \"Морозный доспех\" и \"Ледяной доспех\", а также повышение до 10% вероятности отражения заклинаний магии льда во время действия эффекта \"Защита от магии льда\"."},
[11190] = {name = "Улучшенный конус холода", additional_info = "[q]Увеличение урона, нанесенного заклинанием \"Конус холода\", на 15%."},
[11195] = {name = "Взрыв дверей Зул'Фаррака", additional_info = nil},
[11196] = {name = "Недавняя перевязка", additional_info = nil},
[11197] = {name = "Ослабление доспеха", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, ослабляющий броню цели в течение 30 сек. на величину, зависящую от длины серии:\n 1 прием: 275 ед. брони\n 2 приема: 550 ед. брони\n 3 приема: 825 ед. брони\n 4 приема: 1100 ед. брони\n 5 приемов: 1375 ед. брони."},
[11198] = {name = "Ослабление доспеха", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, ослабляющий броню цели в течение 30 сек. на величину, зависящую от длины серии:\n 1 прием: 340 ед. брони\n 2 приема: 680 ед. брони\n 3 приема: 1020 ед. брони\n 4 приема: 1360 ед. брони\n 5 приемов: 1700 ед. брони."},
