[11200] = {name = "Ослабление доспеха", additional_info = nil},
[11201] = {name = "Калечащий яд", additional_info = nil},
[11202] = {name = "Калечащий яд", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, который снижает скорость передвижения на 70% в течение 12 сек.\n(Вероятность срабатывания: 30%)"},
[11203] = {name = "Изучить изысканный мифриловый шлем", additional_info = nil},
[11204] = {name = "Изучить изысканные мифриловые сапоги", additional_info = nil},
[11205] = {name = "Изучить изысканную мифриловую кирасу", additional_info = nil},
[11206] = {name = "Объект ключевого противника Ульдамана - визуальный эффект", additional_info = nil},
[11207] = {name = "Ледяные осколки", additional_info = "[q]Увеличение урона от критического поражения вашими заклинаниями льда на 20%."},
[11209] = {name = "[q4]Вызов дробящего молота", additional_info = "Применение: 10 сек\n[q]Вызов молота Мастерства."},
[11210] = {name = "Искусные чары", additional_info = "[q]Снижение сопротивления цели всем вашим заклинаниям на 5 ед. и снижение угрозы от заклинаний тайной магии на 20%."},
[11213] = {name = "Чародейская сосредоточенность", additional_info = "[q]Вероятность 2% войти в состояние \"Ясность мысли\" после того, как любое ваше заклинание нанесет урон противнку. Состояние \"Ясность мысли\" снижает расход маны на ваше следующее поражающее заклинание на 100%.\n(Вероятность срабатывания: 2%, Восстановление: 1с)"},
[11222] = {name = "Средоточие чар", additional_info = "[q]Снижение на 2% вероятности того, что противник сможет противостоять вашим заклинаниям тайной магии."},
[11232] = {name = "Чародейский ум", additional_info = "[q]Повышение максимального запаса маны на 2%."},
[11237] = {name = "Улучшенный чародейский снаряд", additional_info = "[q]\"\"С вероятностью 20% урон не прерывает применение \"Чародейских снарядов\" [ S03 – настройка и отмена пассивных эффектов – маг : \"Регенерации\" или \"Массовой регенерации\". Урон не прерывает применение \"Чародейской вспышки\" и \"Стрелы чар льда\" с вероятностью 14% ].\"\""},
[11242] = {name = "Улучшенный чародейский взрыв", additional_info = "[q]Повышает вероятность критического удара при применении \"Чародейского взрыва\" еще на 2%."},
[11247] = {name = "Магическое созвучие", additional_info = "[q]Усиление действия заклинаний \"Усиление магии\" и \"Ослабление магии\" на 25%."},
[11252] = {name = "Улучшенный щит маны", additional_info = "[q]Снижение на 10% расхода маны на снятие каждой единицы урона, получаемого при использовании заклинания \"Щит маны\"."},
[11255] = {name = "Улучшенная Антимагия", additional_info = "[q]Повышение до 50% вероятности лишить противника дара речи на 4 сек при применении заклинания \"Антимагия\".\n(Вероятность срабатывания: 50%)"},
[11262] = {name = "Улучшенный скачок", additional_info = "[q]Сокращение времени восстановления вашего заклинания \"Скачок\" на 15 сек."},
[11264] = {name = "Ледяной взрыв", additional_info = "{Мгновенное действие} {Восстановление: 15 сек}\n[q]Нанесение 49 в 56 ед.урона от магии льда ближайшим противникам и примораживание их к месту вплоть до 10 сек."},
[11267] = {name = "Внезапный удар", additional_info = "{Энергия: 60} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Незаметность\n[q]Внезапный удар по противнику, наносящий 250% урона оружия и дополнительно 185 ед. урона. Вы должны находиться за спиной цели в состоянии незаметности. Длина серии приемов увеличивается на 1."},
[11268] = {name = "Внезапный удар", additional_info = "{Энергия: 60} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Незаметность\n[q]Внезапный удар по противнику, наносящий 250% урона оружия и дополнительно 230 ед. урона. Вы должны находиться за спиной цели в состоянии незаметности. Длина серии приемов увеличивается на 1."},
[11269] = {name = "Внезапный удар", additional_info = "{Энергия: 60} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Незаметность\n[q]Внезапный удар по противнику, наносящий 250% урона оружия и дополнительно 290 ед. урона. Вы должны находиться за спиной цели в состоянии незаметности. Длина серии приемов увеличивается на 1."},
[11270] = {name = "Внезапный удар", additional_info = nil},
[11271] = {name = "Внезапный удар", additional_info = nil},
[11272] = {name = "Внезапный удар", additional_info = nil},
[11273] = {name = "Рваная рана", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий периодический урон. Урон увеличивается за счет силы атаки. Время действия зависит от длины серии:\n 1 прием: 128 ед. урона за 8 сек.\n 2 приема: 185 ед. урона за 10 сек.\n 3 приема: 252 ед. урона за 12 сек.\n 4 приема: 329 ед. урона за 14 сек.\n 5 приемов: 416 ед. урона за 16 сек."},
[11274] = {name = "Рваная рана", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий периодический урон. Урон увеличивается за счет силы атаки. Время действия зависит от длины серии:\n 1 прием: 176 ед. урона за 8 сек.\n 2 приема: 255 ед. урона за 10 сек.\n 3 приема: 348 ед. урона за 12 сек.\n 4 приема: 455 ед. урона за 14 сек.\n 5 приемов: 576 ед. урона за 16 сек."},
[11275] = {name = "Рваная рана", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий периодический урон. Урон увеличивается за счет силы атаки. Время действия зависит от длины серии:\n 1 прием: 272 ед. урона за 8 сек.\n 2 приема: 380 ед. урона за 10 сек.\n 3 приема: 504 ед. урона за 12 сек.\n 4 приема: 644 ед. урона за 14 сек.\n 5 приемов: 800 ед. урона за 16 сек."},
[11276] = {name = "Рваная рана", additional_info = nil},
