[11297] = {name = "Ошеломление", additional_info = "{Энергия: 65} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Незаметность\n[q]Парализация цели на 45 сек. Прием производится из состояния незаметности и эффективен только против гуманоидов вне боя. Любой урон выводит цель из этого состояния. Единовременно может быть применен к 1 целям."},
[11298] = {name = "Ошеломление", additional_info = nil},
[11299] = {name = "Потрошение", additional_info = "{Энергия: 35} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий урон в зависимости от длины серии и силы атаки:\n 1 прием: 144-212 ед. урона\n 2 приема: 254-322 ед. урона\n 3 приема: 364-432 ед. урона\n 4 приема: 474-542 ед. урона\n 5 приемов: 584-652 ед. урона."},
[11300] = {name = "Потрошение", additional_info = "{Энергия: 35} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, наносящий урон в зависимости от длины серии и силы атаки:\n 1 прием: 199-295 ед. урона\n 2 приема: 350-446 ед. урона\n 3 приема: 501-597 ед. урона\n 4 приема: 652-748 ед. урона\n 5 приемов: 803-899 ед. урона."},
