[11355] = {name = "Смертельный яд III", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 80 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 90 раз.\n(Вероятность срабатывания: 30%)"},
[11356] = {name = "Смертельный яд IV", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 30% отравляет противника ядом, наносящим 108 ед. урона от сил природы в течение 12 сек. На одной цели эффект может быть применен до 5 раз. Яд может сработать 105 раз.\n(Вероятность срабатывания: 30%)"},
