[11399] = {name = "Дурманящий яд III", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 20% отравляет противника ядом, который увеличивает время применения заклинаний на 60% в течение 14 сек. Яд может сработать 100 раз.\n(Вероятность срабатывания: 20%)"},
[11400] = {name = "Дурманящий яд III", additional_info = "Применение: 3 сек\nИнгредиенты:\nПыль обветшания (2), Субстанция агонии (2), Хрустальная колба\n[q]Смазать оружие ядом, действующим в течение 30 мин.\n Каждый удар с вероятностью 20% отравляет противника ядом, который увеличивает время применения заклинаний на 60% в течение 14 сек. Яд может сработать 100 раз."},
