[11426] = {name = "Ледяная преграда", additional_info = "Мана: 305\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Вас мгновенно окружает защитный барьер, поглощающий 455 ед. урона. Время действия – 1 мин. Все время существования щита ваши заклинания невозможно прервать."},
[11427] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\n[q]Нанесение противнику и его ближайшим союзникам обычного урона плюс 10 ед. Распространяется на 3 целей и меньше."},
[11428] = {name = "Нокдаун", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 5 сек}\n[q]Нанесение противнику 60 в 80 ед. урона и оглушение его на 2 сек."},
[11430] = {name = "Сокрушение", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Сбивание врага с ног, нанесение ему физического урона и оглушение на 2 сек."},
[11431] = {name = "Целительное прикосновение", additional_info = "{Мана: 180} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Взывание к силам Природы ради исцеления союзника."},
[11433] = {name = "Смерть и разложение", additional_info = "{Мана: 320} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Смерть и порча обрушиваются на всех противников на избранной территории, нанося урон от темной магии в течение 10 сек."},
[11434] = {name = "Гонг из Зул'Фаррака - гонг", additional_info = nil},
[11435] = {name = "[q2]Создание молота Зул'Фаррака", additional_info = "Применение: 3 сек\n[q]Используйте у алтаря Джинта'Алора для создания молота Зул'Фаррака."},
[11436] = {name = "Замедление", additional_info = "{Мана: 140} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Увеличение времени между атаками противника на 54%, замедление передвижения на 60% в течение 10 сек."},
[11437] = {name = "Открытие сундука", additional_info = nil},
[11438] = {name = "Соединение фрагментов карты", additional_info = "Применение: 2 сек\nИнгредиенты:\nВерхняя часть карты , Нижняя часть карты , Средняя часть карты\n[q]Соединение нижнего, среднего и верхнего фрагментов карты."},
[11440] = {name = "Задание - Взорвать пиратский корабль", additional_info = nil},
[11441] = {name = "Иссушающее прикосновение", additional_info = "[q]Шанс прочитать заклинание \"Иссушающее прикосновение\" после получения урона в ближнем бою.\n(Вероятность срабатывания: 5%)"},
[11442] = {name = "Иссушающее прикосновение", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику 2 ед. урона от темной магии раз в 10 сек. и похищение у него 2 ед. маны раз в 10 сек. Время действия – 3 мин."},
[11443] = {name = "Увечье", additional_info = "{8% от базовой мана} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Увеличение интервала между вражескими атаками на 100%, снижение скорости передвижения на 50% и силы на 50%. Время действия – 15 сек."},
[11444] = {name = "Сковывание нежити", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Сковывает указанную цель-нежить не более чем на 20 сек. Цель становится неспособной передвигаться, атаковать и применять заклинания. Любой нанесенный цели урон снимает эффект. Одновременно может быть скована только одна цель."},
[11445] = {name = "Костяной доспех", additional_info = "10% от базовой мана\n{Мгновенное действие} {Восстановление: 4 сек}\n[q]Поглощение 278 в 322 ед. урона в течение 1 мин. Пока доспех существует, его владельцу нельзя помешать творить заклинания, нападая с оружием."},
[11446] = {name = "Контроль над разумом", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Позволяет управлять гуманоидом не выше 72 уровня, но каждые 5 секунд появляется вероятность, что цель выйдет из под контроля. Время действия – 5 мин."},
[11447] = {name = "Эликсир хождения по воде", additional_info = "Применение: 3 сек\nИнгредиенты:\nМасло черноротика , Жизнекорень , Освинцованная колба"},
[11448] = {name = "Сильное зелье маны", additional_info = "Применение: 3 сек\nИнгредиенты:\nКадгаров ус , Златошип , Освинцованная колба\nТребуется\n[q2]Использование: Восполнение 700 в 900 ед. маны. (2 Мин Восстановление)"},
[11449] = {name = "Эликсир Ловкости", additional_info = "Применение: 3 сек\nИнгредиенты:\nУдавник , Златошип , Освинцованная колба\nТребуется\n[q2]Использование: Повышение ловкости на 15 ед. на 1 ч. (3 Сек Восстановление)"},
[11450] = {name = "Сильный эликсир защиты", additional_info = "Применение: 3 сек\nИнгредиенты:\nДикий сталецвет , Златошип , Освинцованная колба\nТребуется\n[q2]Использование: Усиление брони на 250 ед. на 1 ч. (3 Сек Восстановление)"},
[11451] = {name = "Воспламеняющая смесь", additional_info = "Применение: 3 сек\nИнгредиенты:\nОгнецвет , Златошип , Хрустальная колба\nТребуется\n[q2]Использование: Нанесение 50 ед. урона от огня любым противникам в радиусе 5 м вокруг заклинателя раз в 3 сек. в течение 15 сек. (3 Сек Восстановление)"},
[11452] = {name = "Приводящее в сознание зелье", additional_info = "Применение: 3 сек\nИнгредиенты:\nПервородная земля , Златошип , Хрустальная колба\nТребуется\n[q2]Использование: Снятие 1 эффекта от магии, проклятия, отравления или болезни раз в 5сек. в течение 30 сек. (2 Мин Восстановление)"},
[11453] = {name = "Зелье защиты от магии", additional_info = "Применение: 3 сек\nИнгредиенты:\nКадгаров ус , Лиловый лотос , Хрустальная колба\nТребуется\n[q2]Использование: Повышение сопротивления всем школам магии на 50 ед. на 3 мин. (2 Мин Восстановление)"},
[11454] = {name = "Инкрустированный мифриловый цилиндр", additional_info = "Применение: 3 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nМифриловый слиток (5), Золотой слиток , Слиток истинного серебра\n[q]\"Используется инженерами гномов для усиления их изделий.\""},
[11456] = {name = "Гоблинское ракетное топливо", additional_info = "Применение: 3 сек\nИнгредиенты:\nОгнецвет , Крепленый ром , Освинцованная колба\n[q]\"Используется гоблинскими Ижненерами, чтобы запускать свои изделия.\""},
[11457] = {name = "Мощное лечебное зелье", additional_info = "Применение: 3 сек\nИнгредиенты:\nСолнечник , Кадгаров ус , Хрустальная колба\nТребуется\n[q2]Использование: Восполнение 700 в 900 ед. здоровья. (2 Мин Восстановление)"},
[11458] = {name = "Виноградное зелье", additional_info = "Применение: 3 сек\nИнгредиенты:\nДикая лоза , Лиловый лотос , Хрустальная колба\nЗелье из дикой лозы\nТребуется\n[q2]Использование: Восполнение 1 в 1500 ед. здоровья и 1 в 1500 ед. маны. (2 Мин Восстановление)"},
[11459] = {name = "Философский камень", additional_info = "Применение: 30 сек\nИнгредиенты:\nЖелезный слиток (4), Черный купорос , Лиловый лотос (4), Огнецвет (4)\nСтановится персональным при поднятии\n[q]\"Требуется для\""},
[11460] = {name = "Эликсир обнаружения Нежити", additional_info = "Применение: 3 сек\nИнгредиенты:\nСлезы Артаса , Хрустальная колба\nТребуется\n[q2]Использование: Отображение на карте местонахождения ближайшей нежити в течение 1 ч. (3 Сек Восстановление)"},
[11461] = {name = "Чародейский эликсир", additional_info = "Применение: 3 сек\nИнгредиенты:\nПастушья сумка , Златошип , Хрустальная колба\nТребуется\n[q2]Использование: Увеличение урона от заклинаний до 20 ед. на 30 мин. (3 Сек Восстановление)"},
