[11465] = {name = "Сильный эликсир интеллекта", additional_info = "Применение: 3 сек\nИнгредиенты:\nПастушья сумка , Кадгаров ус , Хрустальная колба\nТребуется\n[q2]Использование: Повышение интеллекта и духа на 25 ед. на 1 ч. (3 Сек Восстановление)"},
[11466] = {name = "Дар Артаса", additional_info = "Применение: 3 сек\nИнгредиенты:\nСлезы Артаса , Пастушья сумка , Хрустальная колба\nЭликсир &quot;Дар Артаса&quot;\nТребуется\n[q2]Использование: Повышение сопротивления темной магии на 10 Если противник наносит удар выпившему эликсир, атакующего с вероятностью 30% поражает болезнь, которая повышает наносимый ему урон на 8 ед. в течение 3 мин. Время действия – 30 мин. (Вероятность срабатывания: 30%) (3 Сек Восстановление)"},
[11467] = {name = "Сильный эликсир ловкости", additional_info = "Применение: 3 сек\nИнгредиенты:\nСолнечник , Златошип , Хрустальная колба\nТребуется\n[q2]Использование: Повышение ловкости на 25 ед. на 1 ч. (3 Сек Восстановление)\nДобывается с: Объездчик нетопырей Пеле'кейки"},
[11468] = {name = "Эликсир Снозрения", additional_info = "Применение: 3 сек\nИнгредиенты:\nЛиловый лотос (3), Хрустальная колба\nТребуется\n[q2]Использование: Возможность осмотреть местности, которые слишком опасны, чтобы посещать их во плоти. (3 Сек Восстановление)"},
