[11640] = {name = "Обновление", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nМгновенное действие\n[q]Исцеление союзника раз в 3 сек. в течение 15 сек."},
[11641] = {name = "Сглаз", additional_info = "{Мана: 120} {Радиус действия: 20 м}\nМгновенное действие\n[q]Превращение противника в лягушку. Он теряет спосбность атаковать или творить заклинания на 10 сек."},
