[11643] = {name = "[q2]Золотые чешуйчатые рукавицы", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСтальной слиток (10), Золотой слиток (4), Тяжелый шлифовальный камень (4), Цитрин\n[q2]Золотые чешуйчатые рукавицы\nСтановится персональным при надевании\nКисти рук Кольчуга\nБроня: 146\n+11 к силе\n+4 к духу\nПрочность: 35 / 35\nТребуется"},
[11644] = {name = "Чертеж: золотые чешуйчатые рукавицы", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению золотых чешуйчатых рукавиц."},
[11645] = {name = "Вызов Мулгорского заступника", additional_info = nil},
[11647] = {name = "Слово силы: Щит", additional_info = "{Мана: 100} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 4 сек}\n[q]Защищает заклинателя щитом, действующим в течение 30 сек. и поглощающим до 801 ед. физического или магического урона. Пока действует щит, физические атаки не прервут чтения заклинаний."},
[11649] = {name = "Обнаружение невидимости", additional_info = "Мана: 90\nМгновенное действие\n[q]Позволяет игроку обнаруживать невидимость."},
[11650] = {name = "Удар головой", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Оглушение цели на 3 сек."},
[11654] = {name = "[q4]Вызов Суль-траза", additional_info = "Применение: 10 сек\nИнгредиенты:\nСанг'траз Отражатель\n[q]Соединение Джанг'траза и Санг'траза для создания могучего меча Суль-траза."},
[11657] = {name = "Джанг'траз", additional_info = "Мгновенное действие\n[q]Защита носящего от физического атак, в течение 20 сек поглощающая 55 в 85 ед. урона."},
