[11711] = {name = "Проклятие агонии", additional_info = "{Мана: 130} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклинает цель, вводит ее в состояние агонии и наносит ей в течение 24 сек. постепенно нарастающий урон. Общая величина урона - 504. Каждый чернокнижник может наложить только одно заклинание проклятия на каждую цель."},
[11712] = {name = "Проклятие агонии", additional_info = "{Мана: 170} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклинает цель, вводит ее в состояние агонии и наносит ей в течение 24 сек. постепенно нарастающий урон. Общая величина урона - 780. Каждый чернокнижник может наложить только одно заклинание проклятия на каждую цель."},
[11713] = {name = "Проклятие агонии", additional_info = "{Мана: 215} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклинает цель, вводит ее в состояние агонии и наносит ей в течение 24 сек. постепенно нарастающий урон. Общая величина урона - 1044. Каждый чернокнижник может наложить только одно заклинание проклятия на каждую цель."},
