[11715] = {name = "Проклятие агонии", additional_info = nil},
[11716] = {name = "Проклятие агонии", additional_info = nil},
[11717] = {name = "Проклятие безрассудства", additional_info = "{Мана: 115} {Радиус действия: 30 м}\nМгновенное действие\n[q]Проклятие цели, увеличивающее силу ее атаку ближнего боя на 90 ед., но ослабляющее броню на 640 ед. на 2 мин. Проклятые таким образом противники станут невосприимчивы к страху и ужасу и не убегут с поля боя. Один чернокнижник может наложить проклятье только на одну цель."},
[11718] = {name = "Проклятие безрассудства", additional_info = nil},
[11719] = {name = "Проклятие косноязычия", additional_info = "{Мана: 110} {Радиус действия: 30 м}\nМгновенное действие\n[q]Принуждение цели разговаривать на демоническом языке, что увеличивает длительность применения ею всех заклинаний на 60%. Один чернокнижник может наложить проклятие только на одну цель. Время действия – 30 сек."},
[11720] = {name = "Проклятие косноязычия", additional_info = nil},
[11721] = {name = "Проклятие стихий", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nМгновенное действие\n[q]Уменьшение сопротивления огню и льду на 60 ед. на 5 мин. и увеличение получаемого урона от огня и льда на 8%. Один чернокнижник может наложить проклятие только на одну цель."},
[11722] = {name = "Проклятие стихий", additional_info = "{Мана: 200} {Радиус действия: 30 м}\nМгновенное действие\n[q]Уменьшение сопротивления огню и льду на 75 ед. на 5 мин. и увеличение получаемого урона от огня и льда на 10%. Один чернокнижник может наложить проклятие только на одну цель."},
[11723] = {name = "Проклятие стихий", additional_info = nil},
[11724] = {name = "Проклятие стихий", additional_info = nil},
[11725] = {name = "Порабощение демона", additional_info = "{Мана: 500} {Радиус действия: 30 м}\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Порабощение демона уровнем не выше 59. Промежуток между атаками пленного демона увеличивается на 40%, а скорость применения заклинаний уменьшается на 30%. Продолжительность – до 5 мин. При регулярном порабощении одного и того же демона управлять им с каждым разом становится все труднее."},
[11726] = {name = "Порабощение демона", additional_info = "{Мана: 700} {Радиус действия: 30 м}\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Порабощение демона уровнем не выше 64. Промежуток между атаками пленного демона увеличивается на 40%, а скорость применения заклинаний уменьшается на 30%. Продолжительность – до 5 мин. При регулярном порабощении одного и того же демона управлять им с каждым разом становится все труднее."},
[11727] = {name = "Порабощение демона", additional_info = nil},
[11728] = {name = "Порабощение демона", additional_info = nil},
[11729] = {name = "Создание большого камня здоровья", additional_info = "Мана: 750\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает большой камень здоровья, способный восстановить 800 ед. здоровья.\n\n Созданные камни исчезают при выходе из игры на 15 мин. и более."},
[11730] = {name = "Создание крупного камня здоровья", additional_info = "Мана: 1120\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает крупный камень здоровья, способный восстановить 1200 ед. здоровья.\n\n Созданные камни исчезают при выходе из игры на 15 мин. и более."},
