[11923] = {name = "[q3]Перековка клинка героев", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСломанный Клинок героев , Стальной слиток (4), Сильный плавень (4), Первородный огонь (2), Тяжелый шлифовальный камень (2)\n[q]Перековка клинка, необходимая перед использованием. Процесс требует расхода 4 слитков стали, 4 ед. сильный флюс, 2 элементного огня и 2 тяжелых шлифовальных камня."},
[11939] = {name = "Призыв беса", additional_info = "Мгновенное действие\n[q]Призыв беса, который будет помогать заклинателю в бою до тех пор, пока не будет освобожден."},
[11958] = {name = "Ледяная глыба", additional_info = "Мана: 15\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Вы оказываетесь в середине ледяной глыбы, которая защищает вас от всех физических атак и заклинаний на 10 сек., но в это время вы не можете никого атаковать, двигаться или применять заклинания."},
[11959] = {name = "Процесс отравления", additional_info = "(Вероятность срабатывания: 15%)"},
