[11961] = {name = "Проклятие Молота Ужаса", additional_info = "(Вероятность срабатывания: 10%)"},
[11962] = {name = "Жертвенный огонь", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Заклинание обжигает противника и наносит дополнительный урон от огня каждые 3 сек. в течение 21 сек."},
[11963] = {name = "Ослабление", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Сила противника снижена на 25, выносливости - на 15 на 2 мин."},
