[11968] = {name = "Огненный щит", additional_info = "Мгновенное действие\n[q]Нанесение 1 ед. урона от огня ближайшим противникам."},
[11969] = {name = "Кольцо огня", additional_info = "Мана: 95\nМгновенное действие\nИнструменты: Тотем огня\n[q]Нанесение урона от огня ближайшим противникам."},
[11970] = {name = "Кольцо огня", additional_info = "Мгновенное действие\nИнструменты: Тотем огня\n[q]Нанесение урона от огня ближайшим противникам."},
[11971] = {name = "Раскол брони", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Проламывание вражеской брони и ослабление ее на 0 ед. при каждом расколе. Можно использовать до 5 раз подряд. Длительность - 30 сек."},
[11972] = {name = "Удар щитом", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит противнику сильный удар щитом. Противник получает физический урон и прерывает чтение заклинания на 8 сек."},
[11974] = {name = "Слово силы: Щит", additional_info = "{Мана: 110} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника щитом, действующим в течение 30 сек. и до 137 ед. физического или магического урона. Пока действует щит, физические атаки не прервут чтения заклинаний."},
[11975] = {name = "Чародейский взрыв", additional_info = "Мана: 120\nПрименение: 1.5 сек\n[q]Создание магической взрывной волны, наносящей противникам урон от тайной магии."},
[11976] = {name = "Разящий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Нанесение врагу урона от оружия плюс 5 ед."},
[11977] = {name = "Кровопускание", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику физического урона раз в 3 сек. в течение 15 сек."},
[11978] = {name = "Пинок", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику 2 ед. урона и прерывание чтения заклинания на 6 сек."},
[11980] = {name = "Проклятие слабости", additional_info = "{Мана: 105} {Радиус действия: 30 м}\nМгновенное действие\n[q]Снижение всего наносимого противником физического урона на 1 ед. в течение 2 мин. Один чернокнижник может наложить проклятие только на одну цель."},
[11981] = {name = "Сожжение маны", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Молния, сжигающая ману. На каждую единицу маны, сожженную молнией, жертва получает 0.5 ед. урона."},
[11983] = {name = "Струя пара", additional_info = "Мгновенное действие\n[q]Нанесение 12 ед. урона от сил природы находящимся поблизости противникам. Их вероятность нанести удар снижается на 30% в течение 10 сек."},
[11984] = {name = "Жертвенный огонь", additional_info = "(Вероятность срабатывания: 10%)"},
[11985] = {name = "Огненный шар", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."},
[11986] = {name = "Волна исцеления", additional_info = "{Мана: 145} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Взывание к силам Природы ради исцеления союзника."},
[11988] = {name = "Град огненных шаров", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Нанесение урона от огня ближайшим противникам."},
[11989] = {name = "Град огненных шаров", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Нанесение урона от огня ближайшим противникам."},
[11990] = {name = "Огненный ливень", additional_info = "{Мана: 15} {Радиус действия: 30 м}\nНаправляемое (Применение: 9 сек)\n[q]Призывание лавового дождя, обжигающего всех противников на выбранном участке с 3 ед. урона от огня раз в 3 сек. в течение 9 сек."},
[11992] = {name = "Обнаружение газриллия", additional_info = "[q]На карте отображаются близлежащие предметы из газриллия."},
[11993] = {name = "Сбор трав", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Возможность находить и собирать более сложные травы до тех пор, пока навык не достигнет значения 300."},
