[12019] = {name = "Увеличенный урон от заклинаний 18 случайный", additional_info = "[q]Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 1 в 35 ед."},
[12020] = {name = "Зов могилы", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение 10 ед. урона от темной магии находящимся рядом противникам через 60 сек."},
[12021] = {name = "Сосредоточение внимания", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Заклинание заставляет противника сосредоточить внимание за заклинателе и увеличивает скорость атаки заклинания на 50% в течение 10 сек. Пока цель сосредоточена на заклинателе, она с большой неохотой атакует кого-либо еще."},
[12022] = {name = "Адмиральская шляпа", additional_info = "Мгновенное действие\n[q]Повышение выносливости участников группы, находящихся в радиусе 30 м. на 10 ед."},
[12023] = {name = "Сеть", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Набрасывание на противника сети, обездвиживая его на 5 сек."},
[12024] = {name = "Сеть", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Обездвиживание противника на 5 сек."},
[12038] = {name = "Черный мор", additional_info = nil},
