[12040] = {name = "Щит Тени", additional_info = "{Мана: 10} {Радиус действия: 40 м}\nМгновенное действие\n[q]Щит, сотканный из темной магии. Существует 30 сек., поглощает до 200 физического или магического урона, в ближнем бою наносит 10 ед. урона атакующим."},
[12042] = {name = "Мощь тайной магии", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Повышение урона от заклинаний на 30% за счет повышения расхода на них маны на 30%. Время действия – 15 сек."},
[12043] = {name = "Присутствие разума", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Мгновенное применение следующего магического заклинания, обычное время применения которого ниже 10 сек."},
