[12287] = {name = "Улучшенный удар грома", additional_info = "[q]Снижает расход ярости на способность \"Удар грома\" на 1 ед."},
[12288] = {name = "Улучшенная зуботычина", additional_info = "[q]Повышение длительности способности \"Взбучка\" на 1 сек. и вероятность впадения противника в оцепенение - 25%."},
[12289] = {name = "Улучшенный порез сухожилия", additional_info = "[q]Есть вероятность 5%, что способность \"Подрезать сухожилия\" обездвижит цель на 5 сек.\n(Вероятность срабатывания: 5%)"},
[12290] = {name = "Улучшенное превосходство", additional_info = "[q]Повышает вероятность критического удара при применении \"Превосходства\" на 25%."},
[12292] = {name = "Размашистые удары", additional_info = "Ярость: 30\n{Мгновенное действие} {Восстановление: 30 сек}\nТребуется: Боевая стойка\n[q]5 ваших следующих атаки ближнего боя попадают еще по одному находящемуся рядом врагу."},
[12294] = {name = "Смертельный удар", additional_info = "{Ярость: 30} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\nТребуется: Оружие ближнего боя\n[q]Жестокий удар, наносящий урон от оружия плюс 85 ед. и наносящий цели серьезную рану, снижающую эффективность любого лечения на 50% в течение 10 сек."},
[12295] = {name = "Тактическое превосходство", additional_info = "[q]Восполнение до 5 ед. ярости при смене стойки."},
[12296] = {name = "Управление злостью", additional_info = "[q]Увеличивает время, по истечении которого у вас начинает убывать ярость, на 30%."},
[12297] = {name = "Предчувствие", additional_info = "[q]Повышение навыка защиты на 2."},
[12298] = {name = "Специализация на щитах", additional_info = "[q]Повышает вероятность блокирования атаки на 1% и дает 20%-й шанс создать 1 ед. ярости при успешном блокировании.\n(Вероятность срабатывания: 20%)"},
[12299] = {name = "Крепость", additional_info = "[q]Увеличение на 2% эффективности усиления брони за счет носимой экипировки."},
[12300] = {name = "Железная воля", additional_info = "[q]Увеличивает вероятность сопротивления эффектам оглушения и подчинения на 3%."},
[12301] = {name = "Улучшенная кровавая ярость", additional_info = "[q]Увеличение на 2 ед. количества ярости, создаваемого при использовании способности \"Кровавая ярость\"."},
[12302] = {name = "Улучшенная провокация", additional_info = "[q]Сокращение времени восстановления способности \"Провокация\" на 1 сек."},
[12303] = {name = "Неукротимость", additional_info = "Требуется: Оборонительная стойка\n[q]Повышение угрозы от ваших атак на 3% в защитной стойке."},
[12304] = {name = "Набор для рисования", additional_info = "Радиус действия: 5 м\nПрименение: 7 сек\n[q]Используется для начертания рун в руинах Эльдарата."},
[12307] = {name = "Улучшенный блок щитом", additional_info = "[q]Способность \"Блок щитом\" блокирует дополнительную атаку; длительность способности увеличивается на 1 сек."},
