[12310] = {name = "Выносливость в бою", additional_info = "[q]Восполнение здоровья в бою со скоростью, равной 10% скорости восполнения здоровья вне боя."},
[12311] = {name = "Улучшенный удар щитом", additional_info = "[q]Когда вы наносите \"Удар щитом\", с вероятностью 50% ваш противник потеряет способность заклинания на 3 сек.\n(Вероятность срабатывания: 50%)"},
[12312] = {name = "Улучшенная глухая оборона", additional_info = "[q]Увеличение длительности эффекта от способности \"Стена щитов\" на 3 сек."},
[12313] = {name = "Улучшенное разоружение", additional_info = "[q]Увеличение длительности способности \"Разоружение\" на 1 сек."},
[12317] = {name = "Исступление", additional_info = "[q]Увеличивает урон в ближнем бою на 5% на 12 сек. Максимум ударов с увеличенным уроном – 12. Действует после получения критического удара."},
[12318] = {name = "Улучшенный боевой крик", additional_info = "[q]Увеличивает силу атаки ближнего боя, прибавляемую способностью \"Боевой крик\" на 5%."},
[12319] = {name = "Шквал", additional_info = "[q]Увеличение на 10% скорости атаки для последующих 3 выпадов после нанесения критического урона в ближнем бою."},
[12320] = {name = "Безжалостность", additional_info = "Требуется: Оружие ближнего боя\n[q]Увеличивает вероятность нанести критический удар оружием ближнего боя на 1%."},
[12321] = {name = "Луженая глотка", additional_info = "[q][ S03 – настройка и отмена пассивных эффектов – воин : Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 10%. Продлевает время действия \"Боевого крика\" на 10%, а \"Деморализующего крика\" – на 10%. Сокращает затраты ярости на \"Боевой крик\" на 20% / Увеличивает область действия и время действия \"Боевого крика\" и \"Деморализующего крика\" на 10%.]"},
[12322] = {name = "Необузданный гнев", additional_info = "Требуется: Оружие ближнего боя\n[q]С вероятностью 8% вы можете получить дополнительную единицу ярости при нанесении урона оружием в ближнем бою.\n(Вероятность срабатывания: 8%)"},
[12323] = {name = "Пронзительный вой", additional_info = "Ярость: 10\nМгновенное действие\n[q]Снижает скорость передвижения всех врагов рядом с воином на 50% в течение 6 сек."},
[12324] = {name = "Улучшенный деморализующий крик", additional_info = "[q]Увеличивает количество снижаемой силы атаки ближнего боя при применении способности \"Деморализующий крик\" на 8%."},
[12325] = {name = "Улучшенная внутренняя ярость", additional_info = "[q]Сокращение времени восстановления способности \"Внутренняя ярость\" на 40 сек."},
[12327] = {name = "Улучшенный вызывающий крик", additional_info = "[q]Сокращение времени восстановления вашей способности \"Вызывающий крик\" на 2 мин."},
[12328] = {name = "Инстинкт смерти", additional_info = "Ярость: 10\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Пр ииспользовании увеличивает ваш физический урон на 20%, уменьшает броню и все сопротивления на 20% и дает невосприимчивость к эффекту страха. Длительность – 30 сек."},
[12329] = {name = "Улучшенный рассекающий удар", additional_info = "[q]Увеличение дополнительного урона, наносимого вашей способностью \"Рассекающий удар\", на 40%."},
[12330] = {name = "Улучшенное сокрушение", additional_info = "[q]Уменьшает время применения способности \"Сокрушение\" на 0.2 сек."},
