[12538] = {name = "Хищный коготь", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Похищение 93 в 107 ед. здоровья у противника и передача его заклинателю."},
[12539] = {name = "Вурдалачий гной", additional_info = "(Вероятность срабатывания: 5%)"},
[12540] = {name = "Парализующий удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику 20 ед. урона и оглушение его на время до 4 сек. Вы автоматически прекращаете атаковать цель. Цель должна быть повернута к вам лицом. Любой полученный урон снимет эффект."},
