[12542] = {name = "Страх", additional_info = "Радиус действия: 20 м\nПрименение: 1.5 сек\n[q]Повержение противника в ужас, заставляющий его бежать в течение 4 сек. Количество одновременно напуганных противников - 1."},
[12543] = {name = "Взрывоопасная бомба", additional_info = "Радиус действия: 15 м\nПрименение: 1 сек\n[q]Нанесение 255 в 345 ед. урона от огня и оглушение целей в радиусе 3 м на 3 сек. Любой урон прекращает действие заклинания."},
[12544] = {name = "Морозный доспех", additional_info = "Мана: 10\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Обволакивает заклинателя толстым слоем льда на 30 мин. Лед усиливает броню на 12 ед., замедляет скорость передвижения противников, атакующих в ближнем бою на 25%, и увеличивает время между их атаками на 30%."},
[12545] = {name = "Бич Злобы", additional_info = nil},
[12546] = {name = "Бич Злобы", additional_info = "(Вероятность срабатывания: 10%)"},
[12548] = {name = "Ледяной шок", additional_info = "{Мана: 115} {Радиус действия: 20 м}\nМгновенное действие\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 8 сек."},
[12549] = {name = "Раздвоенная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Нанесение урона от сил природы противникам, находящимся в конусе перед заклинателем."},
[12550] = {name = "Щит молний", additional_info = "{Мана: 5} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]3 шаровых молний, окружающих заклинателя. 50% вероятность нанести 2 ед. урона противникам, атакующим в ближнем или дальнем бою. Каждый раз, как щит срабатывает, одна из молний рассеивается. Таким образом, щит перестает действовать через 10 мин., либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[12551] = {name = "Ледяной выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\nИнгредиенты:\nМорозный фиал\n[q]Вы стреляете в противника, нанося ему 0 ед. дополнительного урона от магии льда, замедляя скорость его передвижения на 60% в течение 10 сек."},
