[12872] = {name = "Улучшенный ожог", additional_info = "[q]Повышение до 66% вероятности сделать цель уязвимой для урона от огня при применении на ней заклинания \"Ожог\". В случае успеха цель в течение 30 сек получает на 3% больше урона от огня. Эффект может быть суммирован до 5 раз."},
[12873] = {name = "Улучшенный ожог", additional_info = "[q]Повышение до 100% вероятности сделать цель уязвимой для урона от огня при применении на ней заклинания \"Ожог\". В случае успеха цель в течение 30 сек получает на 3% больше урона от огня. Эффект может быть суммирован до 5 раз."},
