[12882] = {name = "Взмах крыла", additional_info = "Мгновенное действие\n[q]Поражение противников, находящихся в конусе перед заклинателем. Их отбрасывает назад."},
[12883] = {name = "Орлиный взор", additional_info = "Радиус действия: 100 м\nПрименение: 1 сек\n[q]Возможность смотреть далеко."},
[12884] = {name = "Кислотное дыхание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение 10 ед. урона от сил природы и дополнительно 2 ед. урона раз в 5 сек. противникам, находящимся в секторе перед заклинателем. Время действия – 45 сек."},
[12885] = {name = "Телепорт в Разелих", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Отправляет игрока на плато Разелиха."},
[12886] = {name = "Улучшенный вызывающий крик", additional_info = "[q]Сокращение времени восстановления вашей способности \"Вызывающий крик\" на 3 мин."},
[12887] = {name = "Сбивающий удар", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение обычного урона плюс 50 ед. противникам перед заклинателем и сбивание их с ног."},
[12888] = {name = "Насылание безумия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Вводит противника в состояние временного безумия, повышая его скорость атаки на 50% и скорость передвижения на 80%. При этом цель атакует своих союзников в течение 6 сек."},
[12889] = {name = "Проклятие косноязычия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Принуждение цели к разговору на демоническом языке, что увеличивает скорость применения всех заклинаний на 50%. Один чернокнижник может наложить проклятие только на одну цель. Длительность - 15 сек."},
[12890] = {name = "Глубокая дремота", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\nИнгредиенты:\nОсколок души\n[q]Усыпление противника на 15 сек., лишая его возможности действовать, но делая его неуязвимым."},
[12891] = {name = "Кислотное дыхание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение 10 ед. урона от сил природы и дополнительно 2 ед. урона раз в 5 сек. противникам, находящимся в секторе перед заклинателем. Время действия – 45 сек."},
[12894] = {name = "Рецепт: инкрустированный мифриловый цилиндр", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению инкрустированного мифрилового цилиндра."},
[12895] = {name = "Инкурстированный мифриловый цилиндр - эскиз", additional_info = "Применение: 25 сек\nИнгредиенты:\nЧистый пергамент , Инженерный краситель\nЧертеж: инкрустированный мифриловый цилиндр\nТребуетКузнечное дело\n(200)\n[q2]Использование: Обучение изготовлению инкрустированного мифрилового цилиндра."},
[12896] = {name = "Зловепрь", additional_info = nil},
[12897] = {name = "[q2]Гномьи очки", additional_info = "Применение: 45 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nОгненные очки , Мифриловая труба , Золотое силовое ядро (2), Настой колдунства (2), Толстая кожа (2)\n[q2]Гномьи очки\nСтановится персональным при поднятии\nГолова Ткань\nБроня: 45\n+9 к ловкости\n+9 к выносливости\n+9 к духу\nПрочность: 45 / 45\nТребуетИнженерное дело\n(210)"},
[12898] = {name = "Дымная аура - визуальное", additional_info = nil},
[12899] = {name = "Уменьшающий луч гномов", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая труба , Нестабильное пусковое устройство , Мифриловый слиток (4), Настой колдунства (4), Нефрит (2)\nСтановится персональным при надевании\nАксессуар\nТребуетИнженерное дело\n(205)\n[q2]Использование: Уменьшение цели и снижение силы ее атаки на 250 ед. По крайней мере, так обычно бывает... (5 Мин Восстановление)"},
[12900] = {name = "Передвижная сирена", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая труба , Нестабильное пусковое устройство , Мифриловый слиток (4)"},
[12901] = {name = "Выкройка: черная рубашка Щитолома", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению черной рубашки Щитолома."},
[12902] = {name = "Сетемет гномов", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая труба , Тенешелк (2), Плотная паутина (4), Твердое взрывчатое вещество (2), Мифриловый слиток (4)\nСтановится персональным при надевании\nАксессуар\nТребуетИнженерное дело\n(210)\n[q2]Использование: Цель запутывается в сети на 10 сек. Однако у этой сети много крючков, и порой она может зацепиться за одежду пользователя. (10 Мин Восстановление)"},
[12903] = {name = "[q2]Пояс гномов, хранящий от вреда", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМглистый пояс , Мифриловый слиток (4), Слиток истинного серебра (2), Нестабильное пусковое устройство , Аквамарин (2)\n[q2]Пояс гномов, хранящий от вреда\nСтановится персональным при надевании\nПояс Кожа\nБроня: 66\n+6 к выносливости\nПрочность: 30 / 30\nТребуетИнженерное дело\n(215)\n[q2]Использование: Защита силовым щитом, в течение 10 мин позволяющим поглотить 500 ед. урона. ВНИМАНИЕ: силовое поле может перегрузиться от удара, на время лишив носящего защиты. (Вероятность срабатывания: 5%) (1 Час Восстановление)"},
[12904] = {name = "Любительское радио гномов", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая обшивка , Мифриловый слиток (2), Гирохронатом , Нестабильное пусковое устройство"},
[12905] = {name = "[q2]Гномьи реактивные сапоги", additional_info = "Применение: 12.5 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nЧерные сапоги из магической ткани , Мифриловая труба (2), Толстая кожа (4), Твердое взрывчатое вещество (8), Гирохронатом (4)\n[q2]Гномьи реактивные сапоги\nСтановится персональным при надевании\nСтупни Ткань\nБроня: 41\nПрочность: 35 / 35\nТребуетИнженерное дело\n(225)\n[q2]Использование: Эти сапоги значительно увеличат скорость вашего бега на 20 сек. ВНИМАНИЕ! Источник энергии и гироскоп не всегда функционируют как полагается. (30 Мин Восстановление)"},
[12906] = {name = "Боевой цыпленок гномов", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая обшивка , Слиток истинного серебра (6), Мифриловый слиток (6), Инкрустированный мифриловый цилиндр (2), Золотое силовое ядро , Нефрит (2)\nСтановится персональным при поднятии\nАксессуар\nТребуетИнженерное дело\n(230)\n[q2]Использование: Создание боевого цыпленка, который будет сражаться на вашей стороне в течение 1.50 мин., либо пока не будет уничтожен. (30 Мин Восстановление)"},
[12907] = {name = "[q2]Гномья шапка контроля над разумом", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловый слиток (10), Слиток истинного серебра (4), Золотое силовое ядро , Звездный рубин (2), Магическая ткань (4)\n[q2]Гномья шапка контроля над разумом\nСтановится персональным при надевании\nГолова Ткань\nБроня: 50\n+14 к духу\nПрочность: 45 / 45\nТребуетИнженерное дело\n(215)\n[q2]Использование: Вступление в ментальное сражение с целью-гуманоидом в попытке получить над ней контроль. В случае успеха контроль над созданием длится 20 сек. (30 Мин Восстановление)"},
[12908] = {name = "Гоблинское драконье ружье", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая труба (2), Гоблинское ракетное топливо (4), Мифриловый слиток (6), Слиток истинного серебра (6), Нестабильное пусковое устройство\nСтановится персональным при поднятии\nАксессуар\n[q2]Использование: Нанесение 61 в 69 ед. урона от огня в течение 10 сек. всем целям в конусе поражения впереди инженера, использующего это оружие. Если оно, конечно, не взорвется... (5 Мин Восстановление)"},
