[13234] = {name = "Пояс предотвращения урона", additional_info = "Мгновенное действие\n[q]Защита силовым щитом, в течение 10 мин позволяющим поглотить 500 ед. урона. ВНИМАНИЕ: силовое поле может перегрузиться от удара, на время лишив носящего защиты.\n(Вероятность срабатывания: 5%)"},
[13235] = {name = "Разрушение силового поля", additional_info = nil},
[13236] = {name = "Направление энергии сил природы", additional_info = nil},
[13237] = {name = "Гоблинская мортира", additional_info = "Радиус действия: 10 - 40 м\nПрименение: 1 сек\n[q]Нанесение 383 в 517 ед. урона от огня и оглушение целей в радиусе 5 м. на 3 сек."},
[13238] = {name = "Гоблинская мортира", additional_info = "Мгновенное действие\n[q]Нанесение 383 в 517 ед. урона от огня и нанесение 0.4 ед. урона в течение 3 сек. целям в радиусе 10 метров."},
[13239] = {name = "Многократный взрыв", additional_info = "Мгновенное действие\nИнгредиенты:\nТвердое взрывчатое вещество (2)"},
[13240] = {name = "Орудие: перезаряжено", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nГоблинская мортира , Мифриловый слиток , Твердое взрывчатое вещество (3)\n[q]Перезарядка пустой гоблинской мортиры.\nГоблинская мортира\nСтановится персональным при надевании\nАксессуар\nТребуетИнженерное дело\n(205)\n[q2]Использование: Нанесение 383 в 517 ед. урона от огня и оглушение целей в радиусе 5 м. на 3 сек. (10 Мин Восстановление)\n6 зарядов"},
[13241] = {name = "Гоблинский саперный заряд", additional_info = "Мгновенное действие\n[q]При инициации происходит взрыв, наносящий 450 в 750 ед. урона от огня всем ближайшим противникам и 375 в 625 ед. урона вам."},
[13258] = {name = "Вызов гоблинской бомбы", additional_info = "{Применение: 0.25 сек} {Восстановление: 30 мин}\n[q]Создает самоходную бомбу, подрывающую ближайшего противника, нанося урон от огня в размере 315 в 385."},
[13259] = {name = "Взрыв", additional_info = nil},
[13260] = {name = "Питомец: бомба", additional_info = nil},
[13261] = {name = "Взрыв из-за неисправности", additional_info = nil},
[13262] = {name = "Разрушение чар", additional_info = "Применение: 3 сек\n[q]Извлечение магических элементов из оружия, доспехов и щитов как минимум высокого качества (зеленый цвет названия). При этом предмет УНИЧТОЖАЕТСЯ безвозвратно."},
[13278] = {name = "Смертоносный луч гномов", additional_info = "Радиус действия: 20 м\nНаправляемое (Применение: 4 сек)\n[q]Устройство постепенно заряжается, используя вашу жизненную силу, а потом выстреливает во врага лучом энергии."},
[13279] = {name = "Смертоносный луч гномов", additional_info = nil},
[13280] = {name = "Смертоносный луч гномов", additional_info = nil},
[13281] = {name = "Земной шок", additional_info = "{Мана: 130} {Радиус действия: 20 м}\nМгновенное действие\n[q]Противника бьет ударной волной с нанесением урона от сил природы и лишением его возможности наложения заклинаний на 2 сек."},
[13298] = {name = "Яд", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение урона от сил природы раз в 3 сек. в течение 30 сек."},
[13299] = {name = "Процесс отравления", additional_info = "(Вероятность срабатывания: 15%)"},
[13318] = {name = "Кровопускание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит цели кровоточащую рану, из-за которой она теряет 100 ед. здоровья за 30 сек."},
[13319] = {name = "Неисправность", additional_info = nil},
[13320] = {name = "Неисправность", additional_info = "(Вероятность срабатывания: 10%)"},
[13321] = {name = "Сожжение маны", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Молния, сжигающая ману. На каждую единицу маны, сожженную молнией, жертва получает 0.5 ед. урона."},
[13322] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 2 сек."},
[13323] = {name = "Превращение", additional_info = "{10% от базовой мана} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Превращает противника в овцу. Он вынужден бродить вокруг в течение 20 сек. Овца не может атаковать или применять заклинания, но быстро восстанавливает здоровье и ману. Любой нанесенный урон прекратит действие заклинания. Одновременно заклинание превращения можно наложить только на одну цель. Действует только на животных, драконов, великанов, гуманоидов и фауну."},
[13325] = {name = "Вызывание передатчика", additional_info = "Мгновенное действие"},
[13326] = {name = "Чародейский интеллект", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышение интеллекта союзника на 10 ед. на 30 мин."},
[13327] = {name = "Безрассудная атака", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Бросается к противнику, выводя его из строя на 30 сек. Вы также падаете, оглушаясь на короткое время. Нанесенный урон приводит цель в себя."},
[13338] = {name = "Проклятие косноязычия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Принуждение цели к разговору на демоническом языке, что увеличивает скорость применения всех заклинаний на 50%. Один чернокнижник может наложить проклятие только на одну цель. Длительность - 15 сек."},
[13339] = {name = "Огненный взрыв", additional_info = "{Мана: 120} {Радиус действия: 20 м}\nМгновенное действие\n[q]Наносит противнику урон от огня."},
[13340] = {name = "Огненный взрыв", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Наносит противнику урон от огня."},
