[13393] = {name = "Формула чар для двуручного оружия: дух", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение наложению на двуручное оружие чар, повышающих дух на 3 ед."},
[13398] = {name = "Бросок гаечного ключа", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\n[q]Бросок гаечного ключа во противника и нанесение ему физического урона."},
[13399] = {name = "Посадка пакетов семян", additional_info = "Применение: 10 сек\nИнгредиенты:\nЗемля Ун'Горо (2), Пакет семян Тарлендриса\n[q]Для создания контейнера для круглогодичного проращивания семян используются два образца земли Ун'Горо и один пакет семян Тарлендриса."},
[13418] = {name = "Слабое зелье незаметности", additional_info = nil},
[13419] = {name = "Чары для плаща: ловкость II", additional_info = "Применение: 5 сек\nТребуется: Оружие\nИнструменты: Рунный серебряный жезл\nИнгредиенты:\nПростая Астральная субстанция\n[q]Наложение на плащ чар, повышающих ловкость на 1 ед."},
[13420] = {name = "Формула чар для плаща: ловкость I", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение наложению на плащ чар, повышающих ловкость на 1 ед."},
[13421] = {name = "Чары для плаща: защита II", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунический медный жезл\nИнгредиенты:\nСтранная пыль (6), Малый мерцающий осколок\n[q]Наложение на плащ чар, усиливающих броню на 20 ед."},
[13422] = {name = "Чары для плаща: защита II", additional_info = nil},
[13424] = {name = "Волшебный огонь", additional_info = "{Мана: 55} {Радиус действия: 30 м}\nМгновенное действие\n[q]Ослабляет броню на 50 ед. на 30 сек. Во время действия заклинания цель не может становиться незаметной или невидимой."},
[13438] = {name = "Огненный шар", additional_info = "{Мана: 45} {Радиус действия: 35 м}\nПрименение: 2 сек\n[q]Бросок огненного шара, который наносит 40 ед. урона от огня единовременно и 9 ед. урона от огня в течение 6 сек."},
[13439] = {name = "Ледяная стрела", additional_info = "{Мана: 25} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]В противника летит ледяная стрела, нанося 20 в 30 ед. урона от магии льда и снижая скорость передвижения на 50% на 5 сек."},
[13440] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 30 м\nПрименение: 2.2 сек\n[q]Поражение противника теневой молнией, наносящей 30 ед. урона от темной магии."},
[13441] = {name = "Огненная стрела", additional_info = "{Мана: 80} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Нанесение цели 50 в 70 ед. урона от огня."},
[13442] = {name = "Огненная стрела", additional_info = "{Мана: 18} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Нанесение цели 35 ед. урона от огня."},
[13443] = {name = "Кровопускание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику физического урона раз в 3 сек. в течение 15 сек."},
[13444] = {name = "Раскол брони", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Проламывание вражеской брони и ослабление ее на 0 ед. при каждом расколе. Можно использовать до 5 раз подряд. Длительность - 30 сек."},
[13445] = {name = "Кровопускание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику физического урона раз в 3 сек. в течение 15 сек."},
[13446] = {name = "Разящий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Удар по противнику с нанесением увеличенного урона в ближнем бою."},
[13459] = {name = "Истребление", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Снижение шанса противника поставить блок на 70% в течение 30 сек."},
[13461] = {name = "Иди домой", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Отсылает Разелиха домой - черт побери этих грязных плутов!"},
[13462] = {name = "Слабое зелье блокирования", additional_info = nil},
