[13578] = {name = "Нефритовый огонь", additional_info = "Мгновенное действие\n[q]Окружение заклинателя обжигающей магией на 8 сек. Пламя усиливает броню на 50% и наносит 50 ед. урона нападающим в ближнем бою."},
[13579] = {name = "Парализующий удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику 20 ед. урона и оглушение его на 4 сек. Ваша атака автоматически прервется, и цель должна будет находиться перед вами. При получении оглушенной целью любого повреждения она вновь придет в себя."},
[13582] = {name = "Смертельный яд", additional_info = "Радиус действия: 10 м\nПрименение: 2 сек\n[q]Наносит 2 ед. урона от сил природы находящимся рядом противникам каждые 10 сек. в течение 2 мин."},
[13583] = {name = "Проклятие Мертвого Леса", additional_info = "Радиус действия: 10 м\nПрименение: 2 сек\n[q]Ослабление целительных воздействий на 50% в течение 2 мин."},
[13584] = {name = "Разящий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение врагу обычного урона плюс 5 ед."},
[13585] = {name = "Щит молний", additional_info = "{Мана: 5} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]3 шаровых молний, окружающих союзника. 50% вероятность нанести 2 ед. урона противникам, атакующим в ближнем или дальнем бою. Каждый раз, как щит срабатывает, одна из молний рассеивается. Таким образом, щит перестает действовать через 10 мин., либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[13586] = {name = "Водные струи", additional_info = "Мгновенное действие\n[q]Разбрызгивание воды во всех направлениях с нанесением противникам урона от магии льда и отбрасыванием их назад."},
[13587] = {name = "Скорость ездового животного", additional_info = "Восстановление: 5 сек\n[q]Увеличение скорости верховой езды на 3%."},
[13589] = {name = "Аура поспешности", additional_info = "Мгновенное действие\n[q]Увеличение скорости атак на 20% у всех ближайших участников группы. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Аура\". Эффект ауры отменяется принудительно."},
