[14514] = {name = "Скачок", additional_info = "Мана: 75\nМгновенное действие\n[q]Телепортация заклинателя на 20 метров вперед, если ничто не перекрывает путь. Освобождение заклинателя от сковывающих эффектов."},
[14515] = {name = "Господство над разумом", additional_info = "{Мана: 30} {Радиус действия: 20 м}\nПрименение: 2 сек\n[q]Подчинение противника-гуманоида 25 уровня и ниже на 15 сек."},
[14516] = {name = "Разящий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Удар по противнику с нанесением увеличенного урона в ближнем бою."},
[14517] = {name = "Удар воина Света", additional_info = "{Мана: 40} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику 27 ед. урона и увеличение получаемого им урона от светлой магии на 10 ед. на каждый эффект \"Удар воина Света\". Эффект может быть применен до 5 раз. Время действия – 30 сек."},
[14518] = {name = "Удар воина Света", additional_info = "{Мана: 40} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику 50 ед. урона и увеличение получаемого им урона от светлой магии на 20 ед. на каждый эффект \"Удар воина Света\". Эффект может быть применен до 5 раз. Время действия – 30 сек."},
[14520] = {name = "Подвижность мысли", additional_info = "[q]Снижение расхода маны на мгновенные заклинания на 2%."},
[14521] = {name = "Медитация", additional_info = "[q]В процессе применения заклинаний продолжается 5% от восполнения маны."},
[14522] = {name = "Непреклонная воля", additional_info = "[q]Увеличивает на 3% вероятность не подвергнуться влиянию оглушающих, устрашающих или лишающих речи эффектов."},
[14523] = {name = "Молчаливая решимость", additional_info = "[q]Снижает уровень угрозы, создаваемой вашими заклинаниями, на 4%."},
[14524] = {name = "Специализация на жезлах", additional_info = "[q]Увеличение на 5% урона, наносимого при использовании магических жезлов."},
[14525] = {name = "Специализация на жезлах", additional_info = "[q]Увеличение на 10% урона, наносимого при использовании магических жезлов."},
[14526] = {name = "Специализация на жезлах", additional_info = "[q]Увеличение на 15% урона, наносимого при использовании магических жезлов."},
[14527] = {name = "Специализация на жезлах", additional_info = "[q]Увеличение на 20% урона, наносимого при использовании магических жезлов."},
[14528] = {name = "Специализация на жезлах", additional_info = "[q]Увеличение на 25% урона, наносимого при использовании магических жезлов."},
[14530] = {name = "Скорость", additional_info = "Мгновенное действие\n[q]Увеличение скорости бега на 40% на 10 сек."},
[14531] = {name = "Мученичество", additional_info = "[q]С вероятностью 50% жрец, получив критический удар оружием ближнего или дальнего боя, окажется под воздействием эффекта \"Средоточие заклинаний\" на 6 сек. Этот эффект предохраняет от сбоев наложения жреческих заклинаний при получении урона и повышает сопротивление прерыванию заклинаний на 10%.\n(Вероятность срабатывания: 50%)"},
[14532] = {name = "Яд паучьего монстра", additional_info = "Применение: 2 сек\n[q]Повышение физического урона, получаемого находящимися поблизости противниками, на 30% на 5 мин."},
[14533] = {name = "Разъединение", additional_info = "Мгновенное действие\n[q]Заклинание повышает урон от огня, магии льда, и тайной магии, получаемый находящимися поблизости противниками, на 50% на 5 мин."},
[14534] = {name = "Колючее жало", additional_info = "Мгновенное действие\n[q]Увеличение времени между атаками находящихся у поблизости противников на 54% в на 5 мин."},
[14535] = {name = "Илистая топь", additional_info = "Мгновенное действие\n[q]Ухудшение всех характеристик находящегося поблизости противника на 25% на 5 мин."},
[14537] = {name = "Сумка Шести Демонов", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит удар по находящимся перед вами противникам с помощью воздуха, огня и прочего!"},
[14538] = {name = "Удар ауры", additional_info = "Мгновенное действие\n[q]Снижение скорости применения заклинаний у находящихся поблизости противников на 35% на 5 мин."},
[14539] = {name = "Гнилостный фермент", additional_info = "Мгновенное действие\n[q]Увеличение урона от сил природы, получаемого находящимся поблизости противникам, на 50%, а получаемого урона от темной магии – на 50%. Время действия – 5 мин."},
[14540] = {name = "Повышенное сопротивление огню 1", additional_info = "[q]+1 к сопротивлению огню."},
[14541] = {name = "Повышенное сопротивление магии льда 1", additional_info = "[q]Сопротивление магии льда +1."},
