[14874] = {name = "Рваная рана", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику физического урона раз в 2 сек. в течение 10 сек."},
[14875] = {name = "Проклятие агонии", additional_info = "{Мана: 75} {Радиус действия: 30 м}\nМгновенное действие\n[q]Невыносимые страдания, наносящие урон от темной магии раз в 3 сек. в течение 30 сек. Один чернокнижник может наложить на каждую цель только одно проклятие."},
[14887] = {name = "Залп стрел Тьмы", additional_info = "{Мана: 160} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Силы тьмы, причиняющая урон о тени находящимся поблизости противникам."},
[14888] = {name = "Превращение Арая", additional_info = "Радиус действия: 5 м\nМгновенное действие\n[q]Превращение в настоящего древнего мудреца!"},
[14889] = {name = "Cпециализация на магии Света", additional_info = "[q]Повышает вероятность критического эффекта ваших заклинаний светлой магии на 1%."},
[14890] = {name = "Спешивающее дуновение", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Заставляет противника спешиться."},
[14891] = {name = "Выплавка черного железа", additional_info = "Применение: 3 сек\nИнгредиенты:\nРуда черного железа (8)\n[q]Обучение горняка выплавлять черное железо из руды черного железа. Выплавка черного железа требует наличия горна.\nСлиток черного железа"},
[14892] = {name = "Вдохновение", additional_info = "[q]Критические эффекты [ S03 – настройка и отмена пассивных эффектов – жрец : ваших исцеляющих заклинаний / вашего \"Быстрого исцеления\", \"Исцеления\", \"Большего исцеления\" или \"Молитвы исцеления\"] усиливают броню цели на 8% на 15 сек."},
[14893] = {name = "Вдохновение", additional_info = nil},
[14894] = {name = "Выплавка черного железа", additional_info = nil},
[14895] = {name = "Превосходство", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 5 сек}\nТребуется: Оружие ближнего боя\n[q]Дает мгновенное превосходство над противником. Наносит урон от оружия плюс 15 ед. Действует только после того, как цель уклоняется от атаки. \"Превосходство\" нельзя блокировать или парировать; также от него нельзя уклониться."},
[14897] = {name = "Замедляющий яд", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Увеличение времени между атаками противника на 25%, замедление передвижения на 30% в течение 25 сек."},
[14898] = {name = "Духовное исцеление", additional_info = "[q]Увеличивает на 2% количество здоровья, восполняемого вашими исцеляющими заклинаниями."},
[14900] = {name = "Цепное исцеление", additional_info = "{Мана: 150} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Целительная энергия, наполняющая раненого союзника. Затем она переходит на другого союзника, находящегося поблизости. Заклинание может исцелить до 3 целей, но с каждой новой целью энергия слабеет на 50%."},
[14901] = {name = "Духовное направление", additional_info = "[q]Увеличивает эффекты исцеления и урон от заклинаний на 5% от вашего духа."},
[14902] = {name = "Подлый трюк", additional_info = "{Энергия: 60} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Незаметность\n[q]Оглушает противника на 4 сек. Необходимо находиться в состоянии незаметности. Длина серии приемов увеличивается на 2."},
[14903] = {name = "Рваная рана", additional_info = "{Энергия: 25} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Наносит противнику физический урон раз в 2 сек. Дополнительные приемы серии повышают периодически наносимый урон и общую длительность."},
[14904] = {name = "Искусный целитель", additional_info = "[q]Уменьшение на 0.1 сек. времени применения заклинаний \"Исцеление\" и \"Большее исцеление\"."},
[14907] = {name = "Кольцо льда", additional_info = "Мгновенное действие\n[q]Наносит ближайшим противникам урон от магии льда, обездвиживая их на 8 сек."},
[14908] = {name = "Улучшенное обновление", additional_info = "[q]Увеличение на 5% количества здоровья, восполняемого при действии заклинания \"Обновление\"."},
[14909] = {name = "Опаляющий свет", additional_info = "[q]Увеличивает урон от заклинаний \"Кара\" и \"Священный Огонь\" на 5%."},
[14911] = {name = "Улучшенная молитва исцеления", additional_info = "[q]Уменьшает на 10% расход маны на ваше заклинание \"Молитва об исцелении\"."},
[14912] = {name = "Улучшенное исцеление", additional_info = "[q]Снижение на 5% расхода маны на применение заклинаний \"Малое исцеление\", \"Исцеление\" и \"Большее исцеление\"."},
[14913] = {name = "Средоточие исцеления", additional_info = "[q]С 35%-й вероятностью ваши заклинания исцеления не прерываются при получении урона."},
[14914] = {name = "Священный огонь", additional_info = "{Мана: 85} {Радиус действия: 30 м}\nПрименение: 3.5 сек\n[q]Навлечение на противника священного пламени, которое наносит 84 в 104 ед. урона от светлой магии и дополнительно 30 ед. урона от светлой магии в течение 10 сек."},
