[15255] = {name = "Автоматический ремонтный набор", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловый слиток , Магическая ткань , Твердое взрывчатое вещество\nТребуетИнженерное дело\n(200)\n[q2]Использование: Восстановление 700 ед. прочности дружественным механическим целям. (2 Мин Восстановление)"},
[15256] = {name = "Автоматический ремонтный набор", additional_info = nil},
[15257] = {name = "Плетение Тьмы", additional_info = "[q]Ваши заклинания темной магии получают 20% вероятность сделать цель уязвимой для темной магии. Эта уязвимость повышает урон, наносимый цели магией этой школы, на 3% и длится 15 сек. Эффект может суммироваться до 5 раз."},
[15258] = {name = "Уязвимость к Тьме", additional_info = nil},
