[15275] = {name = "Улучшенное слово Тьмы: Боль", additional_info = "[q]Увеличение длительности заклинания \"Слово Тьмы: Боль\" на 3 сек."},
[15276] = {name = "Открытие двери бара", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Открытие запертой двери бара."},
[15277] = {name = "Печать расплаты", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nМгновенное действие\n[q]Наложение на союзника печати, которая соханяется 30 сек. Нанося удар по противнику, персонаж, на которого наложено заклинание категории \"Печать\", укрепляет свое здоровье."},
[15278] = {name = "Эффект печати расплаты", additional_info = nil},
[15279] = {name = "Хрустальная спираль", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Окружение дружественной цели хрустальной защитой, наносящей 12 ед. урона каждому, кто наносит ей удар. Время действия – 10 мин."},
[15280] = {name = "Прорубание брони", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Ослабление брони целей на 300 ед. на 20 сек."},
