[15284] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\nТребуется: Оружие ближнего боя\n[q]Наносит противнику и его ближайшим союзникам урон от оружия, увеличенный на 10 ед. Захватывает до 3 целей."},
[15285] = {name = "Град огненных шаров", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Нанесение урона от огня ближайшим противникам."},
[15286] = {name = "Объятия вампира", additional_info = "{Мана: 40} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Поражает цель энергией Тьмы на 1 мин. Когда ваши заклинания наносят пораженной цели урон от темной магии, участники группы восполняют здоровье в объеме 20% нанесенного урона."},
[15288] = {name = "Неистовство Рагнароса", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышение нанесенного союзником магического урона на 25 ед. в течение 30 мин."},
[15290] = {name = "Объятия вампира", additional_info = nil},
[15292] = {name = "[q3]Распылитель из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (18), Сердце огня (4)\n[q3]Распылитель из черного железа\nСтановится персональным при надевании\nДвуручное Дробящее\nУрон: 140-211 Скорость 3.70\n(47.43 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Оглушение цели на 8 сек."},
[15293] = {name = "[q2]Кольчуга из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (10), Сердце огня (2)\n[q2]Кольчуга из черного железа\nСтановится персональным при надевании\nГрудь Кольчуга\n[q2]Броня: 433\n+13 к выносливости\nУстойчивость: +12 Огонь\nПрочность: 100 / 100\nТребуется"},
[15294] = {name = "[q3]Раскалыватель из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (26), Сердце огня (4)\n[q3]Рассекатель из черного железа\nСтановится персональным при надевании\nДвуручное Топор\nУрон: 101-153 Скорость 2.60\n(48.85 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Ослабление брони целей на 300 ед. на 20 сек."},
[15295] = {name = "[q2]Наплечники из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (6), Сердце огня\n[q2]Наплечники из черного железа\nСтановится персональным при надевании\nПлечо Латы\n[q2]Броня: 514\n+10 к выносливости\nУстойчивость: +10 Огонь\nПрочность: 70 / 70\nТребуется"},
[15296] = {name = "[q3]Латы из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (20), Сердце огня (8)\n[q3]Латы из черного железа\nСтановится персональным при поднятии\nГрудь Латы\n[q2]Броня: 817\n+12 к выносливости\nУстойчивость: +19 Огонь\nПрочность: 135 / 135\nТребуется"},
[15297] = {name = "Чертеж: распылитель из черного железа", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению распылителя из черного железа."},
