[15470] = {name = "Проклятие косноязычия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Принуждение цели к разговору на демоническом языке, что увеличивает скорость применения всех заклинаний на 50%. Один чернокнижник может наложить проклятие только на одну цель. Длительность - 15 сек."},
[15471] = {name = "Опутывающая сеть", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Обездвиживание противника на 8 сек., при этом времени между его атаками увеличивается на 100% и он не способен применять заклинания."},
[15472] = {name = "Стрела Тьмы", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[15473] = {name = "Облик Тьмы", additional_info = "40% от базовой мана\n{Мгновенное действие} {Восстановление: 1.5 сек}\n[q]Жрец принимает облик Тьмы, в котором наносимый им урон от темной магии увеличивается на 15% [ S03 – настройка и отмена пассивных эффектов – жрец : затраты маны на заклинания темной магии снижаются на 0% ], а получаемый физический урон уменьшается на 15%. В этом облике нельзя использовать заклинания светлой магии."},
[15474] = {name = "Паутинный взрыв", additional_info = "Мгновенное действие\n[q]Обездвиживание ближайших противников на 10 сек."},
[15475] = {name = "Гибельный яд", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение 510 в 690 ед. урона от сил природы и дополнительно 2 ед. урона находящимся поблизости противникам раз в 5 сек. в течение 2 мин."},
[15487] = {name = "Молчание", additional_info = "{Мана: 225} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 45 сек}\n[q]Онемение противника, не дающее ему применять заклинания в течение 5 сек."},
