[15491] = {name = "Сбор благословенной воды", additional_info = "Применение: 3 сек\n[q]Заполнить а Храме Луны."},
[15493] = {name = "Свет небес", additional_info = "{Мана: 150} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Воззвание к светлой магии для исцеления союзника."},
[15494] = {name = "Неистовство Искусника", additional_info = "Мгновенное действие\n[q]Дает дополнительные атаки в количестве 2 при вашем следующем замахе."},
[15495] = {name = "Разрывной выстрел", additional_info = "Радиус действия: 5 - 30 м\nПрименение: 1 сек\n[q]Нанесение стандартного урона от оружия и дополнительно 100 ед. урона от огня противнику и его ближайшим союзникам."},
[15496] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику и его ближайшему союзнику урона, равного увеличенному на 10 ед. стандартному урону оружия."},
[15497] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 4 сек."},
[15498] = {name = "Божественная кара", additional_info = "{Мана: 75} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Удар по противнику, нанесение урона от светлой магии."},
[15499] = {name = "Ледяной шок", additional_info = "{Мана: 115} {Радиус действия: 20 м}\nМгновенное действие\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 8 сек."},
[15500] = {name = "Шок", additional_info = "{Мана: 135} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Удар молнии, наносящий урон от сил природы."},
[15501] = {name = "Земной шок", additional_info = "{Мана: 130} {Радиус действия: 20 м}\nМгновенное действие\n[q]Противника бьет ударной волной с нанесением урона от сил природы и лишением его возможности наложения заклинаний на 2 сек."},
[15502] = {name = "Раскол брони", additional_info = "Мгновенное действие\nТребуется: Оружие ближнего боя\n[q]Рубящие удары по ближайшим потивникам, снижение их брони на 0 ед. за каждое применение способности \"Раскол брони\". Может применяться несколько раз (до 5 раз). Длительность - 30 сек."},
[15503] = {name = "Глоток исцеляющего зелья", additional_info = "Мгновенное действие\n[q]Использование священного эликсира для исцеления заклинателя."},
[15504] = {name = "Глоток исцеляющего зелья", additional_info = "Мгновенное действие\n[q]Использование священного эликсира для исцеления заклинателя."},
[15505] = {name = "Жертвенный огонь", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Заклинание обжигает противника и наносит дополнительный урон от огня каждые 3 сек. в течение 21 сек."},
[15506] = {name = "Жертвенный огонь", additional_info = "(Вероятность срабатывания: 25%, Восстановление: 4с)"},
[15507] = {name = "Щит молний", additional_info = "{Мана: 5} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]3 шаровых молний, окружающих заклинателя. 50% вероятность нанести 4 ед. урона противникам, атакующим в ближнем или дальнем бою. Каждый раз, как щит срабатывает, одна из молний рассеивается. Таким образом, щит перестает действовать через 10 мин., либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[15508] = {name = "Улучшение брони 120", additional_info = "[q]Броня +120 ед."},
[15529] = {name = "Сгусток пламени", additional_info = nil},
[15530] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 4 сек."},
[15531] = {name = "Кольцо льда", additional_info = "Мана: 75\nМгновенное действие\n[q]Наносит ближайшим противникам урон от магии льда, обездвиживая их на 8 сек."},
[15532] = {name = "Кольцо льда", additional_info = "Мана: 75\nМгновенное действие\n[q]Наносит ближайшим противникам урон от магии льда, обездвиживая их на 8 сек."},
[15533] = {name = "Окаменение - направление заклинания, визуальный эффект", additional_info = nil},
[15534] = {name = "Превращение", additional_info = "Радиус действия: 30 м\nПрименение: 1.5 сек\n[q]Превращает противника в овцу. Он вынужден бродить вокруг в течение 20 сек. Овца не может атаковать или применять заклинания, но быстро восстанавливает здоровье и ману. Любой нанесенный урон прекратит действие заклинания. Одновременно заклинание превращения можно наложить только на одну цель. Действует только на животных, драконов, великанов, гуманоидов и фауну."},
[15535] = {name = "Вихрь", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Противника окружает вихрь. Длительность до 10 сек. Если цель получает какой-либо урон, она вырывается из удерживающих ее вихрей."},
[15536] = {name = "Огненный шар", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."},
[15537] = {name = "Стрела Тьмы", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[15538] = {name = "Сгусток пламени", additional_info = nil},
[15539] = {name = "Сотворение посоха Приказа", additional_info = "Мгновенное действие"},
[15547] = {name = "Выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел в противника с нанесением ему физического урона."},
[15548] = {name = "Раскат грома", additional_info = "Мгновенное действие\n[q]Нанесение 35 в 39 ед. урона от сил природы находящимся поблизости противникам, причем время между их атаками увеличивается на 33%, а скорость передвижения снижается на 40% в течение 10 сек."},
[15549] = {name = "Звенья молний", additional_info = "Радиус действия: 30 м\nПрименение: 1.8 сек\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося каждой урон от сил природы."},
[15550] = {name = "Топот", additional_info = "Мгновенное действие\n[q]Нанесение физического урона ближайшим противникам."},
