[15582] = {name = "Удар в спину", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение противнику обычного урона плюс 30 ед., но только при атаке со спины."},
[15583] = {name = "Рваная рана", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику физического урона раз в 2 сек. в течение 10 сек."},
[15584] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение противнику и его ближайшим союзникам обычного урона плюс 30 ед. Распространяется на 3 целей и меньше."},
[15585] = {name = "Молитва исцеления", additional_info = "Мана: 400\nПрименение: 3 сек\n[q]Призывание светлой магии для исцеления ближайших участников группы."},
[15586] = {name = "Исцеление", additional_info = "{Мана: 215} {Радиус действия: 40 м}\nПрименение: 3.5 сек\n[q]Воззвание к светлой магии для исцеления союзника."},
