[15596] = {name = "[q3]Дымящееся Сердце Горы", additional_info = "Применение: 30 сек\nИнгредиенты:\nКровь Горы , Субстанция Огня , Малый сверкающий осколок (3)\n[q3]Дымящееся сердце горы\nСтановится персональным при поднятии\nУникальныйАксессуар\nБроня: 150\nУстойчивость: +7 Огонь\nУстойчивость: +7 Природа\nУстойчивость: +7 Лед\nУстойчивость: +7 Тьма\nТребуется"},
[15597] = {name = "Формула: дымящееся сердце горы", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение созданию дымящегося сердца горы."},
[15598] = {name = "Огненная стрела", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Нанесение противнику 60 в 80 ед. урона от огня."},
[15599] = {name = "Огненная стрела", additional_info = "[q]Получение 5% шанса нанести противнику удар с причинением 15 в 25 ед. урона от огня.\n(Вероятность срабатывания: 5%)"},
[15600] = {name = "Рука Правосудия", additional_info = "[q]2% шанс при попадании в ближнем бою получить 1 дополнительную атаку.\n(Вероятность срабатывания: 2%, Восстановление: 2с)"},
[15601] = {name = "Рука Правосудия", additional_info = nil},
