[15611] = {name = "Ящеричья молния", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение противнику урона от сил природы."},
[15612] = {name = "Ящеричья молния", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение противнику урона от сил природы."},
[15613] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\n[q]Нанесение обычного урона плюс 20 ед. противнику и его ближайшему союзнику."},
