[15615] = {name = "Зуботычина", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику 45 ед. урона и лишение его на 5 сек. возможности применять заклинания."},
[15616] = {name = "Огненный шок", additional_info = "{Мана: 110} {Радиус действия: 20 м}\nМгновенное действие\n[q]Поджигание противника, в результате чего он получает дополнительный урон от огня раз в 3 сек. в течение 12 сек."},
