[15655] = {name = "Сокрушение щитом", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Щит\n[q]Нанесение противнику 40 ед. урона и оглушение его на 2 сек."},
[15656] = {name = "Ядовитый тычок", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Нанесение 32 ед. урона от сил природы противнику раз в 3 сек., увеличение времени между его атаками на 25%, замедление передвижения на 63%. Длительность - 15 сек."},
[15657] = {name = "Удар в спину", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение противнику обычного урона плюс 20 ед., но только при атаке со спины."},
[15658] = {name = "Пробуждение принцессы", additional_info = nil},
[15659] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося каждой урон от сил природы."},
