[15698] = {name = "Наполнение пустого сосуда", additional_info = "Дистанция ближнего боя\nПрименение: 7 сек\n[q]Наполнение проклятого флакона для образцов образцом проклятого слизнюка. ОСТОРОЖНО! Это скорее всего уничтожит тело существа."},
[15699] = {name = "Наполнение пустого сосуда", additional_info = "Дистанция ближнего боя\nПрименение: 7 сек\n[q]Наполнение пустой банки для нечистого слизнюка образцом тканей нечистого слизнюка. ВНИМАНИЕ: при этом тело существа будет, вероятно, уничтожено."},
[15700] = {name = "Драчливый корнеплод", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]Восполнение 700 в 900 ед. здоровья."},
[15701] = {name = "Ночное дыхание дракона", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 394 в 456 ед. маны и 394 в 456 ед. здоровья."},
