[15799] = {name = "Цепное исцеление", additional_info = "{Мана: 150} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Целительная энергия, наполняющая раненого союзника. Затем она переходит на другого союзника, находящегося поблизости. Заклинание может исцелить до 3 целей, но с каждой новой целью энергия слабеет на 50%."},
[15800] = {name = "Сожжение маны", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Поражение находящихся рядом противников антимагическими молниями. За каждую единицу похищенной маны цель получает 1 ед. урона."},
[15801] = {name = "Молния", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника молнией, урон от сил природы."},
