[15969] = {name = "Всплеск боли", additional_info = "{Мана: 65} {Дистанция ближнего боя}\nМгновенное действие\n[q]Наносит противнику урон от темной магии. Требуется находиться позади цели."},
[15970] = {name = "Сон", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nПрименение: 1 сек\n[q]Погружение противника в сон, длящийся 10 сек. и прерывающийся при любом повреждении. Усыпить можно только одного противника за раз."},
[15971] = {name = "Устрашающий рев", additional_info = "Мгновенное действие\n[q]Снижение силы атаки ближнего боя находящихся рядом врагов на 2 ед. на 30 сек."},
[15972] = {name = "[q2]Блистающий стальной кинжал", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСтальной слиток (10), Сильный плавень (2), Моховой агат , Первородная земля , Толстая кожа\n[q2]Блистающий стальной кинжал\nСтановится персональным при надевании\nОдноручное Кинжал\nУрон: 19-37 Скорость 1.50\n(18.67 ед. урона в секунду)\nПрочность: 55 / 55\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 12."},
[15973] = {name = "[q2]Пылающий золотой клинок", additional_info = "Применение: 25 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСтальной слиток (10), Золотой слиток (4), Первородный огонь (2), Толстая кожа (2)\n[q2]Пылающий золотой клинок\nСтановится персональным при надевании\nОдноручное Кинжал\nУрон: 21-39 Скорость 1.40\n(21.43 ед. урона в секунду)\nПрочность: 55 / 55\nТребуется\n[q2]Если на персонаже: Увеличение наносимого урона от заклинаний и эффектов огня не более чем на 10 ед."},
[15974] = {name = "Блистающий стальной кинжал", additional_info = nil},
