[16006] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося каждой урон от сил природы."},
[16007] = {name = "Драко-инкарцинатор 900", additional_info = "Радиус действия: 10 м\nПрименение: 2 сек\n[q]Воздействуйте на детеныша дракона в степях."},
[16027] = {name = "Создание сущности детеныша дракона", additional_info = nil},
[16028] = {name = "Заморозить яйцо из питомника - модель", additional_info = "Радиус действия: 10 м\nПрименение: 0.5 сек\n[q]Примените к яйцу из питомника, затем вернитесь к Тинки."},
[16029] = {name = "Создание яйцехладоскопа", additional_info = nil},
[16031] = {name = "Освобождение слизнюка из Оскверненного леса", additional_info = "Радиус действия: 30 м\nПрименение: 5 сек\n[q]Выпускает пойманного слизнюка из Оскверненного леса, чтобы он слился с первоначальным слизнюком в кратере Ун'Горо."},
[16032] = {name = "Слияние слизей", additional_info = "Радиус действия: 5 м\nПрименение: 0.5 сек\n[q]Пойманный слизнюк из Оскверненного леса сливается с первоначальным слизнюком из кратера Ун'Горо."},
[16033] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 10 целей, причем каждой следующей цели наносится все больший урон от сил природы."},
[16034] = {name = "Шок", additional_info = "{Мана: 135} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Удар молнии, наносящий урон от сил природы."},
[16035] = {name = "Сотрясение мозга", additional_info = "[q]Увеличивает на 1% урон, наносимый вашими заклинаниями \"Молния\", \"Цепная молния\" и \"Шок\"."},
[16037] = {name = "Мысленный зонд", additional_info = nil},
[16038] = {name = "Зов пламени", additional_info = "[q]Увеличение на 5% урона, наносимого вашими тотемами огня."},
[16039] = {name = "Конвекция", additional_info = "[q]Снижает расход маны на заклинания \"Шок\", \"Молния\" и \"Цепная молния\" на 2%."},
[16040] = {name = "Отзвук", additional_info = "[q]Сокращение времени восстановления заклинания \"Шок\" на 0.2 сек."},
[16041] = {name = "Зов грома", additional_info = "[q]Повышает вероятность критического удара при применении \"Молнии\" и \"Цепной молнии\" на 1%."},
[16043] = {name = "Земной захват", additional_info = "[q]Увеличивает уровень прочности вашего Тотема каменного когтя на 25% и радиус действия Тотема оков земли на 10%."},
[16044] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Нанесение урона от оружия плюс 50 ед. врагу и его ближайшим союзникам. Захватывает до 10 целей."},
[16045] = {name = "Заключение", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 30 сек)\n[q]Заключение противника, оглушение на 30 сек."},
[16046] = {name = "Взрывная волна", additional_info = "Мгновенное действие\n[q]Высвобождает волну пламени, наносящую урон от огня находящимся рядом противникам и снижающую их скорость передвижения на 6 сек."},
