[16055] = {name = "Ночной саблезуб", additional_info = "Применение: 3 сек\n[q]Позволяет вызывать и отпускать ездового ночного саблезуба. Это очень быстроногое ездовое животное."},
[16056] = {name = "Ледопард", additional_info = "Применение: 3 сек\n[q]Позволяет вызывать и отпускать ездового ледопарда. Это очень быстрое ездовое животное."},
[16057] = {name = "Поместить некованную печать", additional_info = "Радиус действия: 5 м\nПрименение: 0.5 сек\n[q]Помещение некованой печати Вознесения перед Огнебором."},
