[16070] = {name = "Атака Нефариуса 0", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Атака противника чародейским снарядом, наносящим 1 ед. урона от тайной магии."},
[16071] = {name = "Проклятие огненного клейма", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение 657 в 843 ед. урона от огня противнику раз в 60 сек. в течение 5 мин."},
[16072] = {name = "Очистить и положить еду", additional_info = "Дистанция ближнего боя\nПрименение: 5 сек\nИнгредиенты:\nОбразец плодов племени Чернолесья , Образец зерна племени Чернолесья , Образец орехов племени Чернолесья\n[q]Создание миски очищенной еды, которая несомненно понравится фурболгам. Для этого требуются фрукты, зерно и орехи из лагеря Чернолесья."},
[16073] = {name = "Наполнение", additional_info = "Радиус действия: 5 м\nПрименение: 3 сек\n[q]Наполнить водой из лунного колодца, чтобы приготовить чашу к очищению положенной в нее еды."},
[16074] = {name = "Появление пылающего стража Скверны", additional_info = nil},
[16075] = {name = "Бросок топора", additional_info = nil},
[16076] = {name = "Невооруженный воевода Вун - постоянный эффект", additional_info = nil},
[16077] = {name = "Наполнение", additional_info = nil},
[16078] = {name = "Углеглаз, исчезновение", additional_info = nil},
[16079] = {name = "Кольцо огня", additional_info = "Мгновенное действие\n[q]Нанесение урона от огня ближайшим противникам."},
[16080] = {name = "Красный волк", additional_info = "Применение: 3 сек\n[q]Призыв и освобождение ездового красного волка. Это очень резвое верховое животное."},
[16081] = {name = "Полярный волк", additional_info = "Применение: 3 сек\n[q]Вызов и освобождение верхового полярного волка. Это очень резвое верховое животное."},
[16082] = {name = "Игреневый жеребец", additional_info = "Применение: 3 сек\n[q]Позволяет вызывать и отпускать игреневого жеребца. Это очень быстроногое ездовое животное."},
[16083] = {name = "Белый жеребец", additional_info = "Применение: 3 сек\n[q]Призыв и освобождение ездового белого жеребца. Это очень быстрое верховое животное."},
[16084] = {name = "Красный крапчатый ящер", additional_info = "Применение: 3 сек\n[q]Позволяет вызывать и отпускать ездового ящера. Это очень быстроногое ездовое животное."},
[16086] = {name = "Улучшенный тотем огня", additional_info = "[q]Уменьшает паузу перед активацией тотема кольца огня на 1 сек. Снижает угрозу, создаваемую тотемом магмы, на 25%."},
[16089] = {name = "Неистовство стихий", additional_info = "[q]Усиливает бонус критического удара опаляющих тотемов, тотемов магмы, кольца огня, а также заклинаний огня, льда и природы на 100%."},
[16094] = {name = "Дыхание льда", additional_info = "Дистанция ближнего боя\nПрименение: 2 сек\n[q]Нанесение противникам, находящихся в пределах конуса холода перед заклинателем, урона от магии льда, похищение их маны и снижение скорости их передвижения в течение 10 сек."},
[16095] = {name = "Жестокий рывок", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение противнику физического урона раз в 3 сек. в течение 15 сек."},
[16096] = {name = "Пугающий рык", additional_info = "Следующая атака\n[q]Оглушение находящихся поблизости противников, лишение их возможности двигаться или атаковать в течение 5 сек."},
[16097] = {name = "Сглаз", additional_info = "{Мана: 120} {Радиус действия: 20 м}\nМгновенное действие\n[q]Превращение находящихся поблизости противников в лягушек. Невозможность атаковать и применять заклинания в течение 10 сек."},
[16098] = {name = "Проклятие крови", additional_info = "Радиус действия: 20 м\nПрименение: 2 сек\n[q]Увеличение физического урона, получаемого находящимися поблизости противниками, на 2 ед. на 10 мин."},
[16099] = {name = "Дыхание льда", additional_info = "Дистанция ближнего боя\nПрименение: 2 сек\n[q]Нанесение противникам, находящихся в пределах конуса холода перед заклинателем, урона от магии льда, похищение их маны и снижение скорости их передвижения в течение 10 сек."},
[16100] = {name = "Выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел в противника с нанесением ему физического урона."},
[16101] = {name = "Огненный шар", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."},
[16102] = {name = "Огненный столб", additional_info = "{Мана: 260} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Призывает столб пламени, обжигающий всех противников на выбранном участке и наносящий дополнительный урон от огня каждые 2 сек. в течение 8 сек."},
[16103] = {name = "Вызов скального паучонка", additional_info = nil},
[16104] = {name = "Кристаллизация", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Оглушение противников, находящихся в секторе конуса перед заклинателем. Они не могут двигаться или атаковать в течение 6 сек."},
[16105] = {name = "Сотрясение мозга", additional_info = "[q]Увеличивает на 2% урон, наносимый вашими заклинаниями \"Молния\", \"Цепная молния\" и \"Шок\"."},
