[16164] = {name = "Концентрация стихий", additional_info = "[q]При произнесении заклинания школы огня, магии льда или природы вы с вероятностью 10% впадаете в состояние \"Ясность мысли\". Состояние \"Ясность мысли\" уменьшает расход маны на следующее боевое заклинание на 100%.\n(Вероятность срабатывания: 10%)"},
[16166] = {name = "Покорение стихий", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Увеличение вероятности критического эффекта последующего заклинания магии огня, льда или сил природы на 100% и снижение расхода маны на него на 100%."},
[16167] = {name = "Ренд Чернорук садится в седло", additional_info = nil},
[16168] = {name = "Удар пламенем", additional_info = "Радиус действия: 20 м\nПрименение: 1.5 сек\n[q]Нанесение урона от огня противнику и увеличение полученного им урона от огня в течение 20 сек."},
[16169] = {name = "Удар по дуге", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Удар по дуге, наносящий 5 ед. урона противникам, которые находятся в секторе перед заклинателем."},
[16170] = {name = "Кровожадность", additional_info = "{Мана: 10} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышение скорости атаки союзника на 60% на 30 сек."},
[16171] = {name = "Подкрепленная воля", additional_info = "Мгновенное действие\n[q]Снимает 1 эффект превращения, подчинения и отключения с находящихся поблизости союзников."},
[16172] = {name = "Трещина в черепе", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Понижение выносливости противника на 1 ед. на 20 сек."},
[16173] = {name = "Тотемное средоточие", additional_info = "[q]Снижение расхода маны на создание тотемов на 5%."},
[16176] = {name = "Исцеление предков", additional_info = "[q]Усиление на 8% брони цели на 15 сек после получения критического эффекта примененого на ней исцеляющего заклинания."},
