[16180] = {name = "Помощь природы", additional_info = "[q]Увеличение на 1% вероятности нанесения удара в атаках ближнего боя и при применении заклинаний."},
[16181] = {name = "Средоточие исцеления", additional_info = "[q]С 14%-й вероятностью ваши заклинания исцеления не прерываются при получении урона."},
[16182] = {name = "Улучшенная волна исцеления", additional_info = "[q]Уменьшение на 0.1 сек. времени применения заклинания \"Волна исцеления\"."},
