[16186] = {name = "Моровая лихорадка", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]250 ед. урона от сил природы, затем 11 дополнительного урона раз в 5 сек. в течение 3 мин."},
[16187] = {name = "Восстанавливающий тотем", additional_info = "[q]Увеличение эффекта Тотема источника маны и Тотема исцеляющего потока на 5%."},
[16188] = {name = "Природная стремительность", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Мгновенное применение следующего заклинания сил природы, обычное время применения которого ниже 10 сек."},
[16189] = {name = "Мастерство владения тотемами", additional_info = "[q]Увеличение радиуса действия тотемов, влияющих на дружественные цели, до 30 метров."},
[16190] = {name = "Тотем прилива маны", additional_info = "Мана: 20\n{Мгновенное действие} {Восстановление: 5 мин}\nИнструменты: Тотем воды\n[q]Создание рядом с заклинателем тотема прилива маны прочностью 5 ед., который в течение 12 сек. раз в 3 сек. восполняет 170 ед. маны всем участникам группы в радиусе 20 м."},
