[16355] = {name = "Оружие ледяного клейма", additional_info = "Мана: 135\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Заклинатель усиливает свое оружие льдом. Каждое попадание дает шанс нанести 166 ед. дополнительного урона от магии льда и замедлить скорость передвижения цели на 25% в течение 8 сек. Время действия – 5 мин."},
[16356] = {name = "Оружие ледяного клейма", additional_info = "Мана: 160\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Заклинатель усиливает свое оружие льдом. Каждое попадание дает шанс нанести 187 ед. дополнительного урона от магии льда и замедлить скорость передвижения цели на 25% в течение 8 сек Время действия – 5 мин."},
