[16495] = {name = "Смертельный укус", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Похищение у противника 100 ед. здоровья. При этом здоровье заклинателя восполняется на величину вплоть до двухкратной от похищенного здоровья."},
[16496] = {name = "Выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел в противника с нанесением ему физического урона."},
