[16781] = {name = "Собирание оберегов", additional_info = "Радиус действия: 30 м\nПрименение: 1.3 сек\nИнгредиенты:\nПоловинка талисмана\n[q]Соединение половинного оберега Удачи с недостающим половинным оберегом Удачи."},
[16782] = {name = "Молния", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Взрыв. Нанесение 35 в 65 ед. урона от сил природы."},
[16783] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 30 м\nПрименение: 2.2 сек\n[q]Поражение противника теневой молнией, наносящей 75 в 125 ед. урона от темной магии."},
[16784] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 30 м\nПрименение: 2.2 сек\n[q]Поражение противника теневой молнией, наносящей 105 в 175 ед. урона от темной магии."},
[16785] = {name = "Огненный разрыв", additional_info = "Мгновенное действие\n[q]Нанесение урона от огня ближайшим противникам, с отбрасыванием их назад."},
