[16788] = {name = "Огненный шар", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."},
[16789] = {name = "Гнев", additional_info = "Мгновенное действие\n[q]Увеличивает наносимый заклинателем физический урон на 50 ед. и скорость атаки на 50% на 15 сек."},
[16790] = {name = "Нокдаун", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 5 сек}\n[q]Нанесение 60 в 80 ед. урона противнику и его ближайшим союзникам, оглушение на 2 сек. Действует на несколько целей (до 3)."},
[16791] = {name = "Яростная злость", additional_info = nil},
[16792] = {name = "Яростная злость", additional_info = "(Восстановление: 2с)"},
[16793] = {name = "Похищающий удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Похищение 250 ед. здоровья у противника и передача его заклинателю."},
[16794] = {name = "Преображение", additional_info = nil},
[16795] = {name = "Некрорахнид-скарабей", additional_info = "Применение: 1.5 сек\n[q]Призывает 8 некрорахнидов-скарабеев в помощь заклинателю в битве в течение 10 сек."},
[16796] = {name = "Вызов Ши-Ротам", additional_info = "Радиус действия: 10 м\nПрименение: 2.5 сек\n[q]Поместите у камня Ши-Ротам."},
[16798] = {name = "Чарующая колыбельная", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\n[q]Усыпление противника на время до 10 сек. Любой нанесенный урон разбудит усыпленного. Усыпить можно не более одного противника за раз."},
[16799] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 1 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 4 сек."},
[16800] = {name = "Вурдалачий гной", additional_info = "(Вероятность срабатывания: 3%)"},
[16801] = {name = "Преобразование Вароша", additional_info = nil},
[16803] = {name = "Мгновенная заморозка", additional_info = "Мгновенное действие\n[q]Заклинание наносит ближайшим противникам урон от магии льда и примораживает их к месту вплоть до 5 сек."},
[16804] = {name = "Огненный шок", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Поджигание противника, в результате чего он получает дополнительный урон от огня раз в 3 сек. в течение 12 сек."},
[16805] = {name = "Воспламенение", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Поджигание противника, наносящее 3000 ед. урон от огня в течение 10 сек. и приводя в панику. Пока цель пылает, пламя периодически обжигает ближайших союзников цели, нанося 300 ед. урона."},
[16806] = {name = "Воспламенение", additional_info = nil},
[16807] = {name = "Copy of Simple Teleport", additional_info = "Мгновенное действие\n[q]Создание эффекта, будто NPC, применяющий заклинание, только что телепортировался."},
[16809] = {name = "Появление едкой слизи", additional_info = nil},
[16810] = {name = "Природный захват", additional_info = "Мана: 65\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Во время действия заклинания каждый раз, как противники наносят удар заклинателю, их с 35% вероятностью поражает заклинание \"Гнев деревьев\" (уровень 2). Можно использовать только под открытым небом. 1 срабатывание. Время действия – 45 сек.\n(Вероятность срабатывания: 35%)"},
[16811] = {name = "Природный захват", additional_info = "Мана: 80\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Во время действия заклинания каждый раз, как противники наносят удар заклинателю, их с 35% вероятностью поражает заклинание \"Гнев деревьев\" (уровень 3). Можно использовать только под открытым небом. 1 срабатывание. Время действия – 45 сек.\n(Вероятность срабатывания: 35%)"},
[16812] = {name = "Природный захват", additional_info = "Мана: 95\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Во время действия заклинания каждый раз, как противники наносят удар заклинателю, их с 35% вероятностью поражает заклинание \"Гнев деревьев\" (уровень 4). Можно использовать только под открытым небом. 1 срабатывание. Время действия – 45 сек.\n(Вероятность срабатывания: 35%)"},
[16813] = {name = "Природный захват", additional_info = "Мана: 110\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Во время действия заклинания каждый раз, как противники наносят удар заклинателю, их с 35% вероятностью поражает заклинание \"Гнев деревьев\" (уровень 5). Можно использовать только под открытым небом. 1 срабатывание. Время действия – 45 сек.\n(Вероятность срабатывания: 35%)"},
