[16845] = {name = "Лунное сияние", additional_info = "[q]Снижение расхода маны на заклинания \"Лунный огонь\", \"Звездный огонь\", \"Гнев\", \"Целительное прикосновение\", \"Восстановление\" и \"Омоложение\" на 3%."},
[16846] = {name = "Лунное сияние", additional_info = "[q]Снижение расхода маны на заклинания \"Лунный огонь\", \"Звездный огонь\", \"Гнев\", \"Целительное прикосновение\", \"Восстановление\" и \"Омоложение\" на 6%."},
[16847] = {name = "Лунное сияние", additional_info = "[q]Снижение расхода маны на заклинания \"Лунный огонь\", \"Звездный огонь\", \"Гнев\", \"Целительное прикосновение\", \"Восстановление\" и \"Омоложение\" на 9%."},
[16850] = {name = "Улучшенный звездный огонь", additional_info = "[q]Уменьшение времени применения заклинания \"Звездный огонь\" на 0.1 с. Кроме того, оно будет с вероятностью 3% оглушать цель на 3 сек.\n(Вероятность срабатывания: 3%)"},
[16856] = {name = "Смертельный удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение урона, равного 200% урона оружия и создание раны, снижающей эффективность любых исцеляющих эффектов на 50% на 5 сек."},
[16857] = {name = "Волшебный огонь (сила зверя)", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 6 сек}\nТребуется: Облик кошки, Облик медведя, Облик лютого медведя\n[q]Ослабляет броню на 175 ед. на 40 сек. Во время действия заклинания цель не может становиться незаметной или невидимой."},
[16858] = {name = "Звериная агрессия", additional_info = "[q]Ваш \"Устрашающий рев\" снижает силу атаки противника дополнительно на 8%. Ваш \"Свирепый укус\" наносит на 3% больше урона."},
[16859] = {name = "Звериная агрессия", additional_info = "[q]Ваш \"Устрашающий рев\" снижает силу атаки противника дополнительно на 16%. Ваш \"Свирепый укус\" наносит на 6% больше урона."},
[16860] = {name = "Звериная агрессия", additional_info = "[q]Ваш \"Устрашающий рев\" снижает силу атаки противника дополнительно на 24%. Ваш \"Свирепый укус\" наносит на 9% больше урона."},
[16861] = {name = "Звериная агрессия", additional_info = "[q]Ваш \"Устрашающий рев\" снижает силу атаки противника дополнительно на 32%. Ваш \"Свирепый укус\" наносит на 12% больше урона."},
[16862] = {name = "Звериная агрессия", additional_info = "[q]Ваш \"Устрашающий рев\" снижает силу атаки противника дополнительно на 40%. Ваш \"Свирепый укус\" наносит на 15% больше урона."},
[16864] = {name = "Знамение ясности", additional_info = "Мана: 120\nМгновенное действие\n[q]Переполняет друида энергией природы. Атаки ближнего боя [ S03 – настройка и отмена пассивных эффектов – друид : и заклинания, примененные не мгновенно ] с некоторой вероятностью дают друиду эффект \"Ясность мысли\", который снижает затраты маны, ярости или энергии на следующую атакующую способность, исцеляющее или наносящее урон заклинание на 100%. Время действия – 10 мин.\n(Восстановление: 10с)"},
