[16969] = {name = "[q2]Изысканный ториевый секач", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (20), Большой опал (2), Массивный шлифовальный камень (2), Грубая кожа (4)\n[q2]Изысканный ториевый секач\nСтановится персональным при поднятии\nПравая рука Топор\nУрон: 43-81 Скорость 1.90\n(32.63 ед. урона в секунду)\n+10 к силе\nПрочность: 75 / 75\nТребуется"},
[16970] = {name = "[q3]Лезвие Рассвета", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (30), Зачарованный ториевый слиток (4), Звездный рубин (4), Синий сапфир (4), Массивный шлифовальный камень (2), Грубая кожа (4)\n[q3]Лезвие Рассвета\nСтановится персональным при надевании\nОдноручное Топор\nУрон: 53-100 Скорость 2.10\n(36.43 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%."},
[16971] = {name = "[q2]Огромный ториевый боевой топор", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (40), Массивный шлифовальный камень (6), Грубая кожа (6)\n[q2]Огромный ториевый боевой топор\nСтановится персональным при надевании\nДвуручное Топор\nУрон: 114-172 Скорость 3.30\n(43.33 ед. урона в секунду)\nПрочность: 85 / 85\nТребуется\n[q2]Если на персонаже: Двуручные топоры +10."},
[16972] = {name = "Удары хищника", additional_info = "[q]Увеличивает силу атаки ближнего боя на 50% от уровня в облике кошки, медведя или лютого медведя."},
[16973] = {name = "[q3]Зачарованный боевой молот", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (20), Зачарованный ториевый слиток (6), Огромный изумруд (2), Мощный амулет (4), Грубая кожа (4)\n[q3]Зачарованный боевой молот\nСтановится персональным при надевании\nДвуручное Дробящее\nУрон: 100-150 Скорость 2.60\n(48.08 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Если на персонаже: Увеличение рейтинга парирования атак на 1%.\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 2%."},
[16974] = {name = "Удары хищника", additional_info = "[q]Увеличивает силу атаки ближнего боя на 100% от уровня в облике кошки, медведя или лютого медведя."},
[16975] = {name = "Удары хищника", additional_info = "[q]Увеличивает силу атаки ближнего боя на 150% от уровня в облике кошки, медведя или лютого медведя."},
[16978] = {name = "[q3]Пылающая рапира", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗачарованный ториевый слиток (10), Субстанция Огня (4), Сердце огня (4), Азеротский алмаз (2), Массивный шлифовальный камень (2)\n[q3]Пылающая рапира\nСтановится персональным при надевании\nОдноручное Меч\nУрон: 44-82 Скорость 1.70\n(37.06 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Возможный эффект при попадании: Обжигание противника с нанесением ему 100 ед. урона в течение 30 сек."},
[16979] = {name = "Звериная атака", additional_info = "{Ярость: 5} {Радиус действия: 8 - 25 м}\n{Мгновенное действие} {Восстановление: 15 сек}\nТребуется: Облик медведя, Облик лютого медведя\n[q]Бросается к противнику, обездвиживая его и прерывая применение заклинаний на 4 сек."},
[16980] = {name = "[q2]Рунный конец", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (30), Большой опал (2), Массивный шлифовальный камень (2), Грубая кожа (4)"},
[16982] = {name = "Шар огня", additional_info = "Мгновенное действие\n[q]Заклинание дает шанс нанести противнику 50 в 70 ед. урона от огня.\n(Вероятность срабатывания: 1%)"},
[16983] = {name = "[q3]Безмятежность", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗачарованный ториевый слиток (6), Арканитовый слиток (2), Мощный амулет (4), Большой опал (2), Синий сапфир (2), Огромный изумруд\n[q3]Безмятежность\nСтановится персональным при надевании\nПравая рука Дробящее\nУрон: 52-98 Скорость 2.00\n(37.50 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Возможный эффект при попадании: Снимает магический эффект с текущего противника."},
[16984] = {name = "[q2]Вулканический молот", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (30), Сердце огня (4), Звездный рубин (4), Грубая кожа (4)\n[q2]Вулканический молот\nСтановится персональным при надевании\nПравая рука Дробящее\nУрон: 60-113 Скорость 2.50\n(34.60 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется\n[q2]Возможный эффект при попадании: Бросок огненного шара, который наносит 100 в 128 ед. урона от огня единовременно и 18 ед. урона от огня в течение 6 сек."},
[16985] = {name = "[q3]Порча", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (40), Арканитовый слиток (2), Демоническая руна (16), Субстанция Нежити (8), Синий сапфир (2), Массивный шлифовальный камень (2), Грубая кожа (4)\n[q3]Порча\nСтановится персональным при поднятии\nДвуручное Меч\nУрон: 119-179 Скорость 3.00\n(49.67 ед. урона в секунду)\n+30 к силе\n+30 к выносливости\n-40 к духу\nПрочность: 100 / 100\nТребуется"},
[16986] = {name = "[q3]Кровавый коготь", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗачарованный ториевый слиток (10), Арканитовый слиток (10), Демоническая руна (8), Звездный рубин (10), Массивный шлифовальный камень (2)"},
[16987] = {name = "[q3]Черное копье", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗачарованный ториевый слиток (20), Мощный амулет (20), Огромный изумруд (2), Азеротский алмаз (2), Массивный шлифовальный камень (2)"},
[16988] = {name = "[q3]Молот Титанов", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (50), Арканитовый слиток (15), Охранный камень (4), Зачарованная кожа (6), Субстанция Земли (10)\n[q3]Молот титанов\nСтановится персональным при надевании\nДвуручное Дробящее\nУрон: 163-246 Скорость 3.80\n(53.82 ед. урона в секунду)\n+15 к силе\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Оглушение цели на 3 сек."},
[16989] = {name = "Установка знамени", additional_info = "Радиус действия: 20 м\nПрименение: 2.3 сек\n[q]Установка знамени Плети в лагере Алого ордена в Западном Лихоземье."},
[16990] = {name = "[q3]Арканитовый защитник", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (15), Азеротский алмаз (8), Сфера Праведности , Большой опал (4), Зачарованная кожа (8), Массивный шлифовальный камень (2)\n[q3]Арканитовый защитник\nСтановится персональным при надевании\nДвуручное Меч\nУрон: 129-194 Скорость 3.00\n(53.83 ед. урона в секунду)\nПрочность: 100 / 100\nТребуется\n[q2]Возможный эффект при попадании: Исцеление себя на 270 в 450 ед. и повышение силы на 120 ед. на 30 сек."},
[16991] = {name = "[q3]Аннигилятор", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевый слиток (40), Арканитовый слиток (12), Субстанция Нежити (10), Огромный изумруд (8), Массивный шлифовальный камень (2), Зачарованная кожа (4)\n[q3]Аннигилятор\nСтановится персональным при надевании\nПравая рука Топор\nУрон: 49-92 Скорость 1.70\n(41.47 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Возможный эффект при попадании: Ослабление брони противника на 200 ед. Эффект может быть суммирован до 3 раз."},
[16992] = {name = "[q3]Ледяная стража", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (18), Синий сапфир (8), Азеротский алмаз (8), Субстанция Воды (4), Массивный шлифовальный камень (2), Зачарованная кожа (4)\n[q3]Ледяной страж\nСтановится персональным при надевании\nПравая рука Меч\nУрон: 66-124 Скорость 2.30\n(41.30 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Возможный эффект при попадании: Скорость передвижения цели снижается на 30%, а время между атаками возрастает на 25% на 5 сек."},
[16993] = {name = "[q3]Буремолот искуссной работы", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗачарованный ториевый слиток (20), Огромный изумруд (8), Большой опал (8), Субстанция Земли (6), Зачарованная кожа (4)\n[q3]Буремолот искусной работы\nСтановится персональным при надевании\nПравая рука Дробящее\nУрон: 58-108 Скорость 2.00\n(41.50 ед. урона в секунду)\nПрочность: 90 / 90\nТребуется\n[q2]Возможный эффект при попадании: Поражение целей числом до 3 с нанесением 105 в 145 ед. урона от сил природы."},
[16994] = {name = "[q3]Арканитовый жнец", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (20), Зачарованная кожа (6), Массивный шлифовальный камень (2)\n[q3]Арканитовый жнец\nСтановится персональным при надевании\nДвуручное Топор\nУрон: 153-256 Скорость 3.80\n(53.82 ед. урона в секунду)\n+13 к выносливости\nПрочность: 100 / 100\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 62."},
[16995] = {name = "[q3]Искатель сердец", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (10), Зачарованный ториевый слиток (10), Зачарованная кожа (2), Звездный рубин (6), Азеротский алмаз (6), Большой опал (6), Массивный шлифовальный камень (4)\n[q3]Искатель сердец\nСтановится персональным при надевании\nУникальныйОдноручное Кинжал\nУрон: 49-92 Скорость 1.70\n(41.47 ед. урона в секунду)\n+4 к силе\nПрочность: 65 / 65\nТребуется\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%."},
[16996] = {name = "Воспламеняющий порошок", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Бросьте Воспламеняющий порошок в священный костер жизни."},
[16997] = {name = "Удар горгульи", additional_info = "Радиус действия: 40 м\nПрименение: 1.5 сек\n[q]Нанесение противнику урона от сил природы."},
