[17137] = {name = "Быстрое исцеление", additional_info = "{Мана: 125} {Радиус действия: 40 м}\nПрименение: 1.5 сек\n[q]Воззвание к светлой магии для исцеления союзника."},
[17138] = {name = "Быстрое исцеление", additional_info = "{Мана: 125} {Радиус действия: 40 м}\nПрименение: 1.5 сек\n[q]Воззвание к светлой магии для исцеления союзника."},
[17139] = {name = "Слово Силы: Щит", additional_info = "{Мана: 110} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника щитом, действующим в течение 30 сек. и поглощающим 274 ед. физического или магического урона. Пока действует щит, физические атаки не прервут чтения заклинаний."},
[17140] = {name = "Священный огонь", additional_info = "{Мана: 115} {Радиус действия: 30 м}\nПрименение: 5 сек\n[q]Противника охватывает пламя, обжигая и нанося дополнительный урон от огня раз в 2 сек.. в течение 8 сек."},
[17141] = {name = "Священный огонь", additional_info = "{Мана: 115} {Радиус действия: 30 м}\nПрименение: 5 сек\n[q]Противника охватывает пламя, обжигая и нанося дополнительный урон от огня раз в 2 сек.. в течение 8 сек."},
[17142] = {name = "Священный огонь", additional_info = "{Мана: 115} {Радиус действия: 30 м}\nПрименение: 5 сек\n[q]Противника охватывает пламя, обжигая и нанося дополнительный урон от огня раз в 2 сек.. в течение 8 сек."},
[17143] = {name = "Священный удар", additional_info = "{Мана: 75} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Освящение оружия заклинания с нанесением 2 ед. дополнительного урона при следующей атаке. Весь нанесенный урон основан на школе Света."},
[17144] = {name = "Гнев", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Взрыв. Нанесение 80 ед. урона от сил природы."},
[17145] = {name = "Взрывная волна", additional_info = "Мана: 120\nМгновенное действие\n[q]Высвобождает волну пламени, наносящую урон от огня находящимся рядом противникам и снижающую их скорость передвижения на 6 сек."},
[17146] = {name = "Слово Тьмы: Боль", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nМгновенное действие\n[q]Произнесение слова, наносящего противнику урон от темной магии раз в 3 сек. в течение 18 сек."},
[17147] = {name = "Экзорцизм", additional_info = "{Мана: 85} {Радиус действия: 30 м}\nМгновенное действие\n[q]Нанесение урона от светлой магии нежити."},
[17148] = {name = "Мозгоруб", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Ранение цели, наносящее 200 в 300 ед. урона и снижающее ее интеллект на 25 ед. на 30 сек."},
[17149] = {name = "Экзорцизм", additional_info = "{Мана: 85} {Радиус действия: 30 м}\nМгновенное действие\n[q]Нанесение урона от светлой магии нежити."},
[17150] = {name = "Чародейская мощь", additional_info = "{Мана: 90} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышение нанесенного союзником магического урона на 50 ед. в течение 30 мин."},
[17151] = {name = "Барьер Тени", additional_info = "{Мана: 450} {Радиус действия: 30 м}\nМгновенное действие\n[q]Ноносимый союзнику урон от темной магии снижен на 50 ед. в течение 10 мин."},
[17152] = {name = "Судьба", additional_info = "Мгновенное действие\n[q]Увеличивает силу на 200 ед. на 10 сек."},
[17153] = {name = "Кровопускание", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит цели кровоточащую рану, из-за которой она теряет 560 ед. здоровья за 30 сек."},
[17154] = {name = "Зеленая башня", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Нанесение 3 ед. урона от сил природы атакующим при нанесении удара и повышение сопротивления силам природы на 50 в течение 30 сек.\n(Вероятность срабатывания: 3%)"},
[17155] = {name = "Брызганье очищенной водой", additional_info = "Радиус действия: 5 м\nПрименение: 6 сек\n[q]Угасание пламени жаровен Джеденара и снятие их защитной магии."},
[17156] = {name = "Кувалда", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Увеличение урона последующей атаки на 10 ед."},
[17157] = {name = "Грозовое дыхание", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Молнии, наносящие урон от сил природы."},
[17158] = {name = "Отравляющий плевок", additional_info = "Радиус действия: 30 м\nПрименение: 2.5 сек\n[q]Ядовитый плевок, причиняющий вред и наносящий дополнительный урон от сил природы раз в 5 сек. в течение 10 сек."},
[17159] = {name = "Перемещение в Халех", additional_info = nil},
[17160] = {name = "Перемещение в Маз-Торил", additional_info = nil},
[17161] = {name = "Взять пробу из Лунного колодца", additional_info = "Радиус действия: 10 м\nПрименение: 3 сек\n[q]Сюда нужно набрать воды из порченного лунного колодца в Джеденаре."},
[17162] = {name = "Призыв элементаля воды", additional_info = nil},
[17163] = {name = "Исчезновение механического йети", additional_info = nil},
[17164] = {name = "Призыв гончей из Алого ордена", additional_info = "Мгновенное действие\n[q]Вызов 1 гончей из Алого ордена. Заклинание действует, пока не будет отменено."},
[17165] = {name = "Пытка разума", additional_info = "{Мана: 60} {Радиус действия: 20 м}\nНаправляемое (Применение: 3 сек)\n[q]Нанесение урона от темной магии противнику и снижение скорости его передвижения на 3 сек."},
[17166] = {name = "Освобождение йети Юми", additional_info = "Радиус действия: 15 м\nПрименение: 2 сек\n[q]Выберите друга Юми и освободите механического йети щелчком мыши."},
[17167] = {name = "Синие драконы", additional_info = nil},
[17168] = {name = "Воля Халеха", additional_info = nil},
[17169] = {name = "Вызов скарабея-падальщика", additional_info = nil},
[17170] = {name = "Убийственное жало", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Дополнительный урон от сил природы раз в 2 сек. в течение 12 сек. Чтобы применить такое заклинание, заклинатель должен быть очень тяжело ранен."},
[17171] = {name = "Залп тьмы", additional_info = "Радиус действия: 5 - 30 м\nВосстановление: 6 сек\nТребуется: Оружие дальнего боя\n[q]Нанесение урона от темной магии."},
[17172] = {name = "Сглаз", additional_info = "{Мана: 300} {Радиус действия: 20 м}\nМгновенное действие\n[q]Превращение противника в лягушку. Он теряет спосбность атаковать или творить заклинания на 5 сек."},
[17173] = {name = "Похищение жизни", additional_info = "{Мана: 75} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Похищение 80 ед. здоровья противника за 5 сек. и передача его заклинателю."},
[17174] = {name = "Шокирующий выстрел", additional_info = "Радиус действия: 5 - 30 м\nТребуется: Оружие дальнего боя\n[q]Замедляет цель, снижая скорость ее движения на 50% на 3 сек."},
[17175] = {name = "Сопротивление чарам", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Увеличение на 2 ед. сопротивления тайной магии вашего союзника в течение 1 ч."},
[17176] = {name = "Ключ от клетки пантеры", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Открытие клетки пантеры."},
[17177] = {name = "Печать защиты", additional_info = "{Мана: 30} {Радиус действия: 30 м}\nМгновенное действие\n[q]Защита выбранного участника группы от всех атак на 8 сек., но лишение его возможности самому атаковать и применять способности. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Печать\"."},
[17178] = {name = "Отвага Алекса", additional_info = "[q]Защита +1000. Считайте, что родились заново!"},
[17179] = {name = "Дар жизни", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 20 сек)\n[q]Использование для того, чтобы сделать Раса Ледяного Шепота, лича, смертным."},
[17180] = {name = "Зачарованный торий", additional_info = "Применение: 12.5 сек\nИнструменты: Рунический жезл из истинного серебра\nИнгредиенты:\nТориевый слиток , Сонная пыль (3)\nЗачарованный ториевый слиток"},
[17181] = {name = "Зачарованная кожа", additional_info = "Применение: 12.5 сек\nИнструменты: Рунический жезл из истинного серебра\nИнгредиенты:\nГрубая кожа , Простая Вечная субстанция"},
[17182] = {name = "Зачарованная кожа", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Создание зачарованной кожи для применения в других областях ремесла."},
[17183] = {name = "Яд", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]24 ед. урона от сил природы раз в 3 сек. в течение 15 сек."},
[17184] = {name = "Зачарованный торий", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Создание зачарованного тория для использования в кузнечном деле."},
[17186] = {name = "Рас превращается в мальчика!", additional_info = nil},
[17187] = {name = "[q2]Трансмутация: арканит", additional_info = "{Применение: 25 сек} {Восстановление: 2 дн.}\nИнструменты: Философский камень\nИнгредиенты:\nТориевый слиток , Чародейный кристалл\n[q]Создание слитка арканита из слитка тория и арканитового кристалла.\n[q2]Арканитовый слиток"},
[17188] = {name = "Рецепт: трансмутация арканита", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение трансмутации арканита."},
[17189] = {name = "Живая кровь Ледяного Шепота", additional_info = nil},
[17190] = {name = "Рас Снегошепот - манекен визуального эффекта", additional_info = nil},
[17191] = {name = "Улучшенное обновление", additional_info = "[q]Увеличение на 15% количества здоровья, восполняемого при действии заклинания \"Обновление\"."},
[17194] = {name = "Взрыв разума", additional_info = "{Мана: 110} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Нанесение противнику урона от темной магии, создающее высокий уровень угрозы."},
[17195] = {name = "Ожог", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Обжигает противника, нанося ему урон от огня."},
[17196] = {name = "Расползающийся ивняк", additional_info = "Применение: 1 сек\n[q]Снижение всех характеристик на 20 ед. и нанесение 20 ед. урона от сил природы раз в 3 сек. всем противникам в радиусе в 8 м. от заклинателя в течение 30 сек."},
[17197] = {name = "Червестудень", additional_info = "Мгновенное действие\n[q]Отравление находящихся поблизости противников с нанесением им 203 в 247 ед. мгновенного урона и последующим нанесением 22 в 28 ед. дополнительного урона от сил природы раз в 2 сек. в течение 6 сек."},
[17198] = {name = "Превосходство", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 5 сек}\nТребуется: Оружие ближнего боя\n[q]Дает мгновенное превосходство над противником. Наносит урон от оружия плюс 30 ед. Действует только после того, как цель уклоняется от атаки. \"Превосходство\" нельзя блокировать или парировать; также от него нельзя уклониться."},
[17199] = {name = "Огненная пушка", additional_info = nil},
[17200] = {name = "Зов героя", additional_info = nil},
[17201] = {name = "Рассеивание заклинаний", additional_info = "{Мана: 75} {Радиус действия: 30 м}\nМгновенное действие\n[q]Рассеивает магический эффект на союзнике, снимая с него 1 вредноносное заклинание."},
[17202] = {name = "Отмщение", additional_info = nil},
