[17204] = {name = "Вызов скелета", additional_info = "Применение: 2 сек\n[q]Призыв 1 скелета для сражения на стороне заклинателя в течение 1 мин."},
[17205] = {name = "Огненный эликсир Зимнего Сна", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]Увеличение физического урона, наносимого заклинателем, на 70 ед. на 20 мин."},
[17207] = {name = "Вихрь", additional_info = "Направляемое (Применение: 2 сек)\n[q]Наносит находящимся рядом противникам обычный урон плюс 50 ед. в течение 2 сек."},
[17213] = {name = "Проклятие отмщения", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Снижение духа противника на 25% на 15 мин."},
