[17227] = {name = "Проклятие слабости", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Снижение всего наносимого противником физического урона на 1 ед. в течение 2 мин. Один чернокнижник может наложить проклятие только на одну цель."},
[17228] = {name = "Залп стрел Тьмы", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Силы тьмы, причиняющая урон от темной магии находящимся поблизости противникам."},
[17229] = {name = "Ледопард Зимних Ключей", additional_info = "Применение: 3 сек\n[q]Призыв и освобождение ледопарда Зимних Ключей. Это очень быстрое верховое животное."},
[17230] = {name = "Зараженная рана", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Увеличение физического урона, получаемого противником, на 29 ед. на 5 мин."},
[17231] = {name = "Призыв иллюзорного призрака", additional_info = "Применение: 1 сек\n[q]Призывание 4 Иллюзорных призраков на помощь заклинателю в течение 1 мин."},
[17232] = {name = "Аура благочестия", additional_info = "Мгновенное действие\n[q]Усиление брони ближайших участников группы на 40 ед. на 4 мин. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Аура\"."},
[17233] = {name = "Возложение рук", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Исцеление союзника на то же количество единиц здоровья, что есть у заклинателя. Заклинатель лишается последней маны."},
[17234] = {name = "Удар Тени", additional_info = "{Мана: 135} {Радиус действия: 20 м}\nМгновенное действие\n[q]Мгновенное поражение противника темной магией и нанесение ему урона от темной магии."},
