[17281] = {name = "Удар воина Света", additional_info = "{Мана: 40} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику 75 ед. урона и увеличение получаемого им урона от светлой магии на 30 ед. на каждый эффект \"Удар воина Света\". Эффект может быть применен до 5 раз. Время действия – 30 сек."},
[17283] = {name = "Воспламенитель Дымка", additional_info = "Мгновенное действие\n[q]Нанесение 125 ед. урона от огня всем целям, находящимся в конусе поражения впереди заклинателя."},
[17284] = {name = "Священный удар", additional_info = "{Мана: 75} {Дистанция ближнего боя}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Освящение оружия заклинания с нанесением 3 ед. дополнительного урона при следующей атаке. Весь нанесенный урон основан на школе Света."},
[17285] = {name = "Зачаровывание, Анналы Дарроушира", additional_info = nil},
[17286] = {name = "Молот рыцаря", additional_info = "Мана: 50\nМгновенное действие\n[q]Оглушение находящихся поблизости противников, лишение их возможности двигаться или атаковать в течение 4 сек."},
[17287] = {name = "Взрыв разума", additional_info = "{Мана: 110} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Нанесение противнику урона от темной магии, создающее высокий уровень угрозы."},
