[17613] = {name = "Исцеление тьмой", additional_info = "{Мана: 215} {Радиус действия: 40 м}\nПрименение: 3.5 сек\n[q]Исцеление союзника посредством темной магии."},
[17615] = {name = "Сожжение маны", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nМгновенное действие\n[q]Молния, сжигающая ману. На каждую единицу маны, сожженную молнией, жертва получает 0.5 ед. урона."},
[17616] = {name = "Взрыв трупа", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Взрыв трупа, наносящий 1500 ед. урона от темной магии ближайшим противникам."},
[17617] = {name = "Улучшение брони 400", additional_info = "[q]Броня +400 ед."},
[17618] = {name = "Вызов восставшего лакея", additional_info = "{Мана: 100} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Призывает 1 восставшего лакея помогающих заклинателю в бою в течение 1 мин."},
[17619] = {name = "Алхимический камень", additional_info = "Мгновенное действие\n[q]Усиливает эффекты зелий исцеления и маны на 33%."},
[17620] = {name = "Похищение жизни", additional_info = "{Мана: 75} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Похищение 240 ед. здоровья противника за 5 сек. и передача его заклинателю."},
[17621] = {name = "Отношение - Каэр Дарроу", additional_info = nil},
[17622] = {name = "Призраки Каэр Дарроу", additional_info = nil},
[17623] = {name = "Призраки прошлого", additional_info = nil},
[17624] = {name = "Окаменение", additional_info = "Мгновенное действие\n[q]Вы обращаетесь в камень, что защищает вас от физических атак и заклинаний в течение 1 мин., но в это время вы не можете атаковать, двигаться или творить заклинания. Одновременно действует только один эликсир."},
[17625] = {name = "Нечистая аура", additional_info = "[q]Увеличение скорости передвижения и восполнения здоровья."},
[17626] = {name = "Склянка Титанов", additional_info = "Мгновенное действие\n[q]Увеличение максимального показателя здоровья игрока на 1200 ед. на 2 ч. Эффект сохраняется и после смерти. Одновременно может действовать только один эффект эликсира."},
[17627] = {name = "Очищенная мудрость", additional_info = "Мгновенное действие\n[q]Повышение максимального запаса маны игрока на 2000 ед. на 2 ч. Эффект сохраняется и после смерти. Одновременно может действовать только один эффект эликсира."},
[17628] = {name = "Превосходная мощь", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\n[q]Увеличение урона, наносимого магическими заклинаниями, не более чем на 150 ед. на 2 ч. Одновременно действует только один эликсир. Эффект сохраняется и после смерти."},
[17629] = {name = "Всецветное сопротивление", additional_info = "Мгновенное действие\n[q]Повышение сопротивления всем школам магии на 25 ед. на 2 ч. Эффект сохраняется после смерти и суммируется с другими подобными эффектами. Одновременно может действовать только один эффект эликсира."},
[17630] = {name = "Сожжение маны", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nМгновенное действие\n[q]Молния, сжигающая ману. На каждую единицу маны, сожженную молнией, жертва получает 0.5 ед. урона."},
[17631] = {name = "Завывание душ", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Нанесение находящимся поблизости противникам урона от темной магии."},
[17632] = {name = "[q4]Камень алхимика", additional_info = "Применение: 1 мин\nИнгредиенты:\nСубстанция Огня (8), Субстанция Земли (8), Субстанция Воздуха (8), Субстанция Воды (8), Субстанция Жизни (8), Черный купорос (2), Черный лотос (4)\n[q4]Алхимический камень\nСтановится персональным при поднятии\nУникальныйАксессуар\n+8 к духу\nТребуетАлхимия\n(300)\n[q2]Если на персонаже: Усиливает эффекты зелий исцеления и маны на 33%."},
[17633] = {name = "Средоточие чар", additional_info = "{Мана: 10} {Радиус действия: 30 м}\nМгновенное действие\n[q]Повышение скорости применения заклинаний союзником на 66% на 30 сек."},
[17634] = {name = "Склянка Оцепенения", additional_info = "Применение: 25 сек\nИнструменты: Философский камень\nИнгредиенты:\nМасло каменного угря (30), Горный серебряный шалфей (10), Черный лотос , Хрустальная колба\nНастой окаменения\nТребуется\n[q2]Использование: Вы обращаетесь в камень, что защищает вас от физических атак и заклинаний в течение 1 мин., но в это время вы не можете атаковать, двигаться или творить заклинания. Одновременно действует только один эликсир. (3 Сек Восстановление)"},
[17635] = {name = "Склянка Титанов", additional_info = "Применение: 25 сек\nИнгредиенты:\nКровь Грома (30), Масло каменного угря (10), Черный лотос , Хрустальная колба\nНастой титанов\nТребуется\n[q2]Использование: Увеличение максимального показателя здоровья игрока на 1200 ед. на 2 ч. Эффект сохраняется и после смерти. Одновременно может действовать только один эффект эликсира. (3 Сек Восстановление)"},
[17636] = {name = "Склянка Концентрированной мудрости", additional_info = "Применение: 25 сек\nИнгредиенты:\nСнолист (30), Ледяной зев (10), Черный лотос , Хрустальная колба\nНастой Концентрированной мудрости\nТребуется\n[q2]Использование: Повышение максимального запаса маны игрока на 2000 ед. на 2 ч. Эффект сохраняется и после смерти. Одновременно может действовать только один эффект эликсира. (3 Сек Восстановление)"},
[17637] = {name = "Склянка Великой силы", additional_info = "Применение: 25 сек\nИнгредиенты:\nСнолист (30), Горный серебряный шалфей (10), Черный лотос , Хрустальная колба\nНастой великой силы\nТребуется\n[q2]Использование: Увеличение урона, наносимого магическими заклинаниями, не более чем на 150 ед. на 2 ч. Одновременно действует только один эликсир. Эффект сохраняется и после смерти. (3 Сек Восстановление)"},
[17638] = {name = "Склянка Разноцветной устойчивости", additional_info = "Применение: 25 сек\nИнгредиенты:\nЛедяной зев (30), Горный серебряный шалфей (10), Черный лотос , Хрустальная колба\nНастой всецветного сопротивления\nТребуется\n[q2]Использование: Повышение сопротивления всем школам магии на 25 ед. на 2 ч. Эффект сохраняется после смерти и суммируется с другими подобными эффектами. Одновременно может действовать только один эффект эликсира. (3 Сек Восстановление)"},
[17639] = {name = "Вой банши", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Уменьшение вероятности нанесения удара на 10% на 12 сек."},
[17640] = {name = "Рецепт: камень алхимика", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению камня алхимика."},
[17641] = {name = "Рецепт: настой окаменения", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению склянки Оцепенения."},
[17642] = {name = "Рецепт: настой титанов", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению склянки Титанов."},
[17643] = {name = "Рецепт: настой Концентрированной мудрости", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению склянки Концентрированной мудрости."},
