[17715] = {name = "Поглощающие тени", additional_info = "Мана: 200\nНаправляемое (Применение: 15 сек)\n[q]Периодическое нанесение заклинателем 200 ед. урона от темной магии всем противникам в выбранной зоне с замедлением скорости их передвижения на 30%. Время действия – 15 сек."},
[17716] = {name = "Поглощающие тени", additional_info = nil},
[17727] = {name = "Создание большого камня чар", additional_info = "Мана: 750\nПрименение: 5 сек\nИнгредиенты:\nОсколок души\n[q]Создание большого камня чар для заклинателя. При использовании камень чар снимает с заклинателя все магические эффекты и поглощает 650 ед. магического урона в течение 1 мин. Помимо этого ношение камня чар повышает вероятность критического удара заклинанием на 1%.\n\n Созданные камни исчезают при выходе из игры на 15 минут."},
[17728] = {name = "Создание крупного камня чар", additional_info = "Мана: 1000\nПрименение: 5 сек\nИнгредиенты:\nОсколок души\n[q]Создание крупного камня чар для заклинателя. При использовании камень чар снимает с заклинателя все магические эффекты и поглощает 900 ед. магического урона в течение 1 мин. Помимо этого ношение камня чар повышает вероятность критического удара заклинанием на 1%.\n\n Созданные камни исчезают при выходе из игры на 15 мин. и более."},
[17729] = {name = "Большой камень чар", additional_info = "Мгновенное действие\n[q]Снимает с заклинателя все магические эффекты и поглощает 650 ед. магического урона в течение 1 мин."},
