[17735] = {name = "Муки", additional_info = "Мана: 150\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Оскорбление всех противников в радиусе 10 м. и увеличение шанса того, что они атакуют демона Бездны."},
