[17738] = {name = "Проклятие чумной крысы", additional_info = "{10% от базовой мана} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Превращение противника в крысу. Противник бегает, нанося 500 ед. урона от сил природы раз в 2 сек. находящимся поблизости союзникам, в течение времени до 14 сек. При этом крыса не может ни атаковать, ни применять заклинания, но очень быстро восполняет здоровье. Проклятие можно накладывать только на одну цель за раз."},
[17739] = {name = "Болезнь", additional_info = nil},
[17740] = {name = "Щит маны", additional_info = "Мана: 40\nМгновенное действие\n[q]Окутывает заклинателя щитом, действующим в течение 1 мин. и поглощающим до 120 ед. физического урона, сжигая ману. Сжигает 2 ед. маны на 1 ед. поглощенного урона."},
[17741] = {name = "Щит маны", additional_info = "Мана: 40\nМгновенное действие\n[q]Окутывает заклинателя щитом, действующим в течение 1 мин. и поглощающим до 120 ед. физического урона, сжигая ману. Сжигает 2 ед. маны на 1 ед. поглощенного урона."},
