[17767] = {name = "Поглощение теней", additional_info = "{Мана: 85} {Дистанция ближнего боя}\nНаправляемое (Применение: 10 сек)\n[q]Демон Бездны поглощает находящиеся поблизости тени и набирается сил, восполняя 310 ед. здоровья в 10 сек. В бою использовать нельзя."},
[17768] = {name = "Волкоголовый шлем", additional_info = "[q]При превращениив кошку, друид получает 20 ед. энергии, при превращении в медведя, друид получает 5 ед. ярости."},
