[17950] = {name = "Портал Тьмы", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\n[q]Телепортация противника в одно из мест (из 6) в Некроситете."},
[17951] = {name = "Создание камня огня", additional_info = "Мана: 700\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает камень огня, который можно взять в левую руку. При оснащении камень огня накладывает на основное оружие чары огня, давая на каждую атаку шанс причинить 40 в 60 ед. урона от огня. Кроме того, оснащение камнем огня увеличивает урон, причиняемый заклинаниями огня, на 14\n\n Сотворенные предметы исчезают, если вы пробыли вне игры более 15 минут."},
[17952] = {name = "Создание большого камня огня", additional_info = "Мана: 900\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает большой камень огня, который можно взять в левую руку. При оснащении камень огня накладывает на основное оружие чары огня, давая на каждую атаку шанс причинить 60 в 90 ед. урона от огня. Кроме того, оснащение крупным камнем огня увеличивает урон, причиняемый заклинаниями огня, на 17\n\n Сотворенные предметы исчезают, если вы пробыли вне игры более 15 минут."},
[17953] = {name = "Создание крупного камня огня", additional_info = "Мана: 1100\nПрименение: 3 сек\nИнгредиенты:\nОсколок души\n[q]Создает крупный камень огня, который можно взять в левую руку. При оснащении камень огня накладывает на основное оружие чары огня, давая на каждую атаку шанс причинить 80 в 120 ед. урона от огня. Кроме того, оснащение крупным камнем огня увеличивает урон, причиняемый заклинаниями огня, на 21\n\n Сотворенные предметы исчезают, если вы пробыли вне игры более 15 минут."},
