[18238] = {name = "Рецепт пятнистого желтохвоста", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырой пятнистый желтохвост\nПятнистый желтохвост\nТребуется\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[18239] = {name = "Рецепт мощь-рыбы в кляре", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырая блестящая мощь-рыба , Ароматные специи\nМощь-рыба в кляре\nТребуется\n[q2]Использование: Восполнение 874.8 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное повышение выносливости на 10 ед. на 10 мин."},
[18240] = {name = "Рецепт жареного кальмара", additional_info = "Применение: 3 сек\nИнгредиенты:\nЗимний кальмар , Ароматные специи\nЖареный кальмар\nТребуется\n[q2]Использование: Восполнение 874.8 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. По истечении 10 сек. действия эффекта персонаж насыщается и его ловкость повышается на 10 ед. на 10 мин."},
[18241] = {name = "Рецепт филе красноперки", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырая краснобородка\nФиле красноперки\nТребуется\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
[18242] = {name = "Рецепт окуня горячего копчения", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырой летний окунь , Острые специи (2)\nОстрый копченый окунь\nТребуется\n[q2]Использование: Восполнение 874.8 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное повышение духа на 10 ед. на 10 мин."},
[18243] = {name = "Рецепт супа из ночницы", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырой черноперый луциан , Освежающая ключевая вода\nСуп из ночницы\nТребуется\n[q2]Использование: Восполнение 874.8 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное восполнение 8 ед. маны раз в 5 сек. в течение 10 мин."},
[18244] = {name = "Рецепт вареного радужного лосося", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырой радужный лосось\nВареный радужный лосось\nТребуется\n[q2]Использование: Восполнение 874.8 ед. здоровья за 27 сек. Действие эффекта прерывается, если персонаж встает с места. Дополнительное восполнение 6 ед. здоровья раз в 5 сек. в течение 10 мин."},
[18245] = {name = "Рецепт похлебки из омаров", additional_info = "Применение: 3 сек\nИнгредиенты:\nТемноклешневый омар , Освежающая ключевая вода\nПохлебка из омаров\nТребуется\n[q2]Использование: Восполняет 2148 ед. здоровья за 30 сек. Действие прерывается, если встать с места."},
