[18530] = {name = "Божественное неистовство", additional_info = "[q]Уменьшает время наложения заклинаний \"Кара\", \"Священный Огонь\", \"Исцеление\" и \"Большее исцеление\" на 0.1 сек."},
[18531] = {name = "Божественное неистовство", additional_info = "[q]Уменьшает время наложения заклинаний \"Кара\", \"Священный Огонь\", \"Исцеление\" и \"Большее исцеление\" на 0.2 сек."},
[18532] = {name = "Выкройка: одеяние истинной веры", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению одеяния Истинной веры."},
[18533] = {name = "Божественное неистовство", additional_info = "[q]Уменьшает время наложения заклинаний \"Кара\", \"Священный Огонь\", \"Исцеление\" и \"Большее исцеление\" на 0.3 сек."},
[18534] = {name = "Божественное неистовство", additional_info = "[q]Уменьшает время наложения заклинаний \"Кара\", \"Священный Огонь\", \"Исцеление\" и \"Большее исцеление\" на 0.4 сек."},
[18535] = {name = "Божественное неистовство", additional_info = "[q]Уменьшает время наложения заклинаний \"Кара\", \"Священный Огонь\", \"Исцеление\" и \"Большее исцеление\" на 0.5 сек."},
[18536] = {name = "Выкройка: одеяние верховного мага", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению одеяния верховного мага."},
[18537] = {name = "Выкройка: одеяние Бездны", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению одеяния Бездны."},
[18540] = {name = "Ритуал Рока", additional_info = "{100% от базовой мана} {Радиус действия: 30 м}\n{Применение: 10 сек} {Восстановление: 1 час}\nИнгредиенты:\nДемоническая статуэтка\n[q]Ритуал, в ходе которого один из участников приносится в жертву, что позволяет призвать стражника ужаса. Стражника ужаса нужно немедленно поработить, иначе он набросится на участников. Для ритуала требуется заклинатель и еще 4 участника группы. Чтобы начать ритуал, все игроки должны щелкнуть по порталу правой кнопкой мыши и не двигаться до тех пор, пока ритуал не закончится."},
[18541] = {name = "Эффект Ритуала Рока", additional_info = nil},
[18542] = {name = "Жертвенный огонь", additional_info = "(Вероятность срабатывания: 10%)"},
[18543] = {name = "Пламенный кнут", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Заклинание обжигает противника и наносит дополнительный урон от огня каждые 3 сек. в течение 21 сек."},
[18544] = {name = "Сила воли", additional_info = "[q]Увеличение на 1% урона, наносимого заклинаниями, и на 1% вероятности критического эффекта атакующих заклинаний."},
[18545] = {name = "Жало скорпида", additional_info = "{Мана: 10} {Радиус действия: 5 - 30 м}\nТребуется: Оружие дальнего боя\n[q]Жало, снижающее силу и ловкость противника на 1 ед. на 20 сек."},
[18546] = {name = "Активность", additional_info = "Мгновенное действие\n[q]Обездвиживание заклинателя, но увеличение скорости его атак на 100% на 6 сек."},
[18547] = {name = "Сила воли", additional_info = "[q]Увеличение на 2% урона, наносимого заклинаниями, и на 2% вероятности критического эффекта атакующих заклинаний."},
[18548] = {name = "Сила воли", additional_info = "[q]Увеличение на 3% урона, наносимого заклинаниями, и на 3% вероятности критического эффекта атакующих заклинаний."},
[18549] = {name = "Сила воли", additional_info = "[q]Увеличение на 4% урона, наносимого заклинаниями, и на 4% вероятности критического эффекта атакующих заклинаний."},
[18550] = {name = "Сила воли", additional_info = "[q]Увеличение на 5% урона, наносимого заклинаниями, и на 5% вероятности критического эффекта атакующих заклинаний."},
[18551] = {name = "Сила мысли", additional_info = "[q]Повышение максимального запаса маны на 2%."},
[18552] = {name = "Сила мысли", additional_info = "[q]Повышение максимального запаса маны на 4%."},
[18553] = {name = "Сила мысли", additional_info = "[q]Повышение максимального запаса маны на 6%."},
