[18555] = {name = "Сила мысли", additional_info = "[q]Повышение максимального запаса маны на 10%."},
[18556] = {name = "Ярость берсерка", additional_info = nil},
[18557] = {name = "Похищение жизни", additional_info = "{Мана: 75} {Радиус действия: 20 м}\nНаправляемое (Применение: 5 сек)\n[q]Похищение 80 ед. здоровья противника за 5 сек. и передача его заклинателю."},
[18559] = {name = "Кирка демона", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Кирка демона для уничтожения кристалла демона."},
[18560] = {name = "Луноткань", additional_info = "{Применение: 1 мин} {Восстановление: 4 дн.}\nИнгредиенты:\nТкань Скверны (2)\n[q]Превращение ткани Скверны в луноткань может производиться только в лунном колодце, и лишь порой воды позволяют это."},
[18561] = {name = "Выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел в противника с нанесением ему физического урона."},
[18562] = {name = "Быстрое восстановление", additional_info = "{20% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q][ S03 – настройка и отмена пассивных эффектов – друид : Мгновенно восполняет здоровье цели с активным эффектом \"Омоложение\" или \"Восстановление\" / Поглощает эффект \"Омоложения\" или \"Восстановления\" на союзнике, мгновенно восполняя ему здоровье] в объеме, соответствующем 12 сек. действия \"Омоложения\" или 18 сек. действия \"Восстановления\"."},
[18563] = {name = "Ритуал: лунная ткань", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение очищению ткани Скверны и превращению ее в луноткань."},
