[18633] = {name = "Ослабляющая болезнь", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение 8 ед. урона от темной магии раз в 2 сек. в течение 30 сек. и понижение силы противника на весь период болезни."},
[18634] = {name = "Манекен цели - событие 1", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Установка на земле манекена-мишени, который будет притягивать к себе монстров. Длительность - 3 мин."},
[18647] = {name = "Изгнание", additional_info = "{Мана: 200} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Изгнание противника на время до 30 сек. В течение этого времени противник не может участвовать в событиях, однако становится неуязвим. Заклинание можно применять только против одного противника за раз. Действует только на демонов и элементалей."},
[18648] = {name = "Изгнание", additional_info = nil},
[18649] = {name = "Залп тьмы", additional_info = "Радиус действия: 5 - 30 м\nВосстановление: 6 сек\nТребуется: Оружие дальнего боя\n[q]Нанесение урона от темной магии."},
[18650] = {name = "Вызов Мардука Черного", additional_info = nil},
[18651] = {name = "Залп", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Обрушивание на противника и его ближайших союзников града снарядов с поражением целей в количестве 3 и нанесением им плюс 75 к обычному урону."},
[18652] = {name = "Вытягивание здоровья", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Нанесение 30 ед. урона от темной магии раз в 3 сек. в течение 15 сек. Нанесенный урон передается заклинателю."},
[18653] = {name = "Вытягивание здоровья", additional_info = nil},
[18654] = {name = "Вытягивание здоровья", additional_info = nil},
[18655] = {name = "Анимация мортиры", additional_info = nil},
[18656] = {name = "Порча", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Наложение на цель порчи, наносящей 210 ед. урона в течение 3 сек."},
[18657] = {name = "Спячка", additional_info = "{Мана: 120} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Усыпление противника на время до 30 сек. Любой нанесенный урон пробуждает цель. За один раз можно усыпить только одну цель. Действует только на зверей, а также драконов и их родичей."},
[18658] = {name = "Спячка", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Усыпление противника на время до 40 сек. Любой нанесенный урон пробуждает цель. За один раз можно усыпить только одну цель. Действует только на зверей, а также драконов и их родичей."},
[18659] = {name = "Спячка", additional_info = nil},
[18660] = {name = "Спячка", additional_info = nil},
[18661] = {name = "Оберег Араджа", additional_info = nil},
[18662] = {name = "Проклятие рока - воздействие", additional_info = nil},
[18663] = {name = "Удар Тени", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Мгновенное поражение противника темной магией и нанесение ему урона от темной магии."},
[18664] = {name = "Выкройка: ярко-желтая рубашка", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению ярко-желтой рубашки."},
[18665] = {name = "Выкройка: клобук волшебника", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению клобука волшебника."},
[18666] = {name = "Осквернение Крассена", additional_info = nil},
[18667] = {name = "Рецепт: масло льда", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению масла льда."},
[18668] = {name = "Выкройка: украшенный самоцветами кожаный пояс", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению украшенного самоцветами кожаного пояса."},
[18669] = {name = "Чертеж: малый атомарный перенаправлятор", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению младшего перенаправлятора."},
[18670] = {name = "Отталкивание", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение противнику увеличенного на 30 ед. стандартного урона и отбрасывание его назад."},
[18671] = {name = "Проклятие агонии", additional_info = "{Мана: 50} {Радиус действия: 30 м}\nМгновенное действие\n[q]Невыносимые страдания, наносящие урон от темной магии раз в 3 сек. в течение 30 сек. Один чернокнижник может наложить на каждую цель только одно проклятие."},
