[18975] = {name = "Создать тотем льда", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Создание тотема льда, который на протяжении 1 мин. наносит урон от магии льда всем противникам раз в 3 сек., замеляя скорость их атак и передвижения."},
