[19509] = {name = "Специализация на оружии дальнего боя", additional_info = "Требуется: Оружие дальнего боя\n[q]Повешение урона, наносимого оружием дальнего боя, на 3%."},
[19510] = {name = "Специализация на оружии дальнего боя", additional_info = "Требуется: Оружие дальнего боя\n[q]Повешение урона, наносимого оружием дальнего боя, на 4%."},
[19511] = {name = "Специализация на оружии дальнего боя", additional_info = "Требуется: Оружие дальнего боя\n[q]Повешение урона, наносимого оружием дальнего боя, на 5%."},
[19512] = {name = "Применение мази", additional_info = "Радиус действия: 5 м\nПрименение: 1.3 сек\nИнструменты: Мазь исцеления животных\n[q]Исцеление больного животного, подвергшегося воздействию яда."},
[19513] = {name = "Грозовая туча", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 40 сек}\n[q]Грозовое облако, которое держится 15 сек., поражая всех противников в избранной игровой зоне с нанесением 28 в 32 ед. урона от сил природы и нанося 42 в 48 дополнительного урона раз в 5 сек."},
[19514] = {name = "Щит молний", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]3 шаровых молний, окружающих заклинателя. 50% вероятность нанести 2 ед. урона противникам, атакующим в ближнем или дальнем бою. Каждый раз, как щит срабатывает, одна из молний рассеивается. Таким образом, щит перестает действовать через 10 мин., либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[19515] = {name = "Инициатор ярости", additional_info = nil},
[19516] = {name = "Исступление", additional_info = nil},
