[19666] = {name = "[q2]Серебряная отмычка", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСеребряный слиток , Грубый шлифовальный камень\n[q2]Серебряная отмычка\n(2)\nТребуетКузнечное дело\n(100)\n[q2]Использование: Позволяет открывать простые замки. Возможно лишь однократное использование."},
[19667] = {name = "[q2]Золотая отмычка", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nЗолотой слиток , Тяжелый шлифовальный камень\n[q2]Золотая отмычка\n(2)\nТребуетКузнечное дело\n(150)\n[q2]Использование: Позволяет отпирать стандартные замки. В процессе отмычка поглощается."},
[19668] = {name = "[q2]Отмычка из истинного серебра", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток истинного серебра , Твердый шлифовальный камень\n[q2]Отмычка из истинного серебра\n(2)\nТребуетКузнечное дело\n(200)\n[q2]Использование: Отпирание сложных замков, для каждого из которых требуется отмычка."},
[19669] = {name = "[q2]Арканитовая отмычка", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток , Массивный шлифовальный камень\n[q]Возможность отпирать сложные замки. После отпирания отмычка исчезает.\n[q2]Арканитовая отмычка\n(2)\nТребуетКузнечное дело\n(275)\n[q2]Использование: Возможность отпирать сложные замки. После отпирания отмычка исчезает."},
