[19687] = {name = "Приручение снежного леопарда", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение снежного леопарда, который будет вашим спутником на протяжении 10 мин. Если вы по какой-то причине теряете внимание животного, процесс приручения прерывается."},
[19688] = {name = "Приручение взрослого долгонога", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение взрослого долгонога, который будет вашим спутником на протяжении 10 мин. Если вы по какой-то причине теряете внимание животного, процесс приручения прерывается."},
[19689] = {name = "Приручение волка прерий", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение волка прерий, который будет вашим спутником на протяжении 10 мин. Если вы по какой-то причине теряете внимание животного, процесс приручения прерывается."},
[19690] = {name = "Алая иллюзия", additional_info = "Мгновенное действие\n[q]Используется для принятия заклинателем облика участника Алого ордена."},
[19691] = {name = "Убийство животных 18", additional_info = "[q]Увеличение на 18 ед. силы атаки в бою с животными."},
[19692] = {name = "Приручение перепелятника", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение перепелятника, который будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19693] = {name = "Приручение чащобного тенетника", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручения чащобного тенетника на 10 мин. Если вы по какой-то причине теряете внимание животного, процесс приручения прерывается."},
[19694] = {name = "Приручение лютого пятнистого вепря.", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение перепелятника, который будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19695] = {name = "Инфернал", additional_info = "Мгновенное действие\n[q]Окружает заклинателя инфернальной аурой, которая периодически наносит урон от огня ближайшим противникам в течение 8 сек. При этом заклинатель не может двигаться или применять свои навыки."},
[19696] = {name = "Приручение приливного краба", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение приливного краба будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19697] = {name = "Приручение бронескорпа", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение бронескорпа, который будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19698] = {name = "Инфернал", additional_info = nil},
[19699] = {name = "Приручение ночного саблезуба", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение ночного саблезуба, который будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19700] = {name = "Приручение совиного крикуна", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 20 сек)\n[q]Приручение совиного крикуна, который будет вашим спутником на протяжении 10 мин. Если животное по какой-то причине отвлекается от вас, процесс приручения прерывается."},
[19701] = {name = "Валун", additional_info = "Радиус действия: 5 - 30 м\nПрименение: 3 сек\n[q]Бросок валуна в противника, отбрасывающий его назад и наносящий физический урон."},
[19702] = {name = "Надвигающийся рок", additional_info = "Мгновенное действие\n[q]Нанесение 2000 ед. урона от темной магии находящимся рядом противникам через 10 сек."},
[19703] = {name = "Проклятие Люцифрона", additional_info = "Мгновенное действие\n[q]Проклятие находящихся рядом противников: увеличение затрат на их заклинания и умения на 100% в течение 5 мин. Повышение затрат касается всех заклинаний и умений, вне зависимости от того, тратится ли на них мана, ярость или энергия."},
[19704] = {name = "Призыв элементаля земли", additional_info = "Мгновенное действие\n[q]Призывает 1 элементаля земли, помогающего заклинателю до тех пор, пока он не откажется от сопровождения."},
[19705] = {name = "Сытость", additional_info = nil},
[19706] = {name = "Сытость", additional_info = nil},
[19707] = {name = "Уровень ненависти достигает 50%", additional_info = nil},
[19708] = {name = "Сытость", additional_info = nil},
