[19712] = {name = "Чародейский взрыв", additional_info = "Применение: 0.5 сек\n[q]Заклинатель пускает магическую взрывную волну, наносящую 800 ед. урона от тайной магии ближайшим противникам."},
[19713] = {name = "Проклятье Шаззраха", additional_info = "Мгновенное действие\n[q]Увеличение магического урона, наносимого ближайшим противникам, на 100% в течение 5 мин."},
[19714] = {name = "Магическое заземление", additional_info = "Мана: 250\nМгновенное действие\n[q]Снижение полученного заклинателем магического урона на 50% в течение 30 сек."},
[19715] = {name = "Антимагия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Противодействие заклинанию противника. Предотвращение применения любого заклинания данной школы магии в течение 10 сек. Создание высокой угрозы."},
[19716] = {name = "Проклятие Гееннаса", additional_info = "Мгновенное действие\n[q]Снижение действующих на противников целительных эффектов на 75% на 5 мин."},
[19717] = {name = "Огненный ливень", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Призывание лавового дождя, обжигающего всех противников на выбранном участке с 925 в 1075 ед. урона от огня раз в 2 сек. в течение до отмены."},
[19719] = {name = "Использовать блесну", additional_info = "Радиус действия: 5 м\nПрименение: 3 сек\n[q]Завершение водного испытания на время в Святилище Ремулоса."},
[19720] = {name = "Собирание подвесок", additional_info = "Радиус действия: 5 м\nПрименение: 3 сек\nИнгредиенты:\nПоловинка подвески Выносливости водяного облика\n[q]Сложение с половинкой подвески Выносливости водяного облика, чтобы создать подвеску Морского Льва."},
[19721] = {name = "Воскресение бойца", additional_info = nil},
[19722] = {name = "Призыв бойца из Алого ордена", additional_info = nil},
[19723] = {name = "Усовершенствованный манекен-мишень - событие 3", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Установка на земле манекена-мишени, который будет притягивать к себе монстров. Время действия – 3 минуты."},
[19725] = {name = "Изгнание нежити", additional_info = "{Мана: 75} {Радиус действия: 20 м}\nПрименение: 1.5 сек\n[q]Противник-нежить спасается бегством в течение времени до 20 сек. Обратить в бегство можно только одну цель за раз."},
[19726] = {name = "Аура сопротивления", additional_info = "Мгновенное действие\n[q]Увеличение у находящихся поблизости участников группы сопротивления ко всем школам магии на 1 ед. на до отмены."},
[19727] = {name = "Водяные миазмы", additional_info = nil},
[19728] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 40 м\nПрименение: 0.5 сек\n[q]Выстрел во врага магической стрелой, наносящей 2250 в 2750 ед. урона от темной магии."},
[19729] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 40 м\nПрименение: 0.5 сек\n[q]Выстрел во врага магической стрелой, наносящей 2250 в 2750 ед. урона от темной магии."},
[19730] = {name = "Разящий удар", additional_info = "Дистанция ближнего боя\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Нанесение врагу обычного урона плюс 25 ед."},
[19731] = {name = "Пожирание магии", additional_info = "{Мана: 130} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Снятие 1 магического отрицательного эффекта с товарища или 1 магического отрицательного эффекта с противника. При поглощении эффекта охотник Скверны получит 348 ед. здоровья."},
[19732] = {name = "Поглощение магического эффекта", additional_info = nil},
[19733] = {name = "Поглощение магического эффекта", additional_info = nil},
[19734] = {name = "Пожирание магии", additional_info = "{Мана: 170} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Снятие 1 магического отрицательного эффекта с товарища или 1 магического отрицательного эффекта с противника. При поглощении эффекта охотник Скверны получит 473 ед. здоровья."},
[19735] = {name = "Поглощение магического эффекта", additional_info = nil},
[19736] = {name = "Пожирание магии", additional_info = "{Мана: 215} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Снятие 1 магического отрицательного эффекта с товарища или 1 магического отрицательного эффекта с противника. При поглощении эффекта охотник Скверны получит 619 ед. здоровья."},
[19737] = {name = "Пожирание магии", additional_info = nil},
[19738] = {name = "Пожирание магии", additional_info = nil},
[19739] = {name = "Пожирание магии", additional_info = nil},
[19740] = {name = "Благословение могущества", additional_info = "{Мана: 20} {Радиус действия: 30 м}\nМгновенное действие\n[q]Накладывает на дружественную цель благословение, увеличивающее силу атаки ближнего боя на 20. Эффект длится 5 мин. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[19741] = {name = "Благословение могущества", additional_info = nil},
[19742] = {name = "Благословение мудрости", additional_info = "{Мана: 30} {Радиус действия: 30 м}\nМгновенное действие\n[q]Наложение на дружескую цель благословения, в течение 5 мин. восполняющего 10 ед. маны раз в 5 сек. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[19743] = {name = "Благословение мудрости", additional_info = nil},
[19746] = {name = "Аура сосредоточенности", additional_info = "Мгновенное действие\n[q]Придание 35% шанса игнорировать прерывание заклинания при получении урона для всех участников группы в радиусе 30 м. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Аура\"."},
[19747] = {name = "Аура сосредоточенности", additional_info = nil},
[19748] = {name = "Аура харизмы", additional_info = "Мгновенное действие\n[q]Уменьшение расстояния, на котором монстры могу атаковать участников группы, находящихся в радиусе 30 м. Каждый паладин единовременно может накладывать на игроков только одно заклинание категории \"Аура\"."},
[19749] = {name = "Удар солдата", additional_info = nil},
[19750] = {name = "Вспышка Света", additional_info = "{Мана: 35} {Радиус действия: 40 м}\nПрименение: 1.5 сек\n[q]Исцеление дружественной цели на 67 в 77 ед."},
[19751] = {name = "Вспышка Света", additional_info = nil},
[19752] = {name = "Божественное вмешательство", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 1 час}\nИнгредиенты:\nЗнак божественности\n[q]Паладин жертвует собой, чтобы отвести опасность от выбранного участника группы. Противник прекращает атаковать того, кто находится под защитой, Защищанная цель неуязвима для всех приноясщих урон атак, но не может предпринимать никаких действий в течение 3 мин."},
[19753] = {name = "Божественное вмешательство", additional_info = nil},
[19754] = {name = "Божественное вмешательство", additional_info = nil},
[19755] = {name = "Жуткокоготь", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\n[q]Снижение всех характеристик на 10 ед. на 1 мин."},
[19767] = {name = "Лук Айнаши", additional_info = "Радиус действия: 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел в противника с нанесением ему физического урона."},
[19768] = {name = "Караван Гизлтона", additional_info = nil},
[19769] = {name = "Ториевая граната", additional_info = "Радиус действия: 45 м\nПрименение: 1 сек\n[q]Нанесение 300 в 500 ед. урона от огня и оглушение целей на 3 сек. в радиусе 3 м. Любой нанесенный урон прекратит действие эффекта."},
[19770] = {name = "Караван Гизлтона", additional_info = nil},
[19771] = {name = "Рваная рана", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение противнику 1500 ед. физического урона за 30 сек."},
[19772] = {name = "Вызов реалистичной жабы", additional_info = "Применение: 1 сек\n[q]Призыв и освобождение жабы как живая по щелчку правой кнопкой мыши."},
[19773] = {name = "Первородный огонь", additional_info = nil},
[19774] = {name = "Призвание Рагнароса", additional_info = nil},
[19775] = {name = "Исцеление тьмой", additional_info = "Мана: 500 Неограниченное расстояние\nПрименение: 2.5 сек\n[q]Излечение 27750 в 32250 ед. повреждений, полученных товарищем, при помощи темной магии."},
[19776] = {name = "Слово Тьмы: Боль", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nМгновенное действие\n[q]Произнесение слова, наносящего противнику урон от темной магии раз в 3 сек. в течение 18 сек."},
[19777] = {name = "Темный удар", additional_info = "{Мана: 250} {Радиус действия: 10 м}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Наделение оружия заклинателя силой, позволяющей наносить 570 в 630 ед. дополнительного урона в следующей атаке. Весь наносимый урон считается уроном от темной магии."},
[19778] = {name = "Деморализующий крик", additional_info = "Мгновенное действие\n[q]Уменьшает силу атаки ближайших противников в ближнем и дальнем бою на 300 ед. на 30 сек."},
[19779] = {name = "Воодушевить", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличение физического урона, причиняемого союзником, на 25% и ускорение его атак на 100% в течение 10 сек."},
[19780] = {name = "Рука Рагнароса", additional_info = "Мгновенное действие\n[q]Нанесение 300 в 400 ед. урона от огня ближайшим противникам, отбрасывание их назад и оглушение на 2 сек."},
[19781] = {name = "Пламенное копье", additional_info = "Радиус действия: 45 м\nМгновенное действие\n[q]Бросок копья пламени, наносящий противнику 850 в 1150 ед. урона от огня, а также обжигающий других противников, находящихся поблизости от цели."},
[19784] = {name = "Бомба из черного железа", additional_info = "Радиус действия: 15 м\nПрименение: 1 сек\n[q]Нанесение 225 в 675 ед. урона от огня и оглушение целей в радиусе 5 м. на 4 сек. Любой урон снимает воздействие."},
[19785] = {name = "Бросок", additional_info = "Радиус действия: 8 - 40 м\nМгновенное действие\n[q]Бросает оружие в противника, нанося 2125 в 2875 ед. урона."},
[19786] = {name = "Сопротивление Безмолвию", additional_info = "[q]Повышение на 7% сопротивления эффектам, лишающим дара речи."},
[19787] = {name = "Улучшение брони 110", additional_info = "[q]Броня +110 ед."},
[19788] = {name = "Концентрированное взрывчатое вещество", additional_info = "Применение: 8 сек\nИнгредиенты:\nМассивный камень (2)"},
[19790] = {name = "Ториевая граната", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nТориевое устройство , Ториевый слиток (3), Концентрированное взрывчатое вещество (3), Рунная ткань (3)\n(3)\nТребуетИнженерное дело\n(260)\n[q2]Использование: Нанесение 300 в 500 ед. урона от огня и оглушение целей на 3 сек. в радиусе 3 м. Любой нанесенный урон прекратит действие эффекта. (1 Мин Восстановление)"},
[19791] = {name = "Ториевое устройство", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nТориевый слиток (3), Рунная ткань"},
[19792] = {name = "[q2]Ториевая винтовка", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nМифриловая труба (2), Мифриловая обшивка (2), Ториевое устройство (2), Ториевый слиток (4), Смертоносный прицел\n[q2]Ториевая винтовка\nСтановится персональным при надевании\nДальний бой Огнестрельное\nУрон: 42-79 Скорость 2.50\n(24.20 ед. урона в секунду)\nПрочность: 65 / 65\nТребуется\n[q2]Если на персонаже: Увеличение силы атаки в дальнем бою на 17 ед."},
[19793] = {name = "Механическая жаба", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nСубстанция Жизни , Ториевое устройство (4), Золотое силовое ядро , Грубая кожа\nСтановится персональным при использовании\n[q2]Использование: Призыв и освобождение жабы как живая по щелчку правой кнопкой мыши."},
[19794] = {name = "[q2]Экстремальные очки магической силы", additional_info = "Применение: 45 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nЭкстремальные очки силы заклинаний , Звездный рубин (4), Зачарованная кожа (2), Рунная ткань (8)\n[q2]Экстремальные-плюс очки силы заклинаний\nСтановится персональным при надевании\nГолова Ткань\nБроня: 57\nПрочность: 45 / 45\nТребуетИнженерное дело\n(270)\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 27 ед."},
[19795] = {name = "Ториевая труба", additional_info = "Применение: 8 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nТориевый слиток (6)"},
[19796] = {name = "[q3]Винтовка из черного железа", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nТориевая труба (2), Слиток черного железа (6), Смертоносный прицел (2), Синий сапфир (2), Большой опал (2), Грубая кожа (4)\n[q3]Винтовка из черного железа\nСтановится персональным при надевании\nДальний бой Огнестрельное\nУрон: 53-100 Скорость 2.70\n(28.33 ед. урона в секунду)\nПрочность: 75 / 75\nТребуется\n[q2]Если на персонаже: Шанс поразить отдаленную цель теневой молнией и нанести ей 18 в 26 ед. урона от темной магии."},
