[19801] = {name = "Усмиряющий выстрел", additional_info = "{Мана: 270} {Радиус действия: 8 - 35 м}\nВосстановление: 20 сек\nТребуется: Оружие дальнего боя\n[q]Попытка снять 1 эффекта заклинания \"Бешенство\" с враждебного создания."},
