[20294] = {name = "Жертвенный огонь", additional_info = "{Мана: 300} {Радиус действия: 40 м}\nМгновенное действие\n[q]Нанесение 760 в 840 ед. урона от огня противнику единовременно плюс 380 в 420 ед. урона раз в 3 сек. в течение 21 сек."},
[20295] = {name = "Молния", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника молнией, урон от сил природы."},
[20296] = {name = "Огненный столб", additional_info = "{Мана: 260} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Призывает столб пламени, обжигающий всех противников на выбранном участке и наносящий дополнительный урон от огня каждые 2 сек. в течение 8 сек."},
[20297] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 4 сек."},
[20298] = {name = "Стрела Тьмы", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[20299] = {name = "Раздвоенная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Нанесение урона от сил природы противникам, находящимся в конусе перед заклинателем."},
