[20554] = {name = "Боевое исступление", additional_info = "7% от базовой мана\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Увеличение на 10%-30% скорости атаки и применения заклинаний. При полном запасе здоровья увеличение составляет 10%, а при значительных ранениях и в состоянии берсерка увеличение достигает 30%. Время действия – 10 сек."},
[20555] = {name = "Регенерация", additional_info = "[q]Уровень восполнения здоровья увеличен на 10%. 10% восполнения здоровья может продолжаться во время битвы."},
[20556] = {name = "Доверие Големагга", additional_info = nil},
