[20572] = {name = "Кровавое неистовство", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Повышает вашу базовую силу атаки в ближнем бою на 25 на 15 сек и ослабляет действующие на вас исцеляющие эффекты на 50% в течение 25 сек."},
[20573] = {name = "Твердость", additional_info = "[q]Повышает вероятность сопротивления эффектам оглушения еще на 25%."},
[20574] = {name = "Специализация на владении топором", additional_info = "[q]Повышает навык владения топорами и двуручными топорами на 5."},
[20575] = {name = "Властность", additional_info = "[q]Увеличивает урон питомцев охотника и чернокнижника на 5%."},
[20576] = {name = "Властность", additional_info = "[q]Увеличивает урон питомцев охотника и чернокнижника на 5%."},
[20577] = {name = "Каннибализм", additional_info = "Радиус действия: 5 м\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]При использовании восполняет 7% максимального запаса здоровья раз в 2 сек. в течение 10 сек. Действует только на трупы гуманоидов или нежити в пределах 5 м. Движения, действия и полученный урон снимают эффект."},
[20578] = {name = "Каннибализм", additional_info = nil},
[20579] = {name = "Сопротивление темной магии", additional_info = "[q]Повышение сопротивления темной магии на 10 ед."},
[20580] = {name = "Слиться с тенью", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]При использовании вы сливаетесь с тенью, снижая вероятность того, что противники заметят вас. Действие прекращается при движении или отмене. Владеющие этой способностью разбойники и друиды ночных эльфов менее заметны при использовании \"Незаметности\" и \"Крадущегося зверя\"."},
[20582] = {name = "Расторопность", additional_info = "[q]Вероятность уклонения увеличивается на 1%."},
[20583] = {name = "Сопротивление силам природы", additional_info = "[q]Сопротивление силам природы повышено на 10 ед."},
[20584] = {name = "Призрак", additional_info = nil},
[20585] = {name = "Дух огонька", additional_info = "[q]Превращение в огонька после смерти, что увеличивает скорость передвижения на 50%."},
[20586] = {name = "Ветрожнец", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит урон от сил природы 2 сек. в течение 20 сек."},
[20587] = {name = "Неупиваемая чаша Джона-Оборванца", additional_info = "Мгновенное действие\n[q]Увеличение выносливости на 10 ед. и уменьшение получаемого физического урона на 5 ед. на 10 мин. При этом сила и ловкость снижены на 5 ед. а получаемый урон от заклинаний - на 20 ед."},
[20589] = {name = "Мастер побега", additional_info = "{Применение: 0.5 сек} {Восстановление: 1 мин}\n[q]Помогает избежать любых эффектов обездвиживания и ограничения скорости движений."},
[20590] = {name = "Неупиваемая чаша Джона-Оборванца", additional_info = nil},
[20591] = {name = "Пытливый ум", additional_info = "[q]Увеличение интеллекта на 5%."},
[20592] = {name = "Сопротивление тайной магии", additional_info = "[q]Повышение сопротивления тайной магии на 10 ед."},
[20593] = {name = "Инженерное дело, специализация", additional_info = "[q]Увеличение навыка \"Инженерное дело\" на 15."},
[20594] = {name = "Каменная форма", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]При активации придает невосприимчивость к эффектам кровотечения, яда и болезни. Броня увеличивается на 10%. Длительность - 8 сек."},
[20595] = {name = "Специализация по стрелковому оружию", additional_info = "[q]Навык владения огнестрельным оружием повышен на 5 ед."},
[20596] = {name = "Сопротивление магии льда", additional_info = "[q]Сопротивление магии льда увеличена на 10 ед."},
[20597] = {name = "Специализация на владении мечами", additional_info = "[q]Повышение навыка владения мечами и двуручными мечами на 5 ед."},
[20598] = {name = "Человеческий дух", additional_info = "[q]Увеличение духа на 5%."},
[20599] = {name = "Дипломатия", additional_info = "[q]Ускорение улучшения отношения на 10%."},
[20600] = {name = "Внимательность", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Резкое повышение способности обнаруживать незаметность на 20 сек."},
[20602] = {name = "Кольцо огня", additional_info = "Мгновенное действие\nИнструменты: Тотем огня\n[q]Нанесение урона от огня ближайшим противникам."},
[20603] = {name = "Удар Тени", additional_info = "Мана: 135\nМгновенное действие\n[q]Моментальное нанесение урона от темной магии находящимся поблизости противникам."},
[20604] = {name = "Господство над разумом", additional_info = "{Мана: 30} {Радиус действия: 20 м}\nПрименение: 2 сек\n[q]Подчинение противника-гуманоида 25 уровня и ниже на 15 сек."},
[20605] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\nТребуется: Оружие ближнего боя\n[q]Нанесение урона от оружия плюс 30 ед. врагу и его ближайшим союзникам. Захватывает до 3 целей."},
[20606] = {name = "Истребитель нежити 15", additional_info = "[q]Увеличение силы атаки на 15 ед. в бою с нежитью."},
[20607] = {name = "Усиление посоха", additional_info = "[q]Повышение навыка использования посохов на 2 ед."},
[20608] = {name = "Восстание из мертвых", additional_info = "Восстановление: 1 час\nИнгредиенты:\nКрест\n[q]Заклинание позволяет вам возродиться после смерти с 20% здоровья и маны."},
[20609] = {name = "Дух предков", additional_info = "{90% от базовой мана} {Радиус действия: 30 м}\nПрименение: 10 сек\n[q]Возвращение души в тело, возрождение покойника к жизни с 150 ед. здоровья и 260 ед. маны. Не может быть применено в бою."},
[20610] = {name = "Дух предков", additional_info = "{90% от базовой мана} {Радиус действия: 30 м}\nПрименение: 10 сек\n[q]Возвращение души в тело, возрождение покойника к жизни с 250 ед. здоровья и 420 ед. маны. Не может быть применено в бою."},
