[20617] = {name = "Перехват", additional_info = "{Ярость: 10} {Радиус действия: 8 - 25 м}\n{Мгновенное действие} {Восстановление: 30 сек}\nТребуется: Стойка берсерка\n[q]Бросается к противнику, нанося 65 ед. урона и оглушая его на 3 сек."},
