[20628] = {name = "Рецепт: шахтерская похлебка из моллюсков", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению шахтерской похлебки из моллюсков."},
[20629] = {name = "Разъедающий ядовитый плевок", additional_info = "Радиус действия: 30 м\nПрименение: 2.5 сек\n[q]Плевок яда, наносящий урон и ослабляющий броню противника, а также наносящий дополнительный урон от сил природы раз в 5 сек. в течение 10 сек."},
