[20873] = {name = "[q4]Пламенные плетеные наплечники", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (16), Огненное ядро (4), Ядро лавы (5)\n[q4]Пламенные плетеные наплечники\nСтановится персональным при надевании\nПлечо Кольчуга\nБроня: 299\n+10 к выносливости\n+14 к интеллекту\nУстойчивость: +25 Огонь\nПрочность: 85 / 85\nТребуется"},
[20874] = {name = "[q4]Наручи из черного железа", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (4), Огненное ядро (2), Ядро лавы (2)\n[q4]Наручи из черного железа\nСтановится персональным при надевании\nЗапястья Латы\n[q2]Броня: 394\n+7 к выносливости\nУстойчивость: +18 Огонь\nПрочность: 55 / 55\nТребуется"},
[20875] = {name = "Ром Рэмси", additional_info = "Применение: 1 сек\n[q]Повышение выносливости на 10 ед. на 15 мин. и жуткое опьянение!"},
[20876] = {name = "[q4]Поножи из черного железа", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток черного железа (16), Огненное ядро (4), Ядро лавы (6)\n[q4]Поножи из черного железа\nСтановится персональным при надевании\nНоги Латы\n[q2]Броня: 778\n+14 к выносливости\nУстойчивость: +30 Огонь\nПрочность: 120 / 120\nТребуется"},
