[20882] = {name = "Порабощение демона", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Порабощение демона уровнем не выше 62. Промежуток между атаками пленного демона увеличивается на 43%, а скорость применения заклинаний уменьшается на 30%. Продолжительность – до 5 мин."},
[20883] = {name = "Чародейская вспышка", additional_info = "{Мана: 80} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Поражение цели взрывом и нанесение ей 70 ед. урона от тайной магии."},
[20884] = {name = "Оглушение 1% на 1 сек", additional_info = "Дистанция ближнего боя\n[q]Дает 1% шанс оглушить противника в бою в течение 1 сек.\n(Вероятность срабатывания: 1%)"},
