[20989] = {name = "Сон", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Погружение противника в сон, длящийся 10 сек. и прерывающийся при любом повреждении. Усыпить можно только одного противника за раз."},
[21007] = {name = "Проклятие слабости", additional_info = "Мгновенное действие\n[q]Снижение физического урона, наносимого находящимися рядом противниками на 1 ед. на 2 мин. Один чернокнижник может наложить проклятие только на одну цель."},
[21008] = {name = "Дразнящий удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Провокационный удар, наносящий 31 ед. урона и вынуждающий цель атаковать вас в течение 6 сек."},
[21009] = {name = "Слиться с тенью (пассивная)", additional_info = nil},
[21010] = {name = "Увеличение урона заклятия на нежить 14", additional_info = "[q]Повышение не более чем на 14 ед. урона, наносимого нежити заклинаниями и магическими эффектами."},
[21011] = {name = "Повышение урона демонам от заклинания 14", additional_info = "[q]Повышение не более чем на 14 ед. урона, наносимого демонам заклинаниями и магическими эффектами."},
[21012] = {name = "Повышение урона, наносимого при атаках левой рукой 10", additional_info = "[q]Увеличение на 10% урона, наносимого при атаках левой рукой."},
[21013] = {name = "Сила атаки дальнего боя 60", additional_info = "[q]Увеличение силы атаки в дальнем бою на 60 ед."},
[21027] = {name = "Искра", additional_info = "Радиус действия: 10 м\nПрименение: 2 сек\n[q]Поражение противника молнией, урон от сил природы."},
[21029] = {name = "Тауматургический канал", additional_info = "Мгновенное действие\nИнгредиенты:\nПустой волшебный сосуд"},
[21030] = {name = "Ледяной шок", additional_info = "{Мана: 115} {Радиус действия: 20 м}\nМгновенное действие\n[q]Заклинание наносит противнику урон от магии льда и замедляет скорость его передвижения на 8 сек."},
[21047] = {name = "Плевок разъедающей кислоты", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Нанесение урона от сил природы и ослабление брони противника на 10 сек."},
[21048] = {name = "Проклятье племен", additional_info = "Применение: 2 сек\n[q]Снижение наносимого противником урона на 15% на 30 мин."},
[21049] = {name = "Кровожадность", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Повышение скорости атаки союзника на 30% на 30 сек."},
[21050] = {name = "Флейта крысолова", additional_info = "Радиус действия: 5 м\nПрименение: 1 сек\n[q]Звуки этой флейты способны заворожить крыс, обитающих на территории Подземного поезда."},
[21053] = {name = "Пленение души", additional_info = nil},
[21054] = {name = "Пленение души", additional_info = nil},
[21055] = {name = "Сокрушение доспеха", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Нанесение сильного удара по доспехам противника, что ослабляет его броню на 0 ед. при каждом сокрушении. Эффект может суммироваться до 5 раз. Длительность - 30 сек."},
[21056] = {name = "Метка Каззака", additional_info = nil},
[21057] = {name = "Вызов терадримского осколыша", additional_info = nil},
[21058] = {name = "Метка Каззака", additional_info = nil},
[21059] = {name = "Кислотный плевок", additional_info = "Радиус действия: 40 м\nПрименение: 2 сек\n[q]Нанесение противнику урона от сил природы."},
[21060] = {name = "Ослепление", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Ослепление цели. Цель растерянно бродит туда-сюда в течение времени до 10 сек. Любой нанесенный урон снимает эффект."},
[21061] = {name = "Гнилостное дыхание", additional_info = "[q]Вероятность наложения заклинания \"Гнилостное дыхание\" на противника при поражении в ближнем бою.\n(Вероятность срабатывания: 5%)"},
[21062] = {name = "Гнилостное дыхание", additional_info = nil},
[21063] = {name = "Кривое зеркало", additional_info = nil},
[21064] = {name = "Кривое зеркало", additional_info = nil},
[21066] = {name = "Молния Бездны", additional_info = nil},
[21067] = {name = "Ядовитый удар", additional_info = "Радиус действия: 30 м\nПрименение: 2.5 сек\n[q]Наносит урон от сил природы, а затем дополнительный урон раз в 5 сек. в течение 10 сек."},
[21068] = {name = "Порча", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение находящимся рядом противникам урона от темной магии раз в 3 сек. в течение 24 сек."},
[21069] = {name = "Личиночный студень", additional_info = "Мгновенное действие\n[q]Отравление находящихся поблизости противников с нанесением им 68 в 82 ед. мгновенного урона и последующим нанесением 9 в 11 ед. дополнительного урона от сил природы раз в 2 сек. в течение 6 сек."},
[21070] = {name = "Пагубное облако", additional_info = nil},
[21071] = {name = "Валун", additional_info = "Применение: 2 сек\n[q]Броски камней в ближайших противников, нанося физический урон."},
[21072] = {name = "Огненный шар", additional_info = "{Мана: 110} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Наносит противнику урон от огня."},
[21073] = {name = "Чародейский взрыв", additional_info = "Применение: 1.5 сек\n[q]Создание магической взрывной волны, наносящей противникам урон от тайной магии."},
[21075] = {name = "Ранящий щит", additional_info = "Радиус действия: 35 м\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Нанесение 100 ед. урона от тайной магии любому существу, атакующему находящегося рядом приспешника."},
[21076] = {name = "Рассеивание заклинаний", additional_info = "{Мгновенное действие} {Восстановление: 20 сек}\n[q]Рассеивает магический эффект на союзниках, снимая с них 20 вредоносных заклинаний."},
[21077] = {name = "Стрела Тьмы", additional_info = "Радиус действия: 40 м\nПрименение: 0.5 сек\n[q]Выстрел во врага магической стрелой, наносящей 1350 в 1650 ед. урона от темной магии."},
[21079] = {name = "Эхо Архимонда", additional_info = nil},
[21080] = {name = "Гнилостное дыхание", additional_info = "[q]Вероятность наложения заклинания \"Гнилостное дыхание\" на противника при поражении в ближнем бою.\n(Вероятность срабатывания: 15%)"},
[21081] = {name = "Раскол брони", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Проламывание вражеской брони и ослабление ее на 0 ед. при каждом расколе. Можно использовать до 5 раз подряд. Длительность - 30 сек."},
[21082] = {name = "Печать воина Cвета", additional_info = "Мана: 25\nМгновенное действие\n[q]Наполняет паладина рыцарским духом, который повышает его силу атаки в ближнем бою на 36. Паладин становится способен атаковать на 40% быстрее, однако в каждой атаке наносит меньше урона. Эффект длится 30 сек. Единовременно паладин может привести в действие только одно заклинание категории \"Печать\".\n\n Высвобождение энергии этой печати обрушивает на противника правосудие на 10 сек, увеличивая получаемый им урон от светлой магии на 20 ед. Ваши удары в ближнем бою обновляют время действия заклинания. Единовременно паладин может поддерживать только одно заклинание категории \"Правосудие\"."},
[21083] = {name = "Печать воина Cвета", additional_info = nil},
[21084] = {name = "Печать праведности", additional_info = "Мана: 20\nМгновенное действие\n[q]Наполнение паладина святым духом, на 30 сек. наделяющим атаки ближнего боя дополнительным уроном от светлой магии в 3 - 9 ед. Единовременно паладин может привести в действие только одно заклинание категории \"Печать\".\n\n Высвобождение энергии этой печати обрушивается на противника уроном от светлой магии в 26 ед."},
[21085] = {name = "Печать праведности", additional_info = nil},
[21086] = {name = "Поощрение", additional_info = nil},
[21087] = {name = "Невосприимчивость", additional_info = nil},
[21088] = {name = "Улучшенный чародейский интеллект", additional_info = "[q]Заклинание прибавляет к вашей характеристике \"интеллект\" 7 ед."},
[21089] = {name = "Карающий удар", additional_info = "[q]После наложения заклинания \"Большее исцеление\" следующее заклинание \"Кара\" потребует на 300 ед. меньше маны с 15% вероятностью."},
[21090] = {name = "Защитник", additional_info = nil},
[21091] = {name = "Карающий удар", additional_info = "Мгновенное действие\n[q]Modifies Power Cost -300:\nКара , Кара , Кара , Кара , Кара , Кара , Кара , Кара"},
[21092] = {name = "Увеличение рейтинга критического удара заклинаний", additional_info = "[q]Увеличение рейтинга критического удара заклинаний светлой магии на 2%."},
[21093] = {name = "Улучшенная стойкость", additional_info = "[q]Повышение на 7 ед эффекта повышения выносливости при использовании заклинания \"Слово силы: стойкость\"."},
[21094] = {name = "Воссоединение останков", additional_info = nil},
[21095] = {name = "Воссоединение останков", additional_info = nil},
[21096] = {name = "Снежная буря", additional_info = "{Мана: 8} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Начинается снежная буря, длящаяся 10 сек., наносящая 12 ед. урона от магии льда раз в 2 сек. всем противникам в выбранной зоне."},
[21097] = {name = "Буря маны", additional_info = "Радиус действия: 60 м\nПрименение: 2 сек\n[q]Вы вызываете шторм маны, которая длится 10 сек., нанося всем противникам в выбранной зоне 7 ед. урона от магии льда и похищает 9 ед. маны раз в 2 сек."},
[21098] = {name = "Стужа", additional_info = "Мгновенное действие\n[q]Заклинание наносит находящимся рядом противникам урон от магии льда в размере 744 в 956 ед., увеличивает время между атаками на 300% и снижает скорость их передвижения на 40%."},
[21099] = {name = "Дыхание льда", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение противникам, находящихся в пределах конуса холода перед заклинателем, урона от магии льда, похищение их маны и снижение скорости их передвижения в течение 5 сек."},
