[21141] = {name = "Стрела Тьмы", additional_info = "{Мана: 40} {Радиус действия: 30 м}\nМгновенное действие\n[q]Поражение противника теневой молнией, наносящей 50 ед. урона от темной магии и 10 ед. урона раз в 3 сек. в течение 30 сек."},
[21142] = {name = "Испепеление", additional_info = "[q]Нанесение 5 ед. урона от огня любому, кто нападает на вас в ближнем бою."},
[21143] = {name = "Рецепт имбирного пряника", additional_info = "Применение: 3 сек\nИнгредиенты:\nНебольшое яйцо , Праздничные пряности\nИмбирное печенье\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин."},
[21144] = {name = "Рецепт гоголя-моголя", additional_info = "Применение: 3 сек\nИнгредиенты:\nНебольшое яйцо , Ледяное молоко , Праздничная выпивка , Праздничные пряности\nГоголь-моголь\n[q2]Использование: Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин. Сильное пойло..."},
[21145] = {name = "Рецепт: имбирное печенье", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению имбирного печенья."},
[21146] = {name = "Рецепт: гоголь-моголь", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению гоголя-моголя."},
[21147] = {name = "Чародейский вакуум", additional_info = nil},
[21149] = {name = "Гоголь-моголь", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 61.2 ед. здоровья за 18 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 2 на 15 мин. Сильное пойло..."},
[21150] = {name = "Вызов игрока", additional_info = nil},
[21151] = {name = "Потрошитель Гутгора", additional_info = "{Мана: 40} {Радиус действия: 30 м}\nМгновенное действие\n[q]Удар противника теневой молнией, нанесение ему 75 ед. урона от темной магии и понижение всех характеристик на 25 в течение 30 сек."},
[21152] = {name = "Землетрясущий", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Сбивает с ног ближайших противников на 3 сек."},
[21153] = {name = "Кромка костяного разрушителя", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Игнорирование 700 ед. вражеской брони в течение 10 сек. Этот эффект может подействовать до 3 раз подряд."},
