[21170] = {name = "Похищение жизни", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Похищение 100 в 180 ед. жизни у вражеской цели."},
[21171] = {name = "Глаз Рисона в небе", additional_info = "Неограниченное расстояние\nПрименение: 1 сек\n[q]Используя заклинание одновременно с Магическим шаром, вы можете осмотреть крепость Альянса через глаз Рисона в небе."},
