[22355] = {name = "Цепная молния", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося каждой урон от сил природы."},
[22356] = {name = "Замедление", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Увеличение времени между атаками находящихся поблизости противников на 54% и замедление их движений на 60% в течение 10 сек."},
[22357] = {name = "Морозная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 2 сек\n[q]Нанесение урона от магии льда и оглушение противника на 2 сек."},
[22371] = {name = "Проклятие бессилия", additional_info = "{Мана: 5} {Радиус действия: 30 м}\nМгновенное действие\n[q]Снидение магического урона, наносимого целью, на 1 ед. на 2 мин."},
[22372] = {name = "Портал демонов", additional_info = "Применение: 0.5 сек\n[q]Открытие на 35 сек. портала в Круговерть Пустоты, через который время от времени проходят демоны, помогающие заклинателю в бою."},
[22373] = {name = "Восстановление", additional_info = "{Мана: 280} {Радиус действия: 40 м}\nПрименение: 2 сек\n[q]Мгновенное исцеление союзника на определенное количество единиц, затем дополнительное восполнение здоровья раз в 3 сек. в течение 21 сек."},
