[22415] = {name = "Гнев деревьев", additional_info = "Радиус действия: 30 м\nПрименение: 1.5 сек\n[q]Противника опутывают корни, нанося урон от сил природы раз в 3 сек. и не давая цели двигаться на время до 10 сек."},
[22416] = {name = "Удар в спину", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение противнику обычного урона плюс 40 ед., но только при атаке со спины."},
[22417] = {name = "Щит Тени", additional_info = "{Мана: 10} {Радиус действия: 40 м}\nМгновенное действие\n[q]Щит, сотканный из силы Тьмы. Существует 30 сек., поглощает до 400 физического или магического урона, в ближнем бою наносит 20 ед. урона атакующим."},
[22418] = {name = "Средоточие Хаоса", additional_info = "Мана: 200\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Непредсказуемое повышение магического урона, наносимого заклинателем, не более чем на 1 в 75 ед. на 30 мин."},
