[22424] = {name = "Взрывная волна", additional_info = "Мгновенное действие\n[q]Высвобождает волну пламени, наносящую урон от огня находящимся рядом противникам и снижающую их скорость передвижения на 6 сек."},
[22425] = {name = "Град огненных шаров", additional_info = "Радиус действия: 40 м\nПрименение: 2 сек\n[q]Нанесение урона от огня ближайшим противникам."},
[22426] = {name = "Сокрушение доспеха", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Нанесение сильного удара по доспехам противника, что ослабляет его броню на 0 ед. при каждом сокрушении. Эффект может суммироваться до 5 раз. Длительность - 30 сек."},
