[22540] = {name = "Рассекающий удар", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\nТребуется: Оружие ближнего боя\n[q]Нанесение противнику и его ближайшим союзникам урона, равного увеличенному на 20 ед. стандартному урону оружия."},
