[22567] = {name = "Вызов Ар'лии", additional_info = "Применение: 2.5 сек\n[q]Вызов Арл'ии из Моро'гай"},
[22568] = {name = "Свирепый укус", additional_info = "{Энергия: 35} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Завершающий удар, который наносит урон в зависимости от длины серии и дополнительно 1 ед. урона за каждую единицу энергии. На урон также влияет сила атаки.\n 1 прием: 50-66 ед. урона\n 2 приема: 86-102 ед. урона\n 3 приема: 122-138 ед. урона\n 4 приема: 158-174 ед. урона\n 5 приемов: 194-210 ед. урона."},
[22569] = {name = "Свирепый укус", additional_info = nil},
[22570] = {name = "Увечье", additional_info = "{Энергия: 45} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Облик кошки\n[q]Завершающий удар , который наносит урон цели и дезориентирует ее, а также не позволяет вам атаковать. Получив урон, цель придет в себя. Урон и время действия зависят от длины серии:\n 1 прием: 7-11 ед. урона, 2 сек.\n 2 приема: 13-19 ед. урона, 3 сек.\n 3 приема: 19-24 ед. урона, 4 сек.\n 4 приема: 25-30 ед. урона, 5 сек.\n 5 приемов: 31-37 ед. урона, 6 сек."},
[22571] = {name = "Увечье", additional_info = nil},
[22572] = {name = "Болезненный удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Нанесение врагу урона от оружия плюс 5 ед."},
[22573] = {name = "Противозерговый трюк", additional_info = "Мгновенное действие\n[q]Заставляет существо наложить само на себя это заклинание ложной цели, когда оно обнаруживает противника в количестве более 5. Накладывается как заклятие-реакция на уровень существа-монстра и выполняется с использованием исчезновения. Применяется только в определенных зонах к определенным монстрам."},
[22574] = {name = "Темный удар", additional_info = "{Мана: 250} {Радиус действия: 10 м}\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Наделение оружия заклинателя силой, позволяющей наносить 95 в 105 ед. дополнительного урона в следующей атаке. Весь наносимый урон считается уроном от темной магии."},
[22575] = {name = "Удар Тени", additional_info = "{Мана: 135} {Радиус действия: 20 м}\nМгновенное действие\n[q]Мгновенное поражение противника темной магией и нанесение ему урона от темной магии."},
