[22749] = {name = "Чары для оружия: сила заклинаний", additional_info = "Применение: 5 сек\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (4), Великая Вечная субстанция (12), Субстанция Огня (4), Субстанция Воды (4), Субстанция Воздуха (4), Золотая жемчужина (2)\n[q]Наложение на оружие ближнего боя чар, повышающих наносимый урон от заклинаний максимум на 30 ед."},
[22750] = {name = "Чары для оружия: мощь исцеления", additional_info = "Применение: 5 сек\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (4), Великая Вечная субстанция (8), Субстанция Жизни (6), Субстанция Воды (6), Сфера Праведности\n[q]Наложение на оружие ближнего боя чар, усиливающих исцеляющие эффекты не более чем на 55 ед."},
