[23550] = {name = "Повышение критического эффекта молитвы об исцелении", additional_info = "[q]Увеличения на 25% шанса на критический эффект заклинания \"Молитва об исцелении\"."},
[23551] = {name = "Щит молний", additional_info = "[q]При применении заклинаний \"Волна исцеления\" или \"Малая волна исцеления\" возникает 25% вероятность, что цель даром получит также заклинание \"Щит молний\", наносящий 50 ед. урона от сил природы атакующему при нанесении удара.\n(Вероятность срабатывания: 25%)"},
[23552] = {name = "Щит молний", additional_info = "Радиус действия: 100 м\nМгновенное действие\n(Восстановление: 3.5с)"},
