[23687] = {name = "Поражение молнией", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Удар молнии, 200 в 300 ед. урона от сил природы."},
[23688] = {name = "Аура синего дракона", additional_info = "[q]Увеличение до 2% вероятности восполнять ману в процессе применения заклинаний в течение 15 сек. после успешного применения заклинания со скоростью, равной 100% от обычной скорости восполнения.\n(Вероятность срабатывания: 2%)"},
[23689] = {name = "Героизм", additional_info = "[q]Иногда носитель исцеляется от 120 в 180 ед. урона при нанесении урона противнику в ближнем бою."},
