[23705] = {name = "[q3]Рассветные вибрамы", additional_info = "Применение: 1 мин\nИнгредиенты:\nГрубая кожа (30), Охранный камень (2), Субстанция Воды (4), Обработанная грубая шкура (2), Руническая нить (2)\n[q3]Рассветные ботфорты\nСтановится персональным при надевании\nСтупни Кожа\nБроня: 114\n+18 к выносливости\nПрочность: 50 / 50\nТребуется\n[q2]Если на персонаже: Увеличение рейтинга уклонения на 1%."},
[23706] = {name = "[q3]Золотое оплечье Рассвета", additional_info = "Применение: 1 мин\nИнгредиенты:\nЗачарованная кожа (8), Субстанция Жизни (4), Охранный камень (4), Обработанная грубая шкура (2), Руническая нить (2)\n[q3]Золотое оплечье Рассвета\nСтановится персональным при надевании\nПлечо Кожа\nБроня: 134\n+22 к выносливости\nПрочность: 60 / 60\nТребуется\n[q2]Если на персонаже: Увеличение рейтинга уклонения на 1%."},
[23707] = {name = "[q4]Лавовый пояс", additional_info = "Применение: 1 мин\nИнгредиенты:\nЯдро лавы (5), Обработанная грубая шкура (4), Железношелковая паутина (4)\n[q4]Лавовый пояс\nСтановится персональным при надевании\nПояс Кожа\n[q2]Броня: 223\n+15 к выносливости\nУстойчивость: +26 Огонь\nПрочность: 40 / 40\nТребуется"},
[23708] = {name = "[q4]Разноцветные рукавицы", additional_info = "Применение: 1 мин\nИнгредиенты:\nОгненное ядро (5), Ядро лавы (2), Сердцевинная кожа (4), Сверкающая многоцветная чешуя (4), Обработанная грубая шкура (4), Железношелковая паутина (4)\n[q4]Разноцветные рукавицы\nСтановится персональным при надевании\nКисти рук Кольчуга\nБроня: 279\nУстойчивость: +5 Огонь\nУстойчивость: +5 Природа\nУстойчивость: +5 Лед\nУстойчивость: +5 Тьма\nПрочность: 50 / 50\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 44.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%."},
[23709] = {name = "[q4]Пояс пса Недр", additional_info = "Применение: 1 мин\nИнгредиенты:\nОгненное ядро (8), Сердцевинная кожа (12), Зачарованная кожа (10), Обработанная грубая шкура (4), Железношелковая паутина (4)\n[q4]Пояс пса Недр\nСтановится персональным при надевании\nПояс Кожа\nБроня: 118\n+16 к интеллекту\nУстойчивость: +12 Огонь\nПрочность: 40 / 40\nТребуется\n[q2]Если на персонаже: Усиливает исцеление от заклинаний и эффектов максимум на 62 ед."},
[23710] = {name = "[q4]Оплавленный пояс", additional_info = "Применение: 1 мин\nИнгредиенты:\nОгненное ядро (2), Ядро лавы (7), Субстанция Земли (6), Обработанная грубая шкура (4), Железношелковая паутина (4)\n[q4]Оплавленный пояс\nСтановится персональным при надевании\nПояс Кожа\nБроня: 118\n+28 к ловкости\n+16 к выносливости\nУстойчивость: +12 Огонь\nПрочность: 40 / 40\nТребуется"},
