[24356] = {name = "[q3]Очки Кровавой Лозы", additional_info = "Применение: 1 мин\nИнструменты: Шлицевой гироинструмент , Тангенциальный вращатель\nИнгредиенты:\nКровавая лоза (4), Свет Души (5), Сверхточный арканитовый преобразователь (2), Мощный амулет (8), Зачарованная кожа (4)\n[q3]Очки Кровавой Лозы\nСтановится персональным при надевании\nГолова Ткань\nБроня: 75\nПрочность: 50 / 50\nТребуется\nТребуетИнженерное дело\n(300)\n[q2]Если на персонаже: Повышение на 2% рейтинга меткости заклинаний.\n[q2]Если на персонаже: Увеличение рейтинга критического эффекта заклинаний на 1%.\n[q2]Если на персонаже: Восполнение 9 ед. маны раз в 5 сек."},
[24357] = {name = "[q3]Линза Кровавой Лозы", additional_info = "Применение: 1 мин\nИнструменты: Шлицевой гироинструмент , Тангенциальный вращатель\nИнгредиенты:\nКровавая лоза (5), Свет Души (5), Сверхточный арканитовый преобразователь , Мощный амулет (8), Зачарованная кожа (4)\n[q3]Линза Кровавой Лозы\nСтановится персональным при надевании\nГолова Кожа\nБроня: 147\n+12 к выносливости\nПрочность: 60 / 60\nТребуется\nТребуетИнженерное дело\n(300)\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 2%.\n[q2]Если на персонаже: Небольшое повышение вашей способности \"Обнаружение незаметности\"."},
[24358] = {name = "Чертеж: очки Кровавой Лозы", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению очков Кровавой Лозы."},
[24359] = {name = "Чертеж: линза Кровавой Лозы", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению линзы Кровавой Лозы."},
[24360] = {name = "Больший спокойный сон", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Погружение в сон без сновидений на 12 сек. За это время выпивший восполняет 2100 ед. здоровья и 2100 ед. маны."},
[24361] = {name = "Регенерация", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 20 ед. здоровья раз в 5 сек. в течение 1 ч."},
[24362] = {name = "Улучшение владения 1H кистевым оружием", additional_info = "[q]Повышение рейтинга навыка владения кистевым оружием на 4 ед."},
[24363] = {name = "Восполнение маны", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 12 ед. маны каждые 5 сек. в течение 1 ч."},
[24364] = {name = "Живая свобода действий", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Неуязвимость к эффектам оглушения и стеснения движений на ближайшие 5 сек. Удаление уже наложенных эффектов оглушения и стеснения передвижения."},
[24365] = {name = "Зелье крови волшебника", additional_info = "Применение: 3 сек\nИнгредиенты:\nСнолист , Чумоцвет (2), Хрустальная колба\nТребуется\n[q2]Использование: Восполнение 12 ед. маны каждые 5 сек. в течение 1 ч. (3 Сек Восстановление)"},
[24366] = {name = "Сильное зелье спокойного сна", additional_info = "Применение: 3 сек\nИнгредиенты:\nСнолист (2), Золотой сансам , Хрустальная колба\nТребуется\n[q2]Использование: Погружение в сон без сновидений на 12 сек. За это время выпивший восполняет 2100 ед. здоровья и 2100 ед. маны. (2 Мин Восстановление)"},
[24367] = {name = "Зелье актерства", additional_info = "Применение: 3 сек\nИнгредиенты:\nЛедяной зев (2), Горный серебряный шалфей (2), Сердце дикой природы (2), Хрустальная колба\nЗелье неудержимости\nТребуется\n[q2]Использование: Неуязвимость к эффектам оглушения и стеснения движений на ближайшие 5 сек. Удаление уже наложенных эффектов оглушения и стеснения передвижения. (2 Мин Восстановление)"},
[24368] = {name = "Сильнейшее зелье тролльей крови", additional_info = "Применение: 3 сек\nИнгредиенты:\nКровь Грома , Чумоцвет (2), Хрустальная колба\nТребуется\n[q2]Использование: Восполнение 20 ед. здоровья раз в 5 сек. в течение 1 ч. (3 Сек Восстановление)"},
[24369] = {name = "Рецепт: зелье крови волшебника", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению зелья крови волшебника."},
[24370] = {name = "Рецепт: сильное зелье спокойного сна", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает приготовлению сильного зелья спокойного сна."},
[24372] = {name = "Рецепт: зелье неудержимости", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению зелья актерства."},
