[24407] = {name = "Превосходство", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Дает мгновенное превосходство над противником. Наносит урон от оружия плюс 750 ед. Действует только после того, как цель уклоняется от атаки. \"Превосходство\" нельзя блокировать или парировать; также от него нельзя уклониться."},
[24408] = {name = "Рывок", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Поражение врага с нанесением обычного урона плюс 0 ед. и оглушение противника на на 2 сек."},
[24409] = {name = "Полевой паек котловины Арати", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 1074 ед. здоровья и 2202 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места. Можно применять только на территории Котловины Арати."},
[24410] = {name = "Паек из Котловины Арати", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 1608 ед. здоровья и 3306 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места. Можно применять только на территории Котловины Арати."},
[24411] = {name = "Увеличенный паек воина котловины Арати", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 2148 ед. здоровья и 4410 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места. Можно применять только на территории Котловины Арати."},
[24412] = {name = "Первая помощь", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 8 сек)\n[q]Восполнение 640 ед. здоровья в течение 8 сек. Действует только в котловине Арати."},
[24413] = {name = "Первая помощь", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 8 сек)\n[q]Восполнение 1104 ед. здоровья в течение 8 сек. Действует только в котловине Арати."},
[24414] = {name = "Первая помощь", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 8 сек)\n[q]Восполнение 2000 ед. здоровья в течение 8 сек. Действует только в котловине Арати."},
[24415] = {name = "Замедление", additional_info = "{Мана: 140} {Радиус действия: 100 м}\nМгновенное действие\n[q]Увеличение времени между атаками находящихся поблизости противников на 100% и замедление их движений на 50%, замедление скорости применения заклинаний на 50% на 20 сек."},
[24416] = {name = "Высшие аспекты", additional_info = "[q]Наделяет всю группу охотника премуществами способностей \"Дух зверя\" и 1% \"Дух обезьяны\"."},
[24417] = {name = "Блеск Занзы", additional_info = "Мгновенное действие\n[q]Увеличение вероятности отразить вредноносное заклинание на 3% на 2 ч. Отражение первого боевого заклинания происходит автоматически. Одновременно может действовать только один тип эликсира Занзы."},
[24418] = {name = "Рецепт сытной похлебки из кроколиска", additional_info = "Применение: 3 сек\nИнгредиенты:\nНежное мясо кроколиска (2), Ароматные специи\nСытная похлебка из кроколиска\nТребуется\n[q2]Использование: Восполняет 874.8 ед. здоровья за 27 сек. Действие прерывается, если встать с места. По истечении 10 сек. персонаж насыщается и его выносливость и дух повышаются на 8 на 15 мин."},
[24419] = {name = "Рецепт: сытная похлебка из кроколиска", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение приготовлению сытной похлебки из кроколиска."},
[24420] = {name = "Перстень безмятежности Зандалара", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам чары, усиливающие исцеление от заклинаний и эффектов максимум на на 33 ед."},
[24421] = {name = "Магический перстень Зандалара", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам чары, усиливающие урон и исцеление от магических заклинаний и эффектов максимум на 18 ед."},
[24422] = {name = "Перстень могущества Зандалара", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам чары, повышающие силу атаки на 30."},
[24423] = {name = "Визг", additional_info = "{Тонус: 20} {Дистанция ближнего боя}\nМгновенное действие\n[q]Наносит одному противнику 7 в 9 ед. урона и снижает силу атаки ближнего боя противников в радиусе ближнего боя на 25. Время действия – 4 сек."},
[24424] = {name = "Визг", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Наносит одному противнику 7 в 9 ед. урона и снижает силу атаки противников в радиусе ближнего боя на 25. Время действия – 4 сек."},
[24425] = {name = "Дух Зандалара", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышает скорость передвижения на 10% и все характеристики на 15% на 2 часа."},
[24426] = {name = "Увеличение рейтинга критического эффекта заклинаний светлой магии", additional_info = "[q]Повышает вероятность критического эффекта ваших заклинаний светлой магии на 1%."},
[24427] = {name = "Бриллиантовая фляжка", additional_info = "Мгновенное действие\n[q]Восполняет 9 ед. здоровья раз в 5 сек. и повышает силу на 75. Время действия – 1 мин."},
[24428] = {name = "Улучшенное подрезание сухожилий", additional_info = "[q]Снижает расход ярости на способность \"Подрезать сухожилия\" на 2 ед."},
[24429] = {name = "Улучшенная Антимагия", additional_info = "[q]Уменьшение времени до повторного применения заклиания \"Антимагия\" на 2 сек."},
[24430] = {name = "Улучшенный огненный ливень/ливень адского пламени", additional_info = "Улучшенный огненный ливень/ливень адского пламени\n[q]Увеличение радиуса действия заклинаний \"Огненный ливень\" и \"Ливень адского пламени\" на 1 метр."},
[24431] = {name = "Улучшенный вихрь", additional_info = "[q]Уменьшение на 3 ед. расхода ярости на \"Вихрь\"."},
[24432] = {name = "Улучшенная симуляция смерти", additional_info = "[q]Сокращение времени восстановления способности \"Притвориться мертвым\" на 2 сек."},
[24433] = {name = "Улучшенный гнев/звездный огонь", additional_info = "Улучшенный гнев/звездный огонь\n[q]Увеличение рейтинга критического удара \"Гнева\" и \"Звездного огня\" на 2%."},
[24434] = {name = "Улучшенный пинок", additional_info = "[q]Сокращение времени восстановления способности \"Пинок\" на 0.5 сек."},
[24435] = {name = "Похищение жизни", additional_info = "Радиус действия: 20 м\nНаправляемое (Применение: 5 сек)\n[q]Похищение 5000 ед. здоровья противника за 5 сек. и передача его заклинателю."},
[24436] = {name = "Copy of Improved Mana/Health Totems", additional_info = "Copy of Improved Mana/Health Totems\n[q]Снижение на 20 ед. расхода маны на создание тотемов исцеляющего потока и источника маны."},
[24437] = {name = "Пиявка-кровосос", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Похищение 263 в 337 ед. здоровья у ближайших врагов и возвращение заклинателю здоровья в три раза больше украденного."},
[24438] = {name = "Боевой крик", additional_info = "Мгновенное действие\n[q]Увеличение силы атаки ближнего боя находящихся рядом членов группы на 200 ед. на 20 сек."},
[24439] = {name = "Сопротивление огню", additional_info = "[q]Увеличение сопротивления огню на 60 ед."},
[24440] = {name = "Сопротивление огню", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Повышение сопротивления огню на 30 ед."},
[24441] = {name = "Сопротивление огню", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Повышение сопротивления огню на 60 ед."},
