[24658] = {name = "Изменчивая сила", additional_info = "Мгновенное действие\n[q]Повышение на 20 сек. урона от заклинаний не более чем на 204 ед. и эффекта исцеляющих заклинаний не более чем на 408 ед. При применении очередного заклинания эффект снижается на 17 ед. в отношении урона и на 34 ед. в отношении исцеляющих эффектов."},
[24659] = {name = "Изменчивая сила", additional_info = nil},
[24661] = {name = "Неодолимая сила", additional_info = "Мгновенное действие\n[q]Увеличение на 20 сек. наносимого в атаках ближнего и дальнего боя урона на 40 ед. При нанесении очередного удара эффект снижается на 2 ед."},
[24662] = {name = "Неодолимая сила", additional_info = nil},
[24664] = {name = "Сон", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Усыпление всех находящихся поблизости противников на время вплоть до 6 сек. Однако от любого нанесенного им урона они проснутся."},
[24666] = {name = "Увеличеный урон от магии льда 132", additional_info = "[q]Увеличение урона, наносимого заклинаниями и эффектами льда, на 132 ед."},
[24667] = {name = "Увеличеный урон от магии льда 72", additional_info = "[q]Увеличение урона, наносимого заклинаниями и эффектами льда, на 72 ед."},
[24668] = {name = "Стрела Тьмы", additional_info = "{Мана: 250} {Радиус действия: 40 м}\nПрименение: 2 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[24669] = {name = "Огненный ливень", additional_info = "{Мана: 250} {Радиус действия: 30 м}\nНаправляемое (Применение: 10 сек)\n[q]Призывание лавового дождя, обжигающего всех противников на выбранном участке с 500 ед. урона от огня раз в 2 сек. в течение 10 сек."},
[24670] = {name = "Инфернал", additional_info = "{Мана: 350} {Радиус действия: 100 м}\nПрименение: 3 сек\nИнгредиенты:\nКамень инфернала\n[q]Призывает метеор из Круговерти Пустоты, который наносит 200 ед. урона от огня и оглушает противников в области действия на 2 сек. Из кратера появляется инфернал, который в течение 5 мин. подчиняется призывателю. Для сохранения контроля после истечения времени инфернала нужно поработить. Действует только вне помещений."},
[24671] = {name = "Пинок", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Нанесение противнику 875 в 1125 ед. урона и оглушение его на 2 сек."},
[24672] = {name = "Нечестивое бешенство", additional_info = "{Мана: 200} {Радиус действия: 30 м}\nМгновенное действие\n[q]Увеличение скорости атаки союзника на 50% в течение 20 сек. Нанесение тому же союзнику 200 ед. урона от сил природы раз в 2 сек."},
[24673] = {name = "Проклятие крови", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Увеличение физического урона, получаемого противником, на 500 ед. на 10 мин."},
[24674] = {name = "Пелена Тени", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Ослабление целительных воздействий на 75% в течение 10 сек."},
[24675] = {name = "BM ВКЛ.", additional_info = nil},
[24676] = {name = "BM ОТКЛ.", additional_info = nil},
[24677] = {name = "Кладб., среднее, инициатор события", additional_info = nil},
[24678] = {name = "Кладб., среднее, Альянс", additional_info = nil},
[24679] = {name = "Кладб., среднее, Орда", additional_info = nil},
[24680] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 10 целей, причем каждой следующей цели наносится все больший урон от сил природы."},
[24681] = {name = "Вызов кошмарных иллюзий", additional_info = nil},
[24682] = {name = "Раздвоенная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nМгновенное действие\n[q]Нанесение урона от сил природы в 1157 в 1343 ед. противникам, находящимся в конусе перед заклинателем."},
[24683] = {name = "Грозовая туча", additional_info = "{Мана: 60} {Радиус действия: 30 м}\nМгновенное действие\n[q]Грозовое облако, которое держится 15 сек., поражая всех противников в избранной игровой зоне с нанесением 463 в 537 ед. урона от сил природы и нанося 875 в 1125 дополнительного урона раз в 5 сек."},
[24684] = {name = "Цепной ожог", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Молния, выжигающая ману, которая перелетает от первоначальной жертвы к другому ближайшему противнику. На каждую единицу выжженной маны жертва получает 0.5 ед. урона. Заклинание поражает до 3 целей."},
[24685] = {name = "Земной шок", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Противника бьет ударной волной с нанесением урона от сил природы и лишением его возможности наложения заклинаний на 4 сек."},
[24686] = {name = "Аспект Мар'ли", additional_info = nil},
[24687] = {name = "Аспект Джеклик", additional_info = "Мгновенное действие\n[q]Нанесение увеличенного на 1313 в 1687 ед. стандартного урона ближайшим противникам, лишая их возможности применять заклинания в течение 5 сек."},
[24688] = {name = "Аспект Веноксиса", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Ядовитый плевок в находящихся поблизости противников, наносящий урон от сил природы, а затем дополнительный урон раз в 2 сек. в течение 10 сек."},
[24689] = {name = "Аспект Текала", additional_info = nil},
[24690] = {name = "Аспект Арлокк", additional_info = nil},
[24691] = {name = "Заградительный огонь", additional_info = "[q]Увеличение на 15% урона, наносимого вашими заклинаниями \"Залп\" и \"Град стрел\"."},
