[24702] = {name = "Аура Тыквовина", additional_info = nil},
[24703] = {name = "[q4]Кираса чешуи сна", additional_info = "Применение: 1 мин\nИнгредиенты:\nЗачарованная кожа (12), Чешуя сна (6), Субстанция Жизни (4), Обработанная грубая шкура (4), Железношелковая паутина (6)\n[q4]Кираса чешуи сна\nСтановится персональным при надевании\nГрудь Кольчуга\nБроня: 434\n+15 к ловкости\n+15 к выносливости\n+14 к интеллекту\nУстойчивость: +30 Природа\nПрочность: 140 / 140\nТребуется\n[q2]Если на персонаже: Восполнение 4 ед. маны раз в 5 сек."},
[24704] = {name = "Выкройка: кираса чешуи сна", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению кирасы чешуи сна."},
[24705] = {name = "Призывание Ивового человека", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ускоряет восполнение здоровья и маны на 25% и повышает выносливость на 25% на 2 ч."},
[24706] = {name = "Бросок бомбы-вонючки", additional_info = "Радиус действия: 20 м\nПрименение: 2 сек\n[q]Бросьте бомбу-вонючку на Южнобережье!"},
[24707] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполнение 3% здоровья и маны в сек. в течение 25 сек. Действие эффекта прерывается, если персонаж встает с места."},
