[25013] = {name = "Грозовое дыхание", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Выдыхание молнии, моментально наносящей 21 в 24 ед. урона от сил природы врагу."},
[25014] = {name = "Грозовое дыхание", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Выдыхание молнии, моментально наносящей 36 в 41 ед. урона от сил природы врагу."},
