[25017] = {name = "Грозовое дыхание", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Выдыхание молнии, моментально наносящей 99 в 113 ед. урона от сил природы врагу."},
[25018] = {name = "Вызов Ворчаля", additional_info = "Применение: 1 сек\n[q]Призыв и освобождение Ворчаля по щелчку правой кнопкой мыши."},
[25019] = {name = "Снежная буря", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 10 сек)\n[q]Начинается снежная буря, длящаяся 10 сек., наносящая 12 ед. урона от магии льда раз в 2 сек. всем противникам в выбранной зоне."},
[25020] = {name = "Щит молний", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]3 шаровых молний, окружающих заклинателя. 50% вероятность нанести 4 ед. урона противникам, атакующим в ближнем или дальнем бою. Каждый раз, как щит срабатывает, одна из молний рассеивается. Таким образом, щит перестает действовать через 10 мин., либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[25021] = {name = "Цепная молния", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 5 целей, причем каждой следующей цели наносится все больший урон от сил природы."},
[25022] = {name = "Тыквовинская страшилка", additional_info = nil},
[25023] = {name = "Тыквовинская страшилка", additional_info = "(Вероятность срабатывания: 5%)"},
[25024] = {name = "Упавшая мина", additional_info = "{Мана: 30} {Радиус действия: 50 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Взрыв мины. Срабатывает в течение 3 сек. и наносит 35 в 45 ед. урон всем танкам в радиусе 2 м."},
[25025] = {name = "Земной шок", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Противника бьет ударной волной с нанесением урона от сил природы и лишением его возможности наложения заклинаний на 2 сек."},
[25026] = {name = "Активация гномской турели", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]10 ед. маны в секунду.\n Автоматический обстрел ближайшего вражеского танка в пределах 10 м раз в 1 сек., наносящий 2 в 4 ед. урона за выстрел."},
[25027] = {name = "Огнемет", additional_info = "Радиус действия: 15 м\n{Мгновенное действие} {Восстановление: 2 сек}\n[q]10 ед. маны в секунду.\n Нанесение 18 в 22 ед. урона раз в 1 сек. всем танкам впереди вас в пределах 5 м. Замедление движений до 20% и нанесение 5 ед. урона в секунду в течение 2 сек."},
[25028] = {name = "Огненный взрыв", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Наносит противнику урон от огня."},
[25029] = {name = "Огнемет", additional_info = nil},
[25030] = {name = "Запуск ракеты", additional_info = "Применение: 3 сек"},
[25031] = {name = "Запуск снаряда", additional_info = "Применение: 3 сек"},
