[25033] = {name = "Грозовая туча", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Грозовое облако, которое держится 15 сек., поражая всех противников в избранной игровой зоне с нанесением 657 в 843 ед. урона от сил природы и нанося 657 в 843 дополнительного урона раз в 5 сек."},
[25034] = {name = "Раздвоенная молния", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Нанесение урона от сил природы противникам, находящимся в конусе перед заклинателем."},
