[25049] = {name = "Взрывная волна", additional_info = "Мгновенное действие\n[q]Высвобождает волну пламени, наносящую урон от огня находящимся рядом противникам и снижающую их скорость передвижения на 6 сек."},
[25050] = {name = "Знак Пламени", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Увеличение урона от огня, получаемого противником, на 1000 ед. на 2 мин."},
[25051] = {name = "Раскол брони", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Проламывание вражеской брони и ослабление ее на 1000 ед. при каждом расколе. Можно использовать до 5 раз подряд. Длительность - 20 сек."},
[25052] = {name = "Кислотный плевок", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Нанесение противнику урона от сил природы."},
[25053] = {name = "Отравляющий плевок", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Ядовитый плевок в нБO?????oQ?поблизости противников, наносящий урон от сил природы, а затем дополнительный урон раз в 5 сек. в течение 30 сек."},
[25054] = {name = "Божественная кара", additional_info = "{Мана: 75} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Удар по противнику, нанесение урона от светлой магии."},
[25055] = {name = "Чародейская стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 1 сек\n[q]Выстрел во врага магической стрелой, наносящей урон от тайной магии."},
[25056] = {name = "Топот", additional_info = "Мгновенное действие\n[q]Нанесение находящихся рядом врагам обычного урона плюс 250 ед., сбивание их с ног и оглушение на 2 сек."},
[25057] = {name = "Оброненное оружие", additional_info = nil},
[25058] = {name = "Обновление", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nМгновенное действие\n[q]Исцеление союзника раз в 3 сек. в течение 15 сек."},
[25059] = {name = "Измеримый щит", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наделение дружественной цели шипами, которые наносят 10000 ед. урона от сил природы атакующим при ударе. Время действия – до отмены."},
[25060] = {name = "Восходящий поток", additional_info = "Мгновенное действие\n[q]Поражение противников, находящихся в конусе перед заклинателем. Их отбрасывает назад."},
