[25503] = {name = "Исступление", additional_info = "Мгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Дает 20 ед. ярости за 10 сек ., но ослабляет базовую броню на 27% в облике медведя и на 16% в облике лютого медведя . Во время действия этого эффекта вы находитесь в режиме боя."},
[25514] = {name = "Вспышка Света", additional_info = "{Мана: 200} {Радиус действия: 60 м}\nПрименение: 1.5 сек\n[q]Воззвание к светлой магии для исцеления союзника."},
[25515] = {name = "Оглушить", additional_info = "{Мана: 50} {Радиус действия: 10 м}\nМгновенное действие\n[q]Оглушение противника, делая его неспособным передвигаться и атаковать в течение 5 сек."},
