[25890] = {name = "Великое благословение Света", additional_info = "{Мана: 260} {Радиус действия: 40 м}\nМгновенное действие\nИнгредиенты:\nЗнак королей\n[q]Наложение на всех участников рейда или группы того же класса, что и цель, Великое благословение Света, на 15 мин. повышающего применяемый на них эффект заклинания \"Свет небес\" не более чем на 400 ед. и эффект заклинания \"Вспышка Света\" не более чем на 115 ед. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[25891] = {name = "Земной удар", additional_info = "Мгновенное действие\n[q]Увеличение силы атаки ближнего и дальнего боя на 280 ед. на 20 сек."},
