[25893] = {name = "Нечистотон уменьшается", additional_info = nil},
[25894] = {name = "Великое благословение мудрости", additional_info = "{Мана: 230} {Радиус действия: 40 м}\nМгновенное действие\nИнгредиенты:\nЗнак королей\n[q]Наложение на всех участников рейда или группы того же класса, что и цель, заклинания \"Великое благословения мудрости\", в течение 15 мин. восполняющего им 30 ед. маны раз в 5 сек. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[25895] = {name = "Великое благословение спасения", additional_info = "{16% от базовой мана} {Радиус действия: 40 м}\nМгновенное действие\nИнгредиенты:\nЗнак королей\n[q]Наложение на всех участников рейда или группы того же класса, что и цель заклинания \"Великое благословение спасения\", на 15 мин. уменьшающего количество всей производимой ими угрозы на 30%. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[25896] = {name = "Присоединение к Нечистотону", additional_info = nil},
[25897] = {name = "Нечистотон растет", additional_info = nil},
[25898] = {name = "Великое благословение королей", additional_info = "{Мана: 150} {Радиус действия: 40 м}\nМгновенное действие\nИнгредиенты:\nЗнак королей\n[q]Наложение на всех участников рейда или группы того же класса, что и цель, заклинания \"Великое Благословение Королей\", на 15 мин. повышающего все их характеристики на 10%. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
[25899] = {name = "Великое благословение неприкосновенности", additional_info = "{Мана: 270} {Радиус действия: 40 м}\nМгновенное действие\nИнгредиенты:\nЗнак королей\n[q]Наложение на всех участников рейда или группы того же класса, что и цель, заклинания \"Великое благословение неприкосновенности\", на 15 мин. уменьшающего наносимый по ним урон на 24 ед. Кроме того, когда цель блокирует атаку ближнего боя, атакующий получает 35 ед. урона от магии Света. Каждый паладин единовременно может накладывать на одного игрока только одно благословение."},
