[27567] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\nПрименение: 2 сек\n[q]Молния, перелетающая с цели на другого находящегося поблизости противника. Заклинание поражает до 3 целей, нанося каждой урон от сил природы."},
