[27578] = {name = "Боевой крик", additional_info = "Мгновенное действие\n[q]Воин издает крик, повышающий силу атаки участников группы в радиусе 20 м на 193. Время действия – 2 мин."},
[27579] = {name = "Деморализующий крик", additional_info = "Мгновенное действие\n[q]Снижает силу атаки противников в радиусе 10 м на 146 на 30 сек."},
[27580] = {name = "Смертельный удар", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 6 сек}\nТребуется: Оружие ближнего боя\n[q]Жестокий удар, наносящий урон от оружия плюс 160 ед. и наносящий цели серьезную рану, снижающую эффективность любого лечения на 50% в течение 10 сек."},
[27581] = {name = "Разоружение", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Обезоруживает противника на 10 сек."},
[27582] = {name = "Яд воспоминаний Дирга", additional_info = nil},
[27583] = {name = "Dirk's Rememberin' Poison Effect DND", additional_info = nil},
[27584] = {name = "Подрезать сухожилия", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Калечит противника, нанося 45 ед. урона и снижая скорость передвижения на 50% на 15 сек."},
[27585] = {name = "[q3]Тяжелый обсидиановый пояс", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nНебольшой обсидиановый осколок (14), Зачарованный ториевый слиток (4), Субстанция Земли (2)\n[q3]Тяжелый обсидиановый пояс\nСтановится персональным при надевании\nПояс Латы\nБроня: 397\n+25 к силе\nПрочность: 45 / 45\nТребуется\n[q2]Если на персонаже: +5 ко всем видам сопротивления."},
[27586] = {name = "[q4]Изрубленный обсидиановый щит", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nБольшой обсидиановый осколок (8), Небольшой обсидиановый осколок (24), Зачарованный ториевый слиток (8), Субстанция Земли (4)\n[q4]Звездчатый обсидиановый щит\nСтановится персональным при надевании\nЛевая рука Щит\nБроня: 2645\nБлокирование: 48\nПрочность: 120 / 120\nТребуется\n[q2]Если на персонаже: Повышает вероятность блокирования атаки щитом на 2%,\n[q2]Если на персонаже: +5 ко всем видам сопротивления.\n[q2]Если на персонаже: При нанесении урона заклинанием, заклинатель с вероятностью 5% онемеет на 3 сек. (Вероятность срабатывания: 5%, Восстановление: 20с)"},
[27587] = {name = "[q4]Утолщенная обсидиановая кираса", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nБольшой обсидиановый осколок (18), Небольшой обсидиановый осколок (40), Зачарованный ториевый слиток (12), Субстанция Земли (10), Огромный изумруд (4)\n[q4]Толстая обсидиановая кираса\nСтановится персональным при надевании\nГрудь Латы\nБроня: 814\n+38 к силе\n+16 к выносливости\nПрочность: 165 / 165\nТребуется\n[q2]Если на персонаже: При поражении непериодическим заклинанием урона вы получаете вероятность 30% создать 6 сек щит заклятий, который поглотит 300 в 500 ед. этой школы магии. (Вероятность срабатывания: 30%, Восстановление: 10с)"},
[27588] = {name = "[q3]Легкий обсидиановый пояс", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nНебольшой обсидиановый осколок (14), Зачарованная кожа (4)\n[q3]Легкий обсидиановый пояс\nСтановится персональным при надевании\nПояс Кольчуга\nБроня: 224\nПрочность: 40 / 40\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 32.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: +5 ко всем видам сопротивления."},
[27589] = {name = "[q4]Черный напоясник Разрушителя", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nБольшой обсидиановый осколок (8), Небольшой обсидиановый осколок (24), Зачарованная кожа (8), Настой великой силы\n[q4]Черный напоясник Разрушителя\nСтановится персональным при надевании\nКисти рук Кольчуга\nБроня: 279\nПрочность: 50 / 50\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 28.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Восполнение 8 ед. маны и дополнительное похищение 8 ед. маны у противника при ее наличии после успешной атаки ближнего или дальнего боя."},
[27590] = {name = "[q4]Обсидиановый кольчужный мундир", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nБольшой обсидиановый осколок (15), Небольшой обсидиановый осколок (36), Зачарованная кожа (12), Охранный камень (10), Азеротский алмаз (4)\n[q4]Обсидиановый кольчужный мундир\nСтановится персональным при надевании\nГрудь Кольчуга\nБроня: 458\nПрочность: 140 / 140\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 76.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%.\n[q2]Если на персонаже: Получаемый урон от заклинаний снижается на 10 ед."},
[27591] = {name = "Чертеж: тяжелый обсидиановый пояс", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению тяжелого обсидианового пояса."},
[27592] = {name = "Чертеж: звездчатый обсидиановый щит", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению зазубренного обсидианового щит."},
[27593] = {name = "Чертеж: толстая обсидиановая кираса", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению толстой обсидиановой кирасы."},
[27594] = {name = "Чертеж: легкий обсидиановый пояс", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению легкого обсидианового пояса."},
[27595] = {name = "Чертеж: Черный напоясник Разрушителя", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению Черного напоясника Разрушителя."},
