[27602] = {name = "Вызов арканитового дракончика", additional_info = "{Мгновенное действие} {Восстановление: 1 час}\n[q]Арканитовый дракончик сопровождает и защищает вас в течение 1 мин."},
[27603] = {name = "Гоблинское драконье ружье", additional_info = "Направляемое (Применение: 8 сек)\n[q]Нанесение 158 в 192 ед. урона от огня в течение 8 сек. всем целям в конусе поражения впереди инженера, использующего это оружие. Если оно, конечно, не взорвется..."},
