[27829] = {name = "[q4]Титановые поножи", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (12), Зачарованный ториевый слиток (20), Субстанция Земли (10), Настой титанов (2)\n[q4]Поножи титанов\nСтановится персональным при надевании\nНоги Латы\nБроня: 598\n+30 к силе\nПрочность: 120 / 120\nТребуется\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 2%.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%."},
[27830] = {name = "[q4]Довод", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (15), Слиток черного железа (10), Субстанция Нежити (20), Темная руна (20), Кожа девизавра (10), Шкура Тени (2)\n[q4]Довод\nСтановится персональным при надевании\nПравая рука Дробящее\nУрон: 86-161 Скорость 2.70\n(45.74 ед. урона в секунду)\nПрочность: 105 / 105\nТребуется\n[q2]Если на персонаже: Вероятность нанесения удара увеличена на 1%.\n[q2]Если на персонаже: Увеличение вероятности нанесения критического урона на 1%."},
[27831] = {name = "Залп стрел Тьмы", additional_info = "Радиус действия: 30 м\nПрименение: 1.5 сек\n[q]Силы тьмы, причиняющая урон от темной магии находящимся поблизости противникам."},
[27832] = {name = "[q4]Клинок мудреца", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (12), Кристалл-источник (2), Настой великой силы (2), Зачарованная кожа (4)\n[q4]Клинок мудреца\nСтановится персональным при надевании\nПравая рука Меч\nУрон: 49-100 Скорость 1.80\n(41.39 ед. урона в секунду)\n+14 к выносливости\n+6 к интеллекту\nПрочность: 105 / 105\nТребуется\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 20 ед.\n[q2]Если на персонаже: Снижает сопротивление магии целей ваших заклинаний на 10."},
[27833] = {name = "Чертеж: поножи титанов", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению титановых поножей."},
[27834] = {name = "Чертеж: клинок мудреца", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучение изготовлению клинка мудреца."},
