[28812] = {name = "Стремглав", additional_info = "[q]Ваши критические удары посредством заклинаний \"Удар в спину\", \"Коварный удар\" и \"Кровоизлияние\" позволяют восстановить 5 ед. энергии.\n(Восстановление: 500мс)"},
[28813] = {name = "Стремглав", additional_info = "Мгновенное действие\n[q]Восполнение 5 ед. энергии."},
[28814] = {name = "Уязвимое место", additional_info = "[q]При использовании способности \"Потрошение\" вы получаете шанс, увеличивающийся с длиной серии, найти уязвимость в броне противника. Это гарантирует вам нанесение критического урона при последующем использовании приемов \"Удар в спину\", \"Коварный удар\" или \"Кровоизлияние\"."},
[28815] = {name = "Уязвимое место", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Повышает вероятность критического удара при применении \"Коварного удара\", \"Удара в спину\" и \"Кровоизлияния\" на 100%."},
[28816] = {name = "Энергичность", additional_info = "[q]Ваши нормальные удары ближнего боя имеют шанс придать вам энергичности, исцелив вас на 90 в 110 ед."},
[28817] = {name = "Энергичность", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Исцеление себя на 90 в 110."},
