[28821] = {name = "Щит молний", additional_info = "[q]Пока действует заклинание \"Щит молний\", он восстанавливает вам 15 ед. маны раз в 5 сек."},
[28823] = {name = "Тотемная мощь", additional_info = "[q]Ваши заклинания \"Волна исцеления\" и \"Малая волна исцеления\" получают шанс наделить вашу цель Тотемной мощью.\n(Вероятность срабатывания: 10%)"},
[28824] = {name = "Тотемная мощь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ускорение восполнения маны дружественной цели на 28 ед. раз в 5 сек. в течение 8 сек."},
[28825] = {name = "Тотемная мощь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышение урона от заклинаний дружественной цели, а также ее целительских способностей не более чем на 80 ед. на 8 сек."},
[28826] = {name = "Тотемная мощь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышение силы атаки дружественной цели на 140 ед. на 8 сек."},
