[402392] = {name = "Телепорт", additional_info = nil},
[402668] = {name = "Прикосновение вампира", additional_info = "{16% от базовой мана} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Применяет к цели эффект таланта \"Объятия вампира\" и наносит ей [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] ед. урона от темной магии за 15 сек. Все участники вашей группы восполняют ману в объеме 2% любого урона от темной магии, который вы наносите цели."},
[402686] = {name = "Случайное превращение", additional_info = nil},
[402753] = {name = "Вырезание рун: гравировка \"Шаг сквозь тень\"", additional_info = nil},
[402755] = {name = "Вырезание рун: гравировка \"Быстрая реакция\"", additional_info = nil},
[402758] = {name = "Вырезание рун: гравировка \"Бросок сюрикэна\"", additional_info = nil},
[402760] = {name = "Вырезание рун: гравировка \"Смертельное варево\"", additional_info = nil},
[402779] = {name = "Прикосновение вампира", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Восполняет участникам группы ману в объеме 5% получаемого урона от темной магии."},
[402789] = {name = "Око Бездны", additional_info = "Радиус действия: 30 м\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Призывает Око Бездны, которое сражается на вашей стороне в течение 30 сек. Око может насылать на цель проклятия."},
[402790] = {name = "Стрела Тьмы", additional_info = "{5% от базовой мана} {Радиус действия: 35 м}\nПрименение: 3 сек\n[q]Поражение противника темной молнией, наносящей урон от темной магии."},
[402791] = {name = "Проклятие Тьмы", additional_info = "{20% от базовой мана} {Радиус действия: 35 м}\nМгновенное действие\n[q]Проклинает цель, снижая сопротивление тайной и темной магии на 75 на 3 мин. и увеличивая получаемый урон от тайной и темной магии на 10%. Одновременно на цель может действовать только одно проклятие каждого чернокнижника."},
[402792] = {name = "Проклятие стихий", additional_info = "{20% от базовой мана} {Радиус действия: 35 м}\nМгновенное действие\n[q]Проклинает цель, снижая сопротивление огню и магии льда на 75 на 3 мин. и увеличивая получаемый урон от огня и магии льда на 10%. Одновременно на цель может действовать только одно проклятие каждого чернокнижника."},
[402794] = {name = "Проклятие косноязычия", additional_info = "{20% от базовой мана} {Радиус действия: 35 м}\nМгновенное действие\n[q]Заставляет цель говорить на демоническом языке, замедляя применение заклинаний на 60% на 3 мин. Одновременно на цель может действовать только одно проклятие каждого чернокнижника."},
[402799] = {name = "Гомункулы", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Отрывает щепотку души и создает 3 ваших миниатюрных копии:ваших миниатюрных копий, которые пытаются атаковать противника булавой, мечом или топором, снижая скорость атаки, силу атаки и показатель брони соответственно у всех пораженных целей."},
[402801] = {name = "Гомункулы", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Оживляет 5 скелета:скелетов, которые атакуют противников булавой, мечом или топором, снижая их скорость атаки, силу атаки и показатель брони соответственно."},
[402802] = {name = "Гомункулы", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Оживляет 5 скелета:скелетов, которые атакуют противников булавой, мечом или топором, снижая их скорость атаки, силу атаки и показатель брони соответственно."},
[402808] = {name = "Увечье", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Увеличивает интервал между атаками противника на 10% на 15 сек."},
[402811] = {name = "Устрашение", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Снижает силу атаки цели на 190 ед. на 15 сек."},
[402818] = {name = "Раздробление", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Ослабляет броню противника на 2250 ед. на 15 сек."},
[402832] = {name = "Молитва восстановления", additional_info = "[q]Дает способность \"Молитва восстановления\":\n\n\nМолитва оберегает союзника и восстанавливает ему [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] ед. здоровья при следующем получении урона или восполнении здоровья. После исцеления заклинание переходит к другому участнику рейда в пределах 20 м. Молитва может совершить переход 5 раз и длится 30 сек. после каждой смены цели. Это заклинание можно накладывать только на одну цель единовременно."},
[402833] = {name = "Слово Тьмы: Смерть", additional_info = "[q]Дает способность \"Слово Тьмы: Смерть\":\n\n\nНаносит противнику [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100]-[(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] ед. урона от темной магии. Если он не погибает, вы получаете 50% урона от этого заклинания."},
[402834] = {name = "Оберег души", additional_info = "[q]Дает способность \"Оберег души\":\n\n\n\"Слово силы: Щит\" больше не требует времени на восстановление, расходует на 15% меньше маны, поглощает на 10% больше урона и усиливается еще на 10% от вашей силы исцеления."},
[402836] = {name = "Гомункулы", additional_info = "[q]Дает способность \"Гомункулы\":\n\n\nОтрывает щепотку души и создает 3 ваших миниатюрных копии:ваших миниатюрных копий, которые пытаются атаковать противника булавой, мечом или топором, снижая скорость атаки, силу атаки и показатель брони соответственно у всех пораженных целей."},
[402837] = {name = "Связующее исцеление", additional_info = "[q]Дает способность \"Связующее исцеление\":\n\n\nВосстанавливает себе и союзнику [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 161 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 197 / 100] ед. здоровья. Низкий уровень угрозы. Это заклинание взаимодействует с теми же эффектами, что и \"Быстрое исцеление\"."},
[402838] = {name = "Общая боль", additional_info = "[q]Дает способность \"Общая боль\":\n\n\n\"Слово Тьмы: Боль\" теперь поражает еще до 2 противников в радиусе 15 м."},
[402839] = {name = "Подавление боли", additional_info = "[q]Дает способность \"Подавление боли\":\n\n\nУменьшает урон, получаемый союзником, на 40% и повышает сопротивление рассеиванию магии на 65% на 8 сек."},
[402841] = {name = "Прикосновение вампира", additional_info = "[q]Дает способность \"Прикосновение вампира\":\n\n\nПрименяет к цели эффект таланта \"Объятия вампира\" и наносит ей [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] ед. урона от темной магии за 15 сек. Все участники вашей группы восполняют ману в объеме 2% любого урона от темной магии, который вы наносите цели."},
[402842] = {name = "Круг исцеления", additional_info = "[q]Дает способность \"Круг исцеления\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] ед. здоровья."},
[402843] = {name = "Исчадие Тьмы", additional_info = "[q]Дает способность \"Исчадие Тьмы\":\n\n\nПризывает исчадие Тьмы, атакующее цель. Когда исчадие наносит урон, призыватель восполняет 5% маны. Время существования – 15 сек."},
[402844] = {name = "Исповедь", additional_info = "[q]Дает способность \"Исповедь\":\n\n\nВыпускает в цель поток небесного света, наносящий [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] ед. урона от светлой магии противнику или восполняющий [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] ед. здоровья союзнику мгновенно и далее раз в 1 сек. в течение 2 сек."},
[402846] = {name = "Око Бездны", additional_info = "[q]Дает способность \"Око Бездны\":\n\n\nПризывает Око Бездны, которое сражается на вашей стороне в течение 30 сек. Око может насылать на цель проклятия."},
[402848] = {name = "Гравировка поножей \"Молитва восстановления\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Молитва восстановления\":\n\n\nМолитва оберегает союзника и восстанавливает ему [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] ед. здоровья при следующем получении урона или восполнении здоровья. После исцеления заклинание переходит к другому участнику рейда в пределах 20 м. Молитва может совершить переход 5 раз и длится 30 сек. после каждой смены цели. Это заклинание можно накладывать только на одну цель единовременно."},
[402849] = {name = "Гравировка перчаток \"Слово Тьмы: Смерть\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Слово Тьмы: Смерть\":\n\n\nНаносит противнику [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100]-[(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] ед. урона от темной магии. Если он не погибает, вы получаете 50% урона от этого заклинания."},
[402850] = {name = "Гравировка плаща \"Оберег души\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Оберег души\":\n\n\n\"Слово силы: Щит\" больше не требует времени на восстановление, расходует на 15% меньше маны, поглощает на 10% больше урона и усиливается еще на 10% от вашей силы исцеления."},
[402852] = {name = "Гравировка поножей \"Гомункулы\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Гомункулы\":\n\n\nОтрывает щепотку души и создает 3 ваших миниатюрных копии:ваших миниатюрных копий, которые пытаются атаковать противника булавой, мечом или топором, снижая скорость атаки, силу атаки и показатель брони соответственно у всех пораженных целей."},
[402853] = {name = "Гравировка плаща \"Связующее исцеление\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Связующее исцеление\":\n\nВосстанавливает себе и союзнику [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 161 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 197 / 100] ед. здоровья. Низкий уровень угрозы. Это заклинание взаимодействует с теми же эффектами, что и \"Быстрое исцеление\"."},
[402854] = {name = "Гравировка поножей \"Общая боль\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Общая боль\":\n\n\n\"Слово Тьмы: Боль\" теперь поражает еще до 2 противников в радиусе 15 м."},
[402855] = {name = "Гравировка обуви \"Подавление боли\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Подавление боли\":\n\n\nУменьшает урон, получаемый союзником, на 40% и повышает сопротивление рассеиванию магии на 65% на 8 сек."},
[402857] = {name = "Гравировка плаща \"Прикосновение вампира\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Прикосновение вампира\":\n\n\nПрименяет к цели эффект таланта \"Объятия вампира\" и наносит ей [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] ед. урона от темной магии за 15 сек. Все участники вашей группы восполняют ману в объеме 2% любого урона от темной магии, который вы наносите цели."},
[402859] = {name = "Гравировка перчаток \"Круг исцеления\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Круг исцеления\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]-[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] ед. здоровья."},
[402861] = {name = "Гравировка поножей \"Исчадие Тьмы\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Исчадие Тьмы\":\n\nПризывает исчадие Тьмы, атакующее цель. Когда исчадие наносит урон, призыватель восполняет 5% маны. Время существования – 15 сек."},
[402862] = {name = "Гравировка перчаток \"Исповедь\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Исповедь\":\n\n\nВыпускает в цель поток небесного света, наносящий [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] ед. урона от светлой магии противнику или восполняющий [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] ед. здоровья союзнику мгновенно и далее раз в 1 сек. в течение 2 сек."},
[402864] = {name = "Гравировка шлема \"Око Бездны\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Око Бездны\":\n\n\nПризывает Око Бездны, которое сражается на вашей стороне в течение 30 сек. Око может насылать на цель проклятия."},
[402877] = {name = "Флагелляция", additional_info = "[q]При получении физического урона вы накапливаете столько ярости, как если бы вы не носили брони."},
[402906] = {name = "Флагелляция", additional_info = nil},
[402911] = {name = "Яростный выпад", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 8 сек}\nТребуется: Оружие ближнего боя\n[q]Свирепый удар, наносящий 115% урона от оружия. Способность можно применить только под действием \"Исступления\", \"Ярости берсерка\" или \"Кровавой ярости\". Другие способности ближнего боя, примененные под действием этих эффектов, сокращают время восстановления \"Яростного выпада\" на 1 сек."},
[402913] = {name = "Безудержное восстановление", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Восстанавливает вам 30% максимального запаса здоровья за 10 сек. Способность можно применить только под действием \"Исступления\", \"Ярости берсерка\" или \"Кровавой ярости\". Можно применить, пока персонаж оглушен."},
[402922] = {name = "Точный расчет", additional_info = "[q]\"Мощный удар\" теперь применяется мгновенно, но имеет время восстановления, равное 6 сек."},
[402927] = {name = "Победный раж", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 8 сек}\n[q]Вы мгновенно атакуете цель, нанося (1 + Сила атаки * 45 / 100) ед. урона и восполняя 30% своего максимального запаса здоровья. Можно применить только в течение 20 сек. после убийства противника, за которого можно получить опыт или честь."},
[402975] = {name = "Победоносное состояние", additional_info = "Мгновенное действие\n[q]Наступает после победы над противником."},
[403172] = {name = "Вырезание рун: гравировка \"Промеж глаз\"", additional_info = nil},
[403195] = {name = "Сокрушение", additional_info = "[q]Когда вы используете защитную стойку и держите в руке щит, \"Раскол брони\" также наносит урон в размере 150% урона в секунду вашего оружия. Урон увеличивается на 15% за каждый эффект \"Раскола брони\", уже наложенный на цель. Пока вы находитесь в защитной стойке, \"Сокрушение\" создает высокий уровень угрозы."},
[403196] = {name = "Сокрушение", additional_info = "Неограниченное расстояние\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]\"Раскол брони\" также наносит 150% урона от оружия. Урон увеличивается на 15% за каждый эффект \"Раскола брони\", уже наложенный на цель."},
[403215] = {name = "Командирский крик", additional_info = "Мгновенное действие\n[q]Воин издает крик, повышающий выносливость участников группы в радиусе 30 м на 2. Время действия – 5 мин."},
[403218] = {name = "Бесконечная ярость", additional_info = "[q]Нанося любой урон, вы накапливаете на 25% больше ярости."},
[403219] = {name = "Неистовый гром", additional_info = "[q]\"Удар грома\" теперь увеличивает интервал между атаками еще на 6% и наносит на 100% больше урона. Эту способность можно применять во всех стойках, а уровень создаваемой ею угрозы повышается на 75%."},
[403228] = {name = "Мясной крюк", additional_info = "{Ярость: 15} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 35 сек}\n[q]Бросает крюк на цепи, сковывающий и притягивающий цель. Нельзя применять к противникам, уровень которых выше ( 60 + 1)-го, а также к боссам."},
[403231] = {name = "Мясной крюк", additional_info = "Неограниченное расстояние\n{Мгновенное действие} {Восстановление: 35 сек}\n[q]Бросает крюк на цепи, связывающий и притягивающий цель."},
[403233] = {name = "Мясной крюк", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Бросает крюк на цепи, сковывающий и притягивающий цель. Пока вы притягиваете цель, ее нельзя оглушить."},
[403332] = {name = "Героический выстрел", additional_info = "Радиус действия: 8 - 35 м\nВосстановление: 6 сек\nТребуется: Оружие дальнего боя\n[q]Выстрел в цель, наносящий 300% урона от оружия дальнего боя. Дает 20 ед. ярости."},
[403338] = {name = "Вмешательство", additional_info = "{Ярость: 10} {Радиус действия: 8 - 25 м}\n{Мгновенное действие} {Восстановление: 30 сек}\nТребуется: Оборонительная стойка\n[q]Воин совершает стремительный рывок к участнику группы, прерывая следующую направленную на того атаку ближнего или дальнего боя. Снижает уровень угрозы, созданной целью, на 10%."},
[403339] = {name = "Вмешательство", additional_info = nil},
[403344] = {name = "Флагелляция", additional_info = "[q]Дает способность \"Флагелляция\":\n\n\nПри получении физического урона вы накапливаете столько ярости, как если бы вы не носили брони."},
[403349] = {name = "Бесконечная ярость", additional_info = "[q]Дает способность \"Бесконечная ярость\":\n\n\nНанося любой урон, вы накапливаете на 25% больше ярости."},
[403352] = {name = "Кровавое бешенство", additional_info = "[q]Дает способность \"Кровавое бешенство\":\n\n\n\"Кровопускание\" теперь можно применять в стойке берсерка. Урон от \"Кровопускания\" увеличивается на 100%. Каждый раз, когда \"Кровопускание\" наносит урон, цель получает дополнительный урон в объеме 4% вашей силы атаки."},
[403355] = {name = "Сокрушение", additional_info = "[q]Дает способность \"Сокрушение\":\n\n\nКогда вы используете защитную стойку и держите в руке щит, \"Раскол брони\" также наносит урон в размере 150% урона в секунду вашего оружия. Урон увеличивается на 15% за каждый эффект \"Раскола брони\", уже наложенный на цель. Пока вы находитесь в защитной стойке, \"Сокрушение\" создает высокий уровень угрозы."},
[403356] = {name = "Неистовый гром", additional_info = "[q]Дает способность \"Неистовый гром\":\n\n\n\"Удар грома\" теперь увеличивает интервал между атаками еще на 6% и наносит на 100% больше урона. Эту способность можно применять во всех стойках, а уровень создаваемой ею угрозы повышается на 75%."},
[403359] = {name = "Безудержное восстановление", additional_info = "[q]Дает способность \"Безудержное восстановление\":\n\n\nВосстанавливает вам 30% максимального запаса здоровья за 10 сек. Способность можно применить только под действием \"Исступления\", \"Ярости берсерка\" или \"Кровавой ярости\". Можно применить, пока персонаж оглушен."},
[403434] = {name = "Победный раж", additional_info = "[q]Дает способность \"Победный раж\":\n\n\nВы мгновенно атакуете цель, нанося (1 + Сила атаки * 45 / 100) ед. урона и восполняя 30% своего максимального запаса здоровья. Можно применить только в течение 20 сек. после убийства противника, за которого можно получить опыт или честь."},
[403435] = {name = "Командирский крик", additional_info = "[q]Дает способность \"Командирский крик\":\n\n\nВоин издает крик, повышающий выносливость участников группы в радиусе 30 м на 2. Время действия – 5 мин."},
[403436] = {name = "Мясной крюк", additional_info = "[q]Дает способность \"Мясной крюк\":\n\n\nБросает крюк на цепи, сковывающий и притягивающий цель. Нельзя применять к противникам, уровень которых выше ( 60 + 1)-го, а также к боссам."},
[403437] = {name = "Вмешательство", additional_info = "[q]Дает способность \"Вмешательство\":\n\n\nВоин совершает стремительный рывок к участнику группы, прерывая следующую направленную на того атаку ближнего или дальнего боя. Снижает уровень угрозы, созданной целью, на 10%."},
[403446] = {name = "Гравировка поножей \"Командирский крик\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Командирский крик\":\n\n\nВоин издает крик, повышающий выносливость участников группы в радиусе 30 м на 2. Время действия – 5 мин."},
[403467] = {name = "Гравировка обуви \"Безудержное восстановление\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Безудержное восстановление\":\n\n\nВосстанавливает вам 30% максимального запаса здоровья за 10 сек. Способность можно применить только под действием \"Исступления\", \"Ярости берсерка\" или \"Кровавой ярости\". Можно применить, пока персонаж оглушен."},
[403470] = {name = "Гравировка перчаток \"Победный раж\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Победный раж\":\n\n\nВы мгновенно атакуете цель, нанося (1 + Сила атаки * 45 / 100) ед. урона и восполняя 30% своего максимального запаса здоровья. Можно применить только в течение 20 сек. после убийства противника, за которого можно получить опыт или честь."},
[403472] = {name = "Гравировка обуви \"Вмешательство\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Вмешательство\":\n\n\nВоин совершает стремительный рывок к участнику группы, прерывая следующую направленную на того атаку ближнего или дальнего боя. Снижает уровень угрозы, созданной целью, на 10%."},
[403474] = {name = "Гравировка нагрудника \"Кровавое бешенство\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике руну \"Кровавое бешенство\":\n\n\n\"Кровопускание\" теперь можно применять в стойке берсерка. Урон от \"Кровопускания\" увеличивается на 100%. Каждый раз, когда \"Кровопускание\" наносит урон, цель получает дополнительный урон в объеме 4% вашей силы атаки."},
[403475] = {name = "Гравировка перчаток \"Сокрушение\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Сокрушение\":\n\n\nКогда вы используете защитную стойку и держите в руке щит, \"Раскол брони\" также наносит урон в размере 150% урона в секунду вашего оружия. Урон увеличивается на 15% за каждый эффект \"Раскола брони\", уже наложенный на цель. Пока вы находитесь в защитной стойке, \"Сокрушение\" создает высокий уровень угрозы."},
[403476] = {name = "Гравировка поножей \"Неистовый гром\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Неистовый гром\":\n\n\n\"Удар грома\" теперь увеличивает интервал между атаками еще на 6% и наносит на 100% больше урона. Эту способность можно применять во всех стойках, а уровень создаваемой ею угрозы повышается на 75%."},
[403480] = {name = "Гравировка нагрудника \"Флагелляция\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике руну \"Флагелляция\":\n\n\nПри получении физического урона вы накапливаете столько ярости, как если бы вы не носили брони."},
[403489] = {name = "Гравировка шлема \"Бесконечная ярость\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Бесконечная ярость\":\n\n\nНанося любой урон, вы накапливаете на 25% больше ярости."},
[403501] = {name = "Блуждающий дух", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 12 сек}\n[q]Насылает на противника блуждающего духа, наносящего [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] ед. урона и увеличивающего получаемый целью периодический урон от ваших эффектов темной магии на 40% на 15 сек. По истечении времени действия или в случае рассеивания эффекта блуждающий дух возвращается к вам, восполняя здоровье в объеме 100% урона, нанесенного противнику."},
[403506] = {name = "Блуждающий дух", additional_info = nil},
[403511] = {name = "Вытягивание души", additional_info = "[q]Теперь ваше \"Похищение души\" наносит урон в 3 раза:раз быстрее, при этом \"Похищение жизни\" и \"Похищение души\" вытягивают на 6% больше здоровья за каждый ваш эффект темной магии, действующий на цель. Максимальный бонус – 18%. Когда вы применяете \"Похищение души\" к цели с уровнем здоровья ниже 20%, этот бонус становится равен 50% за каждый эффект вплоть до 150%. Кроме того, ваше \"Похищение души\" теперь может вызвать срабатывание таланта \"Сумерки\".\n(Вероятность срабатывания: 8%)"},
[403619] = {name = "Доспех Скверны", additional_info = "28% от базовой мана\nМгновенное действие\n[q]Окружает вас энергией Скверны, увеличивающей урон и силу исцеления заклинаний на 1 ед. плюс 50% параметра духа. Кроме того, раз в 5 сек. вы восполняете 2% максимального запаса здоровья. Единовременно на чернокнижника может действовать только одно заклинание категории \"Доспех\". Время действия – 30 мин."},
[403628] = {name = "Залп стрел Тьмы", additional_info = "[q]\"Стрела Тьмы\" поражает до 5 целей на общем расстоянии в 10 м, но наносит на 30% меньше урона."},
[403629] = {name = "Стрела Хаоса", additional_info = "{7% от базовой мана} {Радиус действия: 30 м}\n{Применение: 2.5 сек} {Восстановление: 12 сек}\n[q]Поражает противника стрелой хаотичного пламени, наносящей [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] ед. урона от магии Хаоса. Стрела Хаоса всегда попадает в цель, преодолевает сопротивление противника и позволяет вашим заклинаниям огня игнорировать эффекты поглощения. Монстры, уровень которых превышает ваш на 4 или более, с высокой вероятностью сопротивляются \"Стреле Хаоса\"."},
[403630] = {name = "Стрела Хаоса", additional_info = nil},
[403650] = {name = "Огненное озеро", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]\"Огненный ливень\" оставляет на земле огненное озеро, которое увеличивает урон от огня, наносимый вами и вашим прислужником-демоном стоящим в озере целям, на 50%."},
[403666] = {name = "Огненное озеро", additional_info = "[q]\"Огненный ливень\" больше не нужно поддерживать, но его время восстановления становится равно 8 сек."},
[403668] = {name = "Мастер-чаротворец", additional_info = "[q]\"Похищение жизни\" больше нельзя поддерживать. Теперь оно действует 15 сек., получает время восстановления 15 сек., расходует на 100% больше маны и восстанавливает вам на 50% больше здоровья каждый раз, когда наносит урон."},
[403677] = {name = "Похищение жизни", additional_info = "{Мана: 110} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 10 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403680] = {name = "Рывок в глубину", additional_info = nil},
[403683] = {name = "Рывок в глубину", additional_info = nil},
[403685] = {name = "Похищение жизни", additional_info = "{Мана: 170} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 17 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403686] = {name = "Похищение жизни", additional_info = "{Мана: 270} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 29 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403687] = {name = "Похищение жизни", additional_info = "{Мана: 370} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 41 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403688] = {name = "Похищение жизни", additional_info = "{Мана: 480} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 55 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403689] = {name = "Похищение жизни", additional_info = "{Мана: 600} {Радиус действия: 20 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Похищает у цели 71 ед. здоровья раз 1 сек. Время действия – 15 сек."},
[403789] = {name = "Метаморфоза", additional_info = "100% от базовой мана\nМгновенное действие\n[q]Превращает вас в демона, усиливая броню на 500%, увеличивая запас здоровья на 15%, снижая вероятность получить критический урон на 6%, повышая уровень создаваемой угрозы на 50% и увеличивая количество маны, получаемое от \"Жизнеотвода\", на 100%, но уменьшая наносимый вами урон на 10%. \"Метаморфоза\" меняет действие некоторых способностей и дает вам новые:\n\n \"Жгучая боль\": теперь применяется мгновенно.\n\n \"Стрела Тьмы\": меняется на \"Теневой рассекающий удар\" – атаку ближнего боя, наносящую максимум 10 противникам:противникам урон от темной магии, но требующую 6 сек. на восстановление.\n\n \"Страх\": меняется на \"Устрашение\".\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью.\n\n Демонический прыжок\n\n\nДемон бросается к противнику и оглушает его на 1 сек. Не действует во время боя.\n\n Демонический вой\n\n\nЗаставляет находящихся рядом противников атаковать вас в течение 6 сек."},
[403816] = {name = "Метаморфоза", additional_info = "[q]Превращает вас в демона, усиливая броню на 500%, снижая вероятность получить критический урон на 6%, повышая уровень создаваемой угрозы на 50%, увеличивая количество маны, получаемое от \"Жизнеотвода\", на 100% и меняя действие некоторых способностей:\n\n \"Жгучая боль\": теперь применяется мгновенно.\n\n \"Стрела Тьмы\": меняется на \"Теневой рассекающий удар\" – атаку ближнего боя, поражающую до 500 противников темной магией.\n\n \"Проклятие безрассудства\": также провоцирует цель атаковать вас в течение до отмены.\n\n \"Вой ужаса\": заставляет окружающих противников атаковать вас в течение до отмены., но время восстановления увеличивается до 10 мин."},
[403828] = {name = "Устрашение", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью."},
[403835] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 12} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 3 в 7 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 5 * 5). Время действия эффекта – 15 сек ]"},
[403839] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 20} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 7 в 12 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 11 * 5). Время действия эффекта – 15 сек ]"},
[403840] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 35} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 14 в 23 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 17 * 5). Время действия эффекта – 15 сек ]"},
[403841] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 55} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 26 в 39 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 25 * 5). Время действия эффекта – 15 сек ]"},
[403842] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 80} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 42 в 64 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 33 * 5). Время действия эффекта – 15 сек ]"},
[403843] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 105} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 60 в 91 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 41 * 5). Время действия эффекта – 15 сек ]"},
[403844] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 132} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 82 в 124 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 49 * 5). Время действия эффекта – 15 сек ]"},
[403848] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 157} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 105 в 158 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 57 * 5). Время действия эффекта – 15 сек ]"},
[403851] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 185} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 128 в 193 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия эффекта – 15 сек ]"},
[403852] = {name = "Теневой рассекающий удар", additional_info = "{Мана: 190} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Карает до 10 ближайших противников бичом тьмы, нанося каждому 136 в 204 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\". [ S03 – настройка и отмена пассивных эффектов – все классы : Когда вы поражаете цель \"Теневым рассекающим ударом\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия эффекта – 15 сек ]"},
[403858] = {name = "Блуждающий дух", additional_info = "[q]Дает способность \"Блуждающий дух\":\n\n\nНасылает на противника блуждающего духа, наносящего [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] ед. урона и увеличивающего получаемый целью периодический урон от ваших эффектов темной магии на 40% на 15 сек. По истечении времени действия или в случае рассеивания эффекта блуждающий дух возвращается к вам, восполняя здоровье в объеме 100% урона, нанесенного противнику."},
[403860] = {name = "Стрела Хаоса", additional_info = "[q]Дает способность \"Стрела Хаоса\":\n\n\nПоражает противника стрелой хаотичного пламени, наносящей [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] ед. урона от магии Хаоса. Стрела Хаоса всегда попадает в цель, преодолевает сопротивление противника и позволяет вашим заклинаниям огня игнорировать эффекты поглощения. Монстры, уровень которых превышает ваш на 4 или более, с высокой вероятностью сопротивляются \"Стреле Хаоса\"."},
[403863] = {name = "Вытягивание души", additional_info = "[q]Дает способность \"Вытягивание души\":\n\n\nТеперь ваше \"Похищение души\" наносит урон в 3 раза:раз быстрее, при этом \"Похищение жизни\" и \"Похищение души\" вытягивают на 6% больше здоровья за каждый ваш эффект темной магии, действующий на цель. Максимальный бонус – 18%. Когда вы применяете \"Похищение души\" к цели с уровнем здоровья ниже 20%, этот бонус становится равен 50% за каждый эффект вплоть до 150%. Кроме того, ваше \"Похищение души\" теперь может вызвать срабатывание таланта \"Сумерки\"."},
[403868] = {name = "Мастер-чаротворец", additional_info = "[q]Дает способность \"Мастер-чаротворец\":\n\n\n\"Похищение жизни\" больше нельзя поддерживать. Теперь оно действует 15 сек., получает время восстановления 15 сек., расходует на 100% больше маны и восстанавливает вам на 50% больше здоровья каждый раз, когда наносит урон."},
[403871] = {name = "Залп стрел Тьмы", additional_info = "[q]Дает способность \"Залп стрел Тьмы\":\n\n\n\"Стрела Тьмы\" поражает до 5 целей на общем расстоянии в 10 м, но наносит на 30% меньше урона."},
[403872] = {name = "Огненное озеро", additional_info = "[q]Дает способность \"Огненное озеро\":\n\n\n\"Огненный ливень\" больше не нужно поддерживать, но его время восстановления становится равно 8 сек."},
[403873] = {name = "Метаморфоза", additional_info = "[q]Дает способность \"Метаморфоза\":\n\n\nПревращает вас в демона, усиливая броню на 500%, увеличивая запас здоровья на 15%, снижая вероятность получить критический урон на 6%, повышая уровень создаваемой угрозы на 50% и увеличивая количество маны, получаемое от \"Жизнеотвода\", на 100%, но уменьшая наносимый вами урон на 10%. \"Метаморфоза\" меняет действие некоторых способностей и дает вам новые:\n\n \"Жгучая боль\": теперь применяется мгновенно.\n\n \"Стрела Тьмы\": меняется на \"Теневой рассекающий удар\" – атаку ближнего боя, наносящую максимум 10 противникам:противникам урон от темной магии, но требующую 6 сек. на восстановление.\n\n \"Страх\": меняется на \"Устрашение\".\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью.\n\n Демонический прыжок\n\n\nДемон бросается к противнику и оглушает его на 1 сек. Не действует во время боя.\n\n Демонический вой\n\n\nЗаставляет находящихся рядом противников атаковать вас в течение 6 сек."},
[403919] = {name = "Гравировка перчаток \"Блуждающий дух\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Блуждающий дух\":\n\n\nНасылает на противника блуждающего духа, наносящего [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] ед. урона и увеличивающего получаемый целью периодический урон от ваших эффектов темной магии на 40% на 15 сек. По истечении времени действия или в случае рассеивания эффекта блуждающий дух возвращается к вам, восполняя здоровье в объеме 100% урона, нанесенного противнику."},
[403920] = {name = "Гравировка плаща \"Вытягивание души\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Вытягивание души\":\n\n\nТеперь ваше \"Похищение души\" наносит урон в 3 раза:раз быстрее, при этом \"Похищение жизни\" и \"Похищение души\" вытягивают на 6% больше здоровья за каждый ваш эффект темной магии, действующий на цель. Максимальный бонус – 18%. Когда вы применяете \"Похищение души\" к цели с уровнем здоровья ниже 20%, этот бонус становится равен 50% за каждый эффект вплоть до 150%. Кроме того, ваше \"Похищение души\" теперь может вызвать срабатывание таланта \"Сумерки\"."},
[403925] = {name = "Гравировка перчаток \"Стрела Хаоса\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Стрела Хаоса\":\n\n\nПоражает противника стрелой хаотичного пламени, наносящей [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100]-[(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] ед. урона от магии Хаоса. Стрела Хаоса всегда попадает в цель, преодолевает сопротивление противника и позволяет вашим заклинаниям огня игнорировать эффекты поглощения. Монстры, уровень которых превышает ваш на 4 или более, с высокой вероятностью сопротивляются \"Стреле Хаоса\"."},
[403932] = {name = "Гравировка нагрудника \"Мастер-чаротворец\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Мастер-чаротворец\":\n\n\n\"Похищение жизни\" больше нельзя поддерживать. Теперь оно действует 15 сек., получает время восстановления 15 сек., расходует на 100% больше маны и восстанавливает вам на 50% больше здоровья каждый раз, когда наносит урон."},
[403936] = {name = "Гравировка перчаток \"Залп стрел Тьмы\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Залп стрел Тьмы\":\n\n\n\"Стрела Тьмы\" поражает до 5 целей на общем расстоянии в 10 м, но наносит на 30% меньше урона."},
[403937] = {name = "Гравировка нагрудника \"Огненное озеро\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Огненное озеро\":\n\n\n\"Огненный ливень\" больше не нужно поддерживать, но его время восстановления становится равно 8 сек."},
[403938] = {name = "Гравировка перчаток \"Метаморфоза\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Метаморфоза\":\n\n\nПревращает вас в демона, усиливая броню на 500%, увеличивая запас здоровья на 15%, снижая вероятность получить критический урон на 6%, повышая уровень создаваемой угрозы на 50% и увеличивая количество маны, получаемое от \"Жизнеотвода\", на 100%, но уменьшая наносимый вами урон на 10%. \"Метаморфоза\" меняет действие некоторых способностей и дает вам новые:\n\n \"Жгучая боль\": теперь применяется мгновенно.\n\n \"Стрела Тьмы\": меняется на \"Теневой рассекающий удар\" – атаку ближнего боя, наносящую максимум 10 противникам:противникам урон от темной магии, но требующую 6 сек. на восстановление.\n\n \"Страх\": меняется на \"Устрашение\".\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью.\n\n Демонический прыжок\n\n\nДемон бросается к противнику и оглушает его на 1 сек. Не действует во время боя.\n\n Демонический вой\n\n\nЗаставляет находящихся рядом противников атаковать вас в течение 6 сек."},
