[408755] = {name = "Кровавое подношение", additional_info = "Применение: 3 сек\n[q]Принести в жертву свою кровь, чтобы наполнить артефакт силой."},
[408793] = {name = "Элвиннский лес – мертвый послушник – улики", additional_info = nil},
