[409064] = {name = "Чтение рун", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 0 сек)\n[q]Поражение разума противника энергией темной магии, наносящей 0.0 ед. урона от темной магии в течение до отмены. и снижающей его скорость передвижения на 0%."},
[409073] = {name = "Аннигиляция", additional_info = "[q]Ваши атаки ближнего боя дают 0 ед. ярости."},
[409075] = {name = "Аннигиляция", additional_info = nil},
[409076] = {name = "Боль и страдание", additional_info = nil},
[409163] = {name = "Гравировка пояса \"Сосредоточенная ярость\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Сосредоточенная ярость\":\n\n\nСнижает расход ярости на атакующие способности на 3 ед."},
[409214] = {name = "Элитный враг-танк", additional_info = nil},
[409215] = {name = "Элитный враг-танк", additional_info = nil},
[409239] = {name = "Веер клинков", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мгновенный бросок оружия в обеих руках в противников в радиусе 8 м, наносящий 50% урона от оружия."},
[409240] = {name = "Веер клинков", additional_info = "Энергия: 50\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Вы метаете оружие в обеих руках, поражая противников в радиусе 8 м. Наносит 75% урона при броске кинжалов и 50% при броске другого оружия."},
[409317] = {name = "Сила души", additional_info = nil},
[409324] = {name = "Наставления предков", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]В течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\"."},
[409333] = {name = "Наставления предков", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]В течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\"."},
[409337] = {name = "Наставления предков", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]В течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\"."},
[409368] = {name = "Повелитель зверей", additional_info = "[q]Увеличивает урон и запас здоровья вашего питомца на 15%, а скорость восстановления концентрации – на 50%. Кроме того, \"Рык\" питомца теперь провоцирует цель, заставляя ее атаковать питомца в течение 3 сек."},
[409372] = {name = "Рык", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью."},
[409379] = {name = "Команда \"Взять!\"", additional_info = "{1.5% от базовой мана} {Радиус действия: 45 м}\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Отдает питомцу команду \"Взять!\", увеличивая урон от способностей питомца \"Цапнуть\" и \"Укус\" на 60% на 30 сек. С каждым применением этих способностей бонус к урону уменьшается на 20%."},
[409396] = {name = "Команда \"Взять!\"", additional_info = "Радиус действия: 45 м\nМгновенное действие\n[q]Отдает питомцу команду \"Взять!\", увеличивая урон от способностей питомца \"Цапнуть\" и \"Укус\" на 60% на 30 сек. С каждым применением этих способностей бонус к урону уменьшается на 20%."},
[409418] = {name = "Команда \"Взять!\"", additional_info = "Неограниченное расстояние\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Отдает питомцу команду \"Взять!\", увеличивая урон от способностей питомца \"Цапнуть\" и \"Укус\" на 60% на 30 сек. С каждым применением этих способностей бонус к урону уменьшается на 20%."},
[409423] = {name = "Взрыв трупа", additional_info = nil},
[409428] = {name = "Мастер стрельбы", additional_info = "[q]Повышает вероятность критического урона на 5% и снижает затраты маны на способности-выстрелы на 25%."},
[409433] = {name = "Выстрел химеры", additional_info = "{6% от базовой мана} {Радиус действия: 8 - 35 м}\nВосстановление: 6 сек\nТребуется: Оружие дальнего боя\n[q]Вы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\" и активируя дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще раза в минуту."},
[409493] = {name = "Выстрел химеры – змея", additional_info = "Радиус действия: 100 м\n[q]Вы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\". Кроме того, в зависимости от вида \"Укуса\" активируется дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще, чем раз в минуту."},
[409494] = {name = "Выстрел химеры – гадюка", additional_info = "Радиус действия: 100 м\n[q]Вы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\". Кроме того, в зависимости от вида \"Укуса\" активируется дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще, чем раз в минуту."},
[409495] = {name = "Выстрел химеры – скорпид", additional_info = "Радиус действия: 100 м\n[q]Вы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\". Кроме того, в зависимости от вида \"Укуса\" активируется дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще, чем раз в минуту."},
[409504] = {name = "Выявление слабости", additional_info = "[q]Критические атаки в ближнем и дальнем бою повышают силу атаки на 40% от текущего показателя ловкости на 7 сек."},
[409507] = {name = "Выявление слабости", additional_info = "Мгновенное действие\n[q]Критические атаки дальнего боя увеличивают силу атаки на 40% от показателя ловкости на 7 сек."},
[409510] = {name = "Замораживающая ловушка", additional_info = "{Мана: 50} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом ловушку, которая замораживает первого приблизившегося противника, лишая его возможности совершать какие-либо действия в течение 10 сек. Если цель получает урон, лед разбивается. Устанавливается на 1 мин. Единовременно может быть установлена только одна ловушка."},
[409512] = {name = "Замораживающая ловушка", additional_info = "{Мана: 75} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом ловушку, которая замораживает первого приблизившегося противника, лишая его возможности совершать какие-либо действия в течение 15 сек. Если цель получает урон, лед разбивается. Устанавливается на 1 мин. Единовременно может быть установлена только одна ловушка."},
[409519] = {name = "Замораживающая ловушка", additional_info = "{Мана: 100} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом ловушку, которая замораживает первого приблизившегося противника, лишая его возможности совершать какие-либо действия в течение 20 сек. Если цель получает урон, лед разбивается. Устанавливается на 1 мин. Единовременно может быть установлена только одна ловушка."},
[409520] = {name = "Ледяная ловушка", additional_info = "Мана: 60\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Устанавливает рядом ледяную ловушку, которая создает вокруг себя толстый слой льда на 30 сек., когда к ней приближается первый противник. Все противники в радиусе 10 м замедляются на 60%, пока остаются в зоне действия эффекта. Ловушка существует в течение 1 мин. Единовременно может быть установлена только одна ловушка."},
[409521] = {name = "Обжигающая ловушка", additional_info = "{Мана: 50} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая обжигает первого приблизившегося к ней противника, нанося ему 105 ед. урона от огня в течение 15 сек. Ловушка будет существовать 1 мин. Единовременно может быть установлена только одна ловушка."},
[409524] = {name = "Обжигающая ловушка", additional_info = "{Мана: 90} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая обжигает первого приблизившегося к ней противника, нанося ему 215 ед. урона от огня в течение 15 сек. Ловушка будет существовать 1 мин. Единовременно может быть установлена только одна ловушка."},
[409526] = {name = "Обжигающая ловушка", additional_info = "{Мана: 135} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая обжигает первого приблизившегося к ней противника, нанося ему 340 ед. урона от огня в течение 15 сек. Ловушка будет существовать 1 мин. Единовременно может быть установлена только одна ловушка."},
[409528] = {name = "Обжигающая ловушка", additional_info = "{Мана: 190} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая обжигает первого приблизившегося к ней противника, нанося ему 510 ед. урона от огня в течение 15 сек. Ловушка будет существовать 1 мин. Единовременно может быть установлена только одна ловушка."},
[409530] = {name = "Обжигающая ловушка", additional_info = "{Мана: 245} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая обжигает первого приблизившегося к ней противника, нанося ему 690 ед. урона от огня в течение 15 сек. Ловушка будет существовать 1 мин. Единовременно может быть установлена только одна ловушка."},
[409532] = {name = "Взрывная ловушка", additional_info = "{Мана: 275} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая взрывается при приближении к ней противника, мгновенно нанося 104 в 135 ед. урона от огня и дополнительно 150 ед. урона от огня в течение 20 сек. в радиусе 10 м. Время действия – 1 мин. Единовременно может быть активна только одна ловушка."},
[409534] = {name = "Взрывная ловушка", additional_info = "{Мана: 395} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая взрывается при приближении к ней противника, мгновенно нанося 145 в 193 ед. урона от огня и дополнительно 240 ед. урона от огня в течение 20 сек. в радиусе 10 м. Время действия – 1 мин. Единовременно может быть активна только одна ловушка."},
[409535] = {name = "Взрывная ловушка", additional_info = "{Мана: 520} {Радиус действия: 35 м}\nВосстановление: 15 сек\n[q]Устанавливает рядом огненную ловушку, которая взрывается при приближении к ней противника, мгновенно нанося 208 в 265 ед. урона от огня и дополнительно 330 ед. урона от огня в течение 20 сек. в радиусе 10 м. Время действия – 1 мин. Единовременно может быть активна только одна ловушка."},
[409541] = {name = "Бросок ловушки", additional_info = "[q]Ваши замораживающие, обжигающие и взрывные ловушки теперь можно размещать в любой точке на расстоянии до 35 м. Кроме того, у огненных и ледяных ловушек теперь отдельное время восстановления."},
[409552] = {name = "Разрывной выстрел", additional_info = "{3.5% от базовой мана} {Радиус действия: 8 - 35 м}\nВосстановление: 6 сек\nТребуется: Оружие дальнего боя\n[q]Разрывной выстрел наносит противникам в радиусе 8 м [Сила атаки дальнего боя * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Сила атаки дальнего боя * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. урона от огня. После этого заряд повторно наносит урон раз в сек. в течение 2 сек."},
[409554] = {name = "Разрывной выстрел", additional_info = "Неограниченное расстояние\n[q]Выстрел разрывным снарядом, наносящим врагу (Сила атаки дальнего боя * 0.14 + 10)-(Сила атаки дальнего боя * 0.14 + 10) ед. урона от огня. Заряд продолжает наносить цели урон каждую секунду в течение до отмены. Общее время восстановления с \"Чародейским выстрелом\"."},
[409580] = {name = "Львиное сердце", additional_info = "8% от базовой мана\nМгновенное действие\n[q]Охотник взывает к сердцу льва, повышающему окружающим союзникам все характеристики на 10% и силу атаки на 200 ед., а характеристики самого охотника – еще на 10%."},
[409583] = {name = "Львиное сердце", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Охотник взывает к сердцу льва, повышающему все характеристики окружающих союзников на 10%, а самого охотника – еще на 10%."},
[409593] = {name = "Убийственный выстрел", additional_info = "{3% от базовой мана} {Радиус действия: 35 м}\nВосстановление: 12 сек\nТребуется: Оружие дальнего боя\n[q]Вы пытаетесь добить раненую цель выстрелом, наносящим 100% урона от оружия и еще [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. \"Убийственный выстрел\" не имеет минимальной дальности применения. \"Убийственный выстрел\" мгновенно восстанавливается, когда вы применяете его против противника с уровнем здоровья 20% или менее."},
[409687] = {name = "Специализация на бое с оружием в обеих руках", additional_info = "[q]Увеличивает урон оружия в левой руке на 60%. При применении \"Удара ящера\" вы теперь атакуете оружием в обеих руках."},
[409691] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 2 в 3 ед."},
[409693] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 5 ед."},
[409748] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 10 в 11 ед."},
[409750] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 17 ед."},
[409751] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 25 ед."},
[409752] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 40 ед."},
[409754] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 55 ед."},
[409755] = {name = "Удар ящера", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Мощная атака, увеличивающая урон в ближнем бою на 70 ед."},
[409805] = {name = "Дикие удары", additional_info = "[q]Дает способность \"Дикие удары\":\n\n\nПока вы остаетесь в облике кошки, медведя или лютого медведя, участники группы или рейда в радиусе 100 м сражаются еще яростнее. Каждый удар ближнего боя с вероятностью 20% срабатывает повторно с увеличенной на 20% силой атаки. Не срабатывает, если на цель уже действует \"Тотем неистовства ветра\"."},
[409809] = {name = "Инстинкты выживания", additional_info = "[q]Дает способность \"Инстинкты выживания\":\n\n\nПри активации увеличивает максимальный запас здоровья на 30% и усиливает нефизическое исцеление на 20% на 20 сек. По завершении действия эффекта избыточное здоровье теряется. Можно применять в любом облике, кроме облика лунного совуха.\n\n Кроме того, уклоняясь от атаки в облике медведя и лютого медведя, вы накапливаете 5 ед. ярости, в облике кошки – 10 ед. энергии, а в любом другом облике – 1% максимального запаса маны."},
[409810] = {name = "Буйный рост", additional_info = "[q]Дает способность \"Буйный рост\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Скорость исцеления постепенно снижается на протяжении действия \"Буйного роста\"."},
[409813] = {name = "Затмение", additional_info = "[q]Дает способность \"Затмение\":\n\n\n\"Звездный огонь\" повышает вероятность критического удара следующих двух применений \"Гнева\" на 30%, а \"Гнев\" уменьшает время произнесения следующего \"Звездного огня\" на 1,1 сек. Оба эффекта суммируются до 4 раз. У обоих заклинаний теперь с вероятностью 70% не срабатывает задержка применения при получении урона."},
[409819] = {name = "Дикий рев", additional_info = "[q]Дает способность \"Дикий рев\":\n\n\nЗавершающий прием, увеличивающий наносимый физический урон в облике кошки на 30%. Время действия зависит от длины серии:\n 1 прием: 14 секунд\n 2 приема: 19 секунд.\n 3 приема: 24 секунды\n 4 приема: 29 секунд\n 5 приемов: 34 секунды."},
[409824] = {name = "Жизнецвет", additional_info = "[q]Сокращает общее время восстановления для \"Жизнецвета\" и \"Омоложения\" на 0.5 сек. и дает способность \"Жизнецвет\":\n\n\nВосполняет цели [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Когда время действия \"Жизнецвета\" завершается или эффект рассеивают, цель восстанавливает еще [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья, а друид восполняет половину маны, затраченной на заклинание. Эффект суммируется на одной цели до 3 раз."},
[409826] = {name = "Гнев природы", additional_info = "[q]Дает способность \"Гнев природы\":\n\n\nУвеличивает силу исцеления на 90% от урона заклинаний природы на 30 сек."},
[409828] = {name = "Увечье", additional_info = "[q]Дает способность \"Увечье\" (медведь) и заменяет \"Цапнуть\" на \"Увечье\" (кошка). Эта способность получает усиление от всех эффектов, связанных со способностями \"Цапнуть\" и \"Трепка\", а также активирует такие эффекты.\n\n\nУвечит цель, нанося ей 160% обычного урона и увеличивая урон, получаемый целью от эффектов кровотечения и способности \"Полоснуть\", на 30%. Действует в течение 1 мин.\n\n Когда вы поражаете цель \"Увечьем\" в облике медведя, ваша сила атаки повышается на 4 за каждую единицу навыка защиты выше ( 60 * 5). Действует в течение 15 сек.\n\n\nУвечит цель, нанося ей 270% обычного урона и увеличивая урон, получаемый целью от эффектов кровотечения и способности \"Полоснуть\", на 30%. Действует в течение 1 мин. Продлевает серию приемов на 1. Эта способность получает усиление от всех эффектов, связанных со способностями \"Цапнуть\" и \"Трепка\", а также активирует такие эффекты."},
[409830] = {name = "Покровительство природы", additional_info = "[q]Дает способность \"Покровительство природы\":\n\n\nВосстанавливает союзнику [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]-[189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья. Эффект усиливается на 20%, если цель находится под воздействием ваших заклинаний \"Омоложение\", \"Восстановление\", \"Жизнецвет\" или \"Буйный рост\". Это заклинание взаимодействует с теми же эффектами, что и \"Целительное прикосновение\" и \"Восстановление\"."},
[409831] = {name = "Состояние сна", additional_info = "[q]Дает способность \"Состояние сна\":\n\n\n\"\"После того как ваши заклинания прямого действия наносят критический урон или \"Звездный поток\" наносит любой урон, вы восполняете ману во время произнесения заклинаний со скоростью 50% от обычной в течение 8 сек. При этом урон от тайной магии и сил природы, наносимый цели, увеличивается на 20% на 12 сек., если она не является игроком.\"\""},
[409832] = {name = "Гнев Ярости Бури", additional_info = "[q]Дает способность \"Гнев Ярости Бури\":\n\n\n\"Гнев\" теперь расходует на 100% меньше маны, и его можно применять в облике Древа Жизни. Каждый раз, когда \"Гнев\" наносит урон, он с вероятностью 12% позволяет применить следующее \"Целительное прикосновение\" мгновенно и в любом облике. Время действия эффекта – 15 сек."},
[409856] = {name = "Ритуал души", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 10 мин)\n[q]Начинает ритуал освобождения души павшего искателя приключений."},
[409858] = {name = "Dummy Trigger", additional_info = nil},
[409906] = {name = "Частица Света", additional_info = "[q]Дает способность \"Частица Света\":\n\n\nНаделяет выбранного игрока частицей Света. Любое исцеление, которое вы применяете к участникам группы или рейда в радиусе 40 м от цели, также применяется к выбранному игроку с эффективностью 75%. Частицей Света можно наделить только одну цель. Время действия – 1 ч."},
[409911] = {name = "Длань возмездия", additional_info = "[q]Дает способность \"Длань возмездия\":\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если эта цель уже атакует вас.\n\n Пока вам известна эта способность, бонус к уровню создаваемой угрозы от \"Праведного неистовства\" увеличивается до 80%. Когда другие игроки исцеляют вас, \"Праведное неистовство\" восстанавливает вам ману в объеме 25% восполненного здоровья. Кроме того, если вы должны получить урон, после которого ваш уровень здоровья упадет ниже 35%, этот урон уменьшается на 20%. \"Праведное неистовство\" действует до отмены."},
[409914] = {name = "Удар воина Света", additional_info = "[q]Дает способность \"Удар воина Света\":\n\n\nМгновенный удар, наносящий 75% урона от оружия как урон от светлой магии и восстанавливающий 5% вашего максимального запаса маны. Время действия всех эффектов правосудия на цели обновляется до 30 сек."},
[409918] = {name = "Вдохновение (Правосудие)", additional_info = nil},
[409920] = {name = "Изучить реликвию (Правосудие)", additional_info = nil},
[409922] = {name = "Молот праведника", additional_info = "[q]Дает способность \"Молот праведника\":\n\n\nПоражает светлой магией текущую цель и до 3 находящихся поблизости целей, нанося урон от светлой магии, равный урону в секунду от оружия в правой руке, умноженному на 4."},
[409924] = {name = "Божественная буря", additional_info = "[q]Дает способность \"Божественная буря\":\n\n\nМгновенная атака, наносящая 110% урона от оружия 4 противникам:противникам в радиусе 8 м. \"Божественная буря\" исцеляет до 3 участников группы или рейда на 25% от нанесенного урона."},
[409925] = {name = "Божественный свет", additional_info = "[q]Дает способность \"Божественный свет\":\n\n\nВосполняет союзнику от [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] до [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] ед. здоровья. 50% избыточного исцеления преобразуется в поглощающий урон щит, существующий в течение 15 сек. Прочность щита не суммируется при повторном применении \"Божественного света\".\n\n \"Божественный свет\" взаимодействует с теми же талантами и эффектами, что и \"Свет небес\"."},
[409930] = {name = "Манускрипт правосудия", additional_info = nil},
[409932] = {name = "Владение аурами", additional_info = "[q]Дает способность \"Владение аурами\":\n\n\n\"Аура сосредоточенности\" дает целям невосприимчивость к немоте и эффектам прерывания. Эффективность других аур повышается на 100%. Время действия – 6 сек."},
[409933] = {name = "Щит мстителя", additional_info = "[q]Дает способность \"Щит мстителя\":\n\n\nБросает в противника священный щит, наносящий от [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] до [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] ед. урона от светлой магии и вызывающий головокружение. Щит затем перескакивает на других находящихся поблизости противников. Максимальное количество целей – 3. Время действия – 5 сек."},
[409934] = {name = "Гнев карателя", additional_info = "[q]Дает способность \"Гнев карателя\":\n\n\nУвеличивает весь наносимый урон и эффективность исцеления на 20% на 20 сек. Накладывает \"Воздержанность\". Нельзя применить под действием \"Воздержанности\"."},
[409935] = {name = "Длань жертвенности", additional_info = "[q]Дает способность \"Длань жертвенности\":\n\n\nНакладывает на участника группы или рейда эффект, перенаправляющий 30% получаемого им урона заклинателю. Длится 12 сек или до тех пор, пока заклинатель не передаст 100% от своего запаса здоровья."},
[409936] = {name = "Пример для подражания", additional_info = "[q]Дает способность\n \"Пример для подражания\":\n\n\nВаш вдохновляющий образ время от времени снимает эффекты страха и сна с находящихся рядом участников группы."},
[409938] = {name = "Кольцо огня", additional_info = "[q]Дает способность \"Кольцо огня\", которая заменяет \"Тотем кольца огня\":\n\n\n\"Тотем кольца огня\" заменяется на \"Кольцо огня\", при применении которого тотем огня пульсирует и наносит урон вокруг себя."},
[409940] = {name = "Специализация на бое с оружием в обеих руках", additional_info = "[q]Дает способность \"Специализация на бое с оружием в обеих руках\":\n\n\nКогда вы сражаетесь с оружием в обеих руках, вероятность попадания заклинаниями и атаками ближнего боя повышается на 5%. Кроме того, \"Удар бури\" теперь позволяет атаковать оружием в обеих руках, а также увеличивает урон оружия в левой руке на 60%."},
[409941] = {name = "Водный щит", additional_info = "[q]Дает способность \"Водный щит\":\n\n\nСоздает щит из 3 водяных сфер:водяных сфер, восполняющий 1% максимального запаса маны раз в 5 секунд. Каждый раз, когда шаман получает удар в ближнем или дальнем бою или его поражает заклинание, щит восполняет 4% максимального запаса маны, теряя одну сферу. Этот эффект срабатывает не чаще, чем раз в несколько секунд. Время действия – 10 мин. Шаман может быть защищен только одним заклинанием категории \"Щит стихий\" одновременно."},
[409943] = {name = "Мастерское владение щитом", additional_info = "[q]Дает способность \"Мастерское владение щитом\":\n\n\nБлокируя атаку, вы восполняете 8% максимального запаса маны и усиливаете броню на 30% от показателя брони вашего щита. Суммируется до 5 раз. Кроме того, ваша базовая вероятность блокирования повышается на 10%, а показатель блокирования – на 15%.\n\n Когда вы применяете способность категории \"Шок\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия – 15 сек."},
[409944] = {name = "Наставления предков", additional_info = "[q]Дает способность \"Наставления предков\":\n\n\nВ течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\"."},
[409945] = {name = "Перегрузка", additional_info = "[q]Дает способность \"Перегрузка\":\n\n\n\"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" с вероятностью 60% применяются к той же цели повторно без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы."},
[409946] = {name = "Оружие Водоворота", additional_info = "[q]Дает способность \"Оружие Водоворота\":\n\n\nАтаки ближнего боя с некоторой вероятностью сокращают время применения и стоимость следующего заклинания \"Молния\", \"Цепная молния\", \"Малая волна исцеления\" или \"Выброс лавы\" на 20%. Вероятность срабатывания повышается на 50%, если оружие в правой руке зачаровано \"Оружием неистовства ветра\", и еще на 50%, если вы используете двуручное оружие. Эффект суммируется до 5 раз. Время действия – 30 сек."},
[409947] = {name = "Щит земли", additional_info = "[q]Дает способность \"Щит земли\":\n\n\nЗащищает цель земляным щитом, который сокращает задержку применения и поддержания заклинаний при получении урона на 30%. Кроме того, когда защищенная цель становится целью атаки, она восполняет [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] ед. здоровья. Этот эффект срабатывает не чаще раза в несколько секунд. 9заряд:заряда:зарядов;. Время действия – 10 мин. \"Щит земли\" можно единовременно применить только к одной цели."},
[409951] = {name = "Дух вожака стаи", additional_info = "[q]Дает способность \"Дух вожака стаи\":\n\n\nУсиливает цель духом вожака стаи, повышая уровень создаваемой целью угрозы на 45% на 30 мин. Максимум 1 цель. Если шаман применяет это заклинание не к себе, он также получает эффект \"Верный помощник\", увеличивающий наносимый физический урон на 5% и уменьшая уровень создаваемой угрозы на 30% на 30 мин. Одна цель не может одновременно получить эффекты \"Дух вожака стаи\" и \"Верный помощник\"."},
[409952] = {name = "Выброс лавы", additional_info = "[q]Дает способность \"Выброс лавы\":\n\n\nВы бросаете в противника раскаленную лаву, наносящую [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]-[605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] ед. урона от огня. Если цель находится под действием эффекта \"Огненный шок\", \"Выброс лавы\" наносит критический удар."},
[409953] = {name = "Вскипание лавы", additional_info = "[q]Дает способность \"Вскипание лавы\":\n\n\nВы заряжаете оружие в левой руке энергией лавы и мгновенно наносите противнику урон в размере 100% от урона этого оружия. Если это оружие зачаровано \"Языком пламени\", наносимый урон увеличивается на 150%."},
[409954] = {name = "Быстрина", additional_info = "[q]Дает способность \"Быстрина\":\n\n\nВосполняет союзнику [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]-[63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. здоровья мгновенно и еще [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. за 15 сек. Каждое \"Цепное исцеление\", примененное вами к той же основной цели в течение 15 сек., восстанавливает на 25% больше здоровья. Вызывает срабатывание \"Пробуждения предка\"."},
[409955] = {name = "Путь земли", additional_info = "[q]Дает способность \"Путь земли\":\n\n\nПока \"Оружие камнедробителя\" действует на оружие в правой руке и вы держите щит в левой руке, уровень создаваемой вами угрозы повышается на 65%, запас здоровья увеличивается на 25%, получаемый урон уменьшается на 10%, вероятность получения критического удара в ближнем бою снижается на 6%, а \"Земной шок\" провоцирует цели, вынуждая атаковать вас, и получает отдельное время восстановления, но его дальность действия снижается до дистанции ближнего боя. Однако дальность заклинаний \"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" снижается на 20 м."},
[409957] = {name = "Верный выстрел", additional_info = "[q]Дает способность \"Верный выстрел\":\n\n\nВерный выстрел, наносящий 100% урона от оружия дальнего боя."},
[409958] = {name = "Мастер стрельбы", additional_info = "[q]Дает способность \"Мастер стрельбы\":\n\n\nПовышает вероятность критического урона на 5% и снижает затраты маны на способности-выстрелы на 25%."},
[409959] = {name = "Выявление слабости", additional_info = "[q]Дает способность \"Выявление слабости\":\n\n\nКритические атаки в ближнем и дальнем бою повышают силу атаки на 40% от текущего показателя ловкости на 7 сек."},
[409960] = {name = "Убийца кобр", additional_info = "[q]Дает способность \"Убийца кобр\":\n\n\nТеперь каждая атака ближнего боя может с вероятностью 10% вызвать срабатывание \"Укуса мангуста\", при этом \"Укус мангуста\" срабатывает с вероятностью 100%, если противник уклоняется. Вероятность постепенно возрастает на 10% с каждой атакой, если не происходит срабатывание. При срабатывании вероятность возвращается к исходному значению. Также \"Укус мангуста\" наносит дополнительный урон в размере 45% вашей силы атаки."},
[409961] = {name = "Специализация на бое с оружием в обеих руках", additional_info = "[q]Дает способность \"Специализация на бое с оружием в обеих руках\":\n\n\nУвеличивает урон оружия в левой руке на 60%. При применении \"Удара ящера\" вы теперь атакуете оружием в обеих руках."},
[409962] = {name = "Повелитель зверей", additional_info = "[q]Дает способность \"Повелитель зверей\":\n\n\nУвеличивает урон и запас здоровья вашего питомца на 15%, а скорость восстановления концентрации – на 50%. Кроме того, \"Рык\" питомца теперь провоцирует цель, заставляя ее атаковать питомца в течение 3 сек."},
[409963] = {name = "Призыв духа", additional_info = nil},
[409968] = {name = "Бросок ловушки", additional_info = "[q]Дает способность \"Бросок ловушки\":\n\n\nВаши замораживающие, обжигающие и взрывные ловушки теперь можно размещать в любой точке на расстоянии до 35 м. Кроме того, у огненных и ледяных ловушек теперь отдельное время восстановления."},
[409974] = {name = "Убийственный выстрел", additional_info = "[q]Дает способность \"Убийственный выстрел\":\n\n\nВы пытаетесь добить раненую цель выстрелом, наносящим 100% урона от оружия и еще [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. \"Убийственный выстрел\" не имеет минимальной дальности применения. \"Убийственный выстрел\" мгновенно восстанавливается, когда вы применяете его против противника с уровнем здоровья 20% или менее."},
[409976] = {name = "Выстрел химеры", additional_info = "[q]Дает способность \"Выстрел химеры\":\n\n\nВы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\" и активируя дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще раза в минуту."},
[409978] = {name = "Разрывной выстрел", additional_info = "[q]Дает способность \"Разрывной выстрел\":\n\n\nРазрывной выстрел наносит противникам в радиусе 8 м [Сила атаки дальнего боя * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Сила атаки дальнего боя * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. урона от огня. После этого заряд повторно наносит урон раз в сек. в течение 2 сек."},
[409979] = {name = "Одинокий волк", additional_info = "[q]Дает способность \"Одинокий волк\":\n\n\nВаши атаки наносят на 25% больше урона, пока у вас нет активного питомца."},
[409988] = {name = "Force Player Cast Delayed Banish", additional_info = nil},
[409999] = {name = "Гравировка перчаток \"Частица Света\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Частица Света\":\n\n\nНаделяет выбранного игрока частицей Света. Любое исцеление, которое вы применяете к участникам группы или рейда в радиусе 40 м от цели, также применяется к выбранному игроку с эффективностью 75%. Частицей Света можно наделить только одну цель. Время действия – 1 ч."},
[410001] = {name = "Гравировка перчаток \"Длань возмездия\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Длань возмездия\":\n\n\nПровоцирует цель, заставляя ее атаковать вас. Не действует, если эта цель уже атакует вас.\n\n Пока вам известна эта способность, бонус к уровню создаваемой угрозы от \"Праведного неистовства\" увеличивается до 80%. Когда другие игроки исцеляют вас, \"Праведное неистовство\" восстанавливает вам ману в объеме 25% восполненного здоровья. Кроме того, если вы должны получить урон, после которого ваш уровень здоровья упадет ниже 35%, этот урон уменьшается на 20%. \"Праведное неистовство\" действует до отмены."},
[410002] = {name = "Гравировка перчаток \"Удар воина Света\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Удар воина Света\":\n\n\nМгновенный удар, наносящий 75% урона от оружия как урон от светлой магии и восстанавливающий 5% вашего максимального запаса маны. Время действия всех эффектов правосудия на цели обновляется до 30 сек."},
[410005] = {name = "Гравировка поножей \"Владение аурами\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Владение аурами\":\n\n\n\"Аура сосредоточенности\" дает целям невосприимчивость к немоте и эффектам прерывания. Эффективность других аур повышается на 100%. Время действия – 6 сек."},
[410008] = {name = "Гравировка поножей \"Щит мстителя\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Щит мстителя\":\n\n\nБросает в противника священный щит, наносящий от [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] до [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] ед. урона от светлой магии и вызывающий головокружение. Щит затем перескакивает на других находящихся поблизости противников. Максимальное количество целей – 3. Время действия – 5 сек."},
[410010] = {name = "Гравировка поножей \"Длань жертвенности\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Длань жертвенности\":\n\n\nНакладывает на участника группы или рейда эффект, перенаправляющий 30% получаемого им урона заклинателю. Длится 12 сек или до тех пор, пока заклинатель не передаст 100% от своего запаса здоровья."},
[410011] = {name = "Гравировка поножей \"Пример для подражания\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Пример для подражания\":\n\n\nВаш вдохновляющий образ время от времени снимает эффекты страха и сна с находящихся рядом участников группы."},
[410013] = {name = "Гравировка наручей \"Молот праведника\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Молот праведника\":\n\n\nПоражает светлой магией текущую цель и до 3 находящихся поблизости целей, нанося урон от светлой магии, равный урону в секунду от оружия в правой руке, умноженному на 4."},
[410014] = {name = "Гравировка нагрудника \"Божественная буря\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике руну \"Божественная буря\":\n\n\nМгновенная атака, наносящая 110% урона от оружия 4 противникам:противникам в радиусе 8 м. \"Божественная буря\" исцеляет до 3 участников группы или рейда на 25% от нанесенного урона."},
[410015] = {name = "Гравировка плаща \"Божественный свет\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Божественный свет\":\n\n\nВосполняет союзнику от [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] до [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] ед. здоровья. 50% избыточного исцеления преобразуется в поглощающий урон щит, существующий в течение 15 сек. Прочность щита не суммируется при повторном применении \"Божественного света\".\n\n \"Божественный свет\" взаимодействует с теми же талантами и эффектами, что и \"Свет небес\"."},
[410021] = {name = "Гравировка нагрудника \"Дикие удары\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Дикие удары\":\n\n\nПока вы остаетесь в облике кошки, медведя или лютого медведя, участники группы или рейда в радиусе 100 м сражаются еще яростнее. Каждый удар ближнего боя с вероятностью 20% срабатывает повторно с увеличенной на 20% силой атаки. Не срабатывает, если на цель уже действует \"Тотем неистовства ветра\"."},
[410023] = {name = "Гравировка поножей \"Дикий рев\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Дикий рев\":\n\n\nЗавершающий прием, увеличивающий наносимый физический урон в облике кошки на 30%. Время действия зависит от длины серии:\n 1 прием: 14 секунд\n 2 приема: 19 секунд.\n 3 приема: 24 секунды\n 4 приема: 29 секунд\n 5 приемов: 34 секунды."},
[410025] = {name = "Гравировка перчаток \"Увечье\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Увечье\":\n\n\nУвечит цель, нанося ей 160% обычного урона и увеличивая урон, получаемый целью от эффектов кровотечения и способности \"Полоснуть\", на 30%. Действует в течение 1 мин.\n\n Когда вы поражаете цель \"Увечьем\" в облике медведя, ваша сила атаки повышается на 4 за каждую единицу навыка защиты выше ( 60 * 5). Действует в течение 15 сек."},
[410027] = {name = "Гравировка обуви \"Инстинкты выживания\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Инстинкты выживания\":\n\n\nПри активации увеличивает максимальный запас здоровья на 30% и усиливает нефизическое исцеление на 20% на 20 сек. По завершении действия эффекта избыточное здоровье теряется. Можно применять в любом облике, кроме облика лунного совуха.\n\n Кроме того, уклоняясь от атаки в облике медведя и лютого медведя, вы накапливаете 5 ед. ярости, в облике кошки – 10 ед. энергии, а в любом другом облике – 1% максимального запаса маны."},
[410028] = {name = "Гравировка перчаток \"Буйный рост\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Буйный рост\":\n\n\nИсцеляет участников группы или рейда выбранного игрока в радиусе 43.5 м от него, восполняя [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Скорость исцеления постепенно снижается на протяжении действия \"Буйного роста\"."},
[410029] = {name = "Гравировка пояса \"Затмение\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Затмение\":\n\n\n\"Звездный огонь\" повышает вероятность критического удара следующих двух применений \"Гнева\" на 30%, а \"Гнев\" уменьшает время произнесения следующего \"Звездного огня\" на 1,1 сек. Оба эффекта суммируются до 4 раз. У обоих заклинаний теперь с вероятностью 70% не срабатывает задержка применения при получении урона."},
[410033] = {name = "Гравировка поножей \"Жизнецвет\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Жизнецвет\":\n\nСокращает общее время восстановления для \"Жизнецвета\" и \"Омоложения\" на 0.5 сек. и дает способность \"Жизнецвет\":\n\n\nВосполняет цели [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья за 7 сек. Когда время действия \"Жизнецвета\" завершается или эффект рассеивают, цель восстанавливает еще [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья, а друид восполняет половину маны, затраченной на заклинание. Эффект суммируется на одной цели до 3 раз."},
[410059] = {name = "Гравировка пояса \"Покровительство природы\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Покровительство природы\":\n\n\nВосстанавливает союзнику [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]-[189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] ед. здоровья. Эффект усиливается на 20%, если цель находится под воздействием ваших заклинаний \"Омоложение\", \"Восстановление\", \"Жизнецвет\" или \"Буйный рост\". Это заклинание взаимодействует с теми же эффектами, что и \"Целительное прикосновение\" и \"Восстановление\"."},
[410060] = {name = "Гравировка обуви \"Состояние сна\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Состояние сна\":\n\n\n\"\"После того как ваши заклинания прямого действия наносят критический урон или \"Звездный поток\" наносит любой урон, вы восполняете ману во время произнесения заклинаний со скоростью 50% от обычной в течение 8 сек. При этом урон от тайной магии и сил природы, наносимый цели, увеличивается на 20% на 12 сек., если она не является игроком.\"\""},
[410061] = {name = "Гравировка нагрудника \"Гнев Ярости Бури\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Гнев Ярости Бури\":\n\n\n\"Гнев\" теперь расходует на 100% меньше маны, и его можно применять в облике Древа Жизни. Каждый раз, когда \"Гнев\" наносит урон, он с вероятностью 12% позволяет применить следующее \"Целительное прикосновение\" мгновенно и в любом облике. Время действия эффекта – 15 сек."},
[410093] = {name = "Гравировка пояса \"Кольцо огня\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Кольцо огня\":\n\n\n\"Тотем кольца огня\" заменяется на \"Кольцо огня\", при применении которого тотем огня пульсирует и наносит урон вокруг себя."},
[410094] = {name = "Гравировка нагрудника \"Перегрузка\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Перегрузка\":\n\n\n\"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" с вероятностью 60% применяются к той же цели повторно без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы."},
[410095] = {name = "Гравировка перчаток \"Выброс лавы\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Выброс лавы\":\n\nВы бросаете в противника раскаленную лаву, наносящую [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]-[605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] ед. урона от огня. Если цель находится под действием эффекта \"Огненный шок\", \"Выброс лавы\" наносит критический удар."},
[410096] = {name = "Гравировка нагрудника \"Специализация на бое с оружием в обеих руках\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Специализация на бое с оружием в обеих руках\":\n\n\nКогда вы сражаетесь с оружием в обеих руках, вероятность попадания заклинаниями и атаками ближнего боя повышается на 5%. Кроме того, \"Удар бури\" теперь позволяет атаковать оружием в обеих руках, а также увеличивает урон оружия в левой руке на 60%."},
[410097] = {name = "Гравировка перчаток \"Водный щит\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Водный щит\":\n\n\nСоздает щит из 3 водяных сфер:водяных сфер, восполняющий 1% максимального запаса маны раз в 5 секунд. Каждый раз, когда шаман получает удар в ближнем или дальнем бою или его поражает заклинание, щит восполняет 4% максимального запаса маны, теряя одну сферу. Этот эффект срабатывает не чаще, чем раз в несколько секунд. Время действия – 10 мин. Шаман может быть защищен только одним заклинанием категории \"Щит стихий\" одновременно."},
[410098] = {name = "Гравировка нагрудника \"Мастерское владение щитом\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Мастерское владение щитом\":\n\n\nБлокируя атаку, вы восполняете 8% максимального запаса маны и усиливаете броню на 30% от показателя брони вашего щита. Суммируется до 5 раз. Кроме того, ваша базовая вероятность блокирования повышается на 10%, а показатель блокирования – на 15%.\n\n Когда вы применяете способность категории \"Шок\", ваш урон от заклинаний увеличивается на 4 ед. за каждую единицу навыка защиты выше ( 60 * 5). Время действия – 15 сек."},
[410099] = {name = "Гравировка поножей \"Наставления предков\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Наставления предков\":\n\n\nВ течение следующих 10 сек. 25% наносимого вами урона восполняют здоровье максимум 3 ближайшим участникам группы, а 100% творимого вами исцеления наносятся как урон последней цели \"Огненного шока\"."},
[410100] = {name = "Гравировка пояса \"Оружие Водоворота\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Оружие Водоворота\":\n\n\nАтаки ближнего боя с некоторой вероятностью сокращают время применения и стоимость следующего заклинания \"Молния\", \"Цепная молния\", \"Малая волна исцеления\" или \"Выброс лавы\" на 20%. Вероятность срабатывания повышается на 50%, если оружие в правой руке зачаровано \"Оружием неистовства ветра\", и еще на 50%, если вы используете двуручное оружие. Эффект суммируется до 5 раз. Время действия – 30 сек."},
[410101] = {name = "Гравировка поножей \"Щит земли\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Щит земли\":\n\n\nЗащищает цель земляным щитом, который сокращает задержку применения и поддержания заклинаний при получении урона на 30%. Кроме того, когда защищенная цель становится целью атаки, она восполняет [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] ед. здоровья. Этот эффект срабатывает не чаще раза в несколько секунд. 9заряд:заряда:зарядов;. Время действия – 10 мин. \"Щит земли\" можно единовременно применить только к одной цели."},
[410103] = {name = "Гравировка обуви \"Дух вожака стаи\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Дух вожака стаи\":\n\n\nУсиливает цель духом вожака стаи, повышая уровень создаваемой целью угрозы на 45% на 30 мин. Максимум 1 цель. Если шаман применяет это заклинание не к себе, он также получает эффект \"Верный помощник\", увеличивающий наносимый физический урон на 5% и уменьшая уровень создаваемой угрозы на 30% на 30 мин. Одна цель не может одновременно получить эффекты \"Дух вожака стаи\" и \"Верный помощник\"."},
[410104] = {name = "Гравировка перчаток \"Вскипание лавы\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Вскипание лавы\":\n\nВы заряжаете оружие в левой руке энергией лавы и мгновенно наносите противнику урон в размере 100% от урона этого оружия. Если это оружие зачаровано \"Языком пламени\", наносимый урон увеличивается на 150%."},
[410105] = {name = "Гравировка наручей \"Быстрина\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Быстрина\":\n\n\nВосполняет союзнику [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]-[63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. здоровья мгновенно и еще [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] ед. за 15 сек. Каждое \"Цепное исцеление\", примененное вами к той же основной цели в течение 15 сек., восстанавливает на 25% больше здоровья. Вызывает срабатывание \"Пробуждения предка\"."},
[410107] = {name = "Гравировка поножей \"Путь земли\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Путь земли\":\n\n\nПока \"Оружие камнедробителя\" действует на оружие в правой руке и вы держите щит в левой руке, уровень создаваемой вами угрозы повышается на 65%, запас здоровья увеличивается на 25%, получаемый урон уменьшается на 10%, вероятность получения критического удара в ближнем бою снижается на 6%, а \"Земной шок\" провоцирует цели, вынуждая атаковать вас, и получает отдельное время восстановления, но его дальность действия снижается до дистанции ближнего боя. Однако дальность заклинаний \"Молния\", \"Цепная молния\", \"Цепное исцеление\", \"Волна исцеления\" и \"Выброс лавы\" снижается на 20 м."},
[410109] = {name = "Гравировка пояса \"Верный выстрел\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Верный выстрел\":\n\n\nВерный выстрел, наносящий 100% урона от оружия дальнего боя."},
[410110] = {name = "Гравировка нагрудника \"Повелитель зверей\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Повелитель зверей\":\n\n\nУвеличивает урон и запас здоровья вашего питомца на 15%, а скорость восстановления концентрации – на 50%. Кроме того, \"Рык\" питомца теперь провоцирует цель, заставляя ее атаковать питомца в течение 3 сек."},
[410111] = {name = "Гравировка поножей \"Убийственный выстрел\"", additional_info = "Применение: 3 сек\nТребуется: Штаны\n[q]Выгравировать на поножах руну \"Убийственный выстрел\":\n\n\nВы пытаетесь добить раненую цель выстрелом, наносящим 100% урона от оружия и еще [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. \"Убийственный выстрел\" не имеет минимальной дальности применения. \"Убийственный выстрел\" мгновенно восстанавливается, когда вы применяете его против противника с уровнем здоровья 20% или менее."},
[410113] = {name = "Гравировка нагрудника \"Мастер стрельбы\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Мастер стрельбы\":\n\n\nПовышает вероятность критического урона на 5% и снижает затраты маны на способности-выстрелы на 25%."},
[410114] = {name = "Гравировка пояса \"Выявление слабости\"", additional_info = "Применение: 3 сек\nТребуется: Пояс\n[q]Выгравировать на поясе руну \"Выявление слабости\":\n\n\nКритические атаки в ближнем и дальнем бою повышают силу атаки на 40% от текущего показателя ловкости на 7 сек."},
[410115] = {name = "Убийца кобр", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Убийца кобр\":\n\n\nТеперь каждая атака ближнего боя может с вероятностью 10% вызвать срабатывание \"Укуса мангуста\", при этом \"Укус мангуста\" срабатывает с вероятностью 100%, если противник уклоняется. Вероятность постепенно возрастает на 10% с каждой атакой, если не происходит срабатывание. При срабатывании вероятность возвращается к исходному значению. Также \"Укус мангуста\" наносит дополнительный урон в размере 45% вашей силы атаки."},
[410116] = {name = "Гравировка обуви \"Специализация на бое с оружием в обеих руках\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Специализация на бое с оружием в обеих руках\":\n\n\nУвеличивает урон оружия в левой руке на 60%. При применении \"Удара ящера\" вы теперь атакуете оружием в обеих руках."},
[410118] = {name = "Гравировка обуви \"Бросок ловушки\"", additional_info = "Применение: 3 сек\nТребуется: Обувь\n[q]Выгравировать на обуви руну \"Бросок ловушки\":\n\n\nВаши замораживающие, обжигающие и взрывные ловушки теперь можно размещать в любой точке на расстоянии до 35 м. Кроме того, у огненных и ледяных ловушек теперь отдельное время восстановления."},
[410121] = {name = "Гравировка перчаток \"Выстрел химеры\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Выстрел химеры\":\n\n\nВы наносите 135% урона от оружия, обновляя действие текущего \"Укуса\" и активируя дополнительный эффект:\n\n \"Укус змеи\" – моментально наносит 48% от урона \"Укуса змеи\".\n\n \"Укус гадюки\" – моментально восполняет 60% маны, вытягиваемой этой способностью.\n\n \"Укус скорпида\" – пытается обезоружить противника на 10 сек сек. Этот эффект срабатывает не чаще раза в минуту."},
[410122] = {name = "Гравировка нагрудника \"Одинокий волк\"", additional_info = "Применение: 3 сек\nТребуется: Грудь, Грудь\n[q]Выгравировать на нагруднике или мантии руну \"Одинокий волк\":\n\n\nВаши атаки наносят на 25% больше урона, пока у вас нет активного питомца."},
[410123] = {name = "Гравировка перчаток \"Разрывной выстрел\"", additional_info = "Применение: 3 сек\nТребуется: Перчатки\n[q]Выгравировать на перчатках руну \"Разрывной выстрел\":\n\n\nРазрывной выстрел наносит противникам в радиусе 8 м [Сила атаки дальнего боя * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Сила атаки дальнего боя * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. урона от огня. После этого заряд повторно наносит урон раз в сек. в течение 2 сек."},
[410140] = {name = "Яд паука", additional_info = nil},
[410144] = {name = "Дикая защита", additional_info = "Мгновенное действие\nТребуется: Облик медведя, Облик лютого медведя"},
[410156] = {name = "Удар бури", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Позволяет совершить еще одну атаку. Увеличивает урон от сил природы, который цель получит от следующих 2 атак, на 20%. Время действия – 12 сек."},
[410163] = {name = "Некротическое заражение", additional_info = nil},
[410169] = {name = "Wounded Adventurer Periodic Dummy", additional_info = nil},
[410176] = {name = "Лобовая атака", additional_info = "{Энергия: 25 /} {Ярость: 10 Радиус действия: 13 м}\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Облик кошки, Облик медведя, Облик лютого медведя\n[q]Вы бросаетесь к противнику в радиусе 13 м и с силой бьете его по голове, прерывая произносимые им заклинания. Противник не сможет произносить заклинания той же школы в течение 2 сек. Имеет общее время восстановления со \"Звериной атакой\"."},
[410262] = {name = "Лив Брэдфорд – дать руну паладина", additional_info = nil},
[410272] = {name = "Очищенный раненый искатель приключений", additional_info = nil},
[410275] = {name = "Раненый искатель приключений – дать руну паладина", additional_info = nil},
[410412] = {name = "Издевка", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если вы уже сражаетесь с целью."},
[410657] = {name = "Дуэль насмерть", additional_info = nil},
[410659] = {name = "Изгнание духа", additional_info = nil},
[410662] = {name = "Отсроченное изгнание", additional_info = nil},
[410718] = {name = "Ада Гельхардт – дать заметку", additional_info = nil},
[410738] = {name = "Бой с Адой Гельхардт", additional_info = nil},
[410829] = {name = "Ада Гельхардт – дать руну в награду", additional_info = nil},
[410881] = {name = "Священная земля", additional_info = nil},
[410935] = {name = "Медитация о Свете", additional_info = nil},
[410958] = {name = "Изучение руны из воспоминания", additional_info = "Применение: 3 сек\n[q]Сосредоточиться на воспоминании, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о духовных тайнах Азерота."},
[410970] = {name = "Медитация о Бездне", additional_info = nil},
[410971] = {name = "Изучение руны из пророчества", additional_info = "Применение: 3 сек\n[q]Сосредоточиться на пророчестве, чтобы изучить новое заклинание. Перед этим нужно очистить сознание медитацией о двух духовных тайнах Азерота."},
[411115] = {name = "Выживание сильнейших", additional_info = "[q]Уменьшает вероятность получить критический удар в ближнем бою на 6% и уменьшает получаемый урон на 10%. В облике медведя или лютого медведя урон уменьшается еще на 10%."},
[411124] = {name = "Выживание сильнейших", additional_info = "Мгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Уменьшает получаемый урон на 10%."},
[411128] = {name = "Размах", additional_info = "{Энергия: 50} {Дистанция ближнего боя}\nМгновенное действие\nТребуется: Облик кошки\n[q]Атакует ближайших противников, нанося им 250% урона от оружия и продлевая серию приемов для текущей цели на 1."},
[411186] = {name = "Установка приманки", additional_info = "Применение: 1 сек\nИнгредиенты:\nМясо мулгорской птицы\n[q]Положить приманку у логова скальной кошки."},
[411210] = {name = "Волна исцеления", additional_info = nil},
[411220] = {name = "Волна исцеления", additional_info = nil},
[411239] = {name = "Волна исцеления", additional_info = nil},
[411249] = {name = "Выслеживание Моквы (один)", additional_info = "Мгновенное действие\n[q]Положить приманку у логова зверя."},
[411253] = {name = "Грохот прилива", additional_info = nil},
[411263] = {name = "Выслеживание Моквы (два)", additional_info = "Мгновенное действие\n[q]Положить приманку у логова зверя."},
[411272] = {name = "Выслеживание Моквы (три)", additional_info = "Мгновенное действие\n[q]Положить приманку у логова зверя."},
[411280] = {name = "Грохот прилива", additional_info = nil},
[411282] = {name = "Молния", additional_info = nil},
[411284] = {name = "Молния", additional_info = nil},
[411583] = {name = "Замена стойки на плавание", additional_info = nil},
[411608] = {name = "Приручение луговой собачки", additional_info = nil},
[411622] = {name = "Мускус луговой собачки", additional_info = "{Мгновенное действие} {Восстановление: 10 мин}\n[q]\"Приручение зверя\" также действует на луговых собачек (как на питомцев - спутников)"},
[411624] = {name = "Приручение зверя", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Начинает приручение животного, которое может стать вашим питомцем. Ваша броня ослабевает на 100% на 20 сек., пока вы заняты приручением. Если вы теряете внимание животного по какой-либо причине, процесс приручения прерывается. Только что укрощенное животное недовольно и хочет сбежать. Постарайтесь его сразу же накормить, чтобы оно повеселело."},
[411631] = {name = "Приручение зверя", additional_info = "{60% от базовой мана} {Радиус действия: 30 м}\nНаправляемое (Применение: 20 сек)\n[q]Начинает приручение животного, которое может стать вашим питомцем. Ваша броня ослабевает на 100% на 20 сек., пока вы заняты приручением. Если вы теряете внимание животного по какой-либо причине, процесс приручения прерывается. Только что укрощенное животное недовольно и хочет сбежать. Постарайтесь его сразу же накормить, чтобы оно повеселело."},
[411684] = {name = "Рывок", additional_info = "Радиус действия: 8 - 25 м\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Воин совершает стремительный рывок к противнику, оглушая его на 1 сек. и накапливая 0 ед. ярости."},
[411688] = {name = "Оглушающий рывок", additional_info = "Радиус действия: 8 - 25 м\nМгновенное действие\nТребуется: Боевая стойка"},
[411774] = {name = "Вихрь", additional_info = "Направляемое (Применение: 2 сек)\n[q]Кружась в вихре, атакует находящихся рядом противников в течение 2 сек., нанося обычный урон плюс 50 ед. дополнительного урона."},
[411775] = {name = "Вихрь", additional_info = nil},
[411777] = {name = "Руна разделки туши – дать руну", additional_info = nil},
[411956] = {name = "Проклятие Черных Глубин", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Цель бьется в агонии, получая 600 ед. урона от темной магии в течение 12 сек. Урон постепенно увеличивается и достигает своего пика к концу действия проклятия."},
[411959] = {name = "Страх", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Повергает противника в ужас и обращает в бегство на 4 сек. Максимум целей – 1."},
[411961] = {name = "Обнаружение браконьера", additional_info = nil},
[411973] = {name = "Проклятие Черных Глубин", additional_info = nil},
[411978] = {name = "Проклятие Черных Глубин", additional_info = nil},
[411990] = {name = "Темное сокрушение", additional_info = nil},
[411991] = {name = "Темное сокрушение", additional_info = nil},
[411992] = {name = "Темное сокрушение", additional_info = nil},
[411993] = {name = "Неубедительная маскировка", additional_info = nil},
[411995] = {name = "Темное сокрушение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Наносит 50 ед. урона от темной магии раз в 1 сек."},
[412009] = {name = "Темное сокрушение", additional_info = nil},
[412018] = {name = "Священный щит", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Каждый раз при получении урона цель ограждается священным щитом, поглощающим 36 ед. урона , а вероятность критического эффекта \"Вспышки Света\" паладина, примененного к цели, повышается на 50% на 6 сек. Эффект срабатывает не чаще, чем раз в 6 секунд. Время действия – 6 сек."},
[412019] = {name = "Священный щит", additional_info = "{12% от базовой мана} {Радиус действия: 40 м}\nМгновенное действие\n[q]Каждый раз, когда цель получает урон, ее окружает священный щит, поглощающий [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] ед. урона. При этом вероятность критического эффекта \"Вспышки Света\" паладина повышается на 50% максимум на 6 сек. Кроме того, \"Вспышка Света\" восстанавливает целям со \"Священным щитом\" еще 100% здоровья за 12 сек. Эффект срабатывает не чаще раза в 6 сек. Время действия – 1 мин. Заклинание можно накладывать единовременно только на одну цель."},
[412020] = {name = "Вспышка Света", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Периодическое исцеление."},
[412040] = {name = "Темное сокрушение", additional_info = nil},
[412072] = {name = "Теневой удар", additional_info = nil},
[412079] = {name = "Теневой удар", additional_info = nil},
[412080] = {name = "Теневой удар", additional_info = nil},
[412096] = {name = "Кровавый вихрь", additional_info = "{Энергия: 35} {Радиус действия: 8 м}\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Завершающий прием, который с размаху бьет противников в радиусе 8 м и вызывает у них кровотечение. Время действия и урон увеличиваются с длиной серии.\n\n 1 прием: (Сила атаки * 0.30) ед. урона за 4 сек.\n 2 приема: (Сила атаки * 0.45) ед. урона за 6 сек.\n 3 приема: (Сила атаки * 0.60) ед. урона за 8 сек.\n 4 приема: (Сила атаки * 0.75) ед. урона за 10 сек.\n 5 приемов: (Сила атаки * 0.90) ед. урона за 12 сек.\n\n \"Кровавый вихрь\" взаимодействует с теми же талантами и эффектами, что и \"Рваная рана\"."},
[412107] = {name = "Ненависть к нулю", additional_info = nil},
[412113] = {name = "Снятие мощного проклятия", additional_info = "{10% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Снимает с союзника 1 проклятие и 1 отрицательный магический эффект."},
[412114] = {name = "Наделение силой Бездны", additional_info = nil},
[412115] = {name = "Улучшенные обереги", additional_info = "[q]\"Щит маны\", \"Защиту от магии льда\" и \"Защиту от огня\" теперь можно применять к любому союзнику. Они поглощают на 100% больше урона, а \"Щит маны\" расходует на 50% меньше маны за единицу поглощенного урона. Кроме того, \"Снятие малого проклятия\" заменяется на \"Снятие мощного проклятия\".\n\n\nСнимает с союзника 1 проклятие и 1 отрицательный магический эффект."},
[412116] = {name = "Щит маны", additional_info = "{Мана: 40} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника, поглощая 240 ед. физического урона и расходуя вместо этого ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412118] = {name = "Щит маны", additional_info = "{Мана: 60} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника, поглощая 420 ед. физического урона и расходуя вместо этого ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412120] = {name = "Щит маны", additional_info = "{Мана: 80} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника, поглощая 600 ед. физического урона и расходуя вместо этого ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412121] = {name = "Щит маны", additional_info = "{Мана: 100} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника, поглощая 780 ед. физического урона и расходуя вместо этого ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412122] = {name = "Щит маны", additional_info = "{Мана: 120} {Радиус действия: 40 м}\nМгновенное действие\n[q]Защищает союзника, поглощая 960 ед. физического урона и расходуя вместо этого ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412123] = {name = "Щит маны", additional_info = "{Мана: 140} {Радиус действия: 40 м}\nМгновенное действие\n[q]Поглощает 1140 ед. физического урона, наносимого союзнику, расходуя ману. За каждую единицу поглощенного урона маг теряет 1 ед. маны. Действует 1 мин."},
[412179] = {name = "Хитроумная маскировка?", additional_info = nil},
[412202] = {name = "Защита от магии льда", additional_info = "{Мана: 85} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 330 ед. урона от магии льда. Время действия – 30 сек."},
[412205] = {name = "Защита от магии льда", additional_info = "{Мана: 135} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 580 ед. урона от магии льда. Время действия – 30 сек."},
[412207] = {name = "Защита от магии льда", additional_info = "{Мана: 195} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 940 ед. урона от магии льда. Время действия – 30 сек."},
[412209] = {name = "Защита от магии льда", additional_info = "{Мана: 255} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 1350 ед. урона от магии льда. Время действия – 30 сек."},
[412210] = {name = "Защита от магии льда", additional_info = "{Мана: 320} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 1840 ед. урона от магии льда. Время действия – 30 сек."},
[412214] = {name = "Защита от огня", additional_info = "{Мана: 85} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 330 ед. урона от огня. Время действия – 30 сек."},
[412218] = {name = "Защита от огня", additional_info = "{Мана: 135} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 580 ед. урона от огня. Время действия – 30 сек."},
[412230] = {name = "Защита от огня", additional_info = "{Мана: 195} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 940 ед. урона от огня. Время действия – 30 сек."},
[412231] = {name = "Защита от огня", additional_info = "{Мана: 255} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 1350 ед. урона от огня. Время действия – 30 сек."},
[412232] = {name = "Защита от огня", additional_info = "{Мана: 320} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Поглощает 1840 ед. урона от огня. Время действия – 30 сек."},
