[412278] = {name = "Сбор взрывчатки", additional_info = nil},
[412286] = {name = "Выгорание", additional_info = "[q]Увеличивает вероятность критического урона заклинаний на 15%. Когда ваши наносящие прямой урон заклинания наносят критический удар, они расходуют еще 1% вашего базового запаса маны."},
[412296] = {name = "Наделение силой Бездны", additional_info = nil},
[412322] = {name = "Сила заклинаний", additional_info = "[q]Увеличивает бонус к критическому урону заклинаний на 50%."},
[412324] = {name = "Просветление", additional_info = "[q]Вы наносите на 10% больше урона, пока уровень маны выше 70%. При уровне маны ниже 30% она продолжает восстанавливаться во время применения заклинаний со скоростью 10% от обычной."},
[412325] = {name = "Просветление", additional_info = "Мгновенное действие\n[q]Во время произнесения заклинаний мана восполняется со скоростью 10% от обычной."},
[412326] = {name = "Просветление", additional_info = "Мгновенное действие\n[q]Увеличивает урон от заклинаний на 10%."},
[412365] = {name = "Сбор шишек", additional_info = nil},
[412421] = {name = "Наделение силой Бездны", additional_info = nil},
[412427] = {name = "Марш мурлоков", additional_info = nil},
[412428] = {name = "Изготовление мази", additional_info = "Применение: 5 сек\nИнгредиенты:\nШишка неистовства ветра (8)\n[q]Растереть 8 шишек Неистовства Ветра, чтобы изготовить ядовитую мазь для оружия. В теории."},
[412437] = {name = "Водяная стрела", additional_info = "{1% от базовой мана} {Радиус действия: 45 м}\nПрименение: 2.5 сек\n[q]Выпускает в противника ледяную стрелу, наносящую [208 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)]-[268 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] ед. урона от магии льда."},
[412443] = {name = "Наделение силой Бездны", additional_info = nil},
[412456] = {name = "Марш мурлоков", additional_info = nil},
[412466] = {name = "Марш мурлоков", additional_info = nil},
[412507] = {name = "Кровавое бешенство", additional_info = "[q]\"Кровопускание\" теперь можно применять в стойке берсерка. Урон от \"Кровопускания\" увеличивается на 100%. Каждый раз, когда \"Кровопускание\" наносит урон, цель получает дополнительный урон в объеме 4% вашей силы атаки."},
[412510] = {name = "Массовая регенерация", additional_info = "{45% от базовой мана} {Радиус действия: 40 м}\n{Направляемое (Применение:} 3 сек) {Восстановление: 12 сек}\n[q]Исцеляет цель и участников ее группы или рейда в радиусе 43.5 м, восполняя [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] ед. здоровья за 3 сек. Исцеленные игроки получают эффект \"Темпоральный маяк\" на 15 сек.\n\n Темпоральный маяк\n\nЗапоминает положение цели в пространстве-времени. 70% наносимого вами урона от тайной магии преобразуется в темпоральное исцеление и применяется к каждой текущей цели \"Темпорального маяка\". Вы получаете на 50% меньше исцеления из этого источника. Заклинания тайной магии, наносящие урон нескольким целям, дают на 80% меньше чародейского исцеления."},
[412513] = {name = "Стойка гладиатора", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\n[q]Агрессивная стойка. Когда вы используете щит, наносимый вами урон увеличивается на 10%, вероятность блока повышается на 10%, но при этом показатель брони уменьшается на 30%, а уровень создаваемой угрозы – на 30%. Кроме того, вы получаете на 50% больше ярости, когда ваша атака наносит урон противнику, который в данный момент не атакует вас.\n\n Если вы держите в руке щит, пока используете стойку гладиатора, вы можете применять все способности, обычно доступные только в других стойках."},
[412526] = {name = "Пытка разума", additional_info = "Неограниченное расстояние\nНаправляемое (Применение: 10 сек)\n[q]Наносит противнику урон от темной магии и снижает скорость его передвижения на 10 сек."},
[412527] = {name = "Облик Тьмы", additional_info = nil},
[412528] = {name = "Земной разлом", additional_info = nil},
[412532] = {name = "Стрела чар льда", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\nПрименение: 2.5 сек\n[q]Стрела чар льда наносит [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 305 / 100 * ( 1 ) ]-[(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 355 / 100 * ( 1 ) ] ед. урона от чар льда и снижает скорость передвижения цели на 40% на 9 сек. В расчет берется наименьшее из значений сопротивления магии льда и тайной магии. Это заклинание принадлежит к обеим школам."},
[412538] = {name = "Воспламенение", additional_info = nil},
[412545] = {name = "Воспламенение", additional_info = nil},
[412569] = {name = "Облик Тьмы", additional_info = nil},
[412570] = {name = "Обездвиживание против страха", additional_info = nil},
[412609] = {name = "Глубокая рана", additional_info = nil},
[412613] = {name = "Глубокая рана", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Кровотечение."},
[412689] = {name = "Беспрерывное колдовство", additional_info = "[q]\"Похищение жизни\", \"Похищение души\", \"Стрела Тьмы\", \"Теневой рассекающий удар\", \"Жгучая боль\", \"Испепеление\" и \"Блуждающий дух\" полностью обновляют время действия \"Порчи\" на цели."},
[412698] = {name = "Беспрерывное колдовство", additional_info = nil},
[412718] = {name = "Тренировка с двумя клинками", additional_info = "Радиус действия: 10 м\nПрименение: 6 сек\nИнгредиенты:\nСырая блестящая рыбка\n[q]Попытка разделать сырую блестящую рыбку."},
[412727] = {name = "Власть над демонами", additional_info = "[q]Вероятность критического удара атак ближнего боя и заклинаний для вас и вашего прислужника повышается на 10%."},
[412732] = {name = "Демоническое знание", additional_info = "[q]Увеличивает урон и силу исцеления от заклинаний на значение, равное 3% от суммы выносливости и интеллекта вашего прислужника-демона."},
[412735] = {name = "Демоническое знание", additional_info = nil},
[412758] = {name = "Испепеление", additional_info = "{14% от базовой мана} {Радиус действия: 30 м}\nПрименение: 2.25 сек\n[q]Обжигает противника, нанося ему от [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] до [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] ед. урона и увеличивая наносимый урон от огня на 40% на 15 сек."},
[412783] = {name = "Метаморфоза: демонический прыжок", additional_info = nil},
[412784] = {name = "Метаморфоза: демонический вой", additional_info = nil},
[412787] = {name = "Прерывание", additional_info = "{5% от базовой мана} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Душит противника волной темной энергии, наносящей 10 ед. урона, прерывающей произнесение заклинаний и не позволяющей применять заклинания той же школы в течение 5 сек."},
[412788] = {name = "Демонический прыжок", additional_info = "{5% от базовой мана} {Радиус действия: 8 - 25 м}\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Демон бросается к противнику и оглушает его на 1 сек. Не действует во время боя."},
[412789] = {name = "Демонический вой", additional_info = "5% от базовой мана\n{Мгновенное действие} {Восстановление: 10 мин}\n[q]Заставляет находящихся рядом противников атаковать вас в течение 6 сек."},
[412790] = {name = "Инфернальный удар", additional_info = "Радиус действия: 8 - 25 м\n{Мгновенное действие} {Восстановление: 45 сек}\n[q]Атака в прыжке, наносящая 100 ед. урона от темной магии всем противникам в радиусе 8 м от выбранной точки и оглушающая их на 2 сек."},
[412798] = {name = "Гибельный танец", additional_info = "[q]Когда вы наносите критический удар, вероятность уклонения для вас и вашего прислужника-демона повышается на значение, равное 70% вероятности критического эффекта заклинаний. Кроме того, вы с прислужником восполняете 2% максимального запаса маны."},
[412800] = {name = "Гибельный танец", additional_info = "Мгновенное действие\n[q]Повышает вероятность уклонения на значение, равное 70% вероятности критического урона заклинаний."},
[413031] = {name = "Бой с оружием в каждой руке", additional_info = nil},
