[413052] = {name = "Темное сокрушение", additional_info = nil},
[413247] = {name = "Прозорливость", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Modifies Cast Time -19%:\nБольшее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Исцеление , Исцеление , Исцеление , Исцеление , Малое исцеление , Малое исцеление , Малое исцеление , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления\n\nModifies Damage/Healing Done +1%:\nБольшее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Исцеление , Исцеление , Исцеление , Исцеление , Малое исцеление , Малое исцеление , Малое исцеление , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления"},
[413248] = {name = "Прозорливость", additional_info = "[q]Когда \"Быстрое исцеление\" восстанавливает здоровье, время произнесения следующего \"Малого исцеления\", \"Большего исцеления\" или \"Молитвы исцеления\" сокращается на 20% на 20 сек. Суммируется до 3 раз."},
[413251] = {name = "Боль и страдание", additional_info = "[q]\"Взрыв разума\", \"Пронзание разума\" и \"Пытка разума\" обновляют время действия одного из ваших эффектов на цели – \"Слово Тьмы: Боль\", \"Чума Бездны\" или \"Прикосновение вампира\" – продлевая время действия до максимального. Всегда обновляется способность с наименьшим оставшимся временем действия."},
[413259] = {name = "Иссушение разума", additional_info = "{28% от базовой мана} {Радиус действия: 30 м}\nНаправляемое (Применение: 6 сек)\n[q]Взрыв темной магии, наносящий цели и противникам рядом с ней от [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] до [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] ед. урона от темной магии раз в 1 сек. в течение 6 сек. Действует в радиусе 10 м от цели."},
[413260] = {name = "Иссушение разума", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Вызывает вокруг цели взрыв темной магии, наносящий противникам в радиусе 10 м 70 в 78 ед. урона от темной магии раз в сек. в течение до отмены."},
[413301] = {name = "Военная машина", additional_info = "[q]Убийство противника, приносящее опыт или честь, дает 10 ед. ярости."},
[413302] = {name = "Эффект ярости \"Военной машины\"", additional_info = nil},
[413338] = {name = "Знак бастиона", additional_info = nil},
[413380] = {name = "Всплеск крови", additional_info = "[q]\"Удар героя\", \"Кровожадность\" и \"Вихрь\" с вероятностью 30% позволяют применить следующий \"Мощный удар\" в течение 15 сек. мгновенно и без затрат ярости. При том вы атакуете оружием в обеих руках.\n(Вероятность срабатывания: 30%)"},
[413399] = {name = "Всплеск крови", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -99%:\nСокрушение , Сокрушение , Сокрушение , Сокрушение\n\nModifies Power Cost -99%:\nСокрушение , Сокрушение , Сокрушение , Сокрушение"},
[413404] = {name = "Свирепая неистовость", additional_info = "[q]Когда вы сражаетесь с оружием в обеих руках, ваша скорость передвижения повышается на 10%, а скорость атаки – на 4% каждый раз, когда ваш удар в ближнем бою попадает по той же цели, что и предыдущий. Суммируется до 5 раз. Длится 10 сек. или пока вы не нанесете удар по другой цели."},
