[413548] = {name = "Режим без степеней", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Режим без степеней включен. Невосприимчивость к эффектам контроля.\n Поглощение смертельного урона.\n Восстановление 100% максимального запаса здоровья раз в 5 сек."},
[413589] = {name = "Удар грома", additional_info = nil},
[413651] = {name = "Венок луговых цветов", additional_info = "Применение: 3 сек\nИнгредиенты:\nЛуговой цветок (3)\n[q]Связать 3 луговых цветка в венок."},
