[414684] = {name = "Солнечный огонь", additional_info = "{21% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Обжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек."},
[414687] = {name = "Солнечный огонь", additional_info = "{Ярость: 20} {Радиус действия: 30 м}\nМгновенное действие\nТребуется: Облик медведя, Облик лютого медведя\n[q]Обжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек."},
[414689] = {name = "Солнечный огонь", additional_info = "{Энергия: 40} {Радиус действия: 30 м}\nМгновенное действие\nТребуется: Облик кошки\n[q]Обжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек. Продлевает серию приемов на 1."},
[414691] = {name = "Оскверненный тотем неистовства ветра", additional_info = nil},
[414692] = {name = "Солнечный огонь", additional_info = "[q]Дает способность \"Солнечный огонь\" и заменяет \"Лунный огонь\" на \"Солнечный огонь\" в облике медведя, кошки и лютого медведя. Это заклинание получает усиление от всех эффектов, связанных с \"Лунным огнем\", а также активирует такие эффекты.\n\n\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек.\n\n\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек.\n\n\nОбжигает противника, нанося ему от [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] до [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы мгновенно и еще [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] ед. урона от сил природы в течение 12 сек. Продлевает серию приемов на 1."},
