[416244] = {name = "Цепное исцеление", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Восполняет союзнику 166 в 191 ед. здоровья, а затем переходит на соседние цели. Если применить к участнику группы, переходит только на других участников группы. Каждый переход снижает эффективность исцеления на 50%. Максимум целей – 3."},
[416245] = {name = "Цепное исцеление", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Восполняет союзнику 210 в 240 ед. здоровья, а затем переходит на соседние цели. Если применить к участнику группы, переходит только на других участников группы. Каждый переход снижает эффективность исцеления на 50%. Максимум целей – 3."},
[416246] = {name = "Цепное исцеление", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Восполняет союзнику 283 в 324 ед. здоровья, а затем переходит на соседние цели. Если применить к участнику группы, переходит только на других участников группы. Каждый переход снижает эффективность исцеления на 50%. Максимум целей – 3."},
[416247] = {name = "Волна исцеления", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Восполняет союзнику 18 в 25 ед. здоровья."},
[416278] = {name = "Засада у оргриммарского сундука", additional_info = nil},
[416288] = {name = "Объединение частей карты", additional_info = "Применение: 3 сек\nИнгредиенты:\nВерхний правый фрагмент карты , Верхний левый фрагмент карты , Нижний правый фрагмент карты , Нижний левый фрагмент карты\n[q]Объединить с 3 другими частями, чтобы создать целую карту."},
