[417057] = {name = "Омоложение", additional_info = "{Мана: 25} {Радиус действия: 40 м}\nМгновенное действие\n[q]Восполняет цели 32 ед. здоровья за 12 сек."},
[417058] = {name = "Омоложение", additional_info = "{Мана: 40} {Радиус действия: 40 м}\nМгновенное действие\n[q]Восполняет цели 56 ед. здоровья за 12 сек."},
