[425226] = {name = "Сожжение", additional_info = "Мгновенное действие\n[q]Горит!"},
[425233] = {name = "Взрыв разума", additional_info = "Радиус действия: 200 м\nПрименение: 1.5 сек\n[q]Наносит противнику урон от темной магии, создавая высокий уровень угрозы."},
