[426953] = {name = "Вкус крови", additional_info = "[q]Когда \"Кровопускание\" наносит урон, способность \"Превосходство\" становится доступна на 9 сек. или одну атаку. Эффект срабатывает не чаще одного раза в 6 сек.\n(Восстановление: 5.8с)"},
[426969] = {name = "Вкус крови", additional_info = nil},
[426972] = {name = "Бдительность", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Вы защищаете выбранного участника группы или рейда, уменьшая получаемый им урон на 3% и перенося на себя 10% создаваемой им угрозы. Каждый раз, когда цель получает удар, способность \"Провокация\" мгновенно восстанавливается. Время действия – 30 мин. Эффект может действовать единовременно только на одну цель."},
[426975] = {name = "Бдительность", additional_info = nil},
[426978] = {name = "Щит и меч", additional_info = "[q]Когда \"Сокрушение\" и \"Реванш\" наносят урон, с вероятностью 30% восстанавливается способность \"Сокрушение щитом\", а расход ярости на ее применение сокращается на 100% на 5 сек.\n(Вероятность срабатывания: 30%)"},
[426979] = {name = "Щит и меч", additional_info = "Мгновенное действие\n[q]Modifies Power Cost -99%:\nСокрушение щитом , Сокрушение щитом , Сокрушение щитом , Сокрушение щитом"},
[426980] = {name = "Мастерское владение щитом", additional_info = "[q]Пока вы используете щит, наносимый физический урон увеличивается на 10%, а время действия применяемых к вам эффектов обезоруживания сокращается на 50%. Не суммируется с другими эффектами, сокращающими время обезоруживания."},
[426981] = {name = "Мастерское владение щитом", additional_info = nil},
[427020] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nМедный слиток (20)\n[q]Пополняет припасы 20 медными слитками:медными слитками."},
[427061] = {name = "[q3]Оплечье Второй войны", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nБронзовый слиток (20), Моховой агат (2), Малый лунный камень (2), Радужная жемчужина (2), Серебряный слиток (4)\n[q3]Оплечье Второй войны\nСтановится персональным при надевании\nПлечо Кольчуга\nБроня: 163\n+8 к выносливости\nПрочность: 70 / 70\nТребуется\n[q2]Если на персонаже: Увеличение урона, наносимого заклинаниями и эффектами светлой магии, на 11 ед."},
[427063] = {name = "Оплечье Второй войны", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Обучает изготовлению оплечья Второй войны."},
[427065] = {name = "Погром", additional_info = "[q]Ваши критические атаки в ближнем бою вводят вас в исступление, позволяя применять требующие этого состояния способности, и увеличивают урон от \"Смертельного удара\", \"Кровожадности\" и \"Мощного удара щитом\" на 10% на 12 сек."},
[427066] = {name = "Исступление", additional_info = "Мгновенное действие\n[q]Modifies Damage/Healing Done +11%:\nКровожадность , Кровожадность , Кровожадность , Кровожадность , Смертельный удар , Смертельный удар , Смертельный удар , Смертельный удар , Сокрушение щитом , Сокрушение щитом , Сокрушение щитом , Сокрушение щитом"},
[427067] = {name = "Вкус крови", additional_info = "[q]Дает способность \"Вкус крови\":\n\n\nКогда \"Кровопускание\" наносит урон, способность \"Превосходство\" становится доступна на 9 сек. или одну атаку. Эффект срабатывает не чаще одного раза в 6 сек."},
[427068] = {name = "Бдительность", additional_info = "[q]Дает способность \"Бдительность\":\n\n\nВы защищаете выбранного участника группы или рейда, уменьшая получаемый им урон на 3% и перенося на себя 10% создаваемой им угрозы. Каждый раз, когда цель получает удар, способность \"Провокация\" мгновенно восстанавливается. Время действия – 30 мин. Эффект может действовать единовременно только на одну цель."},
[427069] = {name = "Мастерское владение щитом", additional_info = "[q]Дает способность \"Мастерское владение щитом\":\n\n\nПока вы используете щит, наносимый физический урон увеличивается на 10%, а время действия применяемых к вам эффектов обезоруживания сокращается на 50%. Не суммируется с другими эффектами, сокращающими время обезоруживания."},
[427070] = {name = "Буйство", additional_info = "[q]Дает способность \"Буйство\":\n\n\nВы впадаете в буйство, и ваша сила атаки повышается на 15% на 30 сек. Эту способность можно применять только в состоянии исступления."},
[427073] = {name = "Щит и меч", additional_info = "[q]Дает способность \"Щит и меч\":\n\n\nКогда \"Сокрушение\" и \"Реванш\" наносят урон, с вероятностью 30% восстанавливается способность \"Сокрушение щитом\", а расход ярости на ее применение сокращается на 100% на 5 сек."},
[427074] = {name = "Погром", additional_info = "[q]Дает способность \"Погром\":\n\n\nВаши критические атаки в ближнем бою вводят вас в исступление, позволяя применять требующие этого состояния способности, и увеличивают урон от \"Смертельного удара\", \"Кровожадности\" и \"Мощного удара щитом\" на 10% на 12 сек."},
[427076] = {name = "Гравировка шлема \"Вкус крови\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Вкус крови\":\n\n\nКогда \"Кровопускание\" наносит урон, способность \"Превосходство\" становится доступна на 9 сек. или одну атаку. Эффект срабатывает не чаще одного раза в 6 сек."},
[427078] = {name = "Гравировка шлема \"Бдительность\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Бдительность\":\n\n\nВы защищаете выбранного участника группы или рейда, уменьшая получаемый им урон на 3% и перенося на себя 10% создаваемой им угрозы. Каждый раз, когда цель получает удар, способность \"Провокация\" мгновенно восстанавливается. Время действия – 30 мин. Эффект может действовать единовременно только на одну цель."},
[427080] = {name = "Гравировка шлема \"Мастерское владение щитом\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Мастерское владение щитом\":\n\n\nПока вы используете щит, наносимый физический урон увеличивается на 10%, а время действия применяемых к вам эффектов обезоруживания сокращается на 50%. Не суммируется с другими эффектами, сокращающими время обезоруживания."},
[427081] = {name = "Гравировка наручей \"Буйство\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Буйство\":\n\n\nВы впадаете в буйство, и ваша сила атаки повышается на 15% на 30 сек. Эту способность можно применять только в состоянии исступления."},
[427082] = {name = "Гравировка наручей \"Щит и меч\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Щит и меч\":\n\n\nКогда \"Сокрушение\" и \"Реванш\" наносят урон, с вероятностью 30% восстанавливается способность \"Сокрушение щитом\", а расход ярости на ее применение сокращается на 100% на 5 сек."},
[427084] = {name = "Гравировка наручей \"Погром\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Погром\":\n\n\nВаши критические атаки в ближнем бою вводят вас в исступление, позволяя применять требующие этого состояния способности, и увеличивают урон от \"Смертельного удара\", \"Кровожадности\" и \"Мощного удара щитом\" на 10% на 12 сек."},
