[428796] = {name = "Использование неполных припасов", additional_info = nil},
[428828] = {name = "Призыв очищающего элементаля", additional_info = nil},
[428837] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nТонкая кожа (14)\n[q]Пополняет припасы 14 кусками тонкой кожи:кусками тонкой кожи."},
[428838] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nМироцвет (20)\n[q]Пополняет припасы 20 пучками мироцвета:пучками мироцвета."},
[428840] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nСребролист (20)\n[q]Пополняет припасы 20 пучками сребролиста:пучками сребролиста."},
[428842] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nСлабое лечебное зелье (20)\n[q]Пополняет припасы 20 слабыми лечебными зельями:слабыми лечебными зельями."},
[428843] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nМедный короткий меч (6)\n[q]Пополняет припасы 6 медными короткими мечами:медными короткими мечами."},
[428844] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nРунические медные штаны (3)\n[q]Пополняет припасы 3 руническими медными штанами."},
[428845] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nМалый магический жезл (2)\n[q]Пополняет припасы 2 малыми магическими жезлами:малыми магическими жезлами."},
[428846] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nСлабое волшебное масло (2)\n[q]Пополняет припасы 2 флаконами слабого волшебного масла:флаконами слабого волшебного масла."},
[428847] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nГрубая медная бомба (12)\n[q]Пополняет припасы 12 грубыми медными бомбами:грубыми медными бомбами."},
[428848] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nГрубый громобой (3)\n[q]Пополняет припасы 3 грубо сработанными огнестрелами:грубо сработанными огнестрелами."},
[428849] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nСшитый вручную кожаный пояс (5)\n[q]Пополняет припасы 5 рукодельными кожаными поясами:рукодельными кожаными поясами."},
[428850] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nТисненый кожаный жилет (3)\n[q]Пополняет припасы 3 тиснеными кожаными жилетами:тиснеными кожаными жилетами."},
[428851] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nКоричневые льняные штаны (6)\n[q]Пополняет припасы 6 коричневыми льняными штанами."},
[428853] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nКоричневое льняное одеяние (4)\n[q]Пополняет припасы 4 коричневыми льняными одеяниями."},
[428855] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nЯйцо с травами (20)\n[q]Пополняет припасы 20 яйцами с травами:яйцами с травами."},
[428856] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nВолчатина с пряностями (20)\n[q]Пополняет припасы 20 кусками волчатины с пряностями:кусками волчатины с пряностями."},
[428857] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nБлестящая рыбка (20)\n[q]Пополняет припасы 20 блестящими рыбками:блестящими рыбками."},
[428858] = {name = "[q2]Пополнение припасов", additional_info = "Применение: 1.5 сек\nИнгредиенты:\nПлотные льняные бинты (10)\n[q]Пополняет припасы 10 плотными льняными бинтами:плотными льняными бинтами."},
[428861] = {name = "Смещение", additional_info = "{35% от базовой мана} {Радиус действия: 100 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Телепортирует вас в точку, из которой вы применили предыдущий \"Скачок\", и восстанавливает его. Можно применить в течение 10 сек. после \"Скачка\"."},
[428863] = {name = "Смещение", additional_info = "[q]Дает способность \"Смещение\":\n\n\nТелепортирует вас в точку, из которой вы применили предыдущий \"Скачок\", и восстанавливает его. Можно применить в течение 10 сек. после \"Скачка\"."},
[428865] = {name = "Недавний скачок", additional_info = nil},
[428872] = {name = "Стрела гибельного огня", additional_info = nil},
[428878] = {name = "Стрела гибельного огня", additional_info = "{20% от базовой мана} {Радиус действия: 35 м}\nПрименение: 2.5 сек\n[q]Вы выпускаете в противника искажающий реальность поток чистой магии, наносящий от [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 280 / 100] до [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 420 / 100] ед. химерического урона.\n\n \"Стрела гибельного огня\" и \"Огненная глыба\" наносят на 25% больше урона, показатель духа cнижается на 20%. Оба эффекта суммируются до 5 раз. Время действия – 30 сек. Если ваш показатель духа опускается до 0, вы погибаете.\n\n В расчет урона берется наименьшее из значений сопротивления тайной магии, огню и магии льда."},
[428885] = {name = "Временная аномалия", additional_info = "{11% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Выпускает сферу темпоральной энергии. Сфера медленно движется вперед и раз в 2 сек. защищает находящихся рядом участников группы щитом, поглощающим [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] ед. урона в течение 15 сек. Если участники группы остаются возле сферы, прочность щита суммируется."},
[428888] = {name = "Временная аномалия", additional_info = nil},
[428895] = {name = "Временная аномалия", additional_info = nil},
[428909] = {name = "Благоволение Света", additional_info = "[q]\"Свет небес\" сокращает время произнесения следующего \"Света небес\" на 1,1 сек. Время действия – 15 сек."},
[428912] = {name = "Благоволение Света", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -499:\nБожественный свет , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес"},
[428917] = {name = "Глубокая заморозка", additional_info = nil},
[428920] = {name = "Глубокая заморозка", additional_info = nil},
[429125] = {name = "Стылая кровь", additional_info = "3% от базовой мана\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Увеличивает скорость произнесения заклинаний на 20%. Сокращает задержку произнесения заклинаний при получении урона на 100%. Время действия – 20 сек."},
[429133] = {name = "Улучшенное святилище", additional_info = "[q]\"Благословение неприкосновенности\" предотвращает на 100% больше урона. Урон от \"Благословения неприкосновенности\" увеличивается на 20% показателя блока щита."},
[429139] = {name = "Гнев", additional_info = "[q]Урон \"Освящения\" теперь может быть критическим, а вероятность критического удара \"Экзорцизма\", \"Шока небес\", \"Солнечного света\", \"Гнева небес\" и \"Освящения\" повышается на величину, равную вашей вероятности критического удара в ближнем бою."},
[429142] = {name = "Фанатизм", additional_info = "[q]Повышает вероятность критического эффекта заклинаний светлой магии на 18%. Кроме того, критические эффекты исцеляющих заклинаний восполняют цели еще 60% восстановленного здоровья за 12 сек."},
[429144] = {name = "Очищающая сила", additional_info = "[q]Сокращает время восстановления \"Экзорцизма\" и \"Гнева небес\" на 50%. Теперь \"Гнев небес\" применяется к любой цели и оглушает демонов и нежить на 2 сек."},
[429145] = {name = "Гнев небес", additional_info = "Мана: 645\n{Применение: 2 сек} {Восстановление: 1 мин}\n[q]Выпускает во всех направлениях заряды священной энергии, нанося 368 в 435 ед. урона от светлой магии целям в радиусе 20 м и оглушая демонов и нежить на 2 сек."},
[429146] = {name = "Гнев небес", additional_info = "Мана: 805\n{Применение: 2 сек} {Восстановление: 1 мин}\n[q]Выпускает во всех направлениях заряды священной энергии, нанося 490 в 576 ед. урона от светлой магии целям в радиусе 20 м и оглушая демонов и нежить на 2 сек."},
[429147] = {name = "Оглушение", additional_info = nil},
[429151] = {name = "Молот гнева", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\nМгновенное действие\n[q]Бросает в противника молот, наносящий от [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Сила заклинаний + 0.15 * Сила атаки] до [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Сила заклинаний + 0.15 * Сила атаки] ед. урона от светлой магии. Применимо только к противникам, чей уровень здоровья не превышает 20%."},
[429152] = {name = "Улучшенный молот гнева", additional_info = "[q]\"Молот гнева\" теперь применяется мгновенно и восстанавливается, когда наносит урон противнику с уровнем здоровья ниже 10%."},
