[429687] = {name = "Господство над разумом", additional_info = "{Мана: 30} {Радиус действия: 20 м}\nПрименение: 2 сек\n[q]Подчиняет противника-гуманоида 25-го уровня и ниже на 15 сек."},
[429688] = {name = "Господство над разумом", additional_info = "{Мана: 30} {Радиус действия: 20 м}\nПрименение: 2 сек\n[q]Подчиняет противника-гуманоида не выше 25-го уровня на 10 сек, но увеличивает интервал между его атаками на 100%."},
