[431704] = {name = "Портал Бездны", additional_info = "[q]Дает способность \"Портал Бездны\":\n\n\nСоздает в указанной области портал Бездны, который раз в секунду наносит находящимся в нем противникам [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 51 / 100] ед. урона от темной магии в течение 10 сек."},
[431705] = {name = "Гравировка наручей \"Портал Бездны\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Портал Бездны\":\n\n\nСоздает в указанной области портал Бездны, который раз в секунду наносит находящимся в нем противникам [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 51 / 100] ед. урона от темной магии в течение 10 сек."},
