[431742] = {name = "Обратный поток", additional_info = "[q]Дает способность \"Обратный поток\":\n\n\n\"Поджигание\" также повышает скорость произнесения заклинаний на 30% на 15 сек и больше не поглощает \"Жертвенный огонь\"."},
[431743] = {name = "Гравировка шлема \"Пандемия\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Пандемия\":\n\n\nПериодический урон от \"Порчи\", \"Нестабильного колдовства\", \"Проклятия агонии\", \"Жертвенного огня\", \"Проклятия рока\" и \"Вытягивания жизни\" теперь может быть критическим."},
[431745] = {name = "Гравировка шлема \"Обратный поток\"", additional_info = "Применение: 3 сек\nТребуется: Шлемы\n[q]Выгравировать на шлеме руну \"Обратный поток\":\n\n\n\"Поджигание\" также повышает скорость произнесения заклинаний на 30% на 15 сек и больше не поглощает \"Жертвенный огонь\"."},
[431747] = {name = "Гравировка наручей \"Нестабильное колдовство\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Нестабильное колдовство\":\n\n\n\"\"Энергия Тьмы медленно уничтожает цель, нанося ей [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] ед. урона за 18 сек. При рассеивании \"Нестабильное колдовство\" наносит рассеявшему [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] ед. урона и поражает его немотой на 5 сек. На каждую цель может действовать только одно \"Нестабильное колдовство\" или один \"Жертвенный огонь\" от каждого чернокнижника.\"\""},
[431748] = {name = "Нестабильное колдовство", additional_info = "[q]Дает способность \"Нестабильное колдовство\":\n\n\n\"\"Энергия Тьмы медленно уничтожает цель, нанося ей [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] ед. урона за 18 сек. При рассеивании \"Нестабильное колдовство\" наносит рассеявшему [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] ед. урона и поражает его немотой на 5 сек. На каждую цель может действовать только одно \"Нестабильное колдовство\" или один \"Жертвенный огонь\" от каждого чернокнижника.\"\""},
[431754] = {name = "Призыв стража Скверны", additional_info = "[q]Дает способность \"Призыв стража Скверны\":\n\n\nПризывает стража Скверны, подчиняющегося чернокнижнику.\n\n На стража Скверны действуют все положительные таланты и эффекты, которые срабатывают за счет других ваших демонов или усиливают их."},
[431756] = {name = "Гравировка наручей \"Призыв стража Скверны\"", additional_info = "Применение: 3 сек\nТребуется: Наручи\n[q]Выгравировать на наручах руну \"Призыв стража Скверны\":\n\n\nПризывает стража Скверны, подчиняющегося чернокнижнику.\n\n На стража Скверны действуют все положительные таланты и эффекты, которые срабатывают за счет других ваших демонов или усиливают их."},
[431757] = {name = "Обжигающий жар", additional_info = "[q]Дает способность \"Обжигающий жар\":\n\n\nПоджигает противников поблизости, нанося [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] ед. урона, каждый раз, когда противник атакует вас в ближнем бою (не чаще одного раза за секунду). Уменьшает весь получаемый магический урон на 10% и увеличивает наносимый урон от огня на 10%. Время действия – до отмены."},
