[436477] = {name = "Окровавленная буря", additional_info = "Мгновенное действие\nТребуется: Оружие ближнего боя\n[q]Призывает безжалостную бурю из стали и крови, наносящую противникам в радиусе 8 м 140 ед. урона от удара Тьмы."},
[436478] = {name = "Инфернальный взрыв", additional_info = "Мгновенное действие\n[q]Вызывает отложенный взрыв огня и крови, наносящий целям в радиусе 10 м 150 ед. урона от пламени Тьмы."},
