[436564] = {name = "Мушкетон", additional_info = "Энергия: 20\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Вы стреляете из мушкетона, поражая до 4 противников в секторе перед собой и нанося от [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Сила атаки] до [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Сила атаки] ед. физического урона."},
[436570] = {name = "Кудах!", additional_info = nil},
[436608] = {name = "Веер клинков", additional_info = "[q]Дает способность \"Веер клинков\":\n\n\nВы метаете оружие в обеих руках, поражая противников в радиусе 8 м. Наносит 75% урона при броске кинжалов и 50% при броске другого оружия."},
[436609] = {name = "Гравировка плаща \"Веер клинков\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Веер клинков\":\n\n\nВы метаете оружие в обеих руках, поражая противников в радиусе 8 м. Наносит 75% урона при броске кинжалов и 50% при броске другого оружия."},
[436610] = {name = "Мушкетон", additional_info = "[q]Дает способность \"Мушкетон\":\n\n\nВы стреляете из мушкетона, поражая до 4 противников в секторе перед собой и нанося от [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Сила атаки] до [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Сила атаки] ед. физического урона."},
[436611] = {name = "Кровавый вихрь", additional_info = "[q]Дает способность \"Кровавый вихрь\":\n\n\nЗавершающий прием, который с размаху бьет противников в радиусе 8 м и вызывает у них кровотечение. Время действия и урон увеличиваются с длиной серии.\n\n 1 прием: (Сила атаки * 0.30) ед. урона за 4 сек.\n 2 приема: (Сила атаки * 0.45) ед. урона за 6 сек.\n 3 приема: (Сила атаки * 0.60) ед. урона за 8 сек.\n 4 приема: (Сила атаки * 0.75) ед. урона за 10 сек.\n 5 приемов: (Сила атаки * 0.90) ед. урона за 12 сек.\n\n \"Кровавый вихрь\" взаимодействует с теми же талантами и эффектами, что и \"Рваная рана\"."},
