[437169] = {name = "Портал призыва", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\n{Направляемое (Применение:} 2 мин) {Восстановление: 2 мин}\nИнгредиенты:\nОсколок души\n[q]Начинает ритуал, создающий портал призыва. С помощью этого портала 2 участника группы или рейда могут призвать третьего. Для создания портала заклинателю необходима помощь 2 участников группы или рейда, все трое должны находиться вне боя. Для поддержания ритуала необходимо щелкнуть правой кнопкой мыши по порталу и не двигаться, пока ритуал не завершится."},
[437280] = {name = "Телепортация в Палящую низину", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Отправляет игрока в Гномреган."},
[437281] = {name = "Телепортация в Штормград", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Отправляет игрока в Гномреган."},
[437283] = {name = "Телепортация в Оргриммар", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Отправляет игрока в Гномреган."},
[437301] = {name = "Глубокая дремота", additional_info = "Применение: 1.5 сек\n[q]Окружает цели сонными облаками."},
