[437311] = {name = "Портал призыва", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\nПрименение: 5 сек\nИнгредиенты:\nОсколок души\n[q]Начинает ритуал, создающий портал призыва. С помощью этого портала 2 участника группы или рейда могут призвать третьего. Для создания портала заклинателю необходима помощь 2 участников группы или рейда, все трое должны находиться вне боя. Для поддержания ритуала необходимо щелкнуть правой кнопкой мыши по порталу и не двигаться, пока ритуал не завершится."},
[437324] = {name = "Глубокая дремота", additional_info = "Мгновенное действие\n[q]Когда сонное облако касается цели, она засыпает на 15 сек. Получаемый целью урон и получаемое ею исцеление уменьшаются на 99%."},
[437327] = {name = "Заряд вдохновения", additional_info = "Мгновенное действие\n[q]Использует разлитую в воздухе чародейскую энергию, чтобы дать вам заряд вдохновения, снижающий затраты маны на применение заклинаний на 50% и увеличивающий наносимый урон и силу исцеления максимум на 50 ед. Заряд действует 12 сек."},
[437340] = {name = "Радикальная защита от радиации", additional_info = "Мгновенное действие\n[q]Включает антирадиационные протоколы шлема, мгновенно снимая с вас все эффекты яда, а также давая вам невосприимчивость к урону от сил природы на 3 сек."},
[437346] = {name = "Ярость Дремлющей", additional_info = nil},
[437349] = {name = "Нейрогномский разряд", additional_info = "Мгновенное действие\n[q]Выпускает нейрогномский разряд, мгновенно наносящий вам 343 в 757 ед. урона и повышающий скорость атаки в ближнем и дальнем бою на 20% на 10 сек."},
[437353] = {name = "Едкое дыхание", additional_info = "Радиус действия: 100 м\nПрименение: 4 сек\n[q]Выдыхает в цель облако разъедающей магии, наносящей 1140 в 1260 ед. урона от сил природы и ослабляющей броню на 33% на 20 сек."},
[437357] = {name = "Нейрогномский транс", additional_info = "Мгновенное действие\n[q]Вы впадаете в нейрогномский транс на 20 сек., в результате чего во время применения заклинаний ваша мана восполняется со скоростью 100% от обычной. Кроме того, ваши заклинания наносят на 50 ед. больше урона и восстанавливают на столько же больше здоровья."},
[437362] = {name = "Разряд сверхпроводника", additional_info = "Мгновенное действие\n[q]Выпускает разряд сверхпроводника, нанося вам 312 в 688 ед. урона и повышая скорость произнесения заклинаний на 20% на 10 сек."},
[437367] = {name = "Бритвенно-острые детали", additional_info = "{Мгновенное действие} {Восстановление: 5 сек}\n[q]При успешном блоке крутящиеся бритвенно-острые детали этого щита наносят 5 в 10 ед. физического урона атакующему и 2 в 10 ед. урона владельцу."},
[437368] = {name = "Подбрасывание монеты", additional_info = "Мгновенное действие\n[q]Вы вытаскиваете из-за пояса монету из сверхпроводника и подбрасываете ее. Лицевая сторона: вероятность критического удара атак и заклинаний повышается на 3% на 30 сек. Обратная сторона: скорость передвижения повышается на 10% на 30 сек."},
[437375] = {name = "Взмах хвоста", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит 760 в 840 ед. урона целям позади и отбрасывает их."},
[437377] = {name = "Полная сосредоточенность", additional_info = "Мгновенное действие\n[q]Позволяет полностью сосредоточиться, в результате чего скорость передвижения снижается на 20%, но сопротивление всем видам магии повышается на 50 ед., а скорость атаки в ближнем бою – на 20% на 10 сек."},
[437382] = {name = "Укрепленная сила воли", additional_info = "Мгновенное действие\n[q]Укрепляет силу воли, давая невосприимчивость к эффектам немоты, прерыванию и задержке произнесения заклинаний на 10 сек."},
[437388] = {name = "Бритвенно-острые детали", additional_info = "Мгновенное действие"},
[437390] = {name = "Летаргический яд", additional_info = "Применение: 0.5 сек\n[q]Плюет в игроков летаргическим ядом, наносящим 300 ед. урона от сил природы раз в 3 сек. в течение 15 сек. Яд снижает вероятность попадания на 50% и увеличивает затраты на способности на 100%."},
[437398] = {name = "Кошмар наяву", additional_info = "{Применение: 6 сек} {Восстановление: 5 сек}\n[q]Раскалывает умы бодрствующих игроков, нанося им 30000 ед. урона от темной магии."},
[437410] = {name = "Глубокая дремота", additional_info = "Применение: 3 сек\n[q]Засыпает глубоким сном на 20 сек. Получаемый урон уменьшается на 99%."},
