[437809] = {name = "Священный огонь", additional_info = "Радиус действия: 30 м\nПрименение: 1 сек\n[q]Цель охватывает священное пламя, которое наносит 475 в 525 ед. урона от светлой магии и еще 500 ед. урона от светлой магии раз в 2 сек. в течение 10 сек."},
[437813] = {name = "Вопящее бешенство", additional_info = "Мгновенное действие\n[q]Оказавшись в освещенной области, вопящий ужас приходит в бешенство, в результате чего его скорость атаки и передвижения повышается на 50$%."},
[437817] = {name = "Кольцо Света", additional_info = "Применение: 2 сек\n[q]Создает области энергии Света, наносящие находящимся в них игрокам 250 ед. урона от светлой магии раз в 1 сек."},
