[439462] = {name = "Подкожный яд", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, ослабляя его броню на 1700 ед. на 15 сек.\n\n \"Подкожный яд\" взаимодействует с талантом \"Улучшенное ослабление доспеха\".\n(Вероятность срабатывания: 30%)"},
[439464] = {name = "Замедляющий яд", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, продлевая время между его атаками ближнего боя на 20% на 15 сек.\n(Вероятность срабатывания: 30%)"},
[439465] = {name = "Атрофический яд", additional_info = "Применение: 3 сек\nТребуется: Оружие ближнего боя\n[q]Покрывает оружие ядом, действующим 30 мин.\n Каждый удар с вероятностью 30% отравляет противника, уменьшая силу атак ближнего боя на 205% на 15 сек.\n(Вероятность срабатывания: 30%)"},
