[440484] = {name = "Свежее мясо", additional_info = "[q]Когда вы поражаете цель \"Кровожадностью\", \"Смертельным ударом\" или \"Мощным ударом щитом\" в первый раз, вы с вероятностью 100% впадаете в исступление и получаете возможность применять способности, требующие этого состояния. Последующие применения этих способностей к той же цели приводят вас в исступление с вероятностью 10%. \"Исступление\" увеличивает наносимый физический урон на 10% на 12 сек."},
[440486] = {name = "Высокое напряжение!", additional_info = nil},
[440488] = {name = "Ударная волна", additional_info = "Ярость: 15\n{Мгновенное действие} {Восстановление: 20 сек}\nТребуется: Оборонительная стойка\n[q]Посылает перед воином силовую волну, наносящую (50 / 100 * Сила атаки) ед. урона и оглушающую всех противников на расстоянии 10 м перед ним на 4 сек."},
[440492] = {name = "Гравировка плаща \"Свежее мясо\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Свежее мясо\":\n\n\nКогда вы поражаете цель \"Кровожадностью\", \"Смертельным ударом\" или \"Мощным ударом щитом\" в первый раз, вы с вероятностью 100% впадаете в исступление и получаете возможность применять способности, требующие этого состояния. Последующие применения этих способностей к той же цели приводят вас в исступление с вероятностью 10%. \"Исступление\" увеличивает наносимый физический урон на 10% на 12 сек."},
[440493] = {name = "Свежее мясо", additional_info = "[q]Дает способность \"Свежее мясо\":\n\n\nКогда вы поражаете цель \"Кровожадностью\", \"Смертельным ударом\" или \"Мощным ударом щитом\" в первый раз, вы с вероятностью 100% впадаете в исступление и получаете возможность применять способности, требующие этого состояния. Последующие применения этих способностей к той же цели приводят вас в исступление с вероятностью 10%. \"Исступление\" увеличивает наносимый физический урон на 10% на 12 сек."},
[440494] = {name = "Гравировка плаща \"Внезапная смерть\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Внезапная смерть\":\n\n\nУдары в ближнем бою с вероятностью 10% дают эффект \"Внезапная смерть\", позволяющий один раз применить \"Казнь\" к цели с любым уровнем здоровья. После применения \"Казни\" за счет \"Внезапной смерти\" у вас остается 10 ед. ярости."},
[440495] = {name = "Внезапная смерть", additional_info = "[q]Дает способность \"Свежее мясо\":\n\n\nУдары в ближнем бою с вероятностью 10% дают эффект \"Внезапная смерть\", позволяющий один раз применить \"Казнь\" к цели с любым уровнем здоровья. После применения \"Казни\" за счет \"Внезапной смерти\" у вас остается 10 ед. ярости."},
[440496] = {name = "Гравировка плаща \"Ударная волна\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Ударная волна\":\n\n\nПосылает перед воином силовую волну, наносящую (50 / 100 * Сила атаки) ед. урона и оглушающую всех противников на расстоянии 10 м перед ним на 4 сек."},
[440497] = {name = "Ударная волна", additional_info = "[q]Дает способность \"Ударная волна\":\n\n\nПосылает перед воином силовую волну, наносящую (50 / 100 * Сила атаки) ед. урона и оглушающую всех противников на расстоянии 10 м перед ним на 4 сек."},
[440505] = {name = "Невидимость", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Делает выпившего невидимым на 30 сек."},
[440520] = {name = "Улучшенный град стрел", additional_info = "[q]Сокращает затраты маны на \"Град стрел\" на 50% и его время восстановления – на 100%, а также увеличивает наносимый им урон на 100%. Применение способности больше не задерживается при получении урона. Каждая атака \"Града стрел\" наносит дополнительный урон в объеме 3% вашей силы атаки дальнего боя."},
[440529] = {name = "Находчивость", additional_info = "[q]Сокращает затраты маны на размещение ловушек на 100%, а их время восстановления – на 40%."},
[440531] = {name = "Бей и беги", additional_info = nil},
[440533] = {name = "Бей и беги", additional_info = "[q]\"Удар ящера\" повышает скорость передвижения на 30% на 15 сек.\n\n Наносящие урон способности питомца вызывают у цели \"Неистовое бешенство\", повышающее силу атаки ближнего боя на 91 ед., но ослабляющее броню на 640 ед. на 2 мин. Взбешенные противники не сбегают из боя и невосприимчивы к эффектам страха и ужаса."},
[440557] = {name = "Гравировка плаща \"Находчивость\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Находчивость\":\n\n\nСокращает затраты маны на размещение ловушек на 100%, а их время восстановления – на 40%."},
[440558] = {name = "Находчивость", additional_info = "[q]Дает способность \"Находчивость\":\n\n\nСокращает затраты маны на размещение ловушек на 100%, а их время восстановления – на 40%."},
[440560] = {name = "Гравировка плаща \"Улучшенный град стрел\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Улучшенный град стрел\":\n\n\nСокращает затраты маны на \"Град стрел\" на 50% и его время восстановления – на 100%, а также увеличивает наносимый им урон на 100%. Применение способности больше не задерживается при получении урона. Каждая атака \"Града стрел\" наносит дополнительный урон в объеме 3% вашей силы атаки дальнего боя."},
[440561] = {name = "Улучшенный град стрел", additional_info = "[q]Дает способность \"Улучшенный град стрел\":\n\n\nСокращает затраты маны на \"Град стрел\" на 50% и его время восстановления – на 100%, а также увеличивает наносимый им урон на 100%. Применение способности больше не задерживается при получении урона. Каждая атака \"Града стрел\" наносит дополнительный урон в объеме 3% вашей силы атаки дальнего боя."},
[440563] = {name = "Гравировка плаща \"Бей и беги\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Бей и беги\":\n\n\n\"Удар ящера\" повышает скорость передвижения на 30% на 15 сек.\n\n Наносящие урон способности питомца вызывают у цели \"Неистовое бешенство\", повышающее силу атаки ближнего боя на 91 ед., но ослабляющее броню на 640 ед. на 2 мин. Взбешенные противники не сбегают из боя и невосприимчивы к эффектам страха и ужаса."},
[440564] = {name = "Бей и беги", additional_info = "[q]Дает способность \"Бей и беги\":\n\n\n\"Удар ящера\" повышает скорость передвижения на 30% на 15 сек.\n\n Наносящие урон способности питомца вызывают у цели \"Неистовое бешенство\", повышающее силу атаки ближнего боя на 91 ед., но ослабляющее броню на 640 ед. на 2 мин. Взбешенные противники не сбегают из боя и невосприимчивы к эффектам страха и ужаса."},
[440569] = {name = "Буря, земля и огонь", additional_info = "[q]Сокращает время восстановления \"Цепной молнии\" на 25% и увеличивает периодический урон от \"Огненного шока\" на 60%. Тотем оков земли может при установке обездвижить противников на 5 сек."},
[440574] = {name = "Хватка земли", additional_info = nil},
[440580] = {name = "Дух дикого волка", additional_info = "{12% от базовой мана} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Призывает 2 духов волка под командование шамана. Время жизни – 45 сек."},
[440586] = {name = "Оглушить", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 45 сек}\n[q]Оглушает цель на 2 сек."},
[440589] = {name = "Многоголосый вой", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Духи волка издают вой, заставляющий противников атаковать их в течение 6 сек."},
[440591] = {name = "Поступь духа", additional_info = "Радиус действия: 25 м\n{Мгновенное действие} {Восстановление: 32 сек}\n[q]Снимает ограничивающие передвижение эффекты и повышает скорость передвижения заклинателя и духов волка на 60% на 15 сек."},
[440593] = {name = "Охота на духов", additional_info = "Восстановление: 10 сек\n[q]Атаки духов волка исцеляют их самих и хозяина на 150% наносимого урона."},
[440594] = {name = "Избежание", additional_info = nil},
[440595] = {name = "Рост силы спутника шамана", additional_info = nil},
[440605] = {name = "Прыжок духа", additional_info = "Радиус действия: 5 - 30 м\n{Мгновенное действие} {Восстановление: 20 сек}\n[q]Прыжок за спину цели."},
[440609] = {name = "Охота на духов", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Атаки духов волка исцеляют их самих и хозяина на долю наносимого урона."},
[440610] = {name = "Поступь духа", additional_info = "Радиус действия: 25 м\nМгновенное действие\n[q]Снимает эффекты, затрудняющие передвижение."},
[440630] = {name = "Гравировка плаща \"Дух дикого волка\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Дух дикого волка\":\n\n\nПризывает 2 духов волка под командование шамана. Время жизни – 45 сек."},
[440631] = {name = "Дух дикого волка", additional_info = "[q]Дает способность \"Дух дикого волка\":\n\n\nПризывает 2 духов волка под командование шамана. Время жизни – 45 сек."},
[440632] = {name = "Сила атаки - зверь (+36)", additional_info = "Требуется: Облик кошки, Облик медведя, Облик лютого медведя\n[q]Увеличивает силу атаки на 36 в облике кошки, медведя и лютого медведя."},
[440633] = {name = "Буря, земля и огонь", additional_info = "[q]Дает способность \"Буря, земля и огонь\":\n\n\nСокращает время восстановления \"Цепной молнии\" на 25% и увеличивает периодический урон от \"Огненного шока\" на 60%. Тотем оков земли может при установке обездвижить противников на 5 сек."},
[440634] = {name = "Гравировка плаща \"Буря, земля и огонь\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Буря, земля и огонь\":\n\n\nСокращает время восстановления \"Цепной молнии\" на 25% и увеличивает периодический урон от \"Огненного шока\" на 60%. Тотем оков земли может при установке обездвижить противников на 5 сек."},
