[440642] = {name = "Электрическая сеть", additional_info = "Радиус действия: 35 м\nНаправляемое (Применение: 0 сек)\n[q]Поражение разума противника энергией темной магии, наносящей 0.0 ед. урона от темной магии в течение до отмены. и снижающей его скорость передвижения на 0%."},
[440643] = {name = "Электрическая сеть", additional_info = "Радиус действия: 35 м\nНаправляемое (Применение: 0 сек)\n[q]Поражение разума противника энергией темной магии, наносящей 0.0 ед. урона от темной магии в течение до отмены. и снижающей его скорость передвижения на 0%."},
[440651] = {name = "Священный щит", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Каждый раз при получении урона цель ограждается священным щитом, поглощающим 50 ед. урона, а вероятность критического эффекта \"Вспышки Света\" паладина, примененного к цели, повышается на 50% на 2 сек. Эффект срабатывает не чаще раза в 6 секунд. Время действия – 2 сек."},
[440656] = {name = "Высокое напряжение!", additional_info = nil},
[440658] = {name = "Щит праведности", additional_info = "{6% от базовой мана} {Дистанция ближнего боя}\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Мощный удар щитом, наносящий урон от светлой магии. Величина урона рассчитывается исходя из показателя блока и увеличивается на [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] ед. дополнительно."},
[440664] = {name = "Ядовитая грязь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Липкая муть создает лужу ядовитой слизи, которая наносит игрокам в области действия 150 ед. урона от сил природы раз в 5 сек.\n\n Скорость перемещения игроков в луже снижается на 150%."},
[440666] = {name = "Воздаятель", additional_info = "[q]Когда срабатывает талант \"Подтверждение\", сила атаки цели уменьшается на ( 30 /- 3) за каждое очко таланта, а ваша сила, ловкость и сила атаки увеличиваются на 5% за каждое очко таланта. Время действия \"Подтверждения\" продлевается на 30 сек."},
[440667] = {name = "Оправдание", additional_info = nil},
[440668] = {name = "Оправдание", additional_info = nil},
[440672] = {name = "Праведная месть", additional_info = "[q]Когда \"Правосудие\", \"Удар воина Света\" или \"Божественная буря\" наносит критический урон, цель получает 30% дополнительного урона в течение до отмены."},
[440675] = {name = "Праведная месть", additional_info = nil},
[440677] = {name = "Праведная месть", additional_info = nil},
[440720] = {name = "Не совсем божественный щит Скути", additional_info = nil},
[440788] = {name = "Гравировка плаща \"Щит праведности\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Щит праведности\":\n\n\nМощный удар щитом, наносящий урон от светлой магии. Величина урона рассчитывается исходя из показателя блока и увеличивается на [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] ед. дополнительно."},
[440789] = {name = "Щит праведности", additional_info = "[q]Дает способность \"Щит праведности\":\n\n\nМощный удар щитом, наносящий урон от светлой магии. Величина урона рассчитывается исходя из показателя блока и увеличивается на [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] ед. дополнительно."},
[440790] = {name = "Гравировка плаща \"Шок и трепет\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Шок и трепет\":\n\n\nЕсли \"Шок небес\" наносит урон, пока \"Праведное неистовство\" не активно, ваш урон от заклинаний увеличивается на 200% интеллекта, а уровень создаваемой вами угрозы снижается на 30%. Время действия – 1 мин.\n\n Если выгравирована руна \"Прилив Света\", вы на 10 сек. получаете эффект \"Солнечный свет\".\n\n\n Пока на вас действует \"Солнечный свет\", умения \"Божественная буря\" и \"Удар воина Света\", а также атаки ближнего боя против целей, не находящихся под контролем игроков, наносят дополнительный урон от светлой магии, равный 60% силы заклинаний светлой магии."},
[440791] = {name = "Шок и трепет", additional_info = "[q]Дает способность \"Шок и трепет\":\n\n\nЕсли \"Шок небес\" наносит урон, пока \"Праведное неистовство\" не активно, ваш урон от заклинаний увеличивается на 200% интеллекта, а уровень создаваемой вами угрозы снижается на 30%. Время действия – 1 мин.\n\n Если выгравирована руна \"Прилив Света\", вы на 10 сек. получаете эффект \"Солнечный свет\".\n\n\n Пока на вас действует \"Солнечный свет\", умения \"Божественная буря\" и \"Удар воина Света\", а также атаки ближнего боя против целей, не находящихся под контролем игроков, наносят дополнительный урон от светлой магии, равный 60% силы заклинаний светлой магии."},
[440792] = {name = "Гравировка плаща \"Праведная месть\"", additional_info = "Применение: 3 сек\nТребуется: Спина\n[q]Выгравировать на плаще руну \"Праведная месть\":\n\n\nКогда \"Правосудие\", \"Удар воина Света\" или \"Божественная буря\" наносит критический урон, цель получает 30% дополнительного урона в течение до отмены."},
[440794] = {name = "Праведная месть", additional_info = "[q]Дает способность \"Праведная месть\":\n\n\nКогда \"Правосудие\", \"Удар воина Света\" или \"Божественная буря\" наносит критический урон, цель получает 30% дополнительного урона в течение до отмены."},
[440802] = {name = "Ледяной шар", additional_info = "{11% от базовой мана} {Радиус действия: 40 м}\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Выпускает кружащийся ледяной шар, который стремительно движется вперед в течение 16 сек. Пока шар движется, он раз в 1 сек. наносит противникам на своем пути [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] ед. урона от магии льда и применяет к ним эффект \"Стужа\", снижающий скорость передвижения на 30%. Поразив первого противника, шар замедляется и с вероятностью 100% вызывает эффект руны \"Ледяные пальцы\"."},
