[446360] = {name = "Стражи Хукку", additional_info = "Мгновенное действие\n[q]Призыв демонических прислужников Хукку, которые сражаются на его стороне, пока он их не отошлет."},
[446361] = {name = "Стрела Тьмы", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Поражает противника стрелой Тьмы, наносящей урон от темной магии."},
[446362] = {name = "Проклятие крови", additional_info = "Радиус действия: 20 м\nПрименение: 2 сек\n[q]Увеличивает получаемый противником физический урон на 1 ед. на 10 мин."},
[446363] = {name = "Восстановление Иодакса", additional_info = "Применение: 3 сек\nИнгредиенты:\nЛевая рука уничтожителя , Правая рука уничтожителя , Правая ступня Уничтожителя , Левая ступня Уничтожителя\n[q]Объединить с 4 другими частями, чтобы восстановить Иодакса."},
[446364] = {name = "Немощь", additional_info = "Мгновенное действие\n[q]Снижает все характеристики находящихся поблизости противников на 10 на 1 мин."},
