[446384] = {name = "[q4]Колода Дюн", additional_info = "Применение: 3 сек\nИнгредиенты:\nТуз из колоды Дюн , Двойка из колоды Дюн , Тройка из колоды Дюн , Четверка из колоды Дюн , Пятерка из колоды Дюн , Шестерка из колоды Дюн , Семерка из колоды Дюн , Восьмерка из колоды Дюн\n[q]Собрать все карты от туза до восьмерки, чтобы составить колоду Дюн."},
[446385] = {name = "[q4]Колода Кошмаров", additional_info = "Применение: 3 сек\nИнгредиенты:\nТуз из колоды Кошмаров , Двойка из колоды Кошмаров , Тройка из колоды Кошмаров , Четверка из колоды Кошмаров , Пятерка из колоды Кошмаров , Шестерка из колоды Кошмаров , Семерка из колоды Кошмаров , Восьмерка из колоды Кошмаров\n[q]Собрать все карты от туза до восьмерки, чтобы составить колоду Кошмаров."},
[446386] = {name = "[q4]Колода Чумы", additional_info = "Применение: 3 сек\nИнгредиенты:\nТуз из колоды Чумы , Двойка из колоды Чумы , Тройка из колоды Чумы , Четверка из колоды Чумы , Пятерка из колоды Чумы , Шестерка из колоды Чумы , Семерка из колоды Чумы , Восьмерка из колоды Чумы\n[q]Собрать все карты от туза до восьмерки, чтобы составить колоду Чумы."},
[446387] = {name = "[q4]Колода Дикой природы", additional_info = "Применение: 3 сек\nИнгредиенты:\nТуз из колоды Дикой природы , Двойка из колоды Дикой природы , Тройка из колоды Дикой природы , Четверка из колоды Дикой природы , Пятерка из колоды Дикой природы , Шестерка из колоды Дикой природы , Семерка из колоды Дикой природы , Восьмерка из колоды Дикой природы\n[q]Собрать все карты от туза до восьмерки, чтобы составить колоду Дикой природы."},
[446388] = {name = "Песчаная буря", additional_info = "Мгновенное действие\n[q]Наносит 100 в 200 ед. урона целям на своем пути."},
[446389] = {name = "Песчаная буря", additional_info = "[q]Заклинания и атаки с некоторой вероятностью призывают песчаную бурю, кружащую вокруг вас и наносящую 50 в 100 ед. урона от сил природы целям на своем пути.\n(Вероятность срабатывания: 30%, Восстановление: 8с)"},
[446390] = {name = "Мучение", additional_info = "[q]Атаки и заклинания владельца с некоторой вероятностью истязают цель, заставляя ее бесцельно бродить в течение 3 сек.\n(Вероятность срабатывания: 5%, Восстановление: 15с)"},
[446391] = {name = "Мучение", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Бесцельно бродит в течение 3 сек."},
[446392] = {name = "Гниение", additional_info = "[q]Заклинания и атаки иногда похищают у цели 40 ед. здоровья и применяют один эффект \"Гниение\". При накоплении 5 эффектов цель получает 225 в 375 ед. урона.\n(Восстановление: 3с)"},
[446393] = {name = "Гниение", additional_info = nil},
[446394] = {name = "Разрастание", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Восполняет 8 ед. энергии, 1% маны или 40 ед. ярости."},
[446395] = {name = "Разрастание", additional_info = "[q]Заклинания прямого исцеления и восполняющие здоровье такты периодического исцеления с некоторой вероятностью восполняют цели 8 ед. энергии, 1% маны или 4 ед. ярости.\n(Вероятность срабатывания: 10%)"},
[446396] = {name = "Живительное колдунство Атал'ай", additional_info = "Мгновенное действие\n[q]Повышает силу исцеления на 45 ед., а скорость восполнения маны на 11 ед. за 5 сек. Ваши исцеляющие заклинания с некоторой вероятностью восполняют 8 ед. энергии, 1% маны или 4 ед. ярости. Одновременно может действовать только одно зелье Атал'ай. Действует только в Затонувшем храме.\n(Вероятность срабатывания: 25%, Восстановление: 20с)"},
[446397] = {name = "Генератор радуги", additional_info = "Радиус действия: 50 м\nНаправляемое (Применение: 25 сек)\n[q]Сила радуги!"},
