[449414] = {name = "Церемония крови Атал'ай", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Кинжал для жертвоприношений. На его поверхности вырезаны слова молитвы для древней церемонии крови Атал'ай."},
[449420] = {name = "Церемония крови Атал'ай", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Кинжал для жертвоприношений. На его поверхности вырезаны слова молитвы для древней церемонии крови Атал'ай."},
[449422] = {name = "Осознанное сновидение", additional_info = "Радиус действия: 200 м\nПрименение: 4 сек\n[q]Поражает противников в секторе перед собой, отбрасывая их."},
[449431] = {name = "Звездопад", additional_info = "Радиус действия: 30 м\nНаправляемое (Применение: 8 сек)\n[q]Наносит противникам в области действия 213 в 237 ед. урона от тайной магии раз в 1 сек. в течение 8 сек."},
[449432] = {name = "Проклятие рока", additional_info = "{Мана: 300} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Проклинает цель, нанося ей 3200 ед. урона от темной магии через 1 мин. Если цель погибает от этого заклинания, с некоторой вероятностью призывает Стража Ужаса. Нельзя применить к игрокам."},
[449668] = {name = "Сила атаки - зверь (+114)", additional_info = "Требуется: Облик кошки, Облик медведя, Облик лютого медведя\n[q]Увеличивает силу атаки на 114 ед. в облике кошки, медведя и лютого медведя."},
[449669] = {name = "Аура воздаяния", additional_info = "Мгновенное действие\n[q]Наносит 3 ед. урона от светлой магии противникам, которые атакуют ближайших участников группы. Единовременно на игрока может действовать только одна аура от каждого паладина. Действует до отмены."},
[449729] = {name = "Пробуждение мертвых", additional_info = "Радиус действия: 50 м\nМгновенное действие\n[q]Изнеможение."},
[449825] = {name = "За пределами", additional_info = "Мгновенное действие\n[q]Войти в другую область, охваченную кошмаром."},
[449869] = {name = "Дыхание разъедающей кислоты", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Выпускает облако кислоты в секторе перед собой. Кислота ослабляет броню противников и наносит им урон от сил природы раз в 5 сек. в течение 30 сек."},
[449879] = {name = "Туман сна", additional_info = nil},
[449890] = {name = "Взмах хвоста", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит 50 в 70 ед. урона противникам в секторе за собой и отбрасывает их."},
[449907] = {name = "Чародейский взрыв", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Создает магическую взрывную волну, наносящую ближайшим противникам урон от тайной магии."},
[449919] = {name = "Злоба", additional_info = "[q]Наносящие урон заклинания с некоторой вероятностью увеличивают урон, получаемый целью от последующих заклинаний, на 50 ед.\n(Вероятность срабатывания: 20%)"},
[449920] = {name = "Зловредность", additional_info = nil},
[449921] = {name = "Вера и магия", additional_info = "[q]Ваши заклинания с уроном от светлой магии увеличивают наносимый урон и силу исцеления на 60 ед. на 15 сек."},
[449923] = {name = "Благо", additional_info = nil},
[449924] = {name = "Могучие когти", additional_info = "[q]\"\"\"Полоснуть\"\" снижает затраты маны на следующую смену облика в течение 10 сек. на 30%.\""},
[449925] = {name = "Могучие когти", additional_info = "Мгновенное действие\n[q]Снижает затраты маны на смену облика на 30%."},
[449926] = {name = "Меткие когти", additional_info = "Требуется: Облик медведя, Облик лютого медведя\n[q]Повышает вероятность попадания всех атак и заклинаний на 2%, пока вы находитесь в облике медведя или лютого медведя."},
[449927] = {name = "Порча крови", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Вызывает у цели кровоизлияние, увеличивая наносимый ей урон максимум на 7 ед. Длится 30 удара:ударов или 15 сек."},
[449928] = {name = "Испорченная кровь", additional_info = "[q]\"\"\"Удар в спину\"\" и \"\"Коварный удар\"\" увеличивают урон, получаемый целью от всех источников, на 7 ед. Длится 30 удара:ударов или 15 сек.\""},
[449929] = {name = "Изгнанный сновидец", additional_info = "[q]Критические эффекты ваших заклинаний прямого исцеления с вероятностью 50% активируют \"Состояние сна\", если у вас выгравирована эта руна.\n(Вероятность срабатывания: 50%)"},
[449930] = {name = "Изумрудные ливни", additional_info = "[q]\"Сокращает время применения \"\"Целительного ливня\"\" на 100%.\""},
[449931] = {name = "Пылающая сила", additional_info = "[q]Когда вы наносите урон от огня, ваша сила атаки повышается на 5. Эффект суммируется до 10 раз. Время действия – 12 сек."},
[449932] = {name = "Пылающая сила", additional_info = "Мгновенное действие\n[q]Повышает силу атаки на 5."},
[449933] = {name = "Критический свет", additional_info = "[q]Повышает вероятность критического эффекта заклинаний светлой магии на 3%."},
[449934] = {name = "Яростный шторм", additional_info = "Мгновенное действие\n[q]Увеличивает урон и силу исцеления от заклинаний и эффектов сил природы максимум на 60 ед."},
[449935] = {name = "Яростный шторм", additional_info = "[q]Заклинания могут увеличить наносимый урон и эффективность исцеления заклинаний сил природы максимум на 60 ед. на 10 сек.\n(Вероятность срабатывания: 10%)"},
[449958] = {name = "Troll Object - Candle Display", additional_info = nil},
[449970] = {name = "Дополнительная атака", additional_info = "[q]С вероятностью 3% позволяет атаковать цель повторно после того, как вы нанесете ей урон оружием.\n(Вероятность срабатывания: 3%, Восстановление: 200мс)"},
[449974] = {name = "Надежное блокирование", additional_info = "[q]Увеличивает показатель блокирования на 50 ед. на 6 сек после блокирования."},
[449975] = {name = "Надежное блокирование", additional_info = "Мгновенное действие\n[q]Увеличивает показатель блокирования щита на 50 ед."},
[449980] = {name = "Манускрипт священного рвения", additional_info = "[q]\"Шок небес\" сокращает время применения 2 следующих заклинаний \"Свет небес\"; на 0.2 сек."},
[449982] = {name = "Манускрипт священного рвения", additional_info = "Мгновенное действие\n[q]\"Сокращает время применения 2 следующих заклинаний:следующих заклинаний \"\"Свет небес\"\" на 0.2000,1 сек.\""},
