[450012] = {name = "Искра Тьмы", additional_info = "[q]\"Урон от \"\"Теневого рассекающего удара\"\" сокращает время применения следующего \"\"Жертвенного огня\"\" на 50%. Эффект суммируется до 2 раз. Время действия – 12 сек.\""},
[450013] = {name = "Искра Тьмы", additional_info = "Мгновенное действие\n[q]\"Сокращает время применения следующего \"\"Жертвенного огня\"\" на 50%.\""},
