[450086] = {name = "Молитва стойкости", additional_info = "{Мана: 3400} {Радиус действия: 40 м}\nМгновенное действие\n[q]Наделяет цель и участников ее группы стойкостью, повышающей выносливость на 43 на 1 ч."},
[450091] = {name = "Глубокая дремота", additional_info = "Мгновенное действие\n[q]Когда сонное облако касается цели, она засыпает на до отмены. Получаемый целью урон и получаемое ею исцеление уменьшаются на 0%."},
[450092] = {name = "Глубокая дремота", additional_info = "Мгновенное действие\n[q]Когда сонное облако касается цели, она засыпает на 3 сек. Получаемый целью урон и получаемое ею исцеление уменьшаются на 0%."},
[450098] = {name = "Разрушающий удар", additional_info = "Радиус действия: 200 м\nМгновенное действие\n[q]Бьет по земле, нанося игрокам 1500 ед. физического урона и отбрасывая их."},
[450105] = {name = "Очищение", additional_info = "Мгновенное действие\n[q]Снимает с выпившего одно проклятие, одну болезнь и один яд."},
[450106] = {name = "Лечебное зелье", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]Восполняет 1350 в 1650 ед. здоровья."},
[450107] = {name = "Лечебное зелье", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]Восполняет 585 в 715 ед. здоровья."},
[450108] = {name = "Внутреннее зрение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Позволяет в течение 1 мин. смотреть на мир глазами цели. Не действует, если цель находится в подземелье или на другом континенте."},
[450109] = {name = "Мучение", additional_info = "(Вероятность срабатывания: 5%, Восстановление: 15с)"},
[450110] = {name = "Гниение", additional_info = "(Вероятность срабатывания: 40%, Восстановление: 3с)"},
[450403] = {name = "Стрельба на поражение", additional_info = "[q]Повышает вероятность критического удара оружием дальнего боя на 2%."},
[450409] = {name = "[q4]Зов Суль'траза", additional_info = "Применение: 10 сек\nИнгредиенты:\nСанг'траз Отражатель\n[q]Соединить Джанг'траз и Санг'траз для создания могучего меча Суль'траза."},
[450512] = {name = "S03 - +40 к силе атаки, +23 к урону от заклинаний, +40 к силе исцеления - дикое сердце", additional_info = "[q]Ваша сила атаки повышается на 40, урон от заклинаний – максимум на 23, а сила исцеления от заклинаний – максимум на 44."},
[450516] = {name = "S03 - +40 к силе атаки, +32 к силе исцеления - Светлая сталь", additional_info = "[q]Ваша сила атаки повышается на 40, а сила исцеления от заклинаний – максимум на 40."},
[450517] = {name = "S03 - +40 к силе атаки, +23 к урону от заклинаний, +44 к силе исцеления - стихии", additional_info = "[q]Ваша сила атаки повышается на 40, урон от заклинаний – максимум на 23, а сила исцеления от заклинаний – максимум на 44."},
[450527] = {name = "S03 - срабатывание восполнения маны от заклинаний - регалии Магистра", additional_info = "[q]Заклинания с вероятностью 6% восполняют вам 300 ед. маны.\n(Вероятность срабатывания: 6%)"},
[450554] = {name = "Неожиданное прозрение", additional_info = "Мгновенное действие\n[q]Восполняет 300 ед. маны."},
[450576] = {name = "S03 - срабатывание восполнения маны от заклинаний - ризы Благочестия", additional_info = "[q]Заклинания с вероятностью 6% восполняют вам 300 ед. маны.\n(Вероятность срабатывания: 6%)"},
[450577] = {name = "S03 - срабатывание восполнения маны от заклинаний - доспехи загонщика", additional_info = "[q]Ваши автоатаки в ближнем и дальнем бою с вероятностью 6% восполняют вам 300 ед. маны.\n(Вероятность срабатывания: 6%)"},
[450583] = {name = "Темная награда", additional_info = "Мгновенное действие\n[q]Восполняет вам 270 в 330 ед. здоровья."},
[450585] = {name = "S03 - срабатывание исцеления от заклинаний - одеяния Багрового Тумана", additional_info = "[q]Автоатаки в ближнем бою и заклинания с вероятностью 6% восполняют вам 270 в 330 ед. здоровья.\n(Вероятность срабатывания: 6%)"},
[450587] = {name = "S03 - Warrior Armor Heal Trigger - Battlegear of Valor", additional_info = "[q]Атаки в ближнем бою с некоторой вероятностью восполняют вам 88 в 132 ед. здоровья и 10 ед. ярости."},
[450588] = {name = "Призыв игрока", additional_info = nil},
[450589] = {name = "Твердость воина", additional_info = nil},
[450600] = {name = "Сглаз", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Превращает противника в лягушку, лишая его возможности атаковать и творить заклинания на 10 сек."},
[450601] = {name = "Цепная молния", additional_info = "Радиус действия: 30 м\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Поражает противника молнией, которая переходит на другого находящегося рядом противника. Поражает до 3 целей, нанося каждой из них возрастающий урон от сил природы."},
[450602] = {name = "Молния", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Поражает противника молнией, наносящей урон от сил природы."},
[450603] = {name = "Волна исцеления", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Призывает силы природы и исцеляет союзника."},
[450606] = {name = "Бродячая чума", additional_info = "(Вероятность срабатывания: 10%)"},
[450607] = {name = "Бродячая чума", additional_info = "Дистанция ближнего боя\n{Применение: 2 сек} {Восстановление: 7 мин}\n[q]Заражает противника болезнью, которая увеличивает получаемый физический урон на 5 ед. и снижает выносливость на 30 на 5 мин. Когда зараженная цель получает урон в бою, болезнь с вероятностью 10% переходит на находящегося рядом союзника.\n(Вероятность срабатывания: 10%)"},
[450608] = {name = "S03 - Druid Energize Trigger - Wildheart Raiment", additional_info = "[q]Заклинания с вероятностью 2% восполняют вам 300 ед. маны. Автоатаки в ближнем бою с вероятностью 6% восполняют вам 40 ед. энергии. Когда противники атакуют вас в ближнем бою, вы с вероятностью 3% восполняете 10 ед. ярости.\n(Вероятность срабатывания: 6%)"},
[450625] = {name = "Предмет – срабатывание \"Гнева рыцаря Света\" – доспехи Светлой стали", additional_info = "[q]Автоатаки в ближнем бою с вероятностью 6%, а заклинания – с вероятностью 4% увеличивают урон и силу исцеления ваших магических эффектов на 95 ед. на 10 сек.\n(Вероятность срабатывания: 6%)"},
[450626] = {name = "Предмет – срабатывание \"Яростного шторма\"", additional_info = "[q]Автоатаки оружием в правой руке с вероятностью 6%, а заклинания – с вероятностью 4% увеличивают урон и силу исцеления ваших магических эффектов на 95 ед. на 10 сек.\n(Вероятность срабатывания: 6%)"},
[450640] = {name = "Бродячая чума", additional_info = "Радиус действия: 10 м\nМгновенное действие\n(Вероятность срабатывания: 10%)"},
