[456485] = {name = "Регенерация", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Восстанавливает цели [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] ед. здоровья за до отмены. и дает эффект \"Темпоральный маяк\" на 30 сек.\n\n Темпоральный маяк\n\nЗапоминает положение цели в пространстве-времени. 70% наносимого вами урона от тайной магии преобразуется в темпоральное исцеление и применяется к каждой текущей цели \"Темпорального маяка\". Вы получаете на 50% меньше исцеления из этого источника. Заклинания тайной магии, наносящие урон нескольким целям, дают на 80% меньше чародейского исцеления."},
[456488] = {name = "S03 - предмет - T1 - паладин - бонус \"Света\" за 2 предмета", additional_info = "[q]Ваши союзники вызывают срабатывание вашего \"Правосудия Света\" или \"Правосудия мудрости\" на 70% чаще."},
[456489] = {name = "S03 - предмет - T1 - паладин - бонус \"Воздаяния\" за 4 предмета", additional_info = "[q]Повышает вероятность критического удара заклинаний и атак на 2%."},
[456492] = {name = "S03 - предмет - T1 - паладин - бонус \"Света\" за 6 предметов", additional_info = "[q]Когда ваши заклинания \"Вспышка Света\", \"Свет небес\" или \"Частица Света\" полностью исцеляют цель, вы также восполняете всем участникам ее группы 189 в 211 ед. здоровья."},
[456493] = {name = "Целебный круг", additional_info = nil},
[456494] = {name = "S03 - предмет - T1 - паладин - бонус \"Воздаяния\" за 2 предмета", additional_info = "[q]Ваши заклинания \"Правосудие Света\" и \"Правосудие мудрости\" также дают эффект \"Правосудие воина Света\"."},
[456496] = {name = "Правосудие воина Света", additional_info = nil},
[456533] = {name = "S03 - предмет - T1 - паладин - бонус \"Воздаяния\" за 6 предметов", additional_info = "[q]\"Печать повиновения\", \"Печать праведности\", \"Печать мученичества\" и \"Солнечный свет\" наносят на 35% меньше урона, но продолжают действовать в течение 6 сек. после применения другой печати или до тех пор, пока вы не примените третью печать. \"Правосудие\" может вызывать срабатывание нескольких действующих печатей одновременно."},
[456536] = {name = "S03 - предмет - T1 - паладин - бонус \"Защиты\" за 2 предмета", additional_info = "[q]Увеличивает показатель блокирования вашего щита на 30 ед."},
[456538] = {name = "S03 - предмет - T1 - паладин - бонус \"Защиты\" за 4 предмета", additional_info = "[q]Когда вы блокируете атаку, вы восполняете 189 в 211 ед. здоровья. Срабатывает раз в несколько секунд.\n(Восстановление: 3.5с)"},
[456540] = {name = "Бастион Света", additional_info = nil},
[456541] = {name = "S03 - предмет - T1 - паладин - бонус \"Защиты\" за 6 предметов", additional_info = "[q]\"Щит небес\" больше не имеет зарядов и теперь всегда действует до окончания времени действия. Кроме того, наносимый им урон увеличивается на 80% от показателя блокирования вашего щита."},
[456544] = {name = "Щит небес", additional_info = nil},
