[459602] = {name = "Повышение вероятности критического эффекта \"Шока небес\"", additional_info = "[q]Повышает вероятность критического эффекта \"Шока небес\" на 2%."},
[459603] = {name = "Сокращение времени действия \"Ослабленной души\"", additional_info = "[q]Сокращает время действия вашего эффекта \"Ослабленная душа\" на 2 сек."},
[459604] = {name = "Сокращение задержки при применении \"Взрыва разума\"", additional_info = "[q]С вероятностью 50% применение \"Взрыва разума\" не прерывается при получении урона."},
[459605] = {name = "Повышение длительности спринта", additional_info = "[q]Продлевает время действия \"Спринта\" на 3 сек."},
[459606] = {name = "Скорость призрачного волка", additional_info = "[q]Повышает скорость передвижения в облике призрачного волка на 15%."},
[459607] = {name = "Сокращение задержки при применении \"Жгучей боли\"", additional_info = "[q]С вероятностью 50% применение \"Жгучей боли\" не прерывается при получении урона."},
[459608] = {name = "Снижение затрат ярости на способность \"Подрезать сухожилия\"", additional_info = "[q]Затраты ярости на способность \"Подрезать сухожилия\" снижены на 3 ед."},
[459610] = {name = "Решимость странника", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышает скорость передвижения на 10%, а все характеристики – на 15% на 2 ч."},
[459611] = {name = "Астральная победа", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Череда побед\n 0 [трофей][трофея:трофеев]."},
