[459624] = {name = "Воздаятель", additional_info = nil},
[459692] = {name = "Плавание", additional_info = nil},
[459695] = {name = "Расовая способность жреца", additional_info = "Мгновенное действие\n[q]Изучите заклинание жреца другой расы, чтобы активировать соответствующую способность."},
[459699] = {name = "Защита от страха", additional_info = "Мгновенное действие\n[q]Дает способность \"Защита от страха\":\n\n\nОграждает дружественную цель от воздействия заклинания \"Страх\". Следующий эффект устрашения, обращенный против цели, будет нейтрализован. Время действия – 10 мин."},
[459702] = {name = "Молитва отчаяния", additional_info = "Мгновенное действие\n[q]Дает способность \"Молитва отчаяния\":\n\n\nМгновенное исцеление заклинателя на 1340 в 1579 ед."},
[459703] = {name = "Ответная реакция", additional_info = "Мгновенное действие\n[q]Дает способность \"Ответная реакция\":\n\n\nЖреца окружает поле антимагической энергии. Любое успешно наложенное на него заклинание сожжет 105 ед. маны атакующего и нанесет 1 ед. урона от темной магии за каждую единицу сожженной маны. Время действия – 15 сек."},
[459705] = {name = "Звездные осколки", additional_info = "Мгновенное действие\n[q]Дает способность \"Звездные осколки\":\n\n\nНа голову противника сыплются звездные осколки, нанося 936 ед. урона от тайной магии в течение 6 сек."},
[459706] = {name = "Благодать Элуны", additional_info = "Мгновенное действие\n[q]Дает способность \"Благодать Элуны\":\n\n\nУменьшение урона, получаемого при дальней атаке, на 95 ед. и увеличение вероятности уклониться от атаки на 10% на 15 сек."},
[459709] = {name = "Страж Тьмы", additional_info = "Мгновенное действие\n[q]Дает способность \"Страж Тьмы\":\n\n\nОкружение заклинателя тенями. При любой атаке заклинателя противник получит 116 ед. урона от темной магии. Наносить урон атакующим можно лишь раз в несколько секунд. Этот урон не создает угрозы. 3 заряда:зарядов. Длительность - 10 мин."},
[459710] = {name = "Обессиливающий сглаз", additional_info = "Мгновенное действие\n[q]Дает способность \"Обессиливающий сглаз\":\n\n\nОслабление, уменьшение наносимого противником урона на 20 ед., замедление любого исцеления на 20%. Время действия – 2 мин."},
[459713] = {name = "Всепожирающая чума", additional_info = "Мгновенное действие\n[q]Дает способность \"Всепожирающая чума\":\n\n\nБолезнь, наносящая 904 ед. урона от темной магии в течение 24 сек. Исцеление применяющего заклинание за счет нанесенного урона."},
[459714] = {name = "Прикосновение слабости", additional_info = "Мгновенное действие\n[q]Дает способность \"Прикосновение слабости\":\n\n\nСледующая атака ближнего боя по заклинателю нанесет атакующему 64 ед. урона от темной магии и снизит наносимый урон на 20 в течение 2 мин."},
[459736] = {name = "Теплый ром Ромси со сливками", additional_info = "Применение: 1 сек\n[q]Повышает выносливость на 30 на 45 мин. Жуткое опьянение!"},
