[460375] = {name = "Призыв духа дворфа", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Потереть зуб Ортаса. Какая гадость."},
[460399] = {name = "Опустошение Разрушителя", additional_info = "Радиус действия: 45 м\nМгновенное действие\n[q]Опустошение Разрушителя уничтожает противников на своем пути."},
[460401] = {name = "Вспышка Пустоты", additional_info = "Радиус действия: 60 м\nПрименение: 4 сек\n[q]Выпускает вспышку огня Пустоты, наносящую урон и поджигающую противников в большом радиусе. Кроме того, вспышка создает кольцо огня, наносящее урон проходящим через него противникам."},
[460402] = {name = "Изнуряющая аура", additional_info = "Мгновенное действие\n[q]Демон излучает ауру порчи, наносящую урон ближайшим противникам."},
[460403] = {name = "Керосиновый удар ногой", additional_info = "Радиус действия: 45 м\nПрименение: 3 сек\n[q]Зилбагоб совершает взрывной взлет на крошшере, создавая ударные волны, которые расчищают эффекты на полу."},
[460406] = {name = "Горящее топливо Скверны", additional_info = "Применение: 0.85 сек\n[q]Бес усиливает и поджигает топливо крошшера."},
[460408] = {name = "Секач хаоса", additional_info = "Применение: 2 сек\n[q]Бес совершает круговой удар лезвиями крошшера, нанося урон ближайшим противникам и отбрасывая их."},
[460455] = {name = "Ускорение", additional_info = "Мгновенное действие\n[q]Повышает скорость атаки на 50% на 30 сек. Не действует на персонажей выше 55-го уровня."},
[460460] = {name = "[q4]Сульфуронский молот", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nСульфуронский слиток (8), Слиток черного железа (20), Арканитовый слиток (50), Субстанция Огня (25), Кровь Горы (10), Ядро лавы (10), Огненное ядро (10)\n[q4]Сульфуронский молот\nСтановится персональным при надевании\nДвуручное Дробящее\nУрон: 181-303 Скорость 3.80\n(63.68 ед. урона в секунду)\n+10 к силе\n+10 к выносливости\nУстойчивость: +30 Огонь\nПрочность: 120 / 120\nТребуется\n[q2]Возможный эффект при попадании: Бросок огненного шара, который наносит 83 в 101 ед. урона от огня единовременно и 16 ед. урона от огня в течение 8 сек.\n[q2]Если на персонаже: Нанесение 5 ед. урона от огня любому, кто нападает на вас в ближнем бою.\n[q2]Если на персонаже: Увеличивает силу атаки на 124 ед. в облике кошки, медведя и лютого медведя."},
[460461] = {name = "Чертеж: сульфуронский молот", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению сульфуронского молота."},
[460462] = {name = "[q5]Око Сульфураса", additional_info = "Применение: 45 сек\nИнгредиенты:\nСульфуронский молот , Глаз Сульфураса\n[q]Око Сульфураса можно соединить с сульфуронским молотом, чтобы создать Сульфурас, легендарный молот Рагнароса."},
