[462814] = {name = "S03 – настройка и отмена пассивных эффектов – паладин", additional_info = "[q]Modifies Effect #2's Value -99%:\nБожественный щит , Божественный щит\n\nModifies Effect #2's Value +101%:\nОтмщение , Отмщение , Отмщение , Отмщение , Отмщение\n\nModifies Effect #4's Value +101%:\nБожественный щит , Божественный щит\n\nModifies Hit Chance +1:\nЩит мстителя"},
[462832] = {name = "Шок и трепет", additional_info = nil},
[462834] = {name = "Шок и трепет", additional_info = "[q]Если \"Шок небес\" наносит урон, пока \"Праведное неистовство\" не активно, ваш урон от заклинаний увеличивается на 200% интеллекта, а уровень создаваемой вами угрозы снижается на 30%. Время действия – 1 мин.\n\n Если выгравирована руна \"Прилив Света\", вы на 10 сек. получаете эффект \"Солнечный свет\".\n\n\n Пока на вас действует \"Солнечный свет\", умения \"Божественная буря\" и \"Удар воина Света\", а также атаки ближнего боя против целей, не находящихся под контролем игроков, наносят дополнительный урон от светлой магии, равный 60% силы заклинаний светлой магии."},
[462853] = {name = "Длань жертвенности", additional_info = "{6% от базовой мана} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Накладывает на участника группы или рейда эффект, перенаправляющий 30% получаемого им урона заклинателю. Длится 12 сек или до тех пор, пока заклинатель не передаст 100% от своего запаса здоровья."},
[462858] = {name = "Круг пламени", additional_info = "Направляемое (Применение: 10 сек)\n[q]Преобразует 150 ед. здоровья в ману раз в 1 сек. в течение 10 сек."},
[462863] = {name = "Призыв беса", additional_info = "Мгновенное действие\n[q]Призывает на помощь беса, который будет служить до отмены заклинания."},
[462868] = {name = "Пожирание магии", additional_info = "Радиус действия: 30 м\n{Применение: 3 сек} {Восстановление: 8 сек}\n[q]Снимает 2 отрицательных магических эффекта:отрицательных магических эффектов с союзника или 2 положительных магических эффекта:положительных магических эффектов с противника. При поглощении эффекта охотник Скверны восполняет 619 ед. здоровья."},
[462871] = {name = "Валун", additional_info = "Радиус действия: 8 - 40 м\nПрименение: 3 сек\n[q]Бросает валун в противника, отбрасывая его и нанося физический урон."},
[462872] = {name = "Нечестивое бешенство", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Повышает скорость атаки союзника на 35% на 20 сек. и наносит ему 1 ед. урона от сил природы раз в 2 сек."},
[462873] = {name = "Плащ теней", additional_info = "{Мгновенное действие} {Восстановление: 1.5 мин}\n[q]Снимает эффекты вредоносных заклинаний и повышает вероятность сопротивления заклинаниям на 90% на 5 сек. Не снимает эффекты, не позволяющие использовать \"Плащ теней\"."},
[462885] = {name = "Исступление", additional_info = nil},
