[462891] = {name = "Вихрь", additional_info = "Мгновенное действие\nТребуется: Оружие ближнего боя\nТребуется: Стойка берсерка\n[q]В вихре стали вы атакуете до 4 противников в радиусе 8 м, нанося каждому урон от оружия."},
