[463564] = {name = "Блок матери драконов", additional_info = "Мгновенное действие\n[q]Увеличивает показатель блокирования вашего щита на 128 ед. на 20 сек."},
[463620] = {name = "Аура воздаяния", additional_info = "[q]Наносит 3 ед. урона от светлой магии противникам, которые атакуют находящихся рядом участников группы. Единовременно на игрока может действовать только одна аура от каждого паладина. Действует до отмены."},
[463621] = {name = "Аура воздаяния", additional_info = "Мгновенное действие\n[q]Наносит 3 ед. урона от светлой магии противникам, которые атакуют находящихся рядом участников группы. Единовременно на игрока может действовать только одна аура от каждого паладина. Действует до отмены."},
[463626] = {name = "Телепорт", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Телепортация игрока в относительно безопасную область."},
[463641] = {name = "Цепная молния", additional_info = "Радиус действия: 30 м\n(Вероятность срабатывания: 10%, Восстановление: 100мс)"},
[463661] = {name = "Метеор", additional_info = nil},
[463864] = {name = "Печать текущей воды", additional_info = "Мгновенное действие\n[q]Зачарованная печать текущей воды увеличивает урон и силу исцеления заклинаний максимум на 30 ед. и повышает силу атаки на 30. Действует на всех участников рейда. Время действия – 1 ч."},
[463866] = {name = "[q3]Печать текущей воды", additional_info = "Применение: 3 сек\nИнструменты: Рунический жезл из истинного серебра\nИнгредиенты:\nПыль иллюзий\n[q3]Зачарованная печать: текущая вода\nСтановится персональным при поднятии\nТребуется\nТребуетНаложение чар\n(290)\n[q2]Использование: Зачарованная печать текущей воды увеличивает урон и силу исцеления заклинаний максимум на 30 ед. и повышает силу атаки на 30. Действует на всех участников рейда. Время действия – 1 ч. (1 Мин Восстановление)"},
[463867] = {name = "Зачарованная печать: текущая вода", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает сотворению печати текущей воды."},
[463868] = {name = "Проводящее покрытие для щита", additional_info = "Применение: 3 сек\nТребуется: Оружие\n[q]Применяется к щиту и увеличивает урон и силу исцеления заклинаний максимум на 24 ед. Время действия – 30 мин."},
[463869] = {name = "Проводящее покрытие для щита", additional_info = "Применение: 5 сек\nИнструменты: Рунический жезл из истинного серебра\nИнгредиенты:\nПыль иллюзий (2), Огнецвет , Хрустальная колба\n[q]Создает проводящее покрытие для щита.\nТребуется\n[q2]Использование: Применяется к щиту и увеличивает урон и силу исцеления заклинаний максимум на 24 ед. Время действия – 30 мин.\n5 зарядов"},
[463870] = {name = "Формула: проводящее покрытие для щита", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает созданию проводящего покрытия для щита."},
[463871] = {name = "Чары для щита – закон природы", additional_info = "Применение: 5 сек\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (4), Великая Вечная субстанция (12), Субстанция Огня (4), Субстанция Воды (4), Субстанция Земли , Сфера Праведности\n[q]Применяет к щиту постоянные чары, увеличивающие урон от заклинаний максимум на 30 ед., а силу исцеления заклинаний – максимум на 55 ед."},
[463872] = {name = "Формула чар для щита – закон природы", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает применению к щиту постоянных чар, увеличивающих урон от заклинаний максимум на 30 ед., а силу исцеления заклинаний – максимум на 55 ед."},
[463873] = {name = "Закон природы", additional_info = "[q]Увеличивает урон от магических эффектов и заклинаний максимум на 30 ед., а силу исцеления магических эффектов и заклинаний – максимум на $2 ед."},
[463903] = {name = "Судный день", additional_info = nil},
[463911] = {name = "Судный день", additional_info = nil},
[463946] = {name = "Цепная молния", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Поражает до 3 целей, нанося 105 в 145 ед. урона от сил природы."},
[463970] = {name = "Выкройка: бездонная сумка", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению бездонной сумки."},
[463972] = {name = "[q3]Бездонная сумка", additional_info = "Применение: 1 мин\nИнгредиенты:\nРулон рунной ткани (8), Луноткань (12), Большой сверкающий осколок (2), Сердцевинная кожа (2), Руническая нить (2)\n[q3]Бездонная сумка\nСтановится персональным при надевании\nСумка (ячеек: 20)"},
[464241] = {name = "Тактик", additional_info = "Мгновенное действие\n[q]Снижает затраты ярости на применение следующей атакующей способности на 10."},
[464250] = {name = "Выброс", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Совершает рывок к противнику, нанося 360 в 540 ед. урона цели и находящимся рядом союзникам, а также отбрасывая пораженных врагов."},
[464279] = {name = "Растаптывание", additional_info = "Мгновенное действие\n[q]Наносит находящимся рядом противникам обычный урон и еще 8 ед."},
