[464591] = {name = "Служитель пламени и чешуи", additional_info = nil},
[464592] = {name = "Град огненных шаров", additional_info = "{Мана: 90} {Радиус действия: 25 м}\nПрименение: 2 сек\n[q]Наносит урон от огня ближайшим противникам."},
[464629] = {name = "Буря маны", additional_info = "Мгновенное действие\n[q]Вы вызываете шторм маны, которая длится до отмены., нанося всем противникам в выбранной зоне 0 ед. урона от магии льда и похищает 0 ед. маны раз в 5 сек."},
[464630] = {name = "Буря маны", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Вы вызываете бурю маны, которая наносит всем противникам в указанной области 7 ед. урона от магии льда и похищает 9 ед. маны раз в 2 сек. Время действия – до отмены."},
