[464743] = {name = "Гасители силы", additional_info = "Мгновенное действие\n[q]Снижает силу атаки ближнего и дальнего боя ближайших противников на 1110 на 30 сек."},
[464945] = {name = "[q4]Призыв Громового удара", additional_info = "Применение: 10 сек\n[q]Преобразует Удар Тьмы в Громовой удар."},
[464946] = {name = "[q4]Призыв Удара Тьмы", additional_info = "Применение: 10 сек\n[q]Преобразует Громовой удар в Удар Тьмы."},
