[465192] = {name = "Проклятие Люцифрона", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Проклятие находящихся рядом противников: увеличение затрат на их заклинания и умения на 1000% в течение до отмены. Повышение затрат касается всех заклинаний и умений, вне зависимости от того, тратится ли на них мана, ярость или энергия."},
[465193] = {name = "Проклятие Люцифрона", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Проклятие находящихся рядом противников: увеличение затрат на их заклинания и умения на 1000% в течение до отмены. Повышение затрат касается всех заклинаний и умений, вне зависимости от того, тратится ли на них мана, ярость или энергия."},
[465194] = {name = "Проклятье Шаззраха", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличение магического урона, наносимого ближайшим противникам, на 1000% в течение до отмены."},
[465195] = {name = "Проклятье Шаззраха", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличение магического урона, наносимого ближайшим противникам, на 1000% в течение до отмены."},
