[465352] = {name = "Изгнание", additional_info = "{Мана: 100} {Радиус действия: 30 м}\nМгновенное действие\n[q]Изгоняет цель. В течение 30 сек. она не может совершать никаких действий и становится неуязвимой. Заклинание можно применять только против одного противника единовременно. Действует только на демонов и элементалей."},
[465404] = {name = "Воплощение огня", additional_info = nil},
[465411] = {name = "Удар мстителя", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит цели 4 ед. дополнительного урона от светлой магии."},
[465412] = {name = "Дополнительный урон от светлой магии – оруж. 4", additional_info = "[q]Позволяет атакам ближнего боя наносить 4 ед. дополнительного урона от светлой магии."},
[465414] = {name = "Рвение рыцаря", additional_info = "Мгновенное действие\n[q]Увеличивает наносимый урон на 15 ед. и повышает скорость атаки на 30% на 8 сек."},
[465417] = {name = "[q4]Смена стойки", additional_info = "{Применение: 1 сек} {Восстановление: 1 мин}\n[q]Вы меняете стойку и держите Правдоносец как полуторный меч, что позволяет вам использовать его вместе с щитом."},
[465418] = {name = "[q4]Смена стойки", additional_info = "Применение: 1 сек\n[q]Вы меняете стойку и держите Правдоносец как двуручный меч."},
[465447] = {name = "Создание лагеря", additional_info = "Радиус действия: 13 м\n{Применение: 4 сек} {Восстановление: 5 мин}\n[q]Вы разбиваете походный лагерь. Чтобы создать укрытие, принесите в лагерь дополнительные припасы."},
[465483] = {name = "Увечье", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Наносит противнику 300 ед. урона раз в 2 сек. и снижает его скорость передвижения на 300% на 20 сек."},
[465626] = {name = "Создание принадлежностей для лагеря", additional_info = "Мгновенное действие\n[q]Оборудует походный лагерь дополнительными удобствами."},
[465675] = {name = "Повышение репутации", additional_info = "Применение: 1 сек\n[q]Улучшает ваши отношения с Кругом Кенария."},
[465700] = {name = "Цепная молния", additional_info = "Неограниченное расстояние\nПрименение: 3 сек\n[q]Выпускает в противника молнию, наносящую 2187 в 2813 ед. урона от сил природы. Затем молния переходит на других находящихся рядом противников. Урон увеличивается с каждым переходом."},
[465725] = {name = "Живая бомба", additional_info = "Радиус действия: 45 м\nМгновенное действие\n[q]Бросает в противника бомбу. Через 8 сек. бомба взрывается, нанося 3200 ед. урона от огня цели и находящимся рядом союзникам."},
[465727] = {name = "Взрыв", additional_info = nil},
