[465945] = {name = "Создание принадлежностей для лагеря – небольшой костер", additional_info = "Мгновенное действие\n[q]Оборудует походный лагерь дополнительными удобствами."},
[465946] = {name = "Создание принадлежностей для лагеря – стойка для мяса", additional_info = "Мгновенное действие\n[q]Оборудует походный лагерь дополнительными удобствами."},
