[466071] = {name = "Испытание бронзовых драконов", additional_info = "Мгновенное действие\n[q]Вы проходите испытание бронзовых драконов. Ход времени случайным образом замедляется и ускоряется."},
[466072] = {name = "Призыв Эстеленн", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Призывает ночную эльфийку - охотницу Эстеленн."},
[466116] = {name = "[q4]Настройка посоха адского пламени", additional_info = "{Применение: 1 сек} {Восстановление: 1 мин}\n[q]Настраивает посох на магию огня."},
[466117] = {name = "[q4]Настройка посоха инея", additional_info = "{Применение: 1 сек} {Восстановление: 1 мин}\n[q]Настраивает посох на магию льда."},
