[466211] = {name = "Нити воздуха", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Поражает противников в секторе перед собой, отбрасывая их."},
[466219] = {name = "Страж Тьмы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Окружает себя тенями. Противники, атакующие в ближнем или дальнем бою, а также с помощью заклинаний, получают 20 ед. урона от темной магии. Срабатывает раз в несколько секунд. Этот урон не создает угрозы. 0 заряда:зарядов. Время действия – 1 мин."},
[466255] = {name = "Бесконечная полночь", additional_info = nil},
[466256] = {name = "Бесконечная полночь", additional_info = nil},
[466261] = {name = "Испытание красных драконов", additional_info = "Мгновенное действие\n[q]Вы проходите испытание красных драконов. При получении урона вы загораетесь, получая 400 ед. урона от огня раз в 3 сек. до тех пор, пока уровень здоровья не поднимется выше 90%. Эффекты прямого исцеления снимают 1 эффект горения."},
[466266] = {name = "Страж Тьмы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Окружает себя тенями. Противники, атакующие в ближнем или дальнем бою, а также с помощью заклинаний, получают 20 ед. урона от темной магии. Срабатывает раз в несколько секунд. Этот урон не создает угрозы. 0 заряда:зарядов. Время действия – 1 мин."},
[466269] = {name = "Страж Тьмы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Окружает себя тенями. Противники, атакующие в ближнем или дальнем бою, а также с помощью заклинаний, получают 20 ед. урона от темной магии. Срабатывает раз в несколько секунд. Этот урон не создает угрозы. 0 заряда:зарядов. Время действия – 1 мин."},
[466270] = {name = "Нити воздуха", additional_info = nil},
[466272] = {name = "Нити воздуха", additional_info = nil},
[466277] = {name = "Испытание синих драконов", additional_info = "Мгновенное действие\n[q]Прохождение испытания синих драконов. Время от времени вы можете стать целью \"Чародейской бомбы\", которая наносит высокий урон, распределяющийся между пораженными целями."},
[466283] = {name = "Чародейская бомба", additional_info = nil},
[466286] = {name = "Таймер контроллера", additional_info = nil},
[466328] = {name = "Полный шлем Волшебного Камня", additional_info = nil},
[466329] = {name = "Апперкот", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Совершает быстрый апперкот, подбрасывающий цель в воздух."},
[466357] = {name = "Чародейская бомба", additional_info = "Мгновенное действие\n[q]Взрывается через 8 сек., нанося высокий урон, распределяющийся между пораженными целями."},
[466416] = {name = "Испытание зеленых драконов", additional_info = "Мгновенное действие\n[q]Вы проходите испытание зеленых драконов. Время от времени вы можете стать целью мощных чар природы, наносящих урон ближайшим игрокам и создающих лужу яда."},
