[468061] = {name = "S03 - предмет - T2 - чернокнижник - бонус танка за 6 предметов", additional_info = "[q]Эффекты избыточного самоисцеления преобразуются в поглощающий урон щит. Прочность щита суммируется и может достигать до 30 + (5 * Серия приёмов)% максимального запаса здоровья."},
[468062] = {name = "Субстанция души", additional_info = nil},
[468065] = {name = "S03 - предмет - T2 - воин - бонус \"Защиты\" за 2 предмета", additional_info = "[q]Когда вы парируете атаку противника или противник парирует вашу, вы накапливаете 10 ед. ярости."},
[468066] = {name = "Пыл битвы", additional_info = nil},
[468067] = {name = "S03 - предмет - T2 - воин - бонус \"Защиты\" за 4 предмета", additional_info = "[q]\"Реванш\" также дает вам \"Шквал\", повышающий скорость атаки на 30% на 3 удара:ударов."},
[468069] = {name = "S03 - предмет - T2 - воин - бонус \"Защиты\" за 6 предметов", additional_info = "[q]Когда ваша цель парирует атаку, вы мгновенно применяете \"Возмездие\", нанося цели 200% урона от оружия. \"Возмездие\" нельзя заблокировать или парировать, и от него нельзя уклониться. Срабатывает против каждой цели не чаще раза в 30 сек."},
[468071] = {name = "Отмщение", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя"},
[468072] = {name = "S03 - предмет - T2 - воин - бонус бойца за 2 предмета", additional_info = "[q]Критические удары \"Превосходства\" продлевают время действия \"Кровопускания\" на цели до максимального."},
[468076] = {name = "Порочный удар", additional_info = "Радиус действия: 50 м\n{Мгновенное действие} {Восстановление: 6 сек}\n[q]Увеличивает урон, получаемый от \"Порочного удара\", на 50%."},
[468078] = {name = "Нейтрализация", additional_info = nil},
[468125] = {name = "[q4]Насыщение субстанции огня", additional_info = "Применение: 3 сек\nИнгредиенты:\nСвиток: сущность огня , Истощенная субстанция Огня\n[q]Насыщает магией истощенную субстанцию огня."},
[468133] = {name = "Начало субстанции огня", additional_info = nil},
[468156] = {name = "Неистовство бури", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Поражает противника молнией, которая наносит 300 ед. урона от сил природы и переходит на других находящихся рядом противников. Каждый переход снижает сопротивление цели силам природы на 25. Максимум целей – 5. Первую цель также охватывает смерч, снижающий скорость атаки на 20% на 12 сек."},
[468157] = {name = "Неистовство бури", additional_info = nil},
[468164] = {name = "Сломанная бобина Пэгла", additional_info = "Мгновенное действие\n[q]Повышает вероятность попадания заклинаниями и атаками на 10% на 15 сек."},
[468165] = {name = "Убийство животных 99", additional_info = "[q]Увеличивает силу атаки на 99 ед. в бою с животными."},
[468166] = {name = "Убийство драконов 60", additional_info = "[q]Увеличивает силу атаки на 60 ед. в бою с драконами."},
[468167] = {name = "Огненный удар", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит цели 2 ед. дополнительного урона от огня."},
[468168] = {name = "Дополнительный урон от огня - оруж. 2", additional_info = "[q]Позволяет атакам ближнего боя наносить 2 ед. дополнительного урона от огня."},
[468169] = {name = "Огненный удар", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит цели 2 ед. дополнительного урона от огня."},
[468170] = {name = "Дополнительный урон от огня - оруж. 2", additional_info = "[q]Позволяет атакам ближнего боя наносить 2 ед. дополнительного урона от огня."},
[468175] = {name = "Убийство демонов 141", additional_info = "[q]Увеличивает силу атаки на 141 ед. в бою с демонами."},
[468181] = {name = "Попадание", additional_info = nil},
[468183] = {name = "Эффект бешенства", additional_info = "Мгновенное действие\n[q]Критические удары вашего питомца с некоторой вероятностью повышают его скорость атаки на 30% на 8 сек."},
[468184] = {name = "Похищение жизни", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Похищает у противника 137 в 143 ед. здоровья."},
[468195] = {name = "Перекат!", additional_info = "Мгновенное действие\n[q]Призывает кислотный дождь, наносящий пораженным игрокам 1000 ед. урона от сил природы."},
