[468758] = {name = "Специализация на исцелении", additional_info = "[q]Усиливает исцеление от заклинаний и эффектов максимум на 26 ед. Эффект не суммируется с эффектами других рун для колец."},
[468761] = {name = "Гравировка кольца – специализация на исцелении", additional_info = "Применение: 3 сек\nТребуется: Кольцо\n[q]Выгравировать на кольце руну \"Специализация на исцелении\":\n\n\nУсиливает исцеление от заклинаний и эффектов максимум на 26 ед. Эффект не суммируется с эффектами других рун для колец."},
[468762] = {name = "Специализация на медитации", additional_info = "[q]Восполняет 5 ед. маны каждые 5 сек. Эффект не суммируется с эффектами других рун для колец."},
[468763] = {name = "Гравировка кольца – специализация на медитации", additional_info = "Применение: 3 сек\nТребуется: Кольцо\n[q]Выгравировать на кольце руну \"Специализация на медитации\":\n\n\nВосполняет 5 ед. маны каждые 5 сек. Эффект не суммируется с эффектами других рун для колец."},
[468764] = {name = "Гибридный бонус к исцелению и урону от заклинаний 55/19", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 55/19\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 55 ед., а наносимый ими урон – максимум на 19 ед."},
[468766] = {name = "Сотворение воды", additional_info = "Мана: 845\nПрименение: 3 сек\n[q]Создает 20 бутыли:бутылей воды из горного источника, чтобы обеспечить себя и союзников питьем.\n\n Сотворенные предметы исчезают, если выйти из игры более чем на 15 минут."},
[468767] = {name = "Питье", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 5100 ед. маны за 30 сек. Действие эффекта прерывается, если персонаж встает с места."},
