[469208] = {name = "Дар земли", additional_info = "Мгновенное действие\n[q]Вероятность критического удара повышается на 1%."},
[469209] = {name = "Дар огня", additional_info = "Мгновенное действие\n[q]Урон от заклинаний увеличивается максимум на 16 ед."},
[469210] = {name = "Дар воды", additional_info = "Мгновенное действие\n[q]Творимое исцеление усиливается максимум на 31 ед."},
[469211] = {name = "Коса Хаоса", additional_info = "[q]Нанося урон заклинаниями прямого действия, вы с некоторой вероятностью получаете возможность призвать следующего прислужника мгновенно и без затрат осколков душ. Время действия – 20 сек.\n(Вероятность срабатывания: 10%, Восстановление: 1мин)"},
[469220] = {name = "Коса Хаоса", additional_info = "Мгновенное действие\n[q]Сокращает время призыва следующего беса, демона Бездны, суккуба, инкуба, охотника Скверны или стража Скверны на 10 сек. и позволяет сделать это без затрат маны и осколков душ."},
[469221] = {name = "Демоническая жатва", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Вы поглощаете душу призванного вами демона и получаете усиление на 15 сек. Эффект снимается, если вы призываете демона."},
[469222] = {name = "Бесовский восторг", additional_info = nil},
[469223] = {name = "Гибридный бонус к исцелению и урону от заклинаний 42/22", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 42/22\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 42 ед., а наносимый ими урон – максимум на 22 ед."},
[469224] = {name = "Путь Бездны", additional_info = nil},
[469225] = {name = "Соблазн теней", additional_info = nil},
[469227] = {name = "Добыча Скверны", additional_info = nil},
[469228] = {name = "Добыча Скверны", additional_info = "{Мана: 200} {Радиус действия: 100 м}\nМгновенное действие\n[q]Вызывает у противника немоту на 3 сек., а также прерывает применение заклинаний и лишает цель возможности применять заклинания соответствующей школы на 6 сек."},
[469229] = {name = "Охотник Хаоса", additional_info = "Мгновенное действие\n[q]Следующее \"Проклятие косноязычия\" вызывает у противника немоту на 3 сек., а также прерывает применение заклинаний и лишает цель возможности применять заклинания соответствующей школы на 6 сек."},
[469230] = {name = "Окрыление Скверны", additional_info = "Мгновенное действие\n[q]Получаемый физический урон уменьшается на 25%. \"Демонический прыжок\" можно применять в бою, и эта способность не требует времени на восстановление."},
[469231] = {name = "Получение свитка: ЦИБУСЯНТАС АЛЬД", additional_info = nil},
[469236] = {name = "Посох порядка", additional_info = "[q]Каждый раз, когда вы наносите урон от тайной магии, время восстановления \"Величия разума\" сокращается на 1 сек."},
[469237] = {name = "Посох адского пламени", additional_info = "Неограниченное расстояние\n[q]Если изучен талант \"Улучшенный ожог\", \"Взрывная волна\" также применяет к пораженным целям 5 эффекта:эффектов \"Уязвимость к огню\"."},
[469238] = {name = "Посох инея", additional_info = "Неограниченное расстояние\n[q]Пока действует \"Ледяная преграда\", урон от эффектов и заклинаний магии льда увеличивается максимум на 100 ед."},
[469239] = {name = "Под защитой льда", additional_info = nil},
