[469262] = {name = "Гоблинофикация", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Активируйте в логове Крыла Тьмы или в Черной горе, чтобы замаскироваться под техника из логова Крыла Тьмы."},
[469266] = {name = "Призыв Миштольда", additional_info = nil},
[469271] = {name = "Астральный облик", additional_info = "Мгновенное действие\n[q]Вы настраиваетесь на небесную энергию, заменяя облик лунного совуха на более возвышенный."},
[469277] = {name = "Приручение зверя", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Начинает приручение животного, которое может стать вашим питомцем. Ваша броня ослабевает на 0% на до отмены., пока вы заняты приручением. Если вы теряете внимание животного по какой-либо причине, процесс приручения прерывается. Только что укрощенное животное недовольно и хочет сбежать. Постарайтесь его сразу же накормить, чтобы оно повеселело."},
[469301] = {name = "Приручение зверя", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Начинает приручение животного, которое может стать вашим питомцем. Ваша броня ослабевает на 0% на до отмены., пока вы заняты приручением. Если вы теряете внимание животного по какой-либо причине, процесс приручения прерывается. Только что укрощенное животное недовольно и хочет сбежать. Постарайтесь его сразу же накормить, чтобы оно повеселело."},
[469306] = {name = "Приручение зверя", additional_info = "Радиус действия: 30 м\nПрименение: 3 сек\n[q]Начинает приручение животного, которое может стать вашим питомцем. Ваша броня ослабевает на 0% на до отмены., пока вы заняты приручением. Если вы теряете внимание животного по какой-либо причине, процесс приручения прерывается. Только что укрощенное животное недовольно и хочет сбежать. Постарайтесь его сразу же накормить, чтобы оно повеселело."},
[469320] = {name = "Выброс лавы", additional_info = "{10% от базовой мана} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Вы бросаете в противника раскаленную лаву, наносящую [875 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]-[1125 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] ед. урона от огня. Если цель находится под действием эффекта \"Огненный шок\", \"Выброс лавы\" наносит критический удар."},
[469348] = {name = "Невосприимчивость к разоружению", additional_info = "[q]Невосприимчивость к разоружению."},
[469357] = {name = "Обжигающий жар", additional_info = "Мгновенное действие\n[q]Обжигает ближайших противников, нанося им [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] ед. урона каждый раз, когда вас атакуют в ближнем бою. Срабатывает не чаще раза в секунду. Уменьшает получаемый магический урон на 1% и увеличивает наносимый урон от огня на 1%. Время действия – до отмены.\n(Восстановление: 1с)"},
[469370] = {name = "Огненная стрела", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Наносит цели 157 ед. урона от огня."},
[469371] = {name = "Водяная стрела", additional_info = "Радиус действия: 45 м\nМгновенное действие\n[q]Выпускает в противника ледяную стрелу, наносящую [131 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)]-[169 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] ед. урона от магии льда."},
[469372] = {name = "Молния", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Поражает противника молнией, наносящей 152 ед. урона от сил природы."},
[469410] = {name = "Гибридный бонус к исцелению и урону от заклинаний 84/28", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 84/28\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 84 ед., а наносимый ими урон – максимум на 28 ед."},
[469414] = {name = "Гибридный бонус к исцелению и урону от заклинаний 70/24", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 70/24\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 70 ед., а наносимый ими урон – максимум на 24 ед."},
[469433] = {name = "Ядовитая стрела", additional_info = "Радиус действия: 10 - 40 м\nМгновенное действие\n[q]Выпускает в цель ядовитый снаряд, наносящий урон от сил природы сразу и дополнительный урон раз в 2 сек. в течение 6 сек."},
[469463] = {name = "Призыв", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Телепортирует 0 противников:противников к себе."},
[469481] = {name = "Гибридный бонус к исцелению и урону от заклинаний 48/16", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 48/16\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 48 ед., а наносимый ими урон – максимум на 16 ед."},
[469493] = {name = "Гибридный бонус к исцелению и урону от заклинаний 90/30", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 90/30\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 90 ед., а наносимый ими урон – максимум на 30 ед."},
