[470104] = {name = "Тотем огня и бури", additional_info = "[q]Пока у вас выгравирована руна \"Громовые раскаты\", \"Выброс лавы\" с вероятностью 0% увеличивает количество зарядов действующего \"Щита молний\" на 1."},
[470105] = {name = "Тотем стихий", additional_info = nil},
[470108] = {name = "Окаменение", additional_info = "Мгновенное действие\nИнгредиенты:\nНастой окаменения\n[q]Вы превращаетесь в камень, защищающий от всех физических атак и заклинаний на 1 мин., но в это время вы не можете атаковать, двигаться или применять заклинания. Одновременно может действовать только один эффект настоя."},
[470117] = {name = "Призыв", additional_info = nil},
[470124] = {name = "DNT", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Карает противника, нанося урон от светлой магии."},
[470235] = {name = "Тотем астрального потока", additional_info = "[q]Увеличивает дополнительную силу атаки от \"Оружия неистовства ветра\" на 68 ед."},
[470240] = {name = "Тотем проводящих потоков", additional_info = "[q]Пока \"Оружие ледяного клейма\" действует на оружие в правой руке, при каждом срабатывании \"Водного щита\" время применения следующей \"Цепной молнии\", использованной в течение 15 сек., сокращается на 20%, а урон от нее увеличивается на 20%. Суммируется до 5 раз."},
[470246] = {name = "Манускрипт гнева", additional_info = "[q]Нанося целям урон, \"Шок небес\" сокращает время применения и затраты маны на следующий \"Гнев небес\" в течение 15 сек. на 20% и увеличивает его урон на 20%. Эффект суммируется до 5 раз."},
[470263] = {name = "Манускрипт возмездия", additional_info = "[q]\"Щит мстителя\" поражает на 2 цели:целей меньше, но наносит цели урон 2 раза:раз."},
[470264] = {name = "Щит мстителя", additional_info = nil},
[470265] = {name = "Щит мстителя", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Бросает в противника священный щит, наносящий от [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] до [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Сила заклинаний + 0.091 * Сила атаки] ед. урона от светлой магии и вызывающий головокружение. Щит затем перескакивает на других находящихся поблизости противников. Максимальное количество целей – 1. Время действия – 5 сек."},
[470266] = {name = "Усиленное исцеление от \"Покровительства природы\"", additional_info = "[q]Усиливает исцеление от \"Покровительства природы\" максимум на 77 ед."},
[470269] = {name = "Идол безжалостности", additional_info = "[q]Увеличивает изначальный и периодический урон от каждого эффекта способности \"Растерзать\" на 7 ед."},
[470270] = {name = "Идол кошачьей концентрации", additional_info = nil},
[470271] = {name = "Манускрипт гнева", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -19%:\nГнев небес , Гнев небес\n\nModifies Power Cost -19%:\nГнев небес , Гнев небес\n\nModifies Damage/Healing Done +21%:\nГнев небес , Гнев небес"},
[470272] = {name = "Тотем проводящих потоков", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -19%:\nЦепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния\n\nModifies Damage/Healing Done +21%:\nЦепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния , Цепная молния"},
[470279] = {name = "Демоническая эгида", additional_info = nil},
[470280] = {name = "Теневой удар", additional_info = "{Применение: 4 сек} {Восстановление: 2 сек}\n[q]Наносит противникам в секторе радиусом 45 м перед собой 4500 ед. урона от темной магии, распределяемого между целями."},
[470317] = {name = "DNT", additional_info = nil},
[470345] = {name = "Первая помощь", additional_info = "Радиус действия: 15 м\nНаправляемое (Применение: 8 сек)\n[q]Восполняет 3400 ед. здоровья за 8 сек."},
[470348] = {name = "Крепкие бинты из рунической ткани", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению крепких бинтов из рунической ткани."},
[470349] = {name = "Крепкие бинты из рунической ткани", additional_info = "Применение: 3 сек\nИнгредиенты:\nПлотные бинты из рунной ткани (2)\nТребуется\nТребуетПервая помощь\n(300)\n[q2]Использование: Восполняет 3400 ед. здоровья за 8 сек."},
[470358] = {name = "Рецепт: суп из темноклешневых омаров", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает приготовлению супа из темноклешневых омаров."},
[470359] = {name = "Суп из темноклешневых омаров", additional_info = "Применение: 3 сек\nИнгредиенты:\nТемноклешневый омар , Пригодная для питья святая вода Стратхольма\nТребуется\n[q2]Использование: Восполняет 2148 ед. здоровья за 30 сек. Действие эффекта прерывается, если персонаж встает с места. По истечении 10 сек. увеличивает урон от заклинаний на 12 ед. на 10 мин."},
[470361] = {name = "Увеличение урона от заклинаний", additional_info = "Мгновенное действие\n[q]Увеличивает урон от заклинаний на 12 ед. на 10 мин."},
[470362] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 2148 ед. здоровья за 30 сек. Действие эффекта прерывается, если персонаж встает с места. По истечении 10 сек. увеличивает урон от заклинаний на 12 ед. на 10 мин."},
[470367] = {name = "Увеличение силы исцеления", additional_info = "Мгновенное действие\n[q]Увеличивает силу исцеления на 22 на 10 мин."},
[470369] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 1392 ед. здоровья за 30 сек. Действие эффекта прерывается, если персонаж встает с места. По истечении 10 сек. повышает силу исцеления на 22 ед. на 10 мин."},
[470370] = {name = "Копченая краснобородка", additional_info = "Применение: 3 сек\nИнгредиенты:\nСырая краснобородка\nТребуется\n[q2]Использование: Восполняет 1392 ед. здоровья за 30 сек. Действие эффекта прерывается, если персонаж встает с места. По истечении 10 сек. повышает силу исцеления на 22 ед. на 10 мин."},
