[470462] = {name = "Связующая тень", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Выпускает в случайного игрока темные сферы, которые затем возвращаются к источнику. Пораженные игроки получают 340 в 460 ед. урона от темной магии."},
