[470497] = {name = "Воспользоваться слабостью", additional_info = "Дистанция ближнего боя\n{Применение: 2.5 сек} {Восстановление: 10 сек}\n[q]Отрезает чешуйку от шкуры Нефариана. Можно применить, только если Нефариан серьезно ослаб в бою."},
[470535] = {name = "Выпад Пустоты", additional_info = "Радиус действия: 15 м\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Наносит противнику 250% урона от оружия и оставляет на его теле серьезную рану, снижающую эффективность любого исцеления на 25% на 5 сек."},
[470537] = {name = "[q3]Воспользоваться слабостью", additional_info = "{Мгновенное действие} {Восстановление: 10 сек}\n[q]Отрезает чешуйку от шкуры Нефариана. Можно применить, только если Нефариан серьезно ослаб в бою."},
