[471400] = {name = "Чудесная тролльская полироль", additional_info = "Применение: 5 сек\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nНастой колдунства (3), Настой большого колдунства (3), Большой сверкающий осколок (2), Укрепленная колба\n[q]Создает чудесную тролльскую полироль.\nТребуется\n[q2]Использование: Применяется к щиту и увеличивает урон и силу исцеления заклинаний максимум на 36 ед., а также повышает вероятность критического эффекта заклинаний на 1%. Время действия – 30 мин.\n5 зарядов"},
[471401] = {name = "Чудесная тролльская полироль", additional_info = "Применение: 3 сек\nТребуется: Оружие\n[q]Применяется к щиту и увеличивает урон и силу исцеления заклинаний максимум на 36 ед., а также повышает вероятность критического эффекта заклинаний на 1%. Время действия – 30 мин."},
[471402] = {name = "Урон от заклинаний +36 и критический удар +1%", additional_info = "[q]Увеличивает урон и силу исцеления магических заклинаний и эффектов максимум на 36 ед. Также повышает вероятность критического эффекта заклинаний на 1%."},
[471487] = {name = "Сапсан", additional_info = nil},
[471698] = {name = "Душа демона", additional_info = "Мгновенное действие\n[q]Вы настраиваетесь на внутреннюю тьму, что позволяет лучше контролировать внутреннего демона."},
[471699] = {name = "Зила Аманемодас", additional_info = "Мгновенное действие\n[q]Вы настраиваетесь на внутреннюю тьму, что позволяет лучше контролировать внутреннего демона."},
