[472686] = {name = "Побег драгоценного скарабея", additional_info = nil},
[472692] = {name = "Побег!", additional_info = nil},
[472709] = {name = "Звук побега", additional_info = nil},
[472717] = {name = "Появление драгоценного скарабея", additional_info = nil},
[472870] = {name = "Шквал", additional_info = nil},
[472891] = {name = "Гоблинофикация", additional_info = nil},
[473384] = {name = "Призыв оруженосца", additional_info = "Дистанция ближнего боя\nПрименение: 1 сек\n[q]Использовать руководство и призвать оруженосца Серебряного Рассвета, чтобы научить его сражаться с силитидами. Когда вы убиваете силитидов вместе с оруженосцем, ваша репутация у Серебряного Рассвета повышается."},
[473387] = {name = "Рог Рассвета", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ободряет находящихся рядом участников группы или рейда, повышая вероятность критического эффекта заклинаний на 10%, вероятность критического удара атак ближнего и дальнего боя – на 5%, а силу атаки – на 140. Время действия – 2 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[473399] = {name = "Колыбельная песнецвета", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Призывает песнецвет, усиливающий участников группы или рейда и повышающий вероятность критического удара атак ближнего и дальнего боя, а также заклинаний на 5%. Кроме того, повышает характеристики на 15. Время действия – 1 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[473403] = {name = "Благословение Нептулона", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Усиливает находящихся рядом участников группы или рейда, повышая силу атаки на 200, выносливость – на 15%, а вероятность критического эффекта заклинаний – на 3% на 2 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[473441] = {name = "Мощь Черной горы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличивает запас здоровья на 300 ед., повышает скорость атак ближнего боя на 15% и восполняет 10 ед. маны каждые 5 сек."},
[473450] = {name = "Темный жребий урона", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличивает урон, наносимый участниками группы или рейда, на 10% на 2 ч."},
[473466] = {name = "Котел с огненной водой", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Призывает котел с огненной водой на 10 мин. Участники группы или рейда могут использовать котел, чтобы повысить силу атаки ближнего боя на 35 и увеличиться в размере на 1 ч."},
[473469] = {name = "Очищенная огненная вода", additional_info = "Мгновенное действие\n[q]Повышает силу атаки ближнего боя на 35 и увеличивает размер на 1 ч."},
[473476] = {name = "Сны о Зандаларе", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышает скорость передвижения участников группы или рейда на 10%, а их характеристики — на 15% на 2 ч."},
