[473482] = {name = "Распад духов стихий", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Ослабляет элементалей из Совета Бездны в Силитусе, уменьшая наносимый ими урон на 20% на 2 мин."},
