[473900] = {name = "Призыв прирученного силитида-танка", additional_info = "Применение: 3 сек\n[q]Издает высокочастотный звук, побуждающий силитида-танка выкопаться из норы под храмом Ан'Киража. Силитид подчиняется призвавшему игроку и может служить транспортом в храме Ан'Киража. Когда наездника атакуют, танк снова прячется под землю."},
[474116] = {name = "Амулет защиты от птиц", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\n[q]Поглощает 1906 в 2374 ед. урона от сил природы. Время действия – 15 сек."},
[474126] = {name = "Погружение", additional_info = "Мгновенное действие\n[q]Увеличивает урон от эффектов и заклинаний максимум на 40 ед."},
[474127] = {name = "Погружение", additional_info = "[q]Когда ваши заклинания природы наносят непериодический критический урон, ваш урон от заклинаний с некоторой вероятностью увеличивается на 40 ед. на 10 сек.\n(Вероятность срабатывания: 50%, Восстановление: 5с)"},
[474142] = {name = "Рой мыслей", additional_info = "[q]Заклинания, наносящие непериодический урон, увеличивают ваш урон от заклинаний на 15 ед. на 15 сек. Если цель находится под контролем игрока, вместо этого проникающая способность ваших заклинаний повышается на 100 на 15 сек.\n(Восстановление: 15с)"},
[474146] = {name = "Рой мыслей", additional_info = "Мгновенное действие\n[q]Ваши заклинания делают цели уязвимыми, снижая сопротивление всем видам магии на 100."},
[474148] = {name = "Рой мыслей", additional_info = "Мгновенное действие\n[q]Увеличивает урон от эффектов и заклинаний максимум на 15 ед."},
