[474386] = {name = "PvP-аксессуар", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Снимает эффекты, затрудняющие передвижение и вызывающие потерю контроля над персонажем."},
[474400] = {name = "Насылание безумия", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Временно сводит цель с ума, повышая скорость атаки на 50% и скорость передвижения – на 80%, а также уменьшая получаемый целью урон на 90% на 6 сек. В состоянии безумия цель атакует своих союзников."},
