[1213234] = {name = "Перешивка", additional_info = "Мгновенное действие\n[q]Ненадолго перестраивает материю вашего тела, мгновенно снимая с вас все эффекты яда, а также давая вам невосприимчивость к урону от сил природы на 3 сек."},
