[1213268] = {name = "Метка охотника", additional_info = "{Мана: 60} {Радиус действия: 100 м}\nМгновенное действие\n[q]Сила всех атак дальнего боя, направленных против отмеченной охотником цели, повышается на 110. Кроме того, охотник всегда видит отмеченного противника, даже если тот находится в состоянии незаметности или невидим, и может следить за ним по мини-карте. Время действия – 2 мин."},
[1213269] = {name = "Разрывной выстрел", additional_info = "Радиус действия: 5 - 30 м\nПрименение: 1 сек\n[q]Наносит урон от оружия и дополнительно 100 ед. урона от огня противнику и находящимся рядом целям."},
[1213271] = {name = "Обжигающая ловушка", additional_info = "Мана: 245\n{Мгновенное действие} {Восстановление: 15 сек}\n[q]Размещает огненную ловушку, которая наносит первому приблизившемуся к ней противнику 690 ед. урона от огня за 15 сек. Время существования ловушки – 1 мин. Размещать ловушки можно только вне битвы. Единовременно может быть активна только одна ловушка."},
[1213272] = {name = "Выстрел", additional_info = "Радиус действия: 5 - 30 м\nМгновенное действие\nТребуется: Оружие дальнего боя\n[q]Выстрел, наносящий противнику физический урон."},
[1213276] = {name = "Ледяная стрела", additional_info = "{Мана: 90} {Радиус действия: 40 м}\nПрименение: 3 сек\n[q]Наносит противнику урон от магии льда и снижает скорость его передвижения на 4 сек."},
[1213278] = {name = "Ледяная преграда", additional_info = "Мана: 480\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Вас мгновенно окружает защитный барьер, поглощающий 826 ед. урона. Время действия – 1 мин. Все время существования щита ваши заклинания невозможно прервать."},
[1213279] = {name = "Снежная буря", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Вызывает снежную бурю, которая длится 10 сек., нанося 4 ед. урона от магии льда раз в 2 сек. противникам в указанной области."},
[1213288] = {name = "Повышение мастерства 1", additional_info = "[q]Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 1%."},
[1213289] = {name = "Повышение мастерства 2", additional_info = "[q]Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 2%."},
[1213290] = {name = "Повышение мастерства 3", additional_info = "[q]Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 3%."},
[1213297] = {name = "Жетон Стража Роя", additional_info = "Направляемое (Применение: 6 сек)\n[q]Обратиться к силе Стража Роя и обрушить на находящихся поблизости противников вихрь клинков. Время действия – 6 сек."},
[1213298] = {name = "Свет небес", additional_info = "{Мана: 150} {Радиус действия: 40 м}\nПрименение: 2.5 сек\n[q]Призывает силы света и исцеляет союзника."},
[1213300] = {name = "Божественная защита", additional_info = "Мана: 35\nМгновенное действие\n[q]Защищает от всех атак и заклинаний на 8 сек., но лишает возможности атаковать и применять заклинания в течение этого времени."},
[1213301] = {name = "Молот правосудия", additional_info = "{Мана: 50} {Радиус действия: 10 м}\nМгновенное действие\n[q]Оглушает противника, не позволяя передвигаться и атаковать в течение 4 сек."},
[1213304] = {name = "Вихрь", additional_info = nil},
[1213306] = {name = "S03 – предмет – TAQ – охотник – бонус дальнего боя за 2 предмета", additional_info = "[q]\"Убийственный выстрел\" наносит целям, не контролируемым игроками, на 10% больше урона."},
[1213307] = {name = "S03 – предмет – TAQ – охотник – бонус ближнего боя за 2 предмета", additional_info = "[q]Увеличивает периодический урон от \"Удара виверны\" на 50%, а максимальный запас концентрации питомца – на 50 ед."},
[1213309] = {name = "S03 – предмет – TAQ – охотник – бонус ближнего боя за 4 предмета", additional_info = "[q]Увеличивает мгновенный урон от \"Укуса мангуста\" и всех способностей-ударов или бросков на 20%."},
[1213310] = {name = "S03 – предмет – RAQ – охотник – бонус \"Повелителя зверей\" за 3 предмета", additional_info = "[q]Ускоряет восстановления тонуса ваших питомцев на 100%."},
[1213312] = {name = "S03 – предмет – TAQ – маг – бонус \"Тайной магии\" за 2 предмета", additional_info = "[q]\"Чародейская вспышка\" увеличивает наносимый урон еще на 10% за каждый эффект."},
[1213314] = {name = "S03 – предмет – TAQ – маг – бонус \"Тайной магии\" за 4 предмета", additional_info = "[q]\"Щит маны\", \"Защита от огня\" и \"Защита от магии льда\" поглощают на 50% больше урона и размещают рядом с целью темпоральный маяк. Время действия – 30 сек."},
[1213317] = {name = "Огненный взрыв", additional_info = "Мгновенное действие\n[q]Modifies Critical Strike Chance +51:\nВзрывная волна , Взрывная волна , Взрывная волна , Взрывная волна , Взрывная волна , Живая бомба , Живой жар , Живой жар , Огненная глыба , Огненная глыба , Огненная глыба , Огненная глыба , Огненная глыба , Огненная глыба , Огненная глыба , Огненная глыба , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный взрыв , Огненный столб , Огненный столб , Огненный столб , Огненный столб , Огненный столб , Огненный столб , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Огненный шар , Ожог , Ожог , Ожог , Ожог , Ожог , Ожог , Ожог , Стрела гибельного огня , Стрела ледяного огня"},
[1213318] = {name = "S03 – предмет – TAQ – маг – бонус \"Огня\" за 2 предмета", additional_info = "[q]\"Огненный взрыв\" теперь также повышает вероятность критического удара следующего заклинания школы огня на 50% на 10 сек."},
[1213319] = {name = "S03 – предмет – TAQ – маг – бонус \"Огня\" за 4 предмета", additional_info = "[q]Увеличивает урон от таланта \"Воспламенение\" на 10%."},
[1213321] = {name = "S03 – предмет – RAQ – маг – бонус \"Огня\" за 3 предмета", additional_info = "[q]Урон от \"Огненного шара\", \"Стрелы ледяного огня\" и \"Стрелы гибельного огня\" увеличивается на 4% за каждый эффект огня, действующий на цель. Максимальная прибавка – 12%."},
[1213331] = {name = "Сожжение маны", additional_info = "{Мана: 95} {Радиус действия: 30 м}\nПрименение: 3 сек\n[q]Поражает противника молнией, сжигающей ману. За каждую единицу маны, сожженную молнией, жертва получает 0.5 ед. урона."},
[1213332] = {name = "Контроль над разумом", additional_info = "Радиус действия: 20 м\nПрименение: 2 сек\n[q]Подчиняет противника-гуманоида 60-го уровня и ниже на 15 сек."},
[1213334] = {name = "Облик Тьмы", additional_info = "40% от базовой мана\nМгновенное действие\n[q]Позволяет принять облик Тьмы, увеличивающий наносимый урон от темной магии на 20% и уменьшающий получаемый в ближнем бою урон на 20%. Облик Тьмы сохраняется до отмены."},
[1213335] = {name = "Земляной покров", additional_info = "Мгновенное действие\n[q]Вы зарываетесь под землю на 10 сек. В это время вас нельзя выбрать целью."},
[1213336] = {name = "Взрыв разума", additional_info = "{Мана: 30} {Радиус действия: 30 м}\nПрименение: 1.5 сек\n[q]Наносит противнику урон от темной магии, создавая высокий уровень угрозы."},
[1213342] = {name = "Temp MC test", additional_info = nil},
[1213349] = {name = "S03 – предмет – TAQ – паладин – бонус \"Света\" за 2 предмета", additional_info = "[q]Сокращает время восстановления \"Божественного света\" на 25%."},
[1213353] = {name = "S03 – предмет – TAQ – паладин – бонус \"Света\" за 4 предмета", additional_info = "[q]Когда \"Частица Света\" исцеляет цель, находящийся поблизости раненый союзник получает 90% этого исцеления."},
[1213355] = {name = "Шок", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Удар молнии, мгновенно наносящий 339 в 377 ед. урона от сил природы."},
[1213356] = {name = "Господство над разумом", additional_info = "Радиус действия: 20 м\nПрименение: 2 сек\n[q]Подчиняет противника-гуманоида не выше 25-го уровня на 5 сек., но увеличивает интервал между его атаками на 100%."},
[1213366] = {name = "Джом Габбар", additional_info = "Мгновенное действие\n[q]Повышает силу атаки на 70 сразу и дополнительно на 70 раз в 2 сек. Время действия – 20 сек."},
[1213367] = {name = "Джом Габбар", additional_info = nil},
[1213375] = {name = "Панцирь копателя", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\n[q]Поглощает 1200 ед. урона. Время действия – 20 сек."},
[1213377] = {name = "Спутник идеала", additional_info = nil},
[1213381] = {name = "Испытанный временем удар", additional_info = nil},
[1213390] = {name = "Испытанный временем удар", additional_info = "[q]Каждый использующийся потрепанный временем предмет снаряжения на 1% повышает вероятность нанести дополнительный удар при атаке ближнего или дальнего боя.\n(Вероятность срабатывания: 8%, Восстановление: 200мс)"},
[1213393] = {name = "Испытанный временем выстрел", additional_info = nil},
[1213395] = {name = "Испытанный временем выстрел", additional_info = "(Вероятность срабатывания: 8%, Восстановление: 200мс)"},
[1213397] = {name = "S03 – предмет – TAQ – паладин – бонус \"Воздаяния\" за 2 предмета", additional_info = "[q]Увеличивает урон от \"Удара воина Света\" на 150%."},
[1213398] = {name = "Испытанное временем заклинание", additional_info = "[q]Повышает скорость применения заклинаний на 2% за каждый использующийся потрепанный временем предмет снаряжения."},
[1213405] = {name = "Испытанное временем исцеление", additional_info = "[q]Повышает эффективность исцеляющих и создающих барьер заклинаний на 2% за каждый использующийся потрепанный временем предмет снаряжения."},
[1213406] = {name = "S03 – предмет – TAQ – паладин – бонус \"Воздаяния\" за 4 предмета", additional_info = "[q]Автоатаки двуручным оружием ближнего боя на 20 сек. увеличивают урон от следующего \"Экзорцизма\" на 35%. Эффект суммируется до 3 раз."},
[1213407] = {name = "Испытанное временем мастерство", additional_info = "[q]Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 1% за каждый использующийся потрепанный временем предмет снаряжения."},
[1213408] = {name = "Благословение королей", additional_info = nil},
[1213410] = {name = "S03 – предмет – TAQ – паладин – бонус \"Защиты\" за 2 предмета", additional_info = "[q]При применении к себе \"Благословение неприкосновенности\" также повышает все характеристики на 10%."},
[1213411] = {name = "Круговерть Пустоты", additional_info = "[q]С вероятностью 100% воскрешает носителя с 20% здоровья и маны. (Время восстановления –3 мин.)"},
[1213412] = {name = "Круговерть Пустоты", additional_info = nil},
[1213413] = {name = "S03 – предмет – TAQ – паладин – бонус \"Защиты\" за 4 предмета", additional_info = "[q]\"Щит праведности\" усиливает следующий \"Свет небес\", в результате чего он применяется мгновенно. При применении к себе \"Свет небес\" возвращает ману в размере 100% затрат на применение и не взаимодействует с эффектом \"Под охраной света\"."},
[1213414] = {name = "Круговерть Пустоты", additional_info = nil},
[1213415] = {name = "Защита праведности", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -99%:\nСвет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес"},
[1213417] = {name = "Поражение молнией", additional_info = "[q]С некоторой вероятностью поражает цель в ближнем бою молнией, наносящей 317 в 517 ед. урона от сил природы."},
[1213418] = {name = "Поражение молнией", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Удар молнии, наносящий 317 в 517 ед. урона от сил природы."},
[1213419] = {name = "Героизм", additional_info = "[q]Когда носитель наносит противнику урон в ближнем бою, время от времени восполняют носителю 170 в 230 ед. здоровья."},
[1213420] = {name = "Героизм", additional_info = "Мгновенное действие\n[q]Атаки время от времени восполняют носителю 170 в 230 ед. здоровья."},
[1213421] = {name = "Аура синего дракона", additional_info = "[q]После каждого успешного заклинания вы с вероятностью 5% восполняете ману во время применения со скоростью, равной 100% обычной, в течение 15 сек.\n(Вероятность срабатывания: 5%)"},
[1213422] = {name = "Аура синего дракона", additional_info = "Мгновенное действие\n[q]После каждого успешного заклинания вы с вероятностью 5% восполняете ману во время применения со скоростью, равной 100% обычной, в течение 15 сек."},
[1213441] = {name = "Коварный удар", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Наносит противнику обычный урон, усиленный на 1 ед."},
[1213442] = {name = "Гаррота", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит противнику 36 ед. урона раз в 3 сек. в течение 18 сек. при нападении из состояния незаметности."},
[1213450] = {name = "Порча", additional_info = "Радиус действия: 30 м\nПрименение: 2 сек\n[q]Наносит находящимся рядом противникам урон от темной магии раз в 3 сек. в течение 24 сек."},
[1213451] = {name = "Огненный ливень", additional_info = "{Мана: 15} {Радиус действия: 30 м}\nНаправляемое (Применение: 9 сек)\n[q]Вызывает огненный ливень, который наносит противникам в выбранной области 3 ед. урона от огня раз в 3 сек. в течение 9 сек."},
[1213452] = {name = "Страх", additional_info = "Радиус действия: 20 м\nПрименение: 1.5 сек\n[q]Повергает противника в ужас и обращает в бегство на 4 сек. Максимум целей – 1."},
[1213461] = {name = "Защита праведности", additional_info = nil},
[1213462] = {name = "Сокрушение щитом", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Щит\n[q]Наносит противнику 20 ед. урона и оглушает его на 2 сек."},
[1213463] = {name = "Рывок", additional_info = "Радиус действия: 8 - 25 м\nМгновенное действие\n[q]Совершает рывок к противнику, нанося обычный урон и еще 0 ед. урона, а также оглушая цель на до отмены."},
[1213464] = {name = "Раскат грома", additional_info = "Мгновенное действие\n[q]Наносит 24 в 26 ед. урона от сил природы находящимся рядом противникам, увеличивает время между их атаками на 33% и снижает скорость передвижения на 40% на 10 сек."},
[1213465] = {name = "Устрашающий крик", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Парализует цель ужасом на 8 сек. и обращает остальных находящихся рядом противников в бегство."},
[1213466] = {name = "Волк Иглогривых", additional_info = "Мгновенное действие\n[q]Призывает 1 волка Иглогривых в спутники к заклинателю."},
[1213467] = {name = "S03 – предмет – RAQ – паладин – бонус \"Воздаяния\" за 3 предмета", additional_info = "[q]Пока вы используете одноручное оружие, \"Удар воина Света\" применяет эффекты печатей, вызываемые \"Правосудием\". При этом печать не поглощается."},
[1213477] = {name = "Цепная молния", additional_info = "{Мана: 150} {Радиус действия: 30 м}\n{Применение: 3 сек} {Восстановление: 6 сек}\n[q]Поражает противника молнией, которая переходит на другого находящегося рядом противника. Поражает до 3 целей, нанося каждой из них возрастающий урон от сил природы."},
[1213478] = {name = "Чертеж: наголовник бритвенных шипов", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению наголовника бритвенных шипов."},
[1213479] = {name = "Щит молний", additional_info = "{Мана: 5} {Радиус действия: 30 м}\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Окружает себя 3 шаровыми молниями, которые с вероятностью 50% наносят 2 ед. урона противникам, атакующим в ближнем или дальнем бою. При каждом срабатывании одна молния рассеивается. Щит перестает действовать через 10 мин. либо после 3 срабатываний.\n(Вероятность срабатывания: 50%)"},
[1213480] = {name = "Тотем оков земли", additional_info = "Мана: 40\nМгновенное действие\nИнструменты: Тотем земли\n[q]Создает тотем оков земли, который существует 45 сек. и периодически снижает скорость передвижения находящихся рядом противников до 50% обычной."},
[1213481] = {name = "[q4]Наголовник бритвенных шипов", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (15), Насыщенный обсидианом ториевый слиток (3), Зачарованная кожа (4), Гибельный коготь (10), Чудовищный силитидский хитин (4)\n[q4]Наголовник бритвенных шипов\nСтановится персональным при надевании\nГолова Латы\nБроня: 722\n+14 к силе\n+40 к выносливости\nПрочность: 100 / 100\nТребуется\n[q2]Если на персонаже: Когда вы получаете урон в бою, наносит атакующему 100 ед. урона от сил природы. Создает угрозу в объеме удвоенного нанесенного урона.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 9 ед."},
[1213482] = {name = "Огненный шок", additional_info = "{Мана: 110} {Радиус действия: 20 м}\nМгновенное действие\n[q]Поджигает противника и наносит ему дополнительный урон от огня раз в 3 сек. в течение 12 сек."},
[1213483] = {name = "Чертеж: латные наплечники бритвенных шипов", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению латных наплечников бритвенных шипов."},
[1213484] = {name = "[q4]Латные наплечники бритвенных шипов", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (15), Насыщенный обсидианом ториевый слиток (3), Зачарованная кожа (4), Гибельный коготь (10), Чудовищный силитидский хитин (4)\n[q4]Латные наплечники бритвенных шипов\nСтановится персональным при надевании\nПлечо Латы\nБроня: 667\n+11 к силе\n+29 к выносливости\nПрочность: 100 / 100\nТребуется\n[q2]Если на персонаже: Когда вы получаете урон в бою, наносит атакующему 80 ед. урона от сил природы. Создает угрозу в объеме удвоенного нанесенного урона.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 7 ед."},
[1213489] = {name = "Чертеж: боевой доспех бритвенных шипов", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению боевого доспеха бритвенных шипов."},
[1213490] = {name = "[q4]Боевой доспех бритвенных шипов", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (20), Насыщенный обсидианом ториевый слиток (4), Зачарованная кожа (4), Гибельный коготь (10), Чудовищный силитидский хитин (8)\n[q4]Боевой доспех бритвенных шипов\nСтановится персональным при надевании\nГрудь Латы\nБроня: 889\n+12 к силе\n+40 к выносливости\nПрочность: 165 / 165\nТребуется\n[q2]Если на персонаже: Когда вы получаете урон в бою, наносит атакующему 100 ед. урона от сил природы. Создает угрозу в объеме удвоенного нанесенного урона.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 10 ед."},
[1213491] = {name = "Чертеж: обсидиановый разоритель", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового разорителя."},
[1213492] = {name = "[q4]Обсидиановый разоритель", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (40), Насыщенный обсидианом ториевый слиток (10), Зачарованная кожа (8), Обсидиановый шлифовальный камень (6), Алебастровый идол (4), Идол Войны (2)\n[q4]Обсидиановый разоритель\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Двуручное Топор\nУрон: 203-340 Скорость 3.70\n(73.38 ед. урона в секунду)\n+40 к силе\n+30 к выносливости\nПрочность: 120 / 120\nТребуется\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213496] = {name = "Чертеж: обсидиановый защитник", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового защитника."},
[1213498] = {name = "[q4]Обсидиановый защитник", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (40), Насыщенный обсидианом ториевый слиток (10), Зачарованная кожа (8), Обсидиановый шлифовальный камень (6), Багровый идол (4), Идол Жизни (2)\n[q4]Обсидиановый защитник\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Двуручное Меч\nУрон: 117-176 Скорость 2.00\n(73.25 ед. урона в секунду)\nПрочность: 120 / 120\nТребуется\n[q2]Возможный эффект при попадании: Исцеление себя на 270 в 450 ед. и повышение силы на 120 ед. на 30 сек.\n[q2]Возможный эффект при попадании: Увеличивает наносимый урон на 20 ед. и повышает скорость атаки на 5% на 15 сек.\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213499] = {name = "Чертеж: обсидиановый разрушитель", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового разрушителя."},
[1213500] = {name = "[q4]Обсидиановый разрушитель", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (40), Насыщенный обсидианом ториевый слиток (10), Обсидиановый шлифовальный камень (8), Алебастровый идол (4), Багровый идол (4), Идол Ночи (2)\n[q4]Обсидиановый разрушитель\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Двуручное Дробящее\nУрон: 117-176 Скорость 2.00\n(73.25 ед. урона в секунду)\n+40 к силе\nПрочность: 120 / 120\nТребуется\n[q2]Если на персонаже: Увеличивает силу атаки на 260 ед. в облике кошки, медведя и лютого медведя.\n[q2]Возможный эффект при попадании: Оглушение цели на 3 сек.\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213501] = {name = "Чертеж: обсидиановый буремолот", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового буремолота."},
[1213502] = {name = "[q4]Обсидиановый буремолот", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (30), Насыщенный обсидианом ториевый слиток (8), Зачарованная кожа (5), Обсидиановый шлифовальный камень (6), Обсидиановый идол (3), Идол возрождения (2)\n[q4]Обсидиановый буремолот\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Правая рука Дробящее\nУрон: 49-117 Скорость 2.00\n(41.50 ед. урона в секунду)\n+10 к выносливости\n+8 к интеллекту\nПрочность: 105 / 105\nТребуется\n[q2]Возможный эффект при попадании: Поражает до 3 целей, нанося 105 в 145 ед. урона от сил природы.\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 60 ед.\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213503] = {name = "Чертеж: обсидиановый клинок мудреца", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового клинка мудреца."},
[1213504] = {name = "[q4]Обсидиановый клинок мудреца", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (30), Насыщенный обсидианом ториевый слиток (8), Кристалл-источник (3), Обсидиановый шлифовальный камень (3), Обсидиановый идол (3), Идол Мудреца (2)\n[q4]Обсидиановый клинок мудреца\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Правая рука Меч\nУрон: 37-88 Скорость 1.50\n(41.67 ед. урона в секунду)\n+14 к выносливости\n+12 к интеллекту\nПрочность: 105 / 105\nТребуется\n[q2]Если на персонаже: Увеличение урона и целительного действия магических заклинаний и эффектов не более чем на 60 ед.\n[q2]Если на персонаже: Снижает сопротивление магии целей ваших заклинаний на 20.\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213505] = {name = "Чертеж: обсидиановый страж", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению обсидианового стража."},
[1213506] = {name = "[q4]Обсидиановый страж", additional_info = "Применение: 1 мин\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (30), Насыщенный обсидианом ториевый слиток (8), Обсидиановый шлифовальный камень (6), Багровый идол (3), Обсидиановый идол (3), Идол Солнца (2)\n[q4]Обсидиановый страж\nСтановится персональным при надевании\nУникальный использующийся: [Obsidian Weapon] (1)Правая рука Топор\nУрон: 106-198 Скорость 2.70\n(56.30 ед. урона в секунду)\n+11 к выносливости\nПрочность: 105 / 105\nТребуется\n[q2]Если на персонаже: Повышает вероятность попадания атак и заклинаний на 1%.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 9 ед.\n[q2]Если на персонаже: Заклинания прямого действия и атаки ближнего боя могут нанести цели 325 в 500 ед. урона от огня. Почти каждый удар наносит силитидам в Силитусе дополнительный урон. (Восстановление: 2.1с)"},
[1213509] = {name = "Выкройка: накладки из светящегося хитина", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению накладок из светящегося хитина."},
[1213513] = {name = "[q3]Накладки из светящегося хитина", additional_info = "Применение: 25 сек\nИнгредиенты:\nШипастый силитидский хитин (5), Луноткань (3), Накладки из кожи Недр\n[q3]Накладки из светящегося хитина\nТребуется\n[q2]Использование: Укрепляет нагрудник, поножи, перчатки или обувь накладками, увеличивающими урон и объем исцеления от заклинаний максимум на 10 ед. Укрепить можно только предметы уровня 45 и выше."},
[1213518] = {name = "Выкройка: накладки из заостренного хитина", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению накладок из заостренного хитина."},
[1213519] = {name = "[q3]Накладки из заостренного хитина", additional_info = "Применение: 25 сек\nИнгредиенты:\nШипастый силитидский хитин (5), Обработанная грубая шкура (3), Накладки из кожи Недр\n[q3]Накладки из заостренного хитина\nТребуется\n[q2]Использование: Применяет постоянный эффект к нагруднику, поножам, перчаткам или обуви, наносящий 20 ед. урона от сил природы атакующему вас противнику, когда вы получаете урон в бою. Действует только на предметы уровня 45 и выше."},
[1213520] = {name = "Выкройка: клобук бритвенного терна", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению клобука бритвенного терна."},
[1213521] = {name = "[q4]Клобук бритвенного терна", additional_info = "Применение: 25 сек\nИнгредиенты:\nШипастый силитидский хитин (15), Зачарованная кожа (8), Рулон киражского шелка (8), Обработанная грубая шкура (8)\n[q4]Клобук бритвенного терна\nСтановится персональным при надевании\nГолова Кожа\n[q2]Броня: 268\n+15 к ловкости\n+37 к выносливости\nПрочность: 70 / 70\nТребуется\n[q2]Если на персонаже: Когда вы получаете урон в бою, наносит атакующему 100 ед. урона от сил природы. Создает угрозу в объеме удвоенного нанесенного урона.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 9 ед."},
[1213522] = {name = "Выкройка: наплечные пластины бритвенного терна", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Обучает изготовлению наплечных пластин бритвенного терна."},
[1213523] = {name = "[q4]Наплечные пластины бритвенного терна", additional_info = "Применение: 25 сек\nИнгредиенты:\nШипастый силитидский хитин (15), Зачарованная кожа (8), Рулон киражского шелка (8), Обработанная грубая шкура (8)\n[q4]Наплечные пластины бритвенного терна\nСтановится персональным при надевании\nПлечо Кожа\n[q2]Броня: 234\n+8 к ловкости\n+29 к выносливости\nПрочность: 70 / 70\nТребуется\n[q2]Если на персонаже: Когда вы получаете урон в бою, наносит атакующему 80 ед. урона от сил природы. Создает угрозу в объеме удвоенного нанесенного урона.\n[q2]Если на персонаже: Увеличение рейтинга защиты на 7 ед."},
