[1216928] = {name = "Направляющий свет факела", additional_info = "Радиус действия: 10 м\nМгновенное действие\n[q]Факел освещает путь. Вы знаете, куда идти. Остается лишь набраться смелости и сделать шаг вперед."},
[1216932] = {name = "Гнетущая тьма", additional_info = "Мгновенное действие\n[q]Все как-то неправильно. Вы чувствуете, что стены давят... и время на исходе."},
[1216968] = {name = "Электростатический заряд", additional_info = "[q]С вероятностью 20% наносит атакующим противникам 35 в 65 ед. урона от сил природы.\n(Вероятность срабатывания: 20%)"},
[1216971] = {name = "Гибридный бонус к исцелению и урону от заклинаний 44/24", additional_info = "Гибридный бонус к исцелению и урону от заклинаний 44/24\n[q]Увеличивает силу исцеления магических эффектов и заклинаний максимум на 44 ед., а наносимый ими урон – максимум на 24 ед."},
[1216982] = {name = "На свету", additional_info = "Мгновенное действие\n[q]Свет отпугивает злых духов и разгоняет тьму, делая путь через склепы немного безопаснее."},
[1216997] = {name = "Неколебимый боевой дух", additional_info = "[q]Уменьшает урон, получаемый от игроков и их питомцев, на 5%. Не суммируется с такими же эффектами, полученными из других источников."},
[1217084] = {name = "Настой песков", additional_info = "Мгновенное действие\n[q]Увеличивает урон, наносимый целям в Силитусе, Ан'Кираже, Восточных Чумных землях и Наксрамасе, на 3%, а критический урон, наносимый целям в этих областях, – еще на 3%."},
