[1217189] = {name = "Чары для наручей: сила заклинаний", additional_info = "Применение: 5 сек\nТребуется: Наручи\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (2), Пыль иллюзий (20), Великая Вечная субстанция (4), Субстанция Воды (2), Субстанция Огня (2), Субстанция Воздуха (2)\n[q]Применяет к наручам постоянные чары, увеличивающие урон от заклинаний максимум на 12 ед."},
[1217203] = {name = "Чары для наручей: ловкость", additional_info = "Применение: 5 сек\nТребуется: Наручи\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nКристалл-источник (2), Пыль иллюзий (10), Великая Вечная субстанция (2), Субстанция Воздуха (2)\n[q]Применяет к наручам постоянные чары, повышающие ловкость на 9."},
[1217206] = {name = "Обсидиановый прицел", additional_info = "Применение: 3 сек\nТребуется: Оружие дальнего боя\n[q]Оснащает лук или огнестрельное оружие прицелом, увеличивающим наносимый урон на 10 ед."},
[1217207] = {name = "[q3]Обсидиановый прицел", additional_info = "Применение: 45 сек\nИнструменты: Кузнечный молот , Тангенциальный вращатель\nИнгредиенты:\nТориевая труба , Чародейный кристалл , Насыщенный обсидианом ториевый слиток\n[q3]Обсидиановый прицел\nТребуется\n[q2]Использование: Оснащает лук или огнестрельное оружие прицелом, увеличивающим наносимый урон на 10 ед."},
