[1218038] = {name = "Погребение", additional_info = "Применение: 3 сек\n[q]Во льду до тех пор, пока не будут разрушены оковы."},
[1218071] = {name = "Колыбельная песнецвета", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Призывает песнецвет, усиливающий участников группы или рейда и повышающий вероятность критического удара атак ближнего и дальнего боя, а также заклинаний на 5%. Кроме того, повышает характеристики на 15. Время действия – 1 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[1218072] = {name = "Благословение Нептулона", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Усиливает находящихся рядом участников группы или рейда, повышая силу атаки на 200, выносливость – на 15%, а вероятность критического эффекта заклинаний – на 3% на 2 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[1218073] = {name = "Темный жребий урона", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличивает урон, наносимый участниками группы или рейда, на 10% на 2 ч."},
[1218074] = {name = "Мощь Черной горы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Увеличивает запас здоровья на 300 ед., повышает скорость атак ближнего боя на 15% и восполняет 10 ед. маны каждые 5 сек. Время действия – 1 ч."},
[1218075] = {name = "Сны о Зандаларе", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Повышает скорость передвижения участников группы или рейда на 10%, а их характеристики — на 15% на 2 ч."},
[1218089] = {name = "Безграничная власть", additional_info = nil},
[1218091] = {name = "Тишина", additional_info = nil},
[1218092] = {name = "Тишина", additional_info = nil},
[1218121] = {name = "Рог Рассвета", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Воодушевляет ближайших участников группы или рейда, повышая вероятность критического эффекта заклинаний на 10%, вероятность критического удара атак ближнего и дальнего боя – на 5%, а силу атаки – на 140. Время действия – 2 ч. Не действует одновременно с аналогичными глобальными эффектами. На этот эффект не действуют темпоральные дары."},
[1218134] = {name = "Усмиряющий выстрел", additional_info = "{Мана: 270} {Радиус действия: 35 м}\nВосстановление: 20 сек\nТребуется: Оружие дальнего боя\n[q]Снимает с противника 1 эффект бешенства."},
[1218154] = {name = "Коварнейшие удары", additional_info = "Мгновенное действие\n[q]Modifies Jump Targets +2:\nКоварный удар , Коварный удар , Коварный удар , Коварный удар , Коварный удар , Коварный удар , Коварный удар , Коварный удар"},
[1218178] = {name = "Kill Shot", additional_info = nil},
[1218198] = {name = "Омерзительное заражение", additional_info = "Мгновенное действие\n[q]Паучий квартал усилен. Во время боя рядом с игроками случайным образом появляются кладки яиц, которые взрываются через несколько секунд."},
[1218212] = {name = "Взрывные яйца", additional_info = nil},
[1218216] = {name = "Подчиненные прядильщики", additional_info = "Мгновенное действие\n[q]Наносит периодический урон от сил природы. Ваши атаки с некоторой вероятностью призывают прислужников-пауков, набрасывающихся на противников.\n(Вероятность срабатывания: 20%)"},
[1218232] = {name = "Власть ледяных пустошей", additional_info = nil},
[1218240] = {name = "Убийственный выстрел", additional_info = "Радиус действия: 10 - 200 м\n[q]Вы пытаетесь добить раненую цель выстрелом, наносящим 587% урона от оружия и еще [587 / 100 * 587 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] ед. \"Убийственный выстрел\" не имеет минимальной дальности применения. \"Убийственный выстрел\" мгновенно восстанавливается, когда вы применяете его против противника с уровнем здоровья 20% или менее."},
[1218271] = {name = "Власть ледяных пустошей", additional_info = "Мгновенное действие\n[q]Войска Плети стали сильнее."},
[1218275] = {name = "Власть ледяных пустошей", additional_info = "Мгновенное действие\n[q]Войска Плети стали сильнее."},
[1218276] = {name = "Власть ледяных пустошей", additional_info = "Мгновенное действие\n[q]Войска Плети стали сильнее."},
[1218283] = {name = "Власть ледяных пустошей", additional_info = "Мгновенное действие\n[q]Вы привлекли внимание самого Короля-лича. Надежды больше нет."},
[1218285] = {name = "Готовность", additional_info = nil},
[1218309] = {name = "Восстановление прочности (PT)", additional_info = nil},
[1218345] = {name = "Вымораживание", additional_info = nil},
[1218352] = {name = "Вымораживание", additional_info = "[q]Заклинания магии льда с вероятностью 100% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара заклинаний магии льда против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 5 раз."},
[1218358] = {name = "Неистовое бешенство", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Вызывает у цели неистовое бешенство, повышающее силу атаки ближнего боя на 91 ед., но ослабляющее броню на 640 ед. на 2 мин. Взбешенные противники не сбегают из боя и невосприимчивы к эффектам страха и ужаса."},
[1218360] = {name = "Мощный удар", additional_info = nil},
[1218363] = {name = "Посидеть", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Карает противника, нанося урон от светлой магии."},
[1218364] = {name = "Свобода!", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Карает противника, нанося урон от светлой магии."},
[1218366] = {name = "Живая тьма", additional_info = "Мгновенное действие\n[q]Вас окутывает холодная магическая тьма..."},
[1218367] = {name = "Размах", additional_info = "Мгновенное действие\n[q]Поднять зачарованный факел и рассеять тьму возле склепов Каражана."},
[1218375] = {name = "Темное приношение", additional_info = nil},
[1218415] = {name = "Сотворение горящего проводника", additional_info = nil},
[1218423] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Исцеления\" за 2 предмета", additional_info = "[q]Когда цель \"Жизнецвета\" получает урон, она с вероятностью 100% восполняет здоровье, как если бы эффект \"Жизнецвета\" был снят. Срабатывает не чаще раза в несколько секунд."},
[1218427] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Исцеления\" за 4 предмета", additional_info = "[q]Когда ваше \"Омоложение\" 10-го или 11-го уровня восполняет здоровье цели, оно с вероятностью 25% также восполняет ей 60 ед. маны, 8 ед. энергии или 2 ед. ярости."},
[1218429] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Исцеления\" за 6 предметов", additional_info = "[q]Когда цели с вашим \"Омоложением\" или \"Восстановлением\" получают урон от нежити, время действия этих эффектов обновляется."},
[1218443] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Баланса\" за 2 предмета", additional_info = "[q]\"Лунный огонь\" и \"Солнечный огонь\" наносят на 20% больше урона."},
[1218444] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Баланса\" за 4 предмета", additional_info = "[q]Время восстановления \"Звездного потока\" сокращается на 1.5 сек."},
[1218445] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Баланса\" за 6 предметов", additional_info = "[q]Когда вы поражаете нежить \"Звездным потоком\", время действия активного \"Звездопада\" восстанавливается до 10 сек."},
[1218476] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Силы зверя\" за 2 предмета", additional_info = "[q]\"Глубокая рана\" теперь наносит целям, не контролируемым игроками, периодический урон раз в 1 сек., в общей сложности нанося на 200% больше урона."},
[1218477] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Силы зверя\" за 4 предмета", additional_info = "[q]Время восстановления \"Тигриного неистовства\" сокращается на 50%."},
[1218478] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Силы зверя\" за 6 предметов", additional_info = "[q]Когда вы наносите нежити урон от кровотечения, наносимый нежити обычный и критический урон увеличивается на 1% на 30 сек. Эффект суммируется до 12 раз."},
[1218479] = {name = "Убийство нежити", additional_info = nil},
[1218482] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Стража\" за 2 предмета", additional_info = "[q]\"Рык\" всегда попадает в цель, а вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1218485] = {name = "Настой песков", additional_info = "Мгновенное действие\n[q]Увеличивает урон, наносимый целям в Силитусе, Ан'Кираже, Восточных Чумных землях и Наксрамасе, на 2%, а критический урон, наносимый целям в этих областях, – еще на 2%."},
[1218499] = {name = "Горящий проводник", additional_info = nil},
[1218506] = {name = "Рык", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Облик медведя, Облик лютого медведя\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если цель уже атакует вас."},
[1218507] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Стража\" за 4 предмета", additional_info = "[q]Время восстановления \"Инстинктов выживания\" сокращается на 2 мин., а время восстановления \"Берсерка\" – на 2 мин."},
[1218509] = {name = "S03 – предмет – Наксрамас – друид – бонус \"Стража\" за 6 предметов", additional_info = "[q]Когда вы получаете урон от нежити, время действия активного \"Неистового восстановления\" становится равным 10 сек. Кроме того, \"Неистовое восстановление\" больше не преобразует последние 15 ед. ярости в здоровье."},
[1218514] = {name = "S03 – предмет – Наксрамас – охотник – бонус дальнего боя за 4 предмета", additional_info = "[q]\"Укус змеи\" наносит на 20% больше урона."},
[1218515] = {name = "S03 – предмет – Наксрамас – охотник – бонус дальнего боя за 2 предмета", additional_info = "[q]Сокращает время восстановления \"Выстрела химеры\", \"Разрывного выстрела\" и \"Прицельного выстрела\" на 1.5 сек., \"Убийственного выстрела\" – на 3 сек., а \"Залпа\" – на 3 сек."},
[1218574] = {name = "Критическая меткость", additional_info = nil},
[1218575] = {name = "S03 – предмет – Наксрамас – охотник – бонус дальнего боя за 6 предметов", additional_info = "[q]После того как вы поражаете нежить атакой дальнего боя, вы наносите нежити на 2% больше обычного и критического урона в течение 30 сек. Эффект суммируется до 7 раз."},
[1218582] = {name = "S03 – предмет – Наксрамас – охотник – бонус ближнего боя за 2 предмета", additional_info = "[q]Изначальный урон от \"Удара виверны\" и \"Укуса мангуста\" увеличивается на 30%."},
[1218583] = {name = "S03 – предмет – Наксрамас – охотник – бонус ближнего боя за 4 предмета", additional_info = "[q]Сокращает время восстановления \"Удара виверны\" на 2 сек., \"Удара ящера\" – на 1 сек., а \"Обходного удара\" – на 8 сек."},
[1218587] = {name = "Убийство нежити", additional_info = nil},
[1218589] = {name = "S03 – предмет – Наксрамас – охотник – бонус ближнего боя за 6 предметов", additional_info = "[q]После того как вы поражаете нежить атакой ближнего боя, вы наносите нежити на 2% больше обычного и критического урона в течение 30 сек. Эффект суммируется до 12 раз. Вы теряете эффекты, когда применяете атаку дальнего боя."},
[1218592] = {name = "S03 – предмет – Наксрамас – маг – бонус \"Тайной магии\" за 2 предмета", additional_info = "[q]\"Темпоральный маяк\" восполняет союзникам [Сила заклинаний * 67 / 1000 + (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 8 / 100] ед. здоровья раз в 1 сек."},
[1218624] = {name = "Resurrection", additional_info = nil},
[1218693] = {name = "S03 – предмет – Наксрамас – маг – бонус \"Тайной магии\" за 4 предмета", additional_info = "[q]Пока вы поддерживаете \"Регенерацию\", скорость передвижения цели повышается на 60%. Когда \"Регенерация\" восполняет здоровье союзнику, его скорость атаки и применения заклинаний с некоторой вероятностью повышается на 10% на 15 сек."},
[1218695] = {name = "Разгон", additional_info = nil},
[1218697] = {name = "S03 – предмет – Наксрамас – маг – бонус \"Тайной магии\" за 6 предметов", additional_info = "[q]Урон, наносимый нежити, преобразуется в темпоральное исцеление с повышенной на 25% эффективностью. Вы восполняете ману в объеме 5% темпорального исцеления, примененного при нанесении урона нежити."},
[1218699] = {name = "Темпоральная переработка", additional_info = nil},
[1218700] = {name = "S03 – предмет – Наксрамас – маг – бонус бойца за 4 предмета", additional_info = "[q]\"Прилив сил\" увеличивает наносимый вами урон на 1% каждую секунду поддержания. Эффект суммируется до 8 раз. Время действия – 45 сек."},
[1218701] = {name = "Пробудитель", additional_info = nil},
[1218988] = {name = "Подчиненные прядильщики", additional_info = "Мгновенное действие\n(Вероятность срабатывания: 10%)"},
[1218993] = {name = "S03 - Item - Naxxramas - Mage - Damage 2P Bonus", additional_info = "[q]Время восстановления \"Прилива сил\" сокращается на 80%."},
[1218995] = {name = "S03 – предмет – Наксрамас – маг – бонус бойца за 6 предметов", additional_info = "[q]Урон от \"Воспламенения\" не ослабевает, когда эффект действует на нежить с уровнем здоровья ниже 20%. Когда вы атакуете нежить с уровнем здоровья ниже 20%, цели получают урон как если бы были заморожены."},
[1219010] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Света\" за 2 предмета", additional_info = "[q]Время восстановления \"Возложения рук\" сокращается на 35. После того как вы применяете \"Возложение рук\", ваш уровень маны становится равен 30% максимального запаса."},
[1219019] = {name = "Ползучий мрак", additional_info = "[q]Эффекты периодического урона от темной магии с некоторой вероятностью применяют \"Ползучий мрак\", суммирующийся до 5 раз. Заклинания, наносящие прямой урон от темной магии, взрывают \"Ползучий мрак\", нанося 100 ед. урона за каждый эффект.\n(Восстановление: 1.5с)"},
[1219020] = {name = "Ползучий мрак", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Эффекты периодического урона от темной магии с некоторой вероятностью применяют \"Ползучий мрак\", суммирующийся до 5 раз. Заклинания, наносящие прямой урон от темной магии, взрывают \"Ползучий мрак\", нанося 100 ед. урона за каждый эффект."},
[1219021] = {name = "Прыжок прядильщика", additional_info = nil},
[1219024] = {name = "Теневой взрыв", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Эффекты периодического урона от темной магии с некоторой вероятностью применяют \"Ползучий мрак\", суммирующийся до 5 раз. Заклинания, наносящие прямой урон от темной магии, взрывают \"Ползучий мрак\", нанося 100 ед. урона за каждый эффект."},
[1219038] = {name = "Прыжок прядильщика", additional_info = nil},
[1219043] = {name = "Сокрушение трупа", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Уничтожает труп павшего друга или врага, нанося ближайшим противникам 588 ед. урона."},
[1219057] = {name = "Сокрушение трупа", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Уничтожает труп павшего друга или врага, нанося ближайшим противникам 588 ед. урона."},
[1219058] = {name = "Приказы о выступлении", additional_info = "Мгновенное действие\n[q]Военный квартал усилен. Во время боя игроки случайным образом получают приказы. Не исполнившие их понесут наказание!"},
[1219059] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Света\" за 4 предмета", additional_info = "[q]\"Вспышка Света\" 6-го уровня и \"Свет небес\" 8-го и 9-го уровня с вероятностью 10% дают цели эффект \"Священная сила\".\n(Вероятность срабатывания: 10%)"},
[1219060] = {name = "Приказы о выступлении", additional_info = "Мгновенное действие\n[q]Вы должны исполнить приказ!"},
[1219066] = {name = "Сокрушение", additional_info = nil},
[1219072] = {name = "Приказ исполнен!", additional_info = "Мгновенное действие\n[q]Повышает силу исцеления на 5% и увеличивает урон на 2%."},
[1219073] = {name = "Указ Харона", additional_info = "[q]\"Ползучий мрак\" наносит на 100% больше урона."},
[1219083] = {name = "Расщепленный щит", additional_info = "[q]Наносит атакующим противникам 100 ед. урона от темной магии. Создает угрозу в объеме удвоенного нанесенного урона."},
[1219085] = {name = "Бегом марш!", additional_info = "Мгновенное действие\n[q]Вынужденный марш. Действует до тех пор, пока вы не усвоите урок!"},
[1219090] = {name = "Удушение", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Вызывает у цели немоту на 3 сек."},
[1219093] = {name = "Хватка смерти", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 5 мин}\n[q]Захватывает нить души противника и притягивает ее к вам вместе с телом. Нельзя применять к противникам, уровень которых выше ( 60 + 1)-го, а также к боссам."},
[1219098] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Света\" за 6 предметов", additional_info = "[q]Цель \"Частицы Света\" получает от нежити на 20% меньше урона.\n(Вероятность срабатывания: 10%)"},
[1219099] = {name = "Теневой рассекающий удар", additional_info = "Радиус действия: 100 м\nПрименение: 5 сек\n[q]Карает до 0 ближайших противников бичом тьмы, нанося каждому 9000 ед. урона.\n\n Большая часть эффектов и талантов, которые активируются \"Стрелой Тьмы\" или усиливают эту способность, также взаимодействует с \"Теневым рассекающим ударом\"."},
[1219101] = {name = "Коса Хаоса", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Сокращает время призыва следующего беса, демона Бездны, суккуба, инкуба, охотника Скверны или стража Скверны на 10 сек. и позволяет сделать это без затрат маны и осколков душ."},
[1219108] = {name = "Приказы о выступлении", additional_info = "Мгновенное действие\n[q]Военный квартал усилен. Во время боя игроки случайным образом получают приказы. Не исполнившие их понесут наказание!"},
[1219110] = {name = "Хватка смерти", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Захватывает нить души противника и притягивает ее к вам вместе с телом. Нельзя применять к противникам, уровень которых выше ( 60 + 1)-го, а также к боссам."},
[1219111] = {name = "Хватка смерти", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Захватывает нить души противника и притягивает ее к вам вместе с телом. Нельзя применять к противникам, уровень которых выше ( 60 + 1)-го, а также к боссам."},
[1219114] = {name = "Грибное заражение", additional_info = "Мгновенное действие\n[q]Чумной квартал усилен. Рядом с игроками случайным образом вырастают усиливающие грибы, но они взрываются, когда достигают максимального размера."},
[1219121] = {name = "Кровавая чума", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Заражает цель кровавой чумой, наносящей 120 ед. урона от темной магии раз в 3 сек. в течение 15 сек."},
[1219124] = {name = "Озноб", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 1 мин}\n[q]Поражает цель ознобом, наносящим 100 ед. урона от магии льда раз в 3 сек. в течение 21 сек."},
[1219150] = {name = "Усиливающие споры", additional_info = "Мгновенное действие\n[q]Повышает скорость атаки и применения заклинаний на 1%. Увеличивает получаемый урон от сил природы на 20%."},
[1219153] = {name = "Кровавая метка", additional_info = "Радиус действия: 20 м\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]Отмечает противника. Когда этот противник наносит урон, цель восполняет 2% максимального запаса здоровья. Время действия – 20 сек. Количество зарядов – 10.\n\n Если цель – нежить, заряды не расходуются. Одновременно можно действовать только одна \"Кровавая метка\".\n(Восстановление: 1с)"},
[1219161] = {name = "Кровавая метка", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Отмечает противника. Когда этот противник наносит урон, цель восполняет 2% максимального запаса здоровья. Время действия – 20 сек. Количество зарядов – 10.\n\n Если цель – нежить, заряды не расходуются. Одновременно можно действовать только одна \"Кровавая метка\"."},
[1219166] = {name = "Грибной взрыв", additional_info = nil},
[1219176] = {name = "Уничтожение", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 1.5 мин}\n[q]Вы совершаете сокрушительный удар, нанося цели 900 ед. урона.\n\n Если на цель действует \"Кровавая чума\" или \"Озноб\", урон увеличивается на 60% за каждый из этих эффектов."},
[1219178] = {name = "Уничтожение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Вы совершаете сокрушительный удар, нанося цели 900 ед. урона.\n\n Если на цель действует \"Кровавая чума\" или \"Озноб\", урон увеличивается на 60% за каждый из этих эффектов."},
[1219189] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Воздания\" за 2 предмета", additional_info = "[q]\"Божественная буря\" наносит на 100% больше урона."},
[1219191] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Воздаяния\" за 4 предмета", additional_info = "[q]Время применения \"Гнева небес\" сокращается на 100%, его время восстановления – на 25%, а затраты маны на его применение – на 75%."},
[1219193] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Воздаяния\" за 6 предметов", additional_info = "[q]Урон, который \"Удар воина Света\", \"Божественная буря\", \"Экзорцизм\" и \"Гнев небес\" наносят нежити, увеличивается на вероятность критического удара. Не действует, когда активно \"Праведное неистовство\" или выгравирована руна \"Длань возмездия\"."},
[1219194] = {name = "Грибное заражение", additional_info = "Мгновенное действие\n[q]Чумной квартал усилен. Рядом с игроками случайным образом вырастают усиливающие грибы, но они взрываются, когда достигают максимального размера."},
[1219195] = {name = "Грибное заражение", additional_info = "Мгновенное действие\n[q]Чумной квартал усилен. Рядом с игроками случайным образом вырастают усиливающие грибы, но они взрываются, когда достигают максимального размера."},
[1219205] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Защиты\" за 2 предмета", additional_info = "[q]\"Длань возмездия\" всегда попадает в цель, а вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1219206] = {name = "Длань возмездия", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если эта цель уже атакует вас.\n\n Пока вам известна эта способность, бонус к уровню создаваемой угрозы от \"Праведного неистовства\" увеличивается до 80%. Когда другие игроки исцеляют вас, \"Праведное неистовство\" восстанавливает вам ману в объеме 25% восполненного здоровья. Кроме того, если вы должны получить урон, после которого ваш уровень здоровья упадет ниже 35%, этот урон уменьшается на 20%. \"Праведное неистовство\" действует до отмены."},
[1219225] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Защиты\" за 4 предмета", additional_info = "[q]Время восстановления \"Божественной защиты\" сокращается на 3 мин., а время восстановления \"Гнева карателя\" – на 2 мин."},
[1219226] = {name = "S03 – предмет – Наксрамас – паладин – бонус \"Защиты\" за 6 предметов", additional_info = "[q]Теперь когда нежить наносит вам урон, после которого ваш уровень здоровья должен упасть ниже 35%, эффект \"Длани возмездия\" и \"Праведного неистовства\" уменьшает этот урон на 50%."},
[1219229] = {name = "Перегрузка", additional_info = "Мгновенное действие\n[q]Квартал Мерзости усилен. Случайных игроков поражает молния, заряжающая энергией."},
[1219230] = {name = "S03 – предмет – Наксрамас – жрец – бонус лекаря за 2 предмета", additional_info = "[q]Время восстановления \"Круга исцеления\" и \"Исповеди\" сокращается на 25%."},
[1219232] = {name = "Око разума", additional_info = nil},
[1219233] = {name = "S03 – предмет – Наксрамас – жрец – бонус лекаря за 4 предмета", additional_info = "[q]\"Исповедь\", \"Быстрое исцеление\" 7-го уровня, \"Связующее исцеление\" и \"Большее исцеление\" 4-го и 5-го уровня с вероятностью 9% повышают вероятность критического удара цели на 10% на 15 сек.\n(Вероятность срабатывания: 9%)"},
[1219234] = {name = "Перегрузка", additional_info = "Мгновенное действие\n[q]Вокруг вас потрескивает воздух."},
[1219235] = {name = "Перегрузка", additional_info = "Мгновенное действие\n[q]Повышает скорость атаки и применения заклинаний. Периодически поражает ближайших игроков электричеством."},
[1219238] = {name = "S03 – предмет – Наксрамас – жрец – бонус лекаря за 6 предметов", additional_info = "[q]Когда цель \"Слова силы: Щит\" получает урон от противника-нежити, щит с вероятностью 50% не теряет прочности."},
[1219239] = {name = "Перегрузка", additional_info = nil},
[1219242] = {name = "S03 – предмет – Наксрамас – жрец – бонус \"Тьмы\" за 2 предмета", additional_info = "[q]\"Слово Тьмы: Боль\" наносит на 20% больше урона."},
[1219243] = {name = "Подавляющее отчаяние", additional_info = nil},
[1219244] = {name = "S03 – предмет – Наксрамас – жрец – бонус \"Тьмы\" за 4 предмета", additional_info = "[q]Время восстановления \"Взрыва разума\" сокращается на 1.0 сек."},
[1219250] = {name = "S03 – предмет – Наксрамас – жрец – бонус \"Тьмы\" за 6 предметов", additional_info = "[q]Урон, который \"Пытка разума\", \"Взрыв разума\" и \"Пронзание разума\" наносят нежити, увеличивается на вероятность критического удара."},
[1219260] = {name = "S03 – предмет – Наксрамас – разбойник – бонус бойца за 2 предмета", additional_info = "[q]\"Внезапный удар\" и \"Быстродействующий яд\" наносят на 20% больше урона. \"Удар в спину\" наносит на 10% больше урона. (Не действует на \"Расправу\".) Вы восполняете здоровье в объеме 5% урона, наносимого вашими ядами."},
[1219261] = {name = "Пожирание боли", additional_info = nil},
[1219267] = {name = "Демоническое разрушение", additional_info = nil},
[1219269] = {name = "Демоническое разрушение", additional_info = nil},
[1219270] = {name = "Стигийская хватка", additional_info = nil},
[1219274] = {name = "Priest Racial Ability RAQ", additional_info = "Мгновенное действие\n[q]Learn a Priest spell from another race to activate an ability in this slot."},
[1219275] = {name = "Всепожирающая чума", additional_info = "Мгновенное действие\n[q]Дает способность \"Всепожирающая чума\":\n\n\nБолезнь, наносящая 904 ед. урона от темной магии в течение 24 сек. Исцеление применяющего заклинание за счет нанесенного урона."},
[1219286] = {name = "S03 – предмет – Наксрамас – разбойник – бонус бойца за 4 предмета", additional_info = "[q]Когда вы наносите периодический урон от сил природы или кровотечения, вы с вероятностью 100% восстанавливаете 1 ед. энергии."},
[1219288] = {name = "Азарт", additional_info = nil},
[1219291] = {name = "Убийство нежити", additional_info = "Мгновенное действие"},
[1219293] = {name = "S03 – предмет – Наксрамас – разбойник – бонус бойца за 6 предметов", additional_info = "[q]За каждый израсходованный прием серии обычный и критический урон, который вы наносите нежити, увеличивается на 3% на 30 сек. Эффект суммируется до 6 раз."},
[1219338] = {name = "Замерзшая земля", additional_info = "Мгновенное действие\n[q]Покрывает землю слоем льда, затрудняющим передвижение."},
[1219351] = {name = "Призыв снежной бури", additional_info = nil},
[1219352] = {name = "Призыв снежной бури", additional_info = nil},
[1219355] = {name = "Издевка", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если цель уже атакует вас."},
[1219356] = {name = "S03 – предмет – Наксрамас – разбойник – бонус танка за 2 предмета", additional_info = "[q]\"Издевка\" всегда попадает в цель, а вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1219357] = {name = "Стужа", additional_info = nil},
[1219358] = {name = "S03 – предмет – Наксрамас – разбойник – бонус танка за 4 предмета", additional_info = "[q]Время восстановления \"Ускользания\" сокращается на 2 мин., а время восстановления \"Шквала клинков\" – на 1 мин."},
[1219359] = {name = "S03 – предмет – Наксрамас – разбойник – бонус танка за 6 предметов", additional_info = "[q]Когда вы получаете смертельный урон от противника-нежити, вы не погибаете, а ваш уровень здоровья падает до 10% максимального запаса либо не изменяется (принимается меньший из показателей). Кроме того, получаемый от нежити урон уменьшается на 90% на 3 сек. Эффект срабатывает не чаще раза в минуту."},
[1219361] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Исцеления\" за 2 предмета", additional_info = "[q]\"Щит земли\" больше не расходует заряды."},
[1219364] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Исцеления\" за 4 предмета", additional_info = "[q]\"Волна исцеления\" 9-го и 10-го уровня и \"Малая волна исцеления\" 6-го уровня с вероятностью 10% дают цели \"Тотемную мощь\".\n(Вероятность срабатывания: 10%)"},
[1219365] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Исцеления\" за 6 предметов", additional_info = "[q]Цель вашего \"Щита земли\" получает на 20% меньше урона от нежити."},
[1219367] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Стихий\" за 2 предмета", additional_info = "[q]Увеличивает периодический урон от \"Огненного шока\" на 40%."},
[1219368] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Стихий\" за 4 предмета", additional_info = "[q]Время восстановления \"Выброса лавы\" сокращается на 2 сек."},
[1219369] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Стихий\" за 6 предметов", additional_info = "[q]Каждый раз, когда атакующие заклинания активируют \"Перегрузку\", наносимый нежити обычный и критический урон увеличивается на 3% на 30 сек. Эффект суммируется до 6 раз."},
[1219370] = {name = "Убийство нежити", additional_info = nil},
[1219373] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Совершенствования\" за 2 предмета", additional_info = "[q]Пока у вас выгравирована руна \"Статический шок\", \"Щит молний\" наносит на 100% больше урона."},
[1219374] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Совершенствования\" за 4 предмета", additional_info = "[q]Время восстановления \"Вскипания лавы\" и \"Удара бури\" сокращается на 1.5 сек."},
[1219375] = {name = "Убийство нежити", additional_info = nil},
[1219376] = {name = "S03 – предмет – Наксрамас – шаман – бонус \"Совершенствования\" за 6 предметов", additional_info = "[q]Когда вы получаете заряд \"Оружия Водоворота\", наносимый нежити обычный и критический урон увеличивается на 3% на 30 сек. Эффект суммируется до 7 раз."},
[1219379] = {name = "Земной шок", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если цель уже атакует вас."},
[1219382] = {name = "S03 – предмет – Наксрамас – шаман – бонус танка за 2 предмета", additional_info = "[q]\"Земной шок\" всегда попадает в цель, когда вы используете его для провокации, а вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1219387] = {name = "Пламенный вихрь", additional_info = "Дистанция ближнего боя\n{Применение: 1.3 сек} {Восстановление: 5 сек}\n[q]Периодически запускает в воздух огненные стрелы, наносящие 693 в 807 ед. урона."},
[1219388] = {name = "Пламенный вихрь", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Наносит 693 в 807 ед. урона от огня."},
[1219389] = {name = "Испепеление", additional_info = "Мгновенное действие\n[q]Автоматически наносит ближайшим противникам 462 в 538 ед. урона от огня раз в 1 сек."},
[1219390] = {name = "Обжигающий жар", additional_info = nil},
[1219397] = {name = "Удушающая тьма", additional_info = "Мгновенное действие\n[q]Тьма сгущается. Вы не можете дышать!"},
[1219413] = {name = "S03 – предмет – Наксрамас – шаман – бонус танка за 4 предмета", additional_info = "[q]\"Ярость шамана\" уменьшает получаемый урон еще на 10%. Во время действия \"Ярости шамана\" скорость атаки и применения заклинаний повышается на 30%."},
[1219414] = {name = "S03 – предмет – Наксрамас – шаман – бонус танка за 6 предметов", additional_info = "[q]Получаемый урон от противников-нежити уменьшается на 20%."},
[1219415] = {name = "Увеличение урона от заклинаний 96", additional_info = "[q]Увеличивает урон и силу исцеления магических заклинаний и эффектов максимум на 96 ед."},
[1219420] = {name = "Притяжение проклятых", additional_info = "{Применение: 3 сек} {Восстановление: 3 сек}\n[q]Предвестник греха создает пылающую воронку, притягивающую противников к центру."},
[1219421] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус бойца за 2 предмета", additional_info = "[q]Увеличивает урон от \"Испепеления\" и \"Порчи\" на 20%."},
[1219423] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус бойца за 4 предмета", additional_info = "[q]Когда вы наносите непериодический критический урон, ваши эффекты \"Порча\", \"Жертвенный огонь\", \"Пламя Тьмы\" и \"Нестабильное колдовство\", действующие на цель, мгновенно наносят ей дополнительный такт урона с эффективностью 33%."},
[1219425] = {name = "Жертвенный огонь", additional_info = nil},
[1219428] = {name = "Порча", additional_info = nil},
[1219429] = {name = "Пламя Тьмы", additional_info = nil},
[1219436] = {name = "Нестабильное колдовство", additional_info = nil},
[1219462] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус бойца за 6 предметов", additional_info = "[q]\"Проклятие агонии\" также применяет к цели эффект \"Проклятия безрассудства\". Кроме того, \"Проклятие агонии\" действует на нежить неограниченно долго, постоянно усиливаясь."},
[1219474] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус танка за 2 предмета", additional_info = "[q]\"Устрашение\" всегда попадает в цель, а вероятность промаха заклинанием и вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1219475] = {name = "Устрашение", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если цель уже атакует вас."},
[1219476] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус танка за 4 предмета", additional_info = "[q]Время восстановления \"Инфернальной брони\" сокращается на 10 сек., а время восстановления \"Демонической грации\" – на 3 сек."},
[1219479] = {name = "S03 – предмет – Наксрамас – чернокнижник – бонус танка за 6 предметов", additional_info = "[q]Когда вас атакует противник-нежить, время действия активного эффекта \"Отмщение\" продлевается до 20 сек."},
[1219481] = {name = "S03 – предмет – Наксрамас – воин – бонус бойца за 2 предмета", additional_info = "[q]Увеличивает урон от таланта \"Глубокие раны\" на 20%."},
[1219483] = {name = "S03 – предмет – Наксрамас – воин – бонус бойца за 4 предмета", additional_info = "[q]Время восстановления \"Кровожадности\", \"Смертельного удара\" и \"Мощного удара щитом\" сокращается на 25%."},
[1219485] = {name = "Убийство нежити", additional_info = nil},
[1219486] = {name = "S03 – предмет – Наксрамас – воин – бонус бойца за 6 предметов", additional_info = "[q]После того как вы наносите нежити критический удар в ближнем бою, вы наносите нежити на 2% больше обычного и критического урона в течение 30 сек. Эффект суммируется до 9 раз."},
[1219500] = {name = "Поцелуй паука", additional_info = "Мгновенное действие\n[q]Повышает скорость атаки на 20% на 15 сек."},
[1219501] = {name = "Отражение Мерзота", additional_info = "Мгновенное действие\n[q]Отражает следующее примененное к вам вредоносное заклинание и повышает сопротивление всем школам магии на 40 на 15 сек."},
[1219503] = {name = "Око Убывания", additional_info = "Мгновенное действие\n[q]Уменьшает вас в размерах и снижает уровень создаваемой вами угрозы на 70% на 20 сек."},
[1219506] = {name = "Настой маны", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восполняет 6000 ед. маны."},
[1219507] = {name = "Устойчивость Плети", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам постоянные чары, повышающие силу исцеления магических эффектов и заклинаний максимум на 31 ед., а также повышающие скорость восполнения маны на 5 ед. раз в 5 сек."},
[1219510] = {name = "Сила Плети", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам постоянные чары, увеличивающие урон и силу исцеления магических эффектов и заклинаний максимум на 15 ед., а также повышающие вероятность критического удара на 1%."},
[1219511] = {name = "Стойкость Плети", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам постоянные чары, повышающие выносливость на 16, а защиту – на 7."},
[1219512] = {name = "Мощь Наказания", additional_info = "Применение: 5 сек\nТребуется: Наплечники\n[q]Применяет к наплечникам постоянные чары, повышающие силу атаки на 26, а вероятность критического удара – на 1%."},
[1219513] = {name = "Глаз Мертвого", additional_info = "Мгновенное действие\n[q]Повышает силу исцеления 5 следующих заклинаний максимум на 450 на 30 сек."},
[1219515] = {name = "Сущность Сапфирона", additional_info = "Мгновенное действие\n[q]Увеличивает урон и силу исцеления магических эффектов и заклинаний максимум на 180 ед. на 20 сек."},
[1219519] = {name = "Гребень убийцы", additional_info = "Мгновенное действие\n[q]Повышает силу атаки на 280 на 20 сек."},
[1219520] = {name = "Символ отражения", additional_info = "Мгновенное действие\n[q]Увеличивает показатель блокирования вашего щита на 400 ед. на 20 сек."},
[1219521] = {name = "Поборник Рассвета", additional_info = "[q]Повышает силу атаки в бою против нежити и демонов на 157. Также позволяет собирать камни Плети по поручению Серебряного Рассвета."},
[1219522] = {name = "Поборник Рассвета", additional_info = "[q]Увеличивает урон, который ваши магические эффекты и заклинания наносят нежити и демонам, максимум на 89 ед. Также позволяет собирать камни Плети по поручению Серебряного Рассвета."},
[1219539] = {name = "Печать Рассвета", additional_info = "Мгновенное действие\n[q]Раскрывает ваш потенциал, когда вы находитесь в Наксрамасе. Увеличивает наносимый урон на 1.25%, а запас здоровья – на 1.25% за каждый используемый освященный предмет снаряжения вплоть до 8."},
[1219540] = {name = "S03 – предмет – Наксрамас – воин – бонус \"Защиты\" за 2 предмета", additional_info = "[q]\"Провокация\" всегда попадает в цель, а вероятность того, что противник уклонится от вашей атаки или парирует ее, снижается на 2%."},
[1219541] = {name = "Провокация", additional_info = "Дистанция ближнего боя\n{Мгновенное действие} {Восстановление: 10 сек}\nТребуется: Оборонительная стойка\n[q]Провоцирует цель, заставляя ее атаковать вас. Не действует, если цель уже атакует вас."},
[1219543] = {name = "S03 – предмет – Наксрамас – воин – бонус \"Защиты\" за 4 предмета", additional_info = "[q]Время восстановления \"Глухой обороны\" сокращается на 3 мин., а время восстановления \"Безрассудства\" – на 3 мин. Вы можете применять \"Безрассудство\" в любой стойке, и оно больше не увеличивает получаемый урон."},
[1219544] = {name = "S03 – предмет – Наксрамас – воин – бонус \"Защиты\" за 6 предметов", additional_info = "[q]Когда вы получаете урон от противника-нежити, время действия эффекта \"Ни шагу назад\" восстанавливается до 20 сек."},
[1219548] = {name = "Печать Рассвета", additional_info = "Мгновенное действие\n[q]Раскрывает ваш потенциал, когда вы находитесь в Наксрамасе. Повышает силу исцеления на 1.25%, а запас здоровья – на 1.25% за каждый используемый освященный предмет снаряжения вплоть до 8."},
[1219552] = {name = "Сила Стража", additional_info = "Мгновенное действие\n[q]Увеличивает урон и силу исцеления магических эффектов и заклинаний участников группы в радиусе 30 м максимум на 33. Эффект не суммируется с такими же эффектами, полученными из других источников."},
[1219553] = {name = "Сила Стража", additional_info = "Мгновенное действие\n[q]Усиливает исцеление от магических эффектов и заклинаний участников группы в радиусе 30 м максимум на 62 ед., а урон от них – максимум на 19 ед. Эффект не суммируется с такими же эффектами, полученными из других источников."},
[1219557] = {name = "Сила Стража", additional_info = "Мгновенное действие\n[q]Повышает скорость применения заклинаний участников группы в радиусе 30 м на 2%. Эффект не суммируется с такими же эффектами, полученными из других источников."},
[1219558] = {name = "Сила Стража", additional_info = "Мгновенное действие\n[q]Повышает вероятность критического удара заклинаний участников группы в радиусе 30 м на 2%. Эффект не суммируется с такими же эффектами, полученными из других источников."},
[1219568] = {name = "Формула чар для предмета в левой руке - высший интеллект", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к предмету в левой руке постоянные чары, повышающие интеллект на 9."},
[1219569] = {name = "Формула чар для предмета в левой руке - превосходный дух", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к предмету в левой руке постоянные чары, повышающие дух на 12."},
[1219570] = {name = "Формула чар для предмета в левой руке - мудрость", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к предмету в левой руке постоянные чары, повышающие интеллект на 6, а дух – на 5."},
[1219571] = {name = "Формула чар для двуручного оружия - взрыв чар", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к двуручному оружие постоянные чары, повышающие силу заклинаний на 65."},
[1219572] = {name = "Формула чар для щита - превосходная выносливость", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к щиту постоянные чары, повышающие выносливость на 12."},
[1219573] = {name = "Формула чар для щита - критический удар", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к щиту постоянные чары, повышающие вероятность критического удара на 1%."},
[1219574] = {name = "Формула чар для наручей - сила заклинаний II", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к наручам постоянные чары, повышающие силу заклинаний на 16."},
[1219575] = {name = "Формула чар для перчаток - высшая сила", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к перчаткам постоянные чары, повышающие силу на 15."},
[1219576] = {name = "Формула чар для плаща - ловкость", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Обучает применять к плащу постоянные чары, повышающие ловкость на 5."},
[1219577] = {name = "Чары для предмета в левой руке - высший интеллект", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nКристалл-источник (2), Пыль иллюзий (18), Субстанция Воздуха (2)\n[q]Применяет к предмету в левой руке постоянные чары, повышающие интеллект на 9."},
[1219578] = {name = "Чары для предмета в левой руке - превосходный дух", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nКристалл-источник (2), Пыль иллюзий (18), Субстанция Воды (2)\n[q]Применяет к предмету в левой руке постоянные чары, повышающие дух на 12."},
[1219579] = {name = "Чары для предмета в левой руке - мудрость", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (6), Пыль иллюзий (18), Субстанция Воздуха , Субстанция Воды\n[q]Применяет к предмету в левой руке постоянные чары, повышающие интеллект на 6, а дух – на 5."},
[1219580] = {name = "Чары для двуручного оружия - взрыв чар", additional_info = "Применение: 5 сек\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nКристалл-источник (3), Пыль иллюзий (24), Кровь героев , Лиловый лотос (6)\n[q]Применяет к двуручному оружие постоянные чары, повышающие силу заклинаний на 65."},
[1219581] = {name = "Чары для щита - превосходная выносливость", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nБольшой сверкающий осколок (6), Пыль иллюзий (18), Субстанция Земли (2)\n[q]Применяет к щиту постоянные чары, повышающие выносливость на 12."},
[1219586] = {name = "Чары для перчаток - высшая сила", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nВеликая Вечная субстанция (7), Пыль иллюзий (21), Субстанция Огня (2)\n[q]Применяет к перчаткам постоянные чары, повышающие силу на 15."},
[1219587] = {name = "Чары для плаща - ловкость", additional_info = "Применение: 5 сек\nТребуется: Броня\nИнструменты: Рунный арканитовый жезл\nИнгредиенты:\nВеликая Вечная субстанция (3), Пыль иллюзий (9), Субстанция Огня\n[q]Применяет к плащу постоянные чары, повышающие ловкость на 5."},
