[1219706] = {name = "Омоложение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Восполняет 8 ед. энергии."},
[1219707] = {name = "Омоложение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Восполняет 20 ед. ярости."},
[1219708] = {name = "Омоложение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Восполняет 60 ед. маны."},
[1219728] = {name = "Ледяное сокрушение", additional_info = nil},
[1219729] = {name = "Ледяное сокрушение", additional_info = "Мгновенное действие\n[q]Когда действие ауры заканчивается, вы получаете высокий урон от магии льда, распределяемый между находящимися рядом союзниками."},
[1219732] = {name = "Ледяное сокрушение", additional_info = "Мгновенное действие\n[q]Когда действие ауры заканчивается, вы получаете высокий урон от магии льда, распределяемый между находящимися рядом союзниками."},
[1219733] = {name = "Ледяное сокрушение", additional_info = nil},
[1219740] = {name = "Душа тактика", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой тактика:\n\nПосле смены стойки затраты ярости на применение следующей атакующей способности снижаются на 10."},
[1219741] = {name = "Хваткие духи", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Наносит 462 в 538 ед. урона от темной магии раз в 1 сек. Снижает скорость передвижения на 35%."},
[1219742] = {name = "Душа ветерана войны", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ветерана войны:\n\nВ течение 15 сек. после выхода из любой стойки вы можете по-прежнему применять способности, требующие данную стойку."},
[1219743] = {name = "Душа предсказателя битв", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой предсказателя битв:\n\nВ течение первых 15 сек. после активации стойки вы получаете дополнительный бонус:\n\n \"Боевая стойка\"/\"Стойка гладиатора\": наносимый урон увеличивается на 5%.\n\n \"Стойка берсерка\": вероятность критического удара повышается на 5%.\n\n \"Защитная стойка\": получаемый физический урон уменьшается на 5%."},
[1219744] = {name = "Хваткие духи", additional_info = nil},
[1219745] = {name = "Душа алчущего крови", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой алчущего крови:\n\nКритические удары \"Превосходства\" продлевают время действия \"Кровопускания\" на цели до максимального."},
[1219747] = {name = "Душа титана", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой титана:\n\n\"Удар героя\", \"Мощный удар\" и \"Превосходство\" наносят на 10 + (5 * Серия приёмов)% больше урона."},
[1219748] = {name = "Душа разрушителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой разрушителя:\n\n\"Мощный удар\" мгновенно восстанавливает \"Смертельный удар\", \"Кровожадность\" и \"Мощный удар щитом\"."},
[1219749] = {name = "Душа заклинателя смерти", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой заклинателя смерти:\n\nСокращает время восстановления \"Инстинкта смерти\" на 50%."},
[1219751] = {name = "Душа кровопускателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой кровопускателя:\n\nВы наносите на 15% больше урона, пока хотя бы на одного ближайшего противника одновременно действуют ваши эффекты \"Кровопускание\" и \"Глубокие раны\"."},
[1219752] = {name = "Душа мастера блокирования", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера блокирования:\n\nУвеличивает показатель блокирования вашего щита на 30 ед."},
[1219753] = {name = "Душа дикости", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой дикости:\n\nКогда вы получаете урон или совершаете автоатаку, вы накапливаете еще 1 ед. ярости."},
[1219754] = {name = "Душа вражды", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вражды:\n\nУвеличивает угрозу, создаваемую вами в \"Защитной стойке\", еще на 10% и увеличивает наносимый урон в \"Стойке гладиатора\" на 4%."},
[1219755] = {name = "Душа отражателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой отражателя:\n\nКогда вы парируете атаку противника или противник парирует вашу, вы накапливаете 10 ед. ярости."},
[1219756] = {name = "Душа мстителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мстителя:\n\n\"Реванш\" также дает вам \"Шквал\", повышающий скорость атаки на 30% на 3 удара:ударов."},
[1219757] = {name = "Душа неутомимого", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой неутомимого:\n\nКогда ваша цель парирует атаку, вы мгновенно применяете \"Возмездие\", нанося цели 200% урона от оружия. \"Возмездие\" нельзя заблокировать или парировать, и от него нельзя уклониться. Срабатывает против каждой цели не чаще раза в 30 сек."},
[1219758] = {name = "Душа громоносца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой громоносца:\n\nСокращает время восстановления \"Удара грома\" на 100%."},
[1219760] = {name = "Душа часового", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой часового:\n\nЕсли цель парирует, блокирует ваше \"Сокрушение щитом\" или уклоняется от него, создаваемый им уровень угрозы повышается на 100%, а его время восстановления обновляется."},
[1219762] = {name = "Душа бойца-левши", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой бойца-левши:\n\nСокращает время восстановления \"Мощного удара щитом\" на 2 сек."},
[1219763] = {name = "Душа гладиатора", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой гладиатора:\n\nСокращает время восстановления \"Кровавой ярости\", пока вы используете \"Стойку гладиатора\", на 30 сек."},
[1219764] = {name = "Душа повторного толчка", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой повторного толчка:\n\nСокращает время восстановления \"Ударной волны\" на 25%."},
[1219766] = {name = "Душа избегающего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой избегающего:\n\n\"Ложный выпад\" также на 6 сек. дает \"Избежание\", уменьшающее получаемый урон от атак по области на 50%. Не действует на атаки, примененные игроками."},
[1219767] = {name = "Душа токсиколога", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой токсиколога:\n\nУвеличивает критический урон от ядов на 100%."},
[1219768] = {name = "Душа палача", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой палача:\n\nС вероятностью 5% за каждый прием в серии ваш завершающий прием позволяет применить следующую способность без затрат энергии."},
[1219769] = {name = "Душа оппортуниста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой оппортуниста:\n\nПриемы, начинающие серию, с вероятностью 100% позволяют применить следующую способность без затрат энергии."},
[1219770] = {name = "Душа мясника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мясника:\n\nВаше оружие в правой руке наносит на 20% больше урона от умений, продлевающих серию приемов."},
[1219771] = {name = "Душа фантома", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой фантома:\n\nСокращает время восстановления \"Исчезновения\" до 1 мин. Данный эффект не суммируется с эффектом \"Неуловимости\"."},
[1219772] = {name = "Душа пройдохи", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пройдохи:\n\nУвеличивает урон от \"Расправы\" и \"Удара саблей\" на 20%."},
[1219773] = {name = "Душа экстремала", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой экстремала:\n\nСокращает время восстановления \"Выброса адреналина\" на 4 мин."},
[1219774] = {name = "Душа гения клинка", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой гения клинка:\n\nПовышает вероятность критического удара при использовании кинжалов на 5%."},
[1219775] = {name = "Душа ловчего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ловчего:\n\nПовышает вероятность критического эффекта \"Внезапного удара\" на 30%."},
[1219776] = {name = "Душа деятельного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой деятельного:\n\nЗавершающие приемы расходуют на 50% меньше энергии."},
[1219777] = {name = "Душа жонглера клинками", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой жонглера клинками:\n\nПока действуют эффекты \"Просто царапина\" и \"Танец клинков\", ваши способности \"Кровавый вихрь\", \"Мушкетон\" и \"Веер клинков\" расходуют на 20 ед. меньше энергии и создают на 100% больше угрозы."},
[1219778] = {name = "Душа повелителя теней", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой повелителя теней:\n\nВо время действия \"Исчезновения\" получаемый магический урон уменьшается на 50%. \"Исчезновение\" больше не дает незаметность и не снимает затрудняющие передвижение эффекты."},
[1219779] = {name = "Душа эквилибриста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой эквилибриста:\n\nЗавершающие приемы с вероятностью 20% за каждый израсходованный прием серии уменьшают получаемый физический урон от следующей атаки ближнего боя на 20% на 10 сек."},
[1219780] = {name = "Душа сосредоточенного борца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой сосредоточенного борца:\n\nЭффект \"Держать удар\" теперь также срабатывает каждый раз, когда вы увеличиваете длину серии приемов."},
[1219781] = {name = "Душа черного пояса", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой черного пояса:\n\nКаждый эффект \"Держать удар\" также усиливает бонус к броне от предметов на 20% вплоть до 100%."},
[1219782] = {name = "Душа фехтовальщика", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой фехтовальщика:\n\nКогда цель уклоняется от атаки или парирует ее, ваш \"Главный аргумент\" мгновенно восстанавливается."},
[1219783] = {name = "Душа сорвиголовы", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой сорвиголовы:\n\n\"Главный аргумент\" поражает еще 1 находящуюся рядом цель и усиливает \"Коварный удар\", позволяя ему поражать еще 1 находящуюся рядом цель в течение 10 сек. \"Шквал клинков\" не дублирует эти дополнительные удары."},
[1219784] = {name = "Душа кровожадного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой кровожадного:\n\nПока действует \"Главный аргумент\", вы восполняете здоровье в объеме 15% урона, нанесенного \"Коварным ударом\". Избыточное исцеление превращается в \"Кровяной барьер\", поглощающий урон в объеме до 20% вашего максимального запаса здоровья."},
[1219785] = {name = "Душа преобразователя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой преобразователя:\n\n\"Жизнеотвод\" дает на 50% больше маны и создает на 100% меньше угрозы."},
[1219786] = {name = "Душа искусного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой искусного:\n\nПовышает вероятность критического удара заклинаний и атак на 2%."},
[1219787] = {name = "Душа истребителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой истребителя:\n\nВероятность срабатывания таланта \"Сумерки\" повышается на 4%. \"Испепеление\" с вероятностью 4% применяет \"Истребление\" к целям с любым уровнем здоровья."},
[1219788] = {name = "Душа гноителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой гноителя:\n\nУвеличивает периодический урон от ваших заклинаний и урон вашего стража Скверны на 10 + (5 * Серия приёмов)%."},
[1219789] = {name = "Душа злонамеренного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой злонамеренного:\n\nПериодический урон от ваших заклинаний \"Пламя Тьмы\", \"Нестабильное колдовство\" и \"Проклятие агонии\", а также урон вашего стража Скверны с вероятностью 4% вводят вас в теневой транс."},
[1219790] = {name = "Душа тенеманта", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой тенеманта:\n\n\"Стрела Тьмы\" наносит на 10 + (5 * Серия приёмов)% больше урона за каждый ваш эффект, действующий на цель. Максимальный бонус – 30 + (5 * Серия приёмов)%."},
[1219791] = {name = "Душа вестника хаоса", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вестника хаоса:\n\nСокращает время восстановления \"Стрелы Хаоса\" на 50% и увеличивает урон от \"Стрелы Хаоса\" и \"Стрелы Тьмы\" на 10%. Кроме того, \"Стрела Хаоса\" теперь может вызвать срабатывание таланта \"Улучшенная стрела Тьмы\" и повышает число его зарядов на 26 (не суммируется с дополнительными зарядами \"Пламени Тьмы\")."},
[1219792] = {name = "Душа поджигателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой поджигателя:\n\nКогда вы поражаете цель \"Поджиганием\", наносимый вами урон от огня увеличивается на 5% на 20 сек. Эффект суммируется до 2 раз."},
[1219793] = {name = "Душа инфернального пастыря", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой инфернального пастыря:\n\nУвеличивает прибавки к силе атаки и урону от заклинаний, которые ваш демон получает от ваших характеристик, на 20%."},
[1219794] = {name = "Душа владыки демонов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой владыки демонов:\n\nУсиливает эффект таланта \"Мастер-демонолог\" на 50%."},
[1219795] = {name = "Душа демонического экзорциста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой демонического экзорциста:\n\n\"Изгнание\" теперь применяется мгновенно, и вы можете применить его к себе, когда находитесь в облике демона. \"Изгнание\" дает вам \"Воздержанность\" на 1 мин, но вы не можете применить \"Изгнание\" к себе, если на вас уже действует \"Воздержанность\"."},
[1219796] = {name = "Душа страдальца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой страдальца:\n\nКогда вы получаете урон, вы и ваш прислужник восполняете ману в объеме полученного урона вплоть до 420 ед. Срабатывает раз в несколько секунд."},
[1219797] = {name = "Душа огненного призрака", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой огненного призрака:\n\nКаждое попадание \"Теневого рассекающего удара\" с вероятностью 20% дает вам осколок души, мгновенно восстанавливает \"Ожог души\" и позволяет мгновенно применить следующий \"Ожог души\" в течение 10 сек."},
[1219798] = {name = "Душа пожирателя плоти", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пожирателя плоти:\n\nЕсли вы выбрали целью противника в радиусе 30 м, \"Жизнеотвод\" восполняет вам ману за счет здоровья противника, но при этом наносит ему на 50 + (5 * Серия приёмов)% меньше урона. Количество восполняемой маны остается без изменений."},
[1219799] = {name = "Душа абиссала", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой абиссала:\n\nВо время действия \"Метаморфозы\" ваши атакующие способности и призыв демонов не требуют осколков души. Кроме того, когда ваш \"Ожог Тьмы\" наносит урон, вы восполняете 15% максимального запаса здоровья."},
[1219800] = {name = "Душа порожденного Бездной", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой порожденного Бездной:\n\nЭффекты избыточного самоисцеления преобразуются в поглощающий урон щит. Прочность щита суммируется и может достигать до 30 + (5 * Серия приёмов)% максимального запаса здоровья."},
[1219801] = {name = "Душа теневого клинка", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой теневого клинка:\n\nСокращает время восстановления \"Теневого рассекающего удара\" на 1.5 сек."},
[1219802] = {name = "Душа ритуалиста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ритуалиста:\n\nЭффекты \"Демонического жертвоприношения\" продолжают действовать, пока с вами активный прислужник-демон, но прекращаются, если вы призываете пожертвованного демона. Единовременно может действовать только один эффект \"Демонического жертвоприношения\"."},
[1219803] = {name = "Душа дарующего боль", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой дарующего боль:\n\nВ течение 6 сек. после того как вы применяете \"Теневой рассекающий удар\", \"Жгучая боль\" поражает 1 дополнительную цель в области ближнего боя."},
[1219804] = {name = "Душа ловкача", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ловкача:\n\nВы создаете на 100% больше угрозы в течение 8 сек. после применения \"Отвлекающего выстрела\"."},
[1219805] = {name = "Душа добытчика", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой добытчика:\n\nКогда вы выслеживаете существ, вы наносите существам выслеживаемой категории на 3% больше урона."},
[1219806] = {name = "Душа стрелка", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой стрелка:\n\nВ течение 12 сек. после применения \"Прицельного выстрела\" ваша следующая способность-выстрел наносит на 20% больше урона."},
[1219807] = {name = "Душа опасного разорителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой опасного разорителя:\n\n\"Прицельный выстрел\" наносит на 20% больше урона целям, на которые действуют эффекты ваших ловушек."},
[1219808] = {name = "Душа переменчивого", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой переменчивого:\n\nВаши наносящие урон способности категории \"Выстрел\" усиливают следующий наносящий урон \"Выстрел\" другого типа на 10%."},
[1219809] = {name = "Душа знатока токсинов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой знатока токсинов:\n\n\"Укус змеи\" наносит дополнительный урон в объеме 25% вашей силы атаки."},
[1219810] = {name = "Душа охотника за головами", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой охотника за головами:\n\n\"Убийственный выстрел\" наносит целям, не контролируемым игроками, на 10% больше урона."},
[1219811] = {name = "Душа виртуоза стрельбы", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой виртуоза стрельбы:\n\nВремя восстановления \"Убийственного выстрела\" сокращается на 50%. Пока у вас выгравирована руна \"Быстрые убийства\" и действует \"Быстрая стрельба\", \"Убийственный выстрел\" не требует времени на восстановление, а против целей, не находящихся под контролем игроков, срабатывает еще 3 раза:раз, нанося 30% урона на минимальном расстоянии."},
[1219812] = {name = "Душа хранителя зверей", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя зверей:\n\nУвеличивает прибавку к силе атаки, которую ваш питомец получает от ваших характеристик, на 20%."},
[1219813] = {name = "Душа псаря", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой псаря:\n\nПовышает скорость восстановления концентрации вашего питомца на 20%."},
[1219814] = {name = "Хваткие духи", additional_info = nil},
[1219815] = {name = "Душа мастера-укротителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера-укротителя:\n\nУскоряет восстановления тонуса ваших питомцев на 100%."},
[1219816] = {name = "Душа охотника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой охотника:\n\n\"Укус мангуста\" также снижает вероятность уклонения цели на 1% и повышает вашу вероятность попадания на 1% на 30 сек."},
[1219818] = {name = "Душа карателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой карателя:\n\n\"Укус мангуста\" также активируется на 5 сек., когда ваша цель парирует или блокирует вашу атаку, а также когда вы промахиваетесь атакой ближнего боя."},
[1219819] = {name = "Душа отголосков", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой отголосков:\n\n\"Удар ящера\" увеличивает урон от следующей другой способности ближнего боя (кроме \"Подрезать крылья\") на 20% на 5 сек."},
[1219820] = {name = "Душа смертоносного бичевателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой смертоносного бичевателя:\n\nВаше оружие в правой руке наносит на 20% больше урона при \"Ударе ящера\" и \"Ударе виверны\"."},
[1219821] = {name = "Душа мастера кинетики", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера кинетики:\n\nВаш периодический урон с вероятностью 5% мгновенно восстанавливает одну из способностей категории \"Удар\". Восстанавливается способность с наибольшим текущим временем восстановления."},
[1219822] = {name = "Душа стратега", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой стратега:\n\nУвеличивает периодический урон от \"Удара виверны\" на 50%, а максимальный запас концентрации питомца – на 50 ед."},
[1219823] = {name = "Душа смертоносного нападающего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой смертоносного нападающего:\n\nУвеличивает мгновенный урон от \"Укуса мангуста\" и всех способностей-ударов или бросков на 20%."},
[1219824] = {name = "Душа скорого лекаря", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой скорого лекаря:\n\nВремя применения \"Быстрого исцеления\" сокращается на 0.1 сек., а время применения \"Большего исцеления\" – на 0.2 сек."},
[1219825] = {name = "Душа искусного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой искусного:\n\nПовышает вероятность критического удара заклинаний и атак на 2%."},
[1219826] = {name = "Душа торжествующего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой торжествующего:\n\nПовышает вероятность критического эффекта \"Молитвы исцеления\" и \"Круга исцеления\" на 25%."},
[1219827] = {name = "Душа преданного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой преданного:\n\nВо время применения заклинаний мана восполняется со скоростью 15% от обычной."},
[1219828] = {name = "Душа непредсказуемого", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой непредсказуемого:\n\nЭффекты периодического исцеления с вероятностью 2% позволяют мгновенно применить следующее заклинание с временем применения менее 10 сек."},
[1219829] = {name = "Душа откликнувшегося", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой откликнувшегося:\n\n\"Круг исцеления\" и \"Исповедь\" дополнительно восполняют целям 25% здоровья за 15 сек."},
[1219830] = {name = "Душа приверженца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой приверженца:\n\nКоличество зарядов \"Молитвы восстановления\" увеличивается на 2."},
[1219831] = {name = "Душа архиепископа", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой архиепископа:\n\n\"Круг исцеления\" теперь восполняет наиболее серьезно раненому участнику группы на 100% больше здоровья."},
[1219832] = {name = "Душа кающегося", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой кающегося:\n\nСокращает время восстановления \"Исповеди\" на 6 сек."},
[1219833] = {name = "Душа духостража", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой духостража:\n\nУвеличивает количество урона, поглощаемого заклинанием \"Слово силы: Щит\", на 10%."},
[1219834] = {name = "Душа сумеречного странника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой сумеречного странника:\n\nВы можете применять \"Быстрое исцеление\" в облике Тьмы."},
[1219835] = {name = "Душа подчинителя разума", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой подчинителя разума:\n\nКритические удары \"Взрыва разума\" сокращают время поддержания следующей \"Пытки разума\" на 50% и увеличивают ее общий урон на 25%."},
[1219836] = {name = "Душа торговца смертью", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой торговца смертью:\n\nСокращает время восстановления \"Слова Тьмы: Смерть\" на 6 сек."},
[1219837] = {name = "Душа чаши духов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой чаши духов:\n\nУрон от \"Слова Тьмы: Боль\" вызывает срабатывание \"Захвата духа\" с вероятностью 2.0% за каждое очко таланта, вложенное в \"Захват духа\". Если цель погибает под действием вашего \"Слова Тьмы: Боль\", вы получаете \"Захват духа\" с вероятностью 20% за каждое вложенное очко талантов. \"Внутреннее сосредоточение\" также вызывает срабатывание \"Захвата духа\" с вероятностью 20% за каждое вложенное очко талантов."},
[1219838] = {name = "Душа фанатика", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой фанатика:\n\nПока действует \"Захват духа\", вы наносите на 25% больше урона от темной магии."},
[1219839] = {name = "Душа непреклонного осквернителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой непреклонного осквернителя:\n\nВремя действия \"Пытки разума\" больше не сокращается при получении урона. При активации \"Пытка разума\" теперь применяет к цели \"Пронзание разума\"."},
[1219840] = {name = "Душа презирающего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой презирающего:\n\n\"Пронзание разума\" теперь применяется мгновенно, наносит на 10% больше урона и может применяться во время поддержания другого заклинания."},
[1219841] = {name = "Душа чумного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой чумного:\n\nРуна \"Боль и страдание\" теперь обновляет время восстановления \"Всепожирающей чумы\"."},
[1219842] = {name = "Душа реверберирующего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой реверберирующего:\n\nВремя действия \"Темпорального маяка\" увеличивается на 20%."},
[1219843] = {name = "Душа хронолекаря", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хронолекаря:\n\nУвеличивает силу творимого темпорального исцеления на 10%."},
[1219844] = {name = "Душа временного порыва", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой временного порыва:\n\nКогда вы восполняете цели здоровье \"Регенерацией\", оставшееся время восстановления \"Перемотки времени\" сокращается на 1 сек."},
[1219845] = {name = "Душа предвидящего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой предвидящего:\n\nКогда ваши \"Чародейские стрелы\" наносят урон, они восполняют вам ману в объеме 10% своей базовой стоимости."},
[1219846] = {name = "Душа чародея", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой чародея:\n\n\"Чародейская вспышка\" вызывает срабатывание \"Заградительных стрел\" с увеличенной на 10% вероятностью. Кроме того, \"Заградительные стрелы\" теперь влияют на \"Регенерацию\" так же, как на \"Чародейские стрелы\"."},
[1219847] = {name = "Душа вечного смотрителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вечного смотрителя:\n\nТеперь \"Массовая регенерация\" применяет \"Темпоральный маяк\" на 21 сек."},
[1219848] = {name = "Душа чароплета", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой чароплета:\n\n\"Чародейская вспышка\" увеличивает наносимый урон еще на 10% за каждый эффект."},
[1219849] = {name = "Душа мастера защиты", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера защиты:\n\n\"Щит маны\", \"Защита от огня\" и \"Защита от магии льда\" поглощают на 50% больше урона и размещают рядом с целью темпоральный маяк. Время действия – 30 сек."},
[1219850] = {name = "Душа хватки зимы", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хватки зимы:\n\nПовышает вероятность срабатывания руны \"Ледяные пальцы\" еще на 15%."},
[1219851] = {name = "Душа криоманта", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой криоманта:\n\nУвеличивает урон от \"Ледяной стрелы\" и \"Стрелы чар льда\" на 75%."},
[1219852] = {name = "Душа пробудителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пробудителя:\n\nВы получаете невосприимчивость к урону на время поддержания \"Прилива сил\"."},
[1219853] = {name = "Душа повелителя стихий", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой повелителя стихий:\n\nНаносимый урон увеличивается на 1% на 15 сек., когда вы применяете заклинание новой школы."},
[1219854] = {name = "Душа магического бронника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой магического бронника:\n\n\"Магический доспех\" повышает скорость восстановления маны во время применения заклинаний еще на 15%. \"Раскаленный доспех\" увеличивает урон от заклинаний и силу исцеления на 18 ед. \"Ледяной доспех\" повышает вероятность срабатывания \"Ледяных пальцев\" на 20%."},
[1219855] = {name = "Душа возжигателя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой возжигателя:\n\nСнижает уровень угрозы, создаваемой вашими заклинаниями огня, на 20%."},
[1219856] = {name = "Душа огненного сопряжения", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой огненного сопряжения:\n\n\"Огненная глыба\" наносит на 20% больше урона целям, на которые действует ваш эффект периодического урона от \"Огненного шара\"."},
[1219857] = {name = "Душа вечного пламени", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вечного пламени:\n\nПериодический урон от \"Огненного шара\" увеличивается на 100% от его мгновенного урона."},
[1219858] = {name = "Душа пиромана", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пиромана:\n\n\"Огненный взрыв\" теперь также повышает вероятность критического удара следующего заклинания школы огня на 50% на 10 сек."},
[1219859] = {name = "Душа подпальщика", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой подпальщика:\n\nУвеличивает урон от таланта \"Воспламенение\" на 10%."},
[1219860] = {name = "Душа испепелителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой испепелителя:\n\nУрон от \"Огненного шара\", \"Стрелы ледяного огня\" и \"Стрелы гибельного огня\" увеличивается на 4% за каждый эффект огня, действующий на цель. Максимальная прибавка – 12%."},
[1219861] = {name = "Душа мастера блокирования", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера блокирования:\n\nУвеличивает показатель блокирования вашего щита на 30 ед."},
[1219862] = {name = "Душа хранителя света", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя света:\n\nКогда вы блокируете атаку, вы восполняете 189 в 211 ед. здоровья. Срабатывает раз в несколько секунд."},
[1219863] = {name = "Душа светозарного поборника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой светозарного поборника:\n\n\"Щит небес\" больше не имеет зарядов и теперь всегда действует до окончания времени действия. Кроме того, наносимый им урон увеличивается на 80% от показателя блокирования вашего щита."},
[1219864] = {name = "Душа щитоносца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой щитоносца:\n\n\"Щит небес\" повышает вероятность блокирования еще на 10%."},
[1219865] = {name = "Душа бастиона", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой бастиона:\n\nВо время действия \"Щита небес\" вы получаете на 10% меньше урона."},
[1219866] = {name = "Душа жаждущего расплаты", additional_info = "Применение: 3 сек\nТребуется: Наплечники"},
[1219867] = {name = "Душа броненосного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой броненосного:\n\nПри применении к себе \"Благословение неприкосновенности\" также повышает все характеристики на 10%."},
[1219868] = {name = "Душа хранителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя:\n\n\"Щит праведности\" усиливает следующий \"Свет небес\", в результате чего он применяется мгновенно. При применении к себе \"Свет небес\" возвращает ману в размере 100% затрат на применение и не взаимодействует с эффектом \"Под охраной света\"."},
[1219869] = {name = "Душа миротворца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой миротворца:\n\nВаши союзники вызывают срабатывание вашего \"Правосудия Света\" или \"Правосудия мудрости\" на 70% чаще."},
[1219870] = {name = "Душа искусного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой искусного:\n\nПовышает вероятность критического удара заклинаний и атак на 2%."},
[1219871] = {name = "Душа эталона", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой эталона:\n\nКогда ваши заклинания \"Вспышка Света\", \"Свет небес\" или \"Частица Света\" полностью исцеляют цель, вы также восполняете всем участникам ее группы 189 в 211 ед. здоровья."},
[1219872] = {name = "Душа инквизитора", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой инквизитора:\n\nПовышает вероятность критического эффекта \"Шока небес\" на 5%."},
[1219873] = {name = "Душа правителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой правителя:\n\nУвеличивает урон от \"Освящения\" на 50%."},
[1219874] = {name = "Душа властителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой властителя:\n\nЕсли \"Частица Света\" действует не на вас, цель \"Частицы Света\" восполняет здоровье в объеме 75% урона, наносимого вашими способностями \"Освящение\", \"Экзорцизм\", \"Шок небес\", \"Гнев небес\" и \"Молот гнева\"."},
[1219875] = {name = "Душа воздаятеля", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой воздаятеля:\n\nСокращает время восстановления \"Божественного света\" на 25%."},
[1219876] = {name = "Душа альтруиста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой альтруиста:\n\nКогда \"Частица Света\" исцеляет цель, находящийся поблизости раненый союзник получает 90% этого исцеления."},
[1219877] = {name = "Душа арбитра", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой арбитра:\n\nВаши заклинания \"Правосудие Света\" и \"Правосудие мудрости\" также дают эффект \"Правосудие воина Света\"."},
[1219878] = {name = "Душа носителя печати", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой носителя печати:\n\n\"Печать повиновения\", \"Печать праведности\", \"Печать мученичества\" и \"Солнечный свет\" наносят на 35% меньше урона, но продолжают действовать в течение 6 сек. после применения другой печати или до тех пор, пока вы не примените третью печать. \"Правосудие\" может вызывать срабатывание нескольких действующих печатей одновременно."},
[1219879] = {name = "Душа юстициария", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой юстициария:\n\n\"Правосудие\" наносит на 5% больше урона и больше не поглощает эффект печати. \"Правосудие\" может вызывать срабатывание нескольких печатей одновременно."},
[1219880] = {name = "Душа вершителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вершителя:\n\nСокращает время восстановления \"Правосудия\" на 5 сек., но уменьшает наносимый им урон на 45%."},
[1219881] = {name = "Душа перерожденного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой перерожденного:\n\n\"Правосудие\" увеличивает наносимый урон от светлой магии на 1% на 8 сек. Эффект суммируется до 5 раз."},
[1219882] = {name = "Душа мстящего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мстящего:\n\nУвеличивает урон от \"Удара воина Света\" на 150%."},
[1219883] = {name = "Душа отлучающего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой отлучающего:\n\nАвтоатаки двуручным оружием ближнего боя на 20 сек. увеличивают урон от следующего \"Экзорцизма\" на 35%. Эффект суммируется до 3 раз."},
[1219884] = {name = "Душа Светоносного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой Светоносного:\n\nУвеличивает урон от \"Шока небес\" на 50%."},
[1219885] = {name = "Душа изгнанника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой изгнанника:\n\nСокращает время восстановления \"Экзорцизма\" на 3 сек. и увеличивает наносимый им урон на 75%."},
[1219886] = {name = "Душа храмовника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой храмовника:\n\nПока вы используете одноручное оружие, \"Удар воина Света\" применяет эффекты печатей, вызываемые \"Правосудием\". При этом печать не поглощается."},
[1219887] = {name = "Душа ветрохода", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ветрохода:\n\nКогда вы уклоняетесь, парируете или блокируете атаку, ваша скорость атаки повышается на 30% на 3 удара."},
[1219888] = {name = "Душа мастера щита", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мастера щита:\n\nКогда вы парируете атаки или уклоняетесь от них, вы также активируете руническую способность \"Мастерское владение щитом\"."},
[1219889] = {name = "Душа тотемного защитника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой тотемного защитника:\n\n\"Тотем каменной кожи\" также уменьшает получаемый физический урон на 5%, а \"Тотем стены ветра\" также уменьшает получаемый магический урон на 5%."},
[1219890] = {name = "Душа шокового нейтрализатора", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой шокового нейтрализатора:\n\n\"Огненный шок\" также повышает вероятность блокирования на 30% на 5 сек. Действует до успешного блокирования."},
[1219891] = {name = "Душа духовного бастиона", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой духовного бастиона:\n\nКогда вы блокируете атаку, ваш показатель блокирования повышается на 10% от бонуса к урону от заклинаний на 6 сек. Эффект суммируется до 3 раз."},
[1219892] = {name = "Душа призывателя водоворота", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой призывателя водоворота:\n\nКогда вы блокируете атаку, с вероятностью 50% срабатывает руна \"Оружие Водоворота\"."},
[1219893] = {name = "Душа лавохода", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой лавохода:\n\nКогда \"Удар бури\", \"Выброс лавы\" или \"Всплеск лавы\" наносит цели урон, получаемый вами урон уменьшается на 10% на 10 сек."},
[1219894] = {name = "Душа истинного вожака", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой истинного вожака:\n\nПри применении к себе \"Дух вожака стаи\" также увеличивает максимальный запас здоровья на 5%, уровень создаваемой угрозы – на 25%, а наносимый урон – на 5%."},
[1219895] = {name = "Душа хранителя тотемов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя тотемов:\n\nРадиус действия тотемов, действующих на союзников, увеличивается до 40 м."},
[1219896] = {name = "Душа предков", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой предков:\n\nПосле применения \"Волны исцеления\", \"Малой волны исцеления\" или \"Быстрины\" вы с вероятностью 25% восполняете ману в объеме 35% базовой стоимости заклинания."},
[1219897] = {name = "Душа заклинателя душ", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой заклинателя душ:\n\n\"Волна исцеления\" переходит на дополнительные находящиеся рядом цели. Каждый из 2 возможных переходов ослабляет эффект на 60%."},
[1219898] = {name = "Душа водохода", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой водохода:\n\nКритические эффекты наносящих урон и исцеляющих непериодических способностей теперь с вероятностью 100% вызывают срабатывание вашего \"Водного щита\", не поглощая заряд и не запуская время восстановления."},
[1219899] = {name = "Душа хранителя бури", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя бури:\n\n\"Цепная молния\" теперь также восполняет последней цели \"Щита земли\" здоровье в объеме 100% нанесенного урона."},
[1219900] = {name = "Душа провидца стихий", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой провидца стихий:\n\nУсиливает исцеление \"Цепного исцеления\" и увеличивает урон от \"Цепной молнии\" на 20%."},
[1219901] = {name = "Душа виталиста", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой виталиста:\n\n\"Быстрина\" повышает объем исцеления от \"Цепного исцеления\" еще на 25%."},
[1219902] = {name = "Душа целителя духов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой целителя духов:\n\nСокращает время произнесения \"Цепного исцеления\" на 0.5 сек."},
[1219903] = {name = "Душа искусного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой искусного:\n\nПовышает вероятность критического удара заклинаний и атак на 2%."},
[1219904] = {name = "Душа вождя", additional_info = "Применение: 3 сек\nТребуется: Наплечники"},
[1219905] = {name = "Душа исполненного ярости", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой исполненного ярости:\n\nВероятность срабатывания \"Статического шока\" повышается на 12% (на 6%, если вы сражаетесь с оружием в обеих руках)."},
[1219906] = {name = "Душа рассекателя туч", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой рассекателя туч:\n\nУвеличивает наносимый \"Ударом бури\" урон от оружия в правой руке на 50%."},
[1219907] = {name = "Душа урагана", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой урагана:\n\nПока у вас выгравирована руна \"Статический шок\", \"Щит молний\" накапливает заряд каждый раз, когда вы поражаете цель \"Молнией\" или \"Цепной молнией\". Максимальное количество зарядов – 9. Кроме того, пока у вас выгравирована руна \"Статический шок\", \"Щит молний\" может наносить критический урон."},
[1219908] = {name = "Душа сейсмического крушителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой сейсмического крушителя:\n\nУвеличивает урон от \"Удара бури\" и \"Вскипания лавы\" на 50%. Бонус увеличивается до 100%, когда вы используете двуручное оружие."},
[1219909] = {name = "Душа пламеносца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пламеносца:\n\nКритические удары \"Удара бури\", \"Вскипания лавы\" и \"Выброса лавы\" поджигают цель, нанося еще 30% урона за 4 сек."},
[1219910] = {name = "Душа вулкана", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой вулкана:\n\nКритические удары \"Молнии\" с вероятностью 35% восстанавливают \"Выброс лавы\" и \"Цепную молнию\", а также позволяют мгновенно применить следующий \"Выброс лавы\" или \"Цепную молнию\" в течение 10 сек."},
[1219911] = {name = "Душа неистового пламени", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой неистового пламени:\n\n\"Выброс лавы\" теперь также обновляет время действия \"Огненного шока\" на цели до 12 сек."},
[1219912] = {name = "Душа властелина стихий", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой властелина стихий:\n\nТеперь критические эффекты ваших заклинаний с вероятностью 100% вызывают срабатывание таланта \"Средоточие стихий\"."},
[1219913] = {name = "Душа защитника рода", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой защитника рода:\n\nЭффект \"Верный помощник\", полученный от способности \"Дух вожака стаи\", теперь также увеличивает урон от огня, магии льда и сил природы на 5 + (5 * Серия приёмов)%."},
[1219914] = {name = "Душа духовного проводника", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой духовного проводника:\n\nПока действует \"Ясность мысли\", наносимый вами нефизический урон увеличивается на 15 + (5 * Серия приёмов)%."},
[1219915] = {name = "Душа старейшины", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой старейшины:\n\nПрименение \"Молнии\", \"Цепной молнии\" или \"Выброса лавы\" с вероятностью 70% не прерывается уроном, а вероятность вызвать срабатывание таланта \"Концентрация стихий\" повышается на 10%."},
[1219916] = {name = "Душа стихий", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой стихий:\n\nУвеличивает бонус к критическому урону от заклинаний огня, магии льда и сил природы на 60%."},
[1219917] = {name = "Душа лавового мудреца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой лавового мудреца:\n\nУрон от \"Выброса лавы\" увеличивается на вероятность критического удара заклинаний."},
[1219918] = {name = "Душа древнего стража", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой древнего стража:\n\nПовышает вероятность блокирования атак щитом на 10%."},
[1219919] = {name = "Душа оскверненного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой оскверненного:\n\nПовышает вероятность срабатывания руны \"Выброс энергии\" еще на 5%."},
[1219920] = {name = "Душа мягкой лапы", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой мягкой лапы:\n\nВы можете применять \"Возрождение\" и \"Озарение\" в облике медведя или лютого медведя."},
[1219921] = {name = "Душа свирепого", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой свирепого:\n\nСокращает время восстановления \"Исступления\" на 30 сек. \"Исступление\" больше не ослабляет вашу броню."},
[1219922] = {name = "Душа оборотня", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой оборотня:\n\nОблики медведя и лютого медведя повышают уровень создаваемой вами угрозы еще на 20%. Способность \"Попятиться\" сбрасывает уровень угрозы по отношению к цели, но время восстановления способности увеличивается на 20 сек."},
[1219923] = {name = "Душа защитника территории", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой защитника территории:\n\nПосле применения способности \"Размах (медведь)\" ваша \"Трепка\" поражает еще 1 цель в течение 6 сек."},
[1219924] = {name = "Душа зверя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой зверя:\n\nВероятность критического удара способностей \"Увечье (медведь)\", \"Размах (медведь)\", \"Трепка\" и \"Растерзать\" повышается на 5% против целей, на которые действует ваш эффект \"Растерзать\"."},
[1219925] = {name = "Душа терзающего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой терзающего:\n\n\"Размах\" теперь распространяет эффект \"Растерзать\", действующий на основную цель, на остальные пораженные цели."},
[1219926] = {name = "Душа неистового", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой неистового:\n\nКогда вы уклоняетесь, находясь в облике лютого медведя, урон от следующего \"Увечья\" или \"Размаха\" увеличивается на 10%. Эффект суммируется до 5 раз."},
[1219927] = {name = "Душа увечащего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой увечащего:\n\nСокращает время восстановления \"Увечья (медведь)\" на 1.5 сек."},
[1219928] = {name = "Душа озаряющего", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой озаряющего:\n\nКогда вы применяете \"Озарение\" к другому игроку, вы также получаете этот эффект."},
[1219929] = {name = "Душа покровителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой покровителя:\n\nПосле применения \"Целительного прикосновения\" или \"Покровительства природы\" вы с вероятностью 25% восполняете ману в объеме 35% базовой стоимости заклинания."},
[1219930] = {name = "Душа спокойствия", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой спокойствия:\n\nСокращает время восстановления \"Безмятежности\" на 100%. \"Безмятежность\" восстанавливает на 100% больше здоровья."},
[1219931] = {name = "Душа сновидца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой сновидца:\n\nКритические эффекты исцеляющих заклинаний дают вам эффект \"Состояние сна\", позволяющий восполнять ману во время применения заклинаний со скоростью 50% от обычной в течение 8 сек."},
[1219932] = {name = "Душа хранительницы рощи", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранительницы рощи:\n\nНепериодические критические эффекты заклинаний сокращают время применения следующего \"Целительного прикосновения\", \"Покровительства природы\" или \"Восстановления\" на 0.5 сек."},
[1219933] = {name = "Душа пернатого мудреца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой пернатого мудреца:\n\nУсиливает исцеление от \"Буйного роста\" на 10%. Кроме того, теперь вы можете применять \"Буйный рост\" в облике лунного совуха, и в этом облике исцеление от \"Буйного роста\" усиливается еще на 50%."},
[1219934] = {name = "Душа благодушного провидца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой благодушного провидца:\n\nСокращает время восстановления \"Возрождения\" и \"Озарения\" на 65%."},
[1219935] = {name = "Душа ткача жизни", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ткача жизни:\n\nКритические эффекты исцеления от \"Целительного прикосновения\", \"Восстановления\" и \"Покровительства природы\" мгновенно восполняют цели дополнительный объем здоровья, равный 50% совершенного исцеления."},
[1219936] = {name = "Душа озаряющего света", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой озаряющего света:\n\n\"Волшебный огонь (сила зверя)\" также повышает вероятность попадания атак, направленных против цели, на 1% на 40 сек."},
[1219937] = {name = "Душа хищного инстинкта", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хищного инстинкта:\n\nПериодический урон от ваших способностей \"Глубокая рана\" и \"Разорвать\" теперь может быть критическим."},
[1219938] = {name = "Душа потрошителя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой потрошителя:\n\nВаши способности \"Разорвать\" и \"Свирепый укус\" с вероятностью 20% за каждый потраченный прием серии обновляют время действия \"Дикого рева\" до изначального."},
[1219939] = {name = "Душа когтя", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой когтя:\n\nПродлевает время действия \"Глубокой раны\" на 3 сек. и увеличивает наносимый ею периодический урон на 10%."},
[1219940] = {name = "Душа гордыни", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой гордыни:\n\nВо время действия \"Тигриного неистовства\" ваша вероятность критического удара повышается на 15%."},
[1219941] = {name = "Душа варварства", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой варварства:\n\nСпособности \"Полоснуть\", \"Свирепый укус\" и \"Увечье (кошка)\" наносят на 10% больше урона за каждый ваш эффект кровотечения, действующий на цель. Максимальный бонус – 20%."},
[1219942] = {name = "Душа исступления", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой исступления:\n\n\"Полоснуть\" теперь может применяться с любой позиции, но наносит на 5% больше урона, если вы находитесь позади цели."},
[1219943] = {name = "Душа кровососа", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой кровососа:\n\nКритические удары \"Увечья\", \"Полоснуть\" и \"Свирепого укуса\" вызывают у цели кровотечение, наносящее урон в объеме 30% нанесенного урона, в течение 4 сек сек."},
[1219944] = {name = "Душа хранителя шипов", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителя шипов:\n\nУвеличивает урон от \"Шипов\" на 100% и продлевает время действия на 200%."},
[1219945] = {name = "Душа безумца", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой безумца:\n\nВероятность попадания заклинаниями и атаками повышена на 3%."},
[1219946] = {name = "Душа призывателя звезд", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой призывателя звезд:\n\nВремя восстановления \"Звездопада\" сокращается на 50%."},
[1219947] = {name = "Душа ночи", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой ночи:\n\nУвеличивает урон и радиус поражения звезд \"Звездопада\" и \"Грозы\" на 25%."},
[1219948] = {name = "Душа хранителей", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой хранителей:\n\nВаш \"Гнев\" с вероятностью 10% призывает 3 древней, атакующих:древней, атакующих вашу цель в течение 15 сек."},
[1219949] = {name = "Душа разгневанного", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой разгневанного:\n\nКритические удары \"Гнева\" с вероятностью 50% увеличивают урон от следующего \"Звездного огня\" на 10%. Эффект суммируется до 3 раз."},
[1219950] = {name = "Душа благоволения", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой благоволения:\n\nПри каждом срабатывании талант \"Благоволение природы\" получает еще 1 дополнительный снаряд."},
[1219951] = {name = "Душа восходящей звезды", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой восходящей звезды:\n\nУвеличивает бонус к критическому урону от \"Звездного огня\", \"Звездного потока\" и \"Гнева\" на 60%."},
[1219952] = {name = "Душа призывателя комет", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой призывателя комет:\n\nСокращает время применения и общее время восстановления \"Звездного огня\" на 0.5 сек."},
[1219953] = {name = "Душа леса", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой леса:\n\nПовышает вероятность критического удара \"Гнева\" на 10%."},
[1219954] = {name = "Душа звериного мастерства", additional_info = "Применение: 3 сек\nТребуется: Наплечники\n[q]Навсегда усилить наплечники душой звериного мастерства:\n\nСнижает вероятность того, что цель парирует ваши атаки в ближнем бою или уклонится от них, на 5%."},
[1219955] = {name = "Гравировка душ", additional_info = "Мгновенное действие\n[q]В этой ячейке можно выгравировать душу павшего воителя."},
[1219956] = {name = "Душа тактика", additional_info = nil},
[1219957] = {name = "Душа тактика", additional_info = "[q]После смены стойки затраты ярости на применение следующей атакующей способности снижаются на 10."},
[1219958] = {name = "Душа ветерана войны", additional_info = "[q]В течение 15 сек. после выхода из любой стойки вы можете по-прежнему применять способности, требующие данную стойку."},
[1219959] = {name = "Душа ветерана войны", additional_info = nil},
[1219960] = {name = "Душа предсказателя битв", additional_info = "[q]В течение первых 15 сек. после активации стойки вы получаете дополнительный бонус:\n\n \"Боевая стойка\"/\"Стойка гладиатора\": наносимый урон увеличивается на 5%.\n\n \"Стойка берсерка\": вероятность критического удара повышается на 5%.\n\n \"Защитная стойка\": получаемый физический урон уменьшается на 5%."},
[1219961] = {name = "Душа предсказателя битв", additional_info = nil},
[1219962] = {name = "Душа алчущего крови", additional_info = "[q]Критические удары \"Превосходства\" продлевают время действия \"Кровопускания\" на цели до максимального."},
[1219963] = {name = "Душа алчущего крови", additional_info = nil},
[1219964] = {name = "Душа титана", additional_info = "[q]\"Удар героя\", \"Мощный удар\" и \"Превосходство\" наносят на 10 + (5 * Серия приёмов)% больше урона."},
[1219965] = {name = "Душа титана", additional_info = nil},
[1219966] = {name = "Душа разрушителя", additional_info = "[q]\"Мощный удар\" мгновенно восстанавливает \"Смертельный удар\", \"Кровожадность\" и \"Мощный удар щитом\"."},
[1219967] = {name = "Душа разрушителя", additional_info = nil},
[1219968] = {name = "Душа заклинателя смерти", additional_info = "[q]Сокращает время восстановления \"Инстинкта смерти\" на 50%."},
[1219969] = {name = "Душа заклинателя смерти", additional_info = nil},
[1219970] = {name = "Душа кровопускателя", additional_info = "[q]Вы наносите на 15% больше урона, пока хотя бы на одного ближайшего противника одновременно действуют ваши эффекты \"Кровопускание\" и \"Глубокие раны\"."},
[1219971] = {name = "Душа кровопускателя", additional_info = nil},
[1219972] = {name = "Душа мастера блокирования", additional_info = "[q]Увеличивает показатель блокирования вашего щита на 30 ед."},
[1219973] = {name = "Душа мастера блокирования", additional_info = nil},
[1219974] = {name = "Душа дикости", additional_info = "[q]Когда вы получаете урон или совершаете автоатаку, вы накапливаете еще 1 ед. ярости."},
[1219975] = {name = "Душа дикости", additional_info = nil},
[1219976] = {name = "Душа вражды", additional_info = "[q]Увеличивает угрозу, создаваемую вами в \"Защитной стойке\", еще на 10% и увеличивает наносимый урон в \"Стойке гладиатора\" на 4%."},
[1219977] = {name = "Душа вражды", additional_info = nil},
[1219978] = {name = "Душа отражателя", additional_info = "[q]Когда вы парируете атаку противника или противник парирует вашу, вы накапливаете 10 ед. ярости."},
[1219979] = {name = "Душа отражателя", additional_info = nil},
[1219980] = {name = "Душа мстителя", additional_info = "[q]\"Реванш\" также дает вам \"Шквал\", повышающий скорость атаки на 30% на 3 удара:ударов."},
[1219981] = {name = "Душа мстителя", additional_info = nil},
[1219982] = {name = "Душа неутомимого", additional_info = "[q]Когда ваша цель парирует атаку, вы мгновенно применяете \"Возмездие\", нанося цели 200% урона от оружия. \"Возмездие\" нельзя заблокировать или парировать, и от него нельзя уклониться. Срабатывает против каждой цели не чаще раза в 30 сек."},
[1219983] = {name = "Душа неутомимого", additional_info = nil},
[1219984] = {name = "Душа громоносца", additional_info = "[q]Сокращает время восстановления \"Удара грома\" на 100%."},
[1219985] = {name = "Душа громоносца", additional_info = nil},
[1219986] = {name = "Душа часового", additional_info = "[q]Если цель парирует, блокирует ваше \"Сокрушение щитом\" или уклоняется от него, создаваемый им уровень угрозы повышается на 100%, а его время восстановления обновляется."},
[1219987] = {name = "Душа часового", additional_info = nil},
[1219988] = {name = "Душа бойца-левши", additional_info = "[q]Сокращает время восстановления \"Мощного удара щитом\" на 2 сек."},
[1219989] = {name = "Душа бойца-левши", additional_info = nil},
[1219990] = {name = "Душа гладиатора", additional_info = "[q]Сокращает время восстановления \"Кровавой ярости\", пока вы используете \"Стойку гладиатора\", на 30 сек."},
[1219991] = {name = "Душа гладиатора", additional_info = nil},
[1219992] = {name = "Душа повторного толчка", additional_info = "[q]Сокращает время восстановления \"Ударной волны\" на 25%."},
[1219993] = {name = "Душа повторного толчка", additional_info = nil},
[1219994] = {name = "Душа избегающего", additional_info = "[q]\"Ложный выпад\" также на 6 сек. дает \"Избежание\", уменьшающее получаемый урон от атак по области на 50%. Не действует на атаки, примененные игроками."},
[1219995] = {name = "Душа избегающего", additional_info = nil},
[1219996] = {name = "Душа токсиколога", additional_info = "[q]Увеличивает критический урон от ядов на 100%."},
[1219997] = {name = "Душа токсиколога", additional_info = nil},
[1219998] = {name = "Душа палача", additional_info = "[q]С вероятностью 5% за каждый прием в серии ваш завершающий прием позволяет применить следующую способность без затрат энергии."},
[1219999] = {name = "Душа палача", additional_info = nil},
[1220000] = {name = "Душа оппортуниста", additional_info = "[q]Приемы, начинающие серию, с вероятностью 100% позволяют применить следующую способность без затрат энергии."},
[1220001] = {name = "Душа оппортуниста", additional_info = nil},
[1220002] = {name = "Душа мясника", additional_info = "[q]Ваше оружие в правой руке наносит на 20% больше урона от умений, продлевающих серию приемов."},
[1220003] = {name = "Душа мясника", additional_info = nil},
[1220004] = {name = "Душа фантома", additional_info = "[q]Сокращает время восстановления \"Исчезновения\" до 1 мин. Данный эффект не суммируется с эффектом \"Неуловимости\"."},
[1220005] = {name = "Душа фантома", additional_info = nil},
[1220006] = {name = "Душа пройдохи", additional_info = "[q]Увеличивает урон от \"Расправы\" и \"Удара саблей\" на 20%."},
[1220007] = {name = "Душа пройдохи", additional_info = nil},
[1220008] = {name = "Душа экстремала", additional_info = "[q]Сокращает время восстановления \"Выброса адреналина\" на 4 мин."},
[1220009] = {name = "Душа экстремала", additional_info = nil},
[1220010] = {name = "Душа гения клинка", additional_info = "[q]Повышает вероятность критического удара при использовании кинжалов на 5%."},
[1220011] = {name = "Душа гения клинка", additional_info = nil},
[1220012] = {name = "Душа ловчего", additional_info = "[q]Повышает вероятность критического эффекта \"Внезапного удара\" на 30%."},
[1220013] = {name = "Душа ловчего", additional_info = nil},
[1220014] = {name = "Душа деятельного", additional_info = "[q]Завершающие приемы расходуют на 50% меньше энергии."},
[1220015] = {name = "Душа деятельного", additional_info = nil},
[1220016] = {name = "Душа жонглера клинками", additional_info = "[q]Пока действуют эффекты \"Просто царапина\" и \"Танец клинков\", ваши способности \"Кровавый вихрь\", \"Мушкетон\" и \"Веер клинков\" расходуют на 20 ед. меньше энергии и создают на 100% больше угрозы."},
[1220017] = {name = "Душа жонглера клинками", additional_info = nil},
[1220018] = {name = "Душа повелителя теней", additional_info = "[q]Во время действия \"Исчезновения\" получаемый магический урон уменьшается на 50%. \"Исчезновение\" больше не дает незаметность и не снимает затрудняющие передвижение эффекты."},
[1220019] = {name = "Душа повелителя теней", additional_info = nil},
[1220020] = {name = "Душа эквилибриста", additional_info = "[q]Завершающие приемы с вероятностью 20% за каждый израсходованный прием серии уменьшают получаемый физический урон от следующей атаки ближнего боя на 20% на 10 сек."},
[1220021] = {name = "Душа эквилибриста", additional_info = nil},
[1220022] = {name = "Душа сосредоточенного борца", additional_info = "[q]Эффект \"Держать удар\" теперь также срабатывает каждый раз, когда вы увеличиваете длину серии приемов."},
[1220023] = {name = "Душа черного пояса", additional_info = "[q]Каждый эффект \"Держать удар\" также усиливает бонус к броне от предметов на 20% вплоть до 100%."},
[1220024] = {name = "Душа сосредоточенного борца", additional_info = nil},
[1220025] = {name = "Душа черного пояса", additional_info = nil},
[1220026] = {name = "Душа фехтовальщика", additional_info = "[q]Когда цель уклоняется от атаки или парирует ее, ваш \"Главный аргумент\" мгновенно восстанавливается."},
[1220027] = {name = "Душа фехтовальщика", additional_info = nil},
[1220028] = {name = "Душа сорвиголовы", additional_info = "[q]\"Главный аргумент\" поражает еще 1 находящуюся рядом цель и усиливает \"Коварный удар\", позволяя ему поражать еще 1 находящуюся рядом цель в течение 10 сек. \"Шквал клинков\" не дублирует эти дополнительные удары."},
[1220029] = {name = "Душа сорвиголовы", additional_info = nil},
[1220030] = {name = "Душа кровожадного", additional_info = "[q]Пока действует \"Главный аргумент\", вы восполняете здоровье в объеме 15% урона, нанесенного \"Коварным ударом\". Избыточное исцеление превращается в \"Кровяной барьер\", поглощающий урон в объеме до 20% вашего максимального запаса здоровья."},
[1220031] = {name = "Душа кровожадного", additional_info = nil},
[1220032] = {name = "Душа преобразователя", additional_info = "[q]\"Жизнеотвод\" дает на 50% больше маны и создает на 100% меньше угрозы."},
[1220033] = {name = "Душа преобразователя", additional_info = nil},
[1220034] = {name = "Душа искусного", additional_info = "[q]Повышает вероятность критического удара заклинаний и атак на 2%."},
[1220035] = {name = "Душа истребителя", additional_info = "[q]Вероятность срабатывания таланта \"Сумерки\" повышается на 4%. \"Испепеление\" с вероятностью 4% применяет \"Истребление\" к целям с любым уровнем здоровья."},
[1220036] = {name = "Душа искусного", additional_info = nil},
[1220037] = {name = "Душа истребителя", additional_info = nil},
[1220038] = {name = "Душа гноителя", additional_info = "[q]Увеличивает периодический урон от ваших заклинаний и урон вашего стража Скверны на 10 + (5 * Серия приёмов)%."},
[1220039] = {name = "Душа гноителя", additional_info = nil},
[1220040] = {name = "Душа злонамеренного", additional_info = "[q]Периодический урон от ваших заклинаний \"Пламя Тьмы\", \"Нестабильное колдовство\" и \"Проклятие агонии\", а также урон вашего стража Скверны с вероятностью 4% вводят вас в теневой транс."},
[1220041] = {name = "Душа злонамеренного", additional_info = nil},
[1220042] = {name = "Душа тенеманта", additional_info = "[q]\"Стрела Тьмы\" наносит на 10 + (5 * Серия приёмов)% больше урона за каждый ваш эффект, действующий на цель. Максимальный бонус – 30 + (5 * Серия приёмов)%."},
[1220043] = {name = "Душа тенеманта", additional_info = nil},
[1220044] = {name = "Душа вестника хаоса", additional_info = "[q]Сокращает время восстановления \"Стрелы Хаоса\" на 50% и увеличивает урон от \"Стрелы Хаоса\" и \"Стрелы Тьмы\" на 10%. Кроме того, \"Стрела Хаоса\" теперь может вызвать срабатывание таланта \"Улучшенная стрела Тьмы\" и повышает число его зарядов на 26 (не суммируется с дополнительными зарядами \"Пламени Тьмы\")."},
[1220045] = {name = "Душа вестника хаоса", additional_info = nil},
[1220046] = {name = "Душа поджигателя", additional_info = "[q]Когда вы поражаете цель \"Поджиганием\", наносимый вами урон от огня увеличивается на 5% на 20 сек. Эффект суммируется до 2 раз."},
[1220047] = {name = "Душа поджигателя", additional_info = nil},
[1220048] = {name = "Душа инфернального пастыря", additional_info = "[q]Увеличивает прибавки к силе атаки и урону от заклинаний, которые ваш демон получает от ваших характеристик, на 20%."},
[1220049] = {name = "Душа инфернального пастыря", additional_info = nil},
[1220050] = {name = "Душа владыки демонов", additional_info = "[q]Усиливает эффект таланта \"Мастер-демонолог\" на 50%."},
[1220051] = {name = "Душа владыки демонов", additional_info = nil},
[1220052] = {name = "Душа демонического экзорциста", additional_info = "[q]\"Изгнание\" теперь применяется мгновенно, и вы можете применить его к себе, когда находитесь в облике демона. \"Изгнание\" дает вам \"Воздержанность\" на 1 мин, но вы не можете применить \"Изгнание\" к себе, если на вас уже действует \"Воздержанность\"."},
[1220053] = {name = "Душа демонического экзорциста", additional_info = nil},
[1220054] = {name = "Душа страдальца", additional_info = "[q]Когда вы получаете урон, вы и ваш прислужник восполняете ману в объеме полученного урона вплоть до 420 ед. Срабатывает раз в несколько секунд."},
[1220055] = {name = "Душа страдальца", additional_info = nil},
[1220056] = {name = "Душа огненного призрака", additional_info = "[q]Каждое попадание \"Теневого рассекающего удара\" с вероятностью 20% дает вам осколок души, мгновенно восстанавливает \"Ожог души\" и позволяет мгновенно применить следующий \"Ожог души\" в течение 10 сек."},
[1220057] = {name = "Душа огненного призрака", additional_info = nil},
[1220058] = {name = "Душа пожирателя плоти", additional_info = "[q]Если вы выбрали целью противника в радиусе 30 м, \"Жизнеотвод\" восполняет вам ману за счет здоровья противника, но при этом наносит ему на 50 + (5 * Серия приёмов)% меньше урона. Количество восполняемой маны остается без изменений."},
[1220059] = {name = "Душа пожирателя плоти", additional_info = nil},
[1220060] = {name = "Душа абиссала", additional_info = "[q]Во время действия \"Метаморфозы\" ваши атакующие способности и призыв демонов не требуют осколков души. Кроме того, когда ваш \"Ожог Тьмы\" наносит урон, вы восполняете 15% максимального запаса здоровья."},
[1220061] = {name = "Душа абиссала", additional_info = nil},
[1220062] = {name = "Душа порожденного Бездной", additional_info = "[q]Эффекты избыточного самоисцеления преобразуются в поглощающий урон щит. Прочность щита суммируется и может достигать до 30 + (5 * Серия приёмов)% максимального запаса здоровья."},
[1220063] = {name = "Душа порожденного Бездной", additional_info = nil},
[1220064] = {name = "Душа теневого клинка", additional_info = "[q]Сокращает время восстановления \"Теневого рассекающего удара\" на 1.5 сек."},
[1220065] = {name = "Душа теневого клинка", additional_info = nil},
[1220066] = {name = "Душа ритуалиста", additional_info = "[q]Эффекты \"Демонического жертвоприношения\" продолжают действовать, пока с вами активный прислужник-демон, но прекращаются, если вы призываете пожертвованного демона. Единовременно может действовать только один эффект \"Демонического жертвоприношения\"."},
[1220067] = {name = "Душа ритуалиста", additional_info = nil},
[1220068] = {name = "Душа дарующего боль", additional_info = "[q]В течение 6 сек. после того как вы применяете \"Теневой рассекающий удар\", \"Жгучая боль\" поражает 1 дополнительную цель в области ближнего боя."},
[1220069] = {name = "Душа дарующего боль", additional_info = nil},
[1220070] = {name = "Душа ловкача", additional_info = "[q]Вы создаете на 100% больше угрозы в течение 8 сек. после применения \"Отвлекающего выстрела\"."},
[1220071] = {name = "Душа ловкача", additional_info = nil},
[1220072] = {name = "Душа добытчика", additional_info = "[q]Когда вы выслеживаете существ, вы наносите существам выслеживаемой категории на 3% больше урона."},
[1220073] = {name = "Душа добытчика", additional_info = nil},
[1220074] = {name = "Душа стрелка", additional_info = "[q]В течение 12 сек. после применения \"Прицельного выстрела\" ваша следующая способность-выстрел наносит на 20% больше урона."},
[1220075] = {name = "Душа стрелка", additional_info = nil},
[1220076] = {name = "Душа опасного разорителя", additional_info = "[q]\"Прицельный выстрел\" наносит на 20% больше урона целям, на которые действуют эффекты ваших ловушек."},
[1220077] = {name = "Душа опасного разорителя", additional_info = nil},
[1220078] = {name = "Душа переменчивого", additional_info = "[q]Ваши наносящие урон способности категории \"Выстрел\" усиливают следующий наносящий урон \"Выстрел\" другого типа на 10%."},
[1220079] = {name = "Душа переменчивого", additional_info = nil},
[1220080] = {name = "Душа знатока токсинов", additional_info = "[q]\"Укус змеи\" наносит дополнительный урон в объеме 25% вашей силы атаки."},
[1220081] = {name = "Душа знатока токсинов", additional_info = nil},
[1220082] = {name = "Душа охотника за головами", additional_info = "[q]\"Убийственный выстрел\" наносит целям, не контролируемым игроками, на 10% больше урона."},
[1220083] = {name = "Душа охотника за головами", additional_info = nil},
[1220084] = {name = "Душа виртуоза стрельбы", additional_info = "[q]Время восстановления \"Убийственного выстрела\" сокращается на 50%. Пока у вас выгравирована руна \"Быстрые убийства\" и действует \"Быстрая стрельба\", \"Убийственный выстрел\" не требует времени на восстановление, а против целей, не находящихся под контролем игроков, срабатывает еще 3 раза:раз, нанося 30% урона на минимальном расстоянии."},
[1220085] = {name = "Душа виртуоза стрельбы", additional_info = nil},
[1220086] = {name = "Душа хранителя зверей", additional_info = "[q]Увеличивает прибавку к силе атаки, которую ваш питомец получает от ваших характеристик, на 20%."},
[1220087] = {name = "Душа хранителя зверей", additional_info = nil},
[1220088] = {name = "Душа псаря", additional_info = "[q]Повышает скорость восстановления концентрации вашего питомца на 20%."},
[1220089] = {name = "Душа псаря", additional_info = nil},
[1220090] = {name = "Душа мастера-укротителя", additional_info = "[q]Ускоряет восстановления тонуса ваших питомцев на 100%."},
[1220091] = {name = "Душа мастера-укротителя", additional_info = nil},
[1220092] = {name = "Душа охотника", additional_info = "[q]\"Укус мангуста\" также снижает вероятность уклонения цели на 1% и повышает вашу вероятность попадания на 1% на 30 сек."},
[1220093] = {name = "Душа охотника", additional_info = nil},
[1220094] = {name = "Душа карателя", additional_info = "[q]\"Укус мангуста\" также активируется на 5 сек., когда ваша цель парирует или блокирует вашу атаку, а также когда вы промахиваетесь атакой ближнего боя."},
[1220095] = {name = "Душа карателя", additional_info = nil},
[1220096] = {name = "Душа отголосков", additional_info = "[q]\"Удар ящера\" увеличивает урон от следующей другой способности ближнего боя (кроме \"Подрезать крылья\") на 20% на 5 сек."},
[1220097] = {name = "Душа отголосков", additional_info = nil},
[1220098] = {name = "Душа смертоносного бичевателя", additional_info = "[q]Ваше оружие в правой руке наносит на 20% больше урона при \"Ударе ящера\" и \"Ударе виверны\"."},
[1220099] = {name = "Душа смертоносного бичевателя", additional_info = nil},
[1220100] = {name = "Душа мастера кинетики", additional_info = "[q]Ваш периодический урон с вероятностью 5% мгновенно восстанавливает одну из способностей категории \"Удар\". Восстанавливается способность с наибольшим текущим временем восстановления."},
[1220101] = {name = "Душа мастера кинетики", additional_info = nil},
[1220102] = {name = "Душа стратега", additional_info = "[q]Увеличивает периодический урон от \"Удара виверны\" на 50%, а максимальный запас концентрации питомца – на 50 ед."},
[1220103] = {name = "Душа стратега", additional_info = nil},
[1220104] = {name = "Душа смертоносного нападающего", additional_info = "[q]Увеличивает мгновенный урон от \"Укуса мангуста\" и всех способностей-ударов или бросков на 20%."},
[1220105] = {name = "Душа смертоносного нападающего", additional_info = nil},
[1220106] = {name = "Душа скорого лекаря", additional_info = "[q]Время применения \"Быстрого исцеления\" сокращается на 0.1 сек., а время применения \"Большего исцеления\" – на 0.2 сек."},
[1220107] = {name = "Душа скорого лекаря", additional_info = nil},
[1220108] = {name = "Душа искусного", additional_info = "[q]Повышает вероятность критического удара заклинаний и атак на 2%."},
[1220109] = {name = "Душа искусного", additional_info = nil},
[1220110] = {name = "Душа торжествующего", additional_info = "[q]Повышает вероятность критического эффекта \"Молитвы исцеления\" и \"Круга исцеления\" на 25%."},
[1220111] = {name = "Душа торжествующего", additional_info = nil},
[1220112] = {name = "Душа преданного", additional_info = "[q]Во время применения заклинаний мана восполняется со скоростью 15% от обычной."},
[1220113] = {name = "Душа преданного", additional_info = nil},
[1220114] = {name = "Душа непредсказуемого", additional_info = "[q]Эффекты периодического исцеления с вероятностью 2% позволяют мгновенно применить следующее заклинание с временем применения менее 10 сек."},
[1220115] = {name = "Душа непредсказуемого", additional_info = nil},
[1220116] = {name = "Душа откликнувшегося", additional_info = "[q]\"Круг исцеления\" и \"Исповедь\" дополнительно восполняют целям 25% здоровья за 15 сек."},
[1220117] = {name = "Душа откликнувшегося", additional_info = nil},
[1220118] = {name = "Душа приверженца", additional_info = "[q]Количество зарядов \"Молитвы восстановления\" увеличивается на 2."},
[1220119] = {name = "Душа приверженца", additional_info = nil},
[1220120] = {name = "Душа архиепископа", additional_info = "[q]\"Круг исцеления\" теперь восполняет наиболее серьезно раненому участнику группы на 100% больше здоровья."},
[1220121] = {name = "Душа архиепископа", additional_info = nil},
[1220122] = {name = "Душа кающегося", additional_info = "[q]Сокращает время восстановления \"Исповеди\" на 6 сек."},
[1220123] = {name = "Душа кающегося", additional_info = nil},
[1220124] = {name = "Душа духостража", additional_info = "[q]Увеличивает количество урона, поглощаемого заклинанием \"Слово силы: Щит\", на 10%."},
[1220125] = {name = "Душа духостража", additional_info = nil},
[1220126] = {name = "Душа сумеречного странника", additional_info = "[q]Вы можете применять \"Быстрое исцеление\" в облике Тьмы."},
[1220127] = {name = "Душа сумеречного странника", additional_info = nil},
[1220128] = {name = "Душа подчинителя разума", additional_info = "[q]Критические удары \"Взрыва разума\" сокращают время поддержания следующей \"Пытки разума\" на 50% и увеличивают ее общий урон на 25%."},
[1220129] = {name = "Душа подчинителя разума", additional_info = nil},
[1220130] = {name = "Душа торговца смертью", additional_info = "[q]Сокращает время восстановления \"Слова Тьмы: Смерть\" на 6 сек."},
[1220131] = {name = "Душа торговца смертью", additional_info = nil},
[1220132] = {name = "Душа чаши духов", additional_info = "[q]Урон от \"Слова Тьмы: Боль\" вызывает срабатывание \"Захвата духа\" с вероятностью 2.0% за каждое очко таланта, вложенное в \"Захват духа\". Если цель погибает под действием вашего \"Слова Тьмы: Боль\", вы получаете \"Захват духа\" с вероятностью 20% за каждое вложенное очко талантов. \"Внутреннее сосредоточение\" также вызывает срабатывание \"Захвата духа\" с вероятностью 20% за каждое вложенное очко талантов."},
[1220133] = {name = "Душа чаши духов", additional_info = nil},
[1220134] = {name = "Душа фанатика", additional_info = "[q]Пока действует \"Захват духа\", вы наносите на 25% больше урона от темной магии."},
[1220135] = {name = "Душа фанатика", additional_info = nil},
[1220136] = {name = "Душа непреклонного осквернителя", additional_info = "[q]Время действия \"Пытки разума\" больше не сокращается при получении урона. При активации \"Пытка разума\" теперь применяет к цели \"Пронзание разума\"."},
[1220137] = {name = "Душа непреклонного осквернителя", additional_info = nil},
[1220138] = {name = "Душа презирающего", additional_info = "[q]\"Пронзание разума\" теперь применяется мгновенно, наносит на 10% больше урона и может применяться во время поддержания другого заклинания."},
[1220139] = {name = "Душа презирающего", additional_info = nil},
[1220140] = {name = "Душа чумного", additional_info = "[q]Руна \"Боль и страдание\" теперь обновляет время восстановления \"Всепожирающей чумы\"."},
[1220141] = {name = "Душа чумного", additional_info = nil},
[1220142] = {name = "Душа реверберирующего", additional_info = "[q]Время действия \"Темпорального маяка\" увеличивается на 20%."},
[1220143] = {name = "Душа реверберирующего", additional_info = nil},
[1220144] = {name = "Душа хронолекаря", additional_info = "[q]Увеличивает силу творимого темпорального исцеления на 10%."},
[1220145] = {name = "Душа хронолекаря", additional_info = nil},
[1220146] = {name = "Душа временного порыва", additional_info = "[q]Когда вы восполняете цели здоровье \"Регенерацией\", оставшееся время восстановления \"Перемотки времени\" сокращается на 1 сек."},
[1220147] = {name = "Душа временного порыва", additional_info = nil},
[1220148] = {name = "Душа предвидящего", additional_info = "[q]Когда ваши \"Чародейские стрелы\" наносят урон, они восполняют вам ману в объеме 10% своей базовой стоимости."},
[1220149] = {name = "Душа предвидящего", additional_info = nil},
[1220150] = {name = "Душа чародея", additional_info = "[q]\"Чародейская вспышка\" вызывает срабатывание \"Заградительных стрел\" с увеличенной на 10% вероятностью. Кроме того, \"Заградительные стрелы\" теперь влияют на \"Регенерацию\" так же, как на \"Чародейские стрелы\"."},
[1220151] = {name = "Душа чародея", additional_info = nil},
[1220152] = {name = "Душа вечного смотрителя", additional_info = "[q]Теперь \"Массовая регенерация\" применяет \"Темпоральный маяк\" на 21 сек."},
[1220153] = {name = "Душа вечного смотрителя", additional_info = nil},
[1220154] = {name = "Душа чароплета", additional_info = "[q]\"Чародейская вспышка\" увеличивает наносимый урон еще на 10% за каждый эффект."},
[1220155] = {name = "Душа чароплета", additional_info = nil},
[1220156] = {name = "Душа мастера защиты", additional_info = "[q]\"Щит маны\", \"Защита от огня\" и \"Защита от магии льда\" поглощают на 50% больше урона и размещают рядом с целью темпоральный маяк. Время действия – 30 сек."},
[1220157] = {name = "Душа мастера защиты", additional_info = nil},
[1220158] = {name = "Душа хватки зимы", additional_info = "[q]Повышает вероятность срабатывания руны \"Ледяные пальцы\" еще на 15%."},
[1220159] = {name = "Душа хватки зимы", additional_info = nil},
[1220160] = {name = "Душа криоманта", additional_info = "[q]Увеличивает урон от \"Ледяной стрелы\" и \"Стрелы чар льда\" на 75%."},
[1220161] = {name = "Душа криоманта", additional_info = nil},
[1220162] = {name = "Душа пробудителя", additional_info = "[q]Вы получаете невосприимчивость к урону на время поддержания \"Прилива сил\"."},
[1220163] = {name = "Душа пробудителя", additional_info = nil},
[1220164] = {name = "Душа повелителя стихий", additional_info = "[q]Наносимый урон увеличивается на 1% на 15 сек., когда вы применяете заклинание новой школы."},
[1220165] = {name = "Душа повелителя стихий", additional_info = nil},
[1220166] = {name = "Душа магического бронника", additional_info = "[q]\"Магический доспех\" повышает скорость восстановления маны во время применения заклинаний еще на 15%. \"Раскаленный доспех\" увеличивает урон от заклинаний и силу исцеления на 18 ед. \"Ледяной доспех\" повышает вероятность срабатывания \"Ледяных пальцев\" на 20%."},
[1220167] = {name = "Душа магического бронника", additional_info = nil},
[1220168] = {name = "Душа возжигателя", additional_info = "[q]Снижает уровень угрозы, создаваемой вашими заклинаниями огня, на 20%."},
[1220169] = {name = "Душа возжигателя", additional_info = nil},
[1220170] = {name = "Душа огненного сопряжения", additional_info = "[q]\"Огненная глыба\" наносит на 20% больше урона целям, на которые действует ваш эффект периодического урона от \"Огненного шара\"."},
[1220171] = {name = "Душа огненного сопряжения", additional_info = nil},
[1220172] = {name = "Душа вечного пламени", additional_info = "[q]Периодический урон от \"Огненного шара\" увеличивается на 100% от его мгновенного урона."},
[1220173] = {name = "Душа вечного пламени", additional_info = nil},
[1220174] = {name = "Душа пиромана", additional_info = "[q]\"Огненный взрыв\" теперь также повышает вероятность критического удара следующего заклинания школы огня на 50% на 10 сек."},
[1220175] = {name = "Душа пиромана", additional_info = nil},
[1220176] = {name = "Душа подпальщика", additional_info = "[q]Увеличивает урон от таланта \"Воспламенение\" на 10%."},
[1220177] = {name = "Душа подпальщика", additional_info = nil},
[1220178] = {name = "Душа испепелителя", additional_info = "[q]Урон от \"Огненного шара\", \"Стрелы ледяного огня\" и \"Стрелы гибельного огня\" увеличивается на 4% за каждый эффект огня, действующий на цель. Максимальная прибавка – 12%."},
[1220179] = {name = "Душа испепелителя", additional_info = nil},
[1220180] = {name = "Душа мастера блокирования", additional_info = "[q]Увеличивает показатель блокирования вашего щита на 30 ед."},
[1220181] = {name = "Душа мастера блокирования", additional_info = nil},
[1220182] = {name = "Душа хранителя света", additional_info = "[q]Когда вы блокируете атаку, вы восполняете 189 в 211 ед. здоровья. Срабатывает раз в несколько секунд."},
[1220183] = {name = "Душа хранителя света", additional_info = nil},
[1220184] = {name = "Душа светозарного поборника", additional_info = "[q]\"Щит небес\" больше не имеет зарядов и теперь всегда действует до окончания времени действия. Кроме того, наносимый им урон увеличивается на 80% от показателя блокирования вашего щита."},
[1220185] = {name = "Душа светозарного поборника", additional_info = nil},
[1220186] = {name = "Душа щитоносца", additional_info = "[q]\"Щит небес\" повышает вероятность блокирования еще на 10%."},
[1220187] = {name = "Душа щитоносца", additional_info = nil},
[1220188] = {name = "Душа бастиона", additional_info = "[q]Во время действия \"Щита небес\" вы получаете на 10% меньше урона."},
[1220189] = {name = "Душа бастиона", additional_info = nil},
[1220190] = {name = "Душа жаждущего расплаты", additional_info = nil},
[1220191] = {name = "Душа жаждущего расплаты", additional_info = nil},
[1220192] = {name = "Душа броненосного", additional_info = "[q]При применении к себе \"Благословение неприкосновенности\" также повышает все характеристики на 10%."},
[1220193] = {name = "Душа броненосного", additional_info = nil},
[1220194] = {name = "Душа хранителя", additional_info = "[q]\"Щит праведности\" усиливает следующий \"Свет небес\", в результате чего он применяется мгновенно. При применении к себе \"Свет небес\" возвращает ману в размере 100% затрат на применение и не взаимодействует с эффектом \"Под охраной света\"."},
[1220195] = {name = "Душа хранителя", additional_info = nil},
[1220196] = {name = "Душа миротворца", additional_info = "[q]Ваши союзники вызывают срабатывание вашего \"Правосудия Света\" или \"Правосудия мудрости\" на 70% чаще."},
[1220197] = {name = "Душа миротворца", additional_info = nil},
[1220198] = {name = "Душа искусного", additional_info = "[q]Повышает вероятность критического удара заклинаний и атак на 2%."},
[1220199] = {name = "Душа искусного", additional_info = nil},
[1220200] = {name = "Душа эталона", additional_info = "[q]Когда ваши заклинания \"Вспышка Света\", \"Свет небес\" или \"Частица Света\" полностью исцеляют цель, вы также восполняете всем участникам ее группы 189 в 211 ед. здоровья."},
[1220201] = {name = "Душа эталона", additional_info = nil},
[1220202] = {name = "Душа инквизитора", additional_info = "[q]Повышает вероятность критического эффекта \"Шока небес\" на 5%."},
[1220203] = {name = "Душа инквизитора", additional_info = nil},
[1220204] = {name = "Душа правителя", additional_info = "[q]Увеличивает урон от \"Освящения\" на 50%."},
[1220205] = {name = "Душа правителя", additional_info = nil},
[1220206] = {name = "Душа властителя", additional_info = "[q]Если \"Частица Света\" действует не на вас, цель \"Частицы Света\" восполняет здоровье в объеме 75% урона, наносимого вашими способностями \"Освящение\", \"Экзорцизм\", \"Шок небес\", \"Гнев небес\" и \"Молот гнева\"."},
[1220207] = {name = "Душа властителя", additional_info = nil},
[1220208] = {name = "Душа воздаятеля", additional_info = "[q]Сокращает время восстановления \"Божественного света\" на 25%."},
[1220209] = {name = "Душа воздаятеля", additional_info = nil},
[1220210] = {name = "Душа альтруиста", additional_info = "[q]Когда \"Частица Света\" исцеляет цель, находящийся поблизости раненый союзник получает 90% этого исцеления."},
[1220211] = {name = "Душа альтруиста", additional_info = nil},
[1220212] = {name = "Душа арбитра", additional_info = "[q]Ваши заклинания \"Правосудие Света\" и \"Правосудие мудрости\" также дают эффект \"Правосудие воина Света\"."},
[1220213] = {name = "Душа арбитра", additional_info = nil},
[1220214] = {name = "Душа носителя печати", additional_info = "[q]\"Печать повиновения\", \"Печать праведности\", \"Печать мученичества\" и \"Солнечный свет\" наносят на 35% меньше урона, но продолжают действовать в течение 6 сек. после применения другой печати или до тех пор, пока вы не примените третью печать. \"Правосудие\" может вызывать срабатывание нескольких действующих печатей одновременно."},
[1220215] = {name = "Душа носителя печати", additional_info = nil},
[1220216] = {name = "Душа юстициария", additional_info = "[q]\"Правосудие\" наносит на 5% больше урона и больше не поглощает эффект печати. \"Правосудие\" может вызывать срабатывание нескольких печатей одновременно."},
[1220217] = {name = "Душа юстициария", additional_info = nil},
[1220218] = {name = "Душа вершителя", additional_info = "[q]Сокращает время восстановления \"Правосудия\" на 5 сек., но уменьшает наносимый им урон на 45%."},
[1220219] = {name = "Душа вершителя", additional_info = nil},
[1220220] = {name = "Душа перерожденного", additional_info = "[q]\"Правосудие\" увеличивает наносимый урон от светлой магии на 1% на 8 сек. Эффект суммируется до 5 раз."},
[1220221] = {name = "Душа перерожденного", additional_info = nil},
[1220222] = {name = "Душа мстящего", additional_info = "[q]Увеличивает урон от \"Удара воина Света\" на 150%."},
[1220223] = {name = "Душа мстящего", additional_info = nil},
[1220224] = {name = "Душа отлучающего", additional_info = "[q]Автоатаки двуручным оружием ближнего боя на 20 сек. увеличивают урон от следующего \"Экзорцизма\" на 35%. Эффект суммируется до 3 раз."},
[1220225] = {name = "Душа отлучающего", additional_info = nil},
[1220226] = {name = "Душа Светоносного", additional_info = "[q]Увеличивает урон от \"Шока небес\" на 50%."},
[1220227] = {name = "Душа Светоносного", additional_info = nil},
[1220228] = {name = "Душа изгнанника", additional_info = "[q]Сокращает время восстановления \"Экзорцизма\" на 3 сек. и увеличивает наносимый им урон на 75%."},
[1220229] = {name = "Душа изгнанника", additional_info = nil},
[1220230] = {name = "Душа храмовника", additional_info = "[q]Пока вы используете одноручное оружие, \"Удар воина Света\" применяет эффекты печатей, вызываемые \"Правосудием\". При этом печать не поглощается."},
[1220231] = {name = "Душа храмовника", additional_info = nil},
[1220232] = {name = "Душа ветрохода", additional_info = "[q]Когда вы уклоняетесь, парируете или блокируете атаку, ваша скорость атаки повышается на 30% на 3 удара."},
[1220233] = {name = "Душа ветрохода", additional_info = nil},
[1220234] = {name = "Душа мастера щита", additional_info = "[q]Когда вы парируете атаки или уклоняетесь от них, вы также активируете руническую способность \"Мастерское владение щитом\"."},
[1220235] = {name = "Душа мастера щита", additional_info = nil},
[1220236] = {name = "Душа тотемного защитника", additional_info = "[q]\"Тотем каменной кожи\" также уменьшает получаемый физический урон на 5%, а \"Тотем стены ветра\" также уменьшает получаемый магический урон на 5%."},
[1220237] = {name = "Душа тотемного защитника", additional_info = nil},
[1220238] = {name = "Душа шокового нейтрализатора", additional_info = "[q]\"Огненный шок\" также повышает вероятность блокирования на 30% на 5 сек. Действует до успешного блокирования."},
[1220239] = {name = "Душа шокового нейтрализатора", additional_info = nil},
[1220240] = {name = "Душа духовного бастиона", additional_info = "[q]Когда вы блокируете атаку, ваш показатель блокирования повышается на 10% от бонуса к урону от заклинаний на 6 сек. Эффект суммируется до 3 раз."},
[1220241] = {name = "Душа духовного бастиона", additional_info = nil},
[1220242] = {name = "Душа призывателя водоворота", additional_info = "[q]Когда вы блокируете атаку, с вероятностью 50% срабатывает руна \"Оружие Водоворота\"."},
[1220243] = {name = "Душа призывателя водоворота", additional_info = nil},
[1220244] = {name = "Душа лавохода", additional_info = "[q]Когда \"Удар бури\", \"Выброс лавы\" или \"Всплеск лавы\" наносит цели урон, получаемый вами урон уменьшается на 10% на 10 сек."},
[1220245] = {name = "Душа лавохода", additional_info = nil},
[1220246] = {name = "Душа истинного вожака", additional_info = "[q]При применении к себе \"Дух вожака стаи\" также увеличивает максимальный запас здоровья на 5%, уровень создаваемой угрозы – на 25%, а наносимый урон – на 5%."},
[1220247] = {name = "Душа истинного вожака", additional_info = nil},
[1220248] = {name = "Душа хранителя тотемов", additional_info = "[q]Радиус действия тотемов, действующих на союзников, увеличивается до 40 м."},
[1220249] = {name = "Душа хранителя тотемов", additional_info = nil},
[1220250] = {name = "Душа предков", additional_info = "[q]После применения \"Волны исцеления\", \"Малой волны исцеления\" или \"Быстрины\" вы с вероятностью 25% восполняете ману в объеме 35% базовой стоимости заклинания."},
[1220251] = {name = "Душа предков", additional_info = nil},
[1220252] = {name = "Душа заклинателя душ", additional_info = "[q]\"Волна исцеления\" переходит на дополнительные находящиеся рядом цели. Каждый из 2 возможных переходов ослабляет эффект на 60%."},
[1220253] = {name = "Душа заклинателя душ", additional_info = nil},
[1220254] = {name = "Душа водохода", additional_info = "[q]Критические эффекты наносящих урон и исцеляющих непериодических способностей теперь с вероятностью 100% вызывают срабатывание вашего \"Водного щита\", не поглощая заряд и не запуская время восстановления."},
[1220255] = {name = "Душа водохода", additional_info = nil},
[1220256] = {name = "Душа хранителя бури", additional_info = "[q]\"Цепная молния\" теперь также восполняет последней цели \"Щита земли\" здоровье в объеме 100% нанесенного урона."},
[1220257] = {name = "Душа хранителя бури", additional_info = nil},
[1220258] = {name = "Душа провидца стихий", additional_info = "[q]Усиливает исцеление \"Цепного исцеления\" и увеличивает урон от \"Цепной молнии\" на 20%."},
[1220259] = {name = "Душа провидца стихий", additional_info = nil},
[1220260] = {name = "Душа виталиста", additional_info = "[q]\"Быстрина\" повышает объем исцеления от \"Цепного исцеления\" еще на 25%."},
[1220261] = {name = "Душа виталиста", additional_info = nil},
[1220262] = {name = "Душа целителя духов", additional_info = "[q]Сокращает время произнесения \"Цепного исцеления\" на 0.5 сек."},
[1220263] = {name = "Душа целителя духов", additional_info = nil},
[1220264] = {name = "Душа искусного", additional_info = "[q]Повышает вероятность критического удара заклинаний и атак на 2%."},
[1220265] = {name = "Душа искусного", additional_info = nil},
[1220266] = {name = "Душа вождя", additional_info = nil},
[1220267] = {name = "Душа вождя", additional_info = nil},
[1220268] = {name = "Душа исполненного ярости", additional_info = "[q]Вероятность срабатывания \"Статического шока\" повышается на 12% (на 6%, если вы сражаетесь с оружием в обеих руках)."},
[1220269] = {name = "Душа исполненного ярости", additional_info = nil},
[1220270] = {name = "Душа рассекателя туч", additional_info = "[q]Увеличивает наносимый \"Ударом бури\" урон от оружия в правой руке на 50%."},
[1220271] = {name = "Душа рассекателя туч", additional_info = nil},
[1220272] = {name = "Душа урагана", additional_info = "[q]Пока у вас выгравирована руна \"Статический шок\", \"Щит молний\" накапливает заряд каждый раз, когда вы поражаете цель \"Молнией\" или \"Цепной молнией\". Максимальное количество зарядов – 9. Кроме того, пока у вас выгравирована руна \"Статический шок\", \"Щит молний\" может наносить критический урон."},
[1220273] = {name = "Душа урагана", additional_info = nil},
[1220274] = {name = "Душа сейсмического крушителя", additional_info = "[q]Увеличивает урон от \"Удара бури\" и \"Вскипания лавы\" на 50%. Бонус увеличивается до 100%, когда вы используете двуручное оружие."},
[1220275] = {name = "Душа сейсмического крушителя", additional_info = nil},
[1220276] = {name = "Душа пламеносца", additional_info = "[q]Критические удары \"Удара бури\", \"Вскипания лавы\" и \"Выброса лавы\" поджигают цель, нанося еще 30% урона за 4 сек."},
[1220277] = {name = "Душа пламеносца", additional_info = nil},
[1220278] = {name = "Душа вулкана", additional_info = "[q]Критические удары \"Молнии\" с вероятностью 35% восстанавливают \"Выброс лавы\" и \"Цепную молнию\", а также позволяют мгновенно применить следующий \"Выброс лавы\" или \"Цепную молнию\" в течение 10 сек."},
[1220279] = {name = "Душа неистового пламени", additional_info = "[q]\"Выброс лавы\" теперь также обновляет время действия \"Огненного шока\" на цели до 12 сек."},
[1220280] = {name = "Душа вулкана", additional_info = nil},
[1220281] = {name = "Душа неистового пламени", additional_info = nil},
[1220282] = {name = "Душа властелина стихий", additional_info = "[q]Теперь критические эффекты ваших заклинаний с вероятностью 100% вызывают срабатывание таланта \"Средоточие стихий\"."},
[1220283] = {name = "Душа властелина стихий", additional_info = nil},
[1220284] = {name = "Душа защитника рода", additional_info = "[q]Эффект \"Верный помощник\", полученный от способности \"Дух вожака стаи\", теперь также увеличивает урон от огня, магии льда и сил природы на 5 + (5 * Серия приёмов)%."},
[1220285] = {name = "Душа защитника рода", additional_info = nil},
[1220286] = {name = "Душа духовного проводника", additional_info = "[q]Пока действует \"Ясность мысли\", наносимый вами нефизический урон увеличивается на 15 + (5 * Серия приёмов)%."},
[1220287] = {name = "Душа духовного проводника", additional_info = nil},
[1220288] = {name = "Душа старейшины", additional_info = "[q]Применение \"Молнии\", \"Цепной молнии\" или \"Выброса лавы\" с вероятностью 70% не прерывается уроном, а вероятность вызвать срабатывание таланта \"Концентрация стихий\" повышается на 10%."},
[1220289] = {name = "Душа старейшины", additional_info = nil},
[1220291] = {name = "Душа стихий", additional_info = "[q]Увеличивает бонус к критическому урону от заклинаний огня, магии льда и сил природы на 60%."},
[1220292] = {name = "Душа стихий", additional_info = nil},
[1220293] = {name = "Душа лавового мудреца", additional_info = "[q]Урон от \"Выброса лавы\" увеличивается на вероятность критического удара заклинаний."},
[1220294] = {name = "Душа лавового мудреца", additional_info = nil},
[1220295] = {name = "Душа древнего стража", additional_info = "[q]Повышает вероятность блокирования атак щитом на 10%."},
[1220296] = {name = "Душа древнего стража", additional_info = nil},
[1220297] = {name = "Душа оскверненного", additional_info = "[q]Повышает вероятность срабатывания руны \"Выброс энергии\" еще на 5%."},
[1220298] = {name = "Душа оскверненного", additional_info = nil},
[1220299] = {name = "Душа мягкой лапы", additional_info = "[q]Вы можете применять \"Возрождение\" и \"Озарение\" в облике медведя или лютого медведя."},
[1220300] = {name = "Душа мягкой лапы", additional_info = nil},
[1220301] = {name = "Душа свирепого", additional_info = "[q]Сокращает время восстановления \"Исступления\" на 30 сек. \"Исступление\" больше не ослабляет вашу броню."},
[1220302] = {name = "Душа свирепого", additional_info = nil},
[1220303] = {name = "Душа оборотня", additional_info = "[q]Облики медведя и лютого медведя повышают уровень создаваемой вами угрозы еще на 20%. Способность \"Попятиться\" сбрасывает уровень угрозы по отношению к цели, но время восстановления способности увеличивается на 20 сек."},
[1220304] = {name = "Душа оборотня", additional_info = nil},
[1220305] = {name = "Душа защитника территории", additional_info = "[q]После применения способности \"Размах (медведь)\" ваша \"Трепка\" поражает еще 1 цель в течение 6 сек."},
[1220306] = {name = "Душа защитника территории", additional_info = nil},
[1220307] = {name = "Душа зверя", additional_info = "[q]Вероятность критического удара способностей \"Увечье (медведь)\", \"Размах (медведь)\", \"Трепка\" и \"Растерзать\" повышается на 5% против целей, на которые действует ваш эффект \"Растерзать\"."},
[1220308] = {name = "Душа зверя", additional_info = nil},
[1220310] = {name = "Душа терзающего", additional_info = "[q]\"Размах\" теперь распространяет эффект \"Растерзать\", действующий на основную цель, на остальные пораженные цели."},
[1220311] = {name = "Душа терзающего", additional_info = nil},
[1220312] = {name = "Душа неистового", additional_info = "[q]Когда вы уклоняетесь, находясь в облике лютого медведя, урон от следующего \"Увечья\" или \"Размаха\" увеличивается на 10%. Эффект суммируется до 5 раз."},
[1220313] = {name = "Душа неистового", additional_info = nil},
[1220314] = {name = "Душа увечащего", additional_info = "[q]Сокращает время восстановления \"Увечья (медведь)\" на 1.5 сек."},
[1220315] = {name = "Душа увечащего", additional_info = nil},
[1220316] = {name = "Душа озаряющего", additional_info = "[q]Когда вы применяете \"Озарение\" к другому игроку, вы также получаете этот эффект."},
[1220317] = {name = "Душа озаряющего", additional_info = nil},
[1220318] = {name = "Душа покровителя", additional_info = "[q]После применения \"Целительного прикосновения\" или \"Покровительства природы\" вы с вероятностью 25% восполняете ману в объеме 35% базовой стоимости заклинания."},
[1220319] = {name = "Душа покровителя", additional_info = nil},
[1220320] = {name = "Душа спокойствия", additional_info = "[q]Сокращает время восстановления \"Безмятежности\" на 100%. \"Безмятежность\" восстанавливает на 100% больше здоровья."},
[1220321] = {name = "Душа спокойствия", additional_info = nil},
[1220322] = {name = "Душа сновидца", additional_info = "[q]Критические эффекты исцеляющих заклинаний дают вам эффект \"Состояние сна\", позволяющий восполнять ману во время применения заклинаний со скоростью 50% от обычной в течение 8 сек."},
[1220323] = {name = "Душа сновидца", additional_info = nil},
[1220324] = {name = "Душа хранительницы рощи", additional_info = "[q]Непериодические критические эффекты заклинаний сокращают время применения следующего \"Целительного прикосновения\", \"Покровительства природы\" или \"Восстановления\" на 0.5 сек."},
[1220325] = {name = "Душа хранительницы рощи", additional_info = nil},
[1220326] = {name = "Душа пернатого мудреца", additional_info = "[q]Усиливает исцеление от \"Буйного роста\" на 10%. Кроме того, теперь вы можете применять \"Буйный рост\" в облике лунного совуха, и в этом облике исцеление от \"Буйного роста\" усиливается еще на 50%."},
[1220327] = {name = "Душа пернатого мудреца", additional_info = nil},
[1220328] = {name = "Душа благодушного провидца", additional_info = "[q]Сокращает время восстановления \"Возрождения\" и \"Озарения\" на 65%."},
[1220329] = {name = "Душа благодушного провидца", additional_info = nil},
[1220330] = {name = "Душа ткача жизни", additional_info = "[q]Критические эффекты исцеления от \"Целительного прикосновения\", \"Восстановления\" и \"Покровительства природы\" мгновенно восполняют цели дополнительный объем здоровья, равный 50% совершенного исцеления."},
[1220331] = {name = "Душа ткача жизни", additional_info = nil},
[1220332] = {name = "Душа озаряющего света", additional_info = "[q]\"Волшебный огонь (сила зверя)\" также повышает вероятность попадания атак, направленных против цели, на 1% на 40 сек."},
