[1220341] = {name = "Душа гордыни", additional_info = nil},
[1220342] = {name = "Душа варварства", additional_info = "[q]Способности \"Полоснуть\", \"Свирепый укус\" и \"Увечье (кошка)\" наносят на 10% больше урона за каждый ваш эффект кровотечения, действующий на цель. Максимальный бонус – 20%."},
[1220343] = {name = "Душа варварства", additional_info = nil},
