[1220529] = {name = "Некрорахниды-скарабеи", additional_info = "Применение: 1.5 сек\n[q]Призывает на помощь 10 некрорахнидов-скарабеев:некроарахнидов-скарабеев на 10 сек."},
[1220533] = {name = "Стигийский захват", additional_info = "Мгновенное действие\n[q]Призывает мертвецов, которые вцепляются в ближайших противников, обездвиживая их на 6 сек."},
