[1226022] = {name = "Гаджет: магнитный переместитель", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Создает возмущение магнитного поля между вами и противником, отбрасывая вас в разные стороны.\n\n Не действует на цели, уровень которых выше вашего более, чем на 2. Некоторые цели отбросить нельзя. Срабатывает против каждой цели не чаще раза в 2 мин."},
[1226032] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Исцеления\" за 2 предмета", additional_info = "[q]Когда ваш \"Жизнецвет\" восстанавливает здоровье цели, вы с вероятностью 5% можете мгновенно применить следующее \"Целительное прикосновение\", \"Покровительство природы\" или \"Восстановление\" в течение 15 сек.\n(Вероятность срабатывания: 5%)"},
[1226035] = {name = "Быстроцвет", additional_info = "Мгновенное действие\n[q]Сокращает время применения следующего \"Целительного прикосновения\", \"Восстановления\" или \"Покровительства природы\" на 100%."},
[1226038] = {name = "Омоложение", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Сокращает время применения следующего \"Целительного прикосновения\", \"Восстановления\" или \"Покровительства природы\" на 20%."},
[1226040] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Исцеления\" за 4 предмета", additional_info = "[q]Вы восстанавливаете на 20% больше здоровья целям, на которые действует ваше \"Омоложение\" 10-го или 11-го уровня."},
[1226044] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Исцеления\" за 6 предметов", additional_info = "[q]Непериодические эффекты \"Восстановления\" 8-го или 9-го уровня, примененного к цели с вашим \"Омоложением\", с вероятностью 100% распространяют эффект \"Омоложения\" на участников группы цели в радиусе 43.5 м, на которых еще не действует этот эффект."},
[1226045] = {name = "Размагничивание", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Создает возмущение магнитного поля между вами и противником, отбрасывая вас в разные стороны.\n\n Не действует на цели, уровень которых выше вашего более, чем на 2. Некоторые цели отбросить нельзя. Срабатывает против каждой цели не чаще раза в 2 мин."},
[1226046] = {name = "Дикое омоложение", additional_info = "Мгновенное действие"},
[1226092] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Баланса\" за 2 предмета", additional_info = "[q]\"Звездный огонь\" наносит на 20% больше урона целям, на которые действует ваш \"Лунный огонь\". \"Гнев\" наносит на 40% больше урона целям, на которые действует ваш \"Солнечный огонь\"."},
[1226103] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Баланса\" за 4 предмета", additional_info = "[q]\"Звездный поток\" теперь увеличивает урон от 2 следующих применений:следующих применений \"Звездного огня\"."},
[1226105] = {name = "Солнечный поток", additional_info = "Мгновенное действие\n[q]Modifies Damage/Healing Done +41%:\nГнев , Гнев , Гнев , Гнев , Гнев , Гнев , Гнев , Гнев"},
[1226106] = {name = "Лунный поток", additional_info = "Мгновенное действие\n[q]Modifies Damage/Healing Done +21%:\nЗвездный огонь , Звездный огонь , Звездный огонь , Звездный огонь , Звездный огонь , Звездный огонь , Звездный огонь"},
[1226108] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Баланса\" за 6 предметов", additional_info = "[q]Периодический урон от \"Солнечного огня\" увеличивает урон от следующего \"Гнева\" на 40%. Эффект суммируется до 5 раз. Периодический урон от \"Лунного огня\" увеличивает урон от следующего \"Звездного огня\" на 20%. Эффект суммируется до 5 раз. Эти бонусы не действуют на \"Звездный поток\"."},
[1226109] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Силы зверя\" за 2 предмета", additional_info = "[q]Когда способности \"Глубокая рана\" и \"Разорвать\" наносят периодический урон, вы восполняете 2 ед. энергии."},
[1226113] = {name = "Запах крови", additional_info = nil},
[1226116] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Силы зверя\" за 4 предмета", additional_info = "[q]Бонус к урону от \"Тигриного неистовства\" увеличивается в 2 раза:раз."},
[1226118] = {name = "S03 - Item - Scarlet Enclave - Druid - Feral 6P Bonus Trigger", additional_info = nil},
[1226119] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Силы зверя\" за 6 предметов", additional_info = "[q]Завершающие удары с вероятностью 20% за каждый израсходованный прием серии вызывают срабатывание \"Ясности мысли\" и продлевают время действия \"Тигриного неистовства\" на 6 сек."},
[1226121] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Стража\" за 2 предмета", additional_info = "[q]Когда вы наносите критический удар в ближнем бою в облике медведя или лютого медведя, вы на 10 сек. получаете щит, поглощающий физический урон от следующего полученного удара в объеме 25% вашей силы атаки. Суммируется до 3 раз."},
[1226125] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Стража\" за 4 предмета", additional_info = "[q]Увеличивает время действия \"Берсерка\" на 15 сек."},
[1226126] = {name = "S03 – предмет – анклав Алого ордена – друид – бонус \"Стража\" за 6 предметов", additional_info = "[q]Критические удары повышают скорость атаки на 30% на 10 сек."},
