[1226136] = {name = "Коварный выстрел", additional_info = nil},
[1226137] = {name = "S03 – предмет – анклав Алого ордена – охотник – бонус дальнего боя за 4 предмета", additional_info = "[q]Критические удары в дальнем бою повышают силу атаки на 25% на 10 сек."},
[1226138] = {name = "S03 – предмет – анклав Алого ордена – охотник – бонус дальнего боя за 6 предметов", additional_info = "[q]\"Залп\" поражает еще 2 цели:целей, а \"Убийственный выстрел\" и \"Выстрел химеры\" увеличивают урон от следующего \"Залпа\" на 12 сек. на 50%, когда наносят цели урон. Эффект суммируется до 4 раз."},
[1226206] = {name = "Коробка гаджета", additional_info = "Применение: 2 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nМифриловая обшивка , Золотое силовое ядро (2)\n(2)\nИспользуется для ремесел\n[q]\"Несложный модуль управления, с помощью которого инженеры создают гаджеты.\""},
[1226207] = {name = "[q2]Коробка гаджета: телепорт", additional_info = "Применение: 2 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Нестабильное пусковое устройство , Ториевое устройство\n[q2]Коробка гаджета: телепорт\nТребуется\n[q2]Использование: Телепортация на 20 м вперед."},
[1226208] = {name = "[q2]Коробка гаджета: нитроускорители", additional_info = "Применение: 2 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Нестабильное пусковое устройство , Ториевая труба\n[q2]Коробка гаджета: нитроускорители\nТребуется\n[q2]Использование: Активировать ускорители, повышающие скорость передвижения максимум на 160%. Время действия – до 8 сек."},
[1226209] = {name = "[q2]Коробка гаджета: магнитный переместитель", additional_info = "Применение: 2 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Нестабильное пусковое устройство , Железная балка (2)\n[q2]Коробка гаджета: магнитный переместитель\nТребуется\n[q2]Использование: Создает возмущение магнитного поля между вами и противником, отбрасывая вас в разные стороны.\n\n Не действует на цели, уровень которых выше вашего более, чем на 2. Некоторые цели отбросить нельзя. Срабатывает против каждой цели не чаще раза в 2 мин."},
[1226210] = {name = "Гаджет: телепорт", additional_info = "Применение: 2 сек\nТребуется: Пояс\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Сверхточный арканитовый преобразователь , Ториевое устройство\n[q]Улучшить пояс и добавить следующий эффект:\n\nТелепортация на 20 м вперед."},
[1226211] = {name = "Гаджет: нитроускорители", additional_info = "Применение: 2 сек\nТребуется: Броня\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Сверхточный арканитовый преобразователь , Ториевая труба\n[q]Улучшить пояс и добавить следующий эффект:\n\nАктивировать ускорители, повышающие скорость передвижения максимум на 160%. Время действия – до 8 сек."},
[1226212] = {name = "Гаджет: магнитный переместитель", additional_info = "Применение: 2 сек\nТребуется: Броня\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nКоробка гаджета , Сверхточный арканитовый преобразователь , Железная балка (2)\n[q]Улучшить пояс и добавить следующий эффект:\n\nСоздает возмущение магнитного поля между вами и противником, отбрасывая вас в разные стороны.\n\n Не действует на цели, уровень которых выше вашего более, чем на 2. Некоторые цели отбросить нельзя. Срабатывает против каждой цели не чаще раза в 2 мин."},
[1226213] = {name = "[q2]Довольно безопасный транспортер в Новый Авалон", additional_info = "Применение: 2 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nСверхточный арканитовый преобразователь , Преобразователь истинного серебра (2), Нестабильное пусковое устройство , Мифриловая обшивка (2), Гоблинский реактивный шлем (2), Сфера Праведности\n[q2]Довольно безопасный транспортер в Новый Авалон\n(2)\nСтановится персональным при использовании\nАксессуар\nТребуется\nТребуетИнженерное дело\n(290)\n[q2]Использование: Отбросить осторожность и протестировать гоблинское экспериментальное телепортирующее устройство. Если оно сработает, вы окажетесь в Новом Авалоне в целости и сохранности. (4 Ч Восстановление)"},
[1226215] = {name = "Довольно безопасный транспортер в Новый Авалон", additional_info = "Применение: 10 сек\n[q]Отбросить осторожность и протестировать гоблинское экспериментальное телепортирующее устройство. Если оно сработает, вы окажетесь в Новом Авалоне в целости и сохранности."},
[1226217] = {name = "Довольно безопасный транспортер в Новый Авалон", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Отбросить осторожность и протестировать гоблинское экспериментальное телепортирующее устройство. Если оно сработает, вы окажетесь в Новом Авалоне в целости и сохранности."},
