[1226365] = {name = "S03 – предмет – анклав Алого ордена – охотник – бонус ближнего боя за 6 предметов", additional_info = "[q]\"Неистовство ящера\" увеличивает наносимый урон еще на 15% за каждый эффект."},
[1226377] = {name = "Временные завихрения", additional_info = nil},
[1226378] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 6P Bonus", additional_info = "[q]Время восстановления \"Мощи тайной магии\" сокращается на 90 сек., а время действия продлевается на 10 сек. Пока действует \"Мощь тайной магии\", вероятность получить \"Чародейское средоточие\" увеличивается на 10%, а каждая \"Чародейская вспышка\" сокращает оставшееся время восстановления \"Массовой регенерации\" на 1.0 сек."},
[1226388] = {name = "Яблоко", additional_info = nil},
[1226396] = {name = "Яблоскоп", additional_info = "Радиус действия: 100 м\nПрименение: 1 сек\n[q]Позволяет искать яблоки со значительного расстояния."},
[1226402] = {name = "Взять яблоко", additional_info = "Неограниченное расстояние\nПрименение: 1.5 сек\n[q]Украсть яблоко с безопасного расстояния."},
[1226406] = {name = "Чародейское средоточие", additional_info = nil},
[1226407] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 2P Bonus", additional_info = "[q]\"Чародейская вспышка\" с вероятностью до 10% дает вам эффект \"Чародейское средоточие\". Пока действует данный эффект, другие заклинания, наносящие урон от тайной магии, не поглощают эффект \"Чародейской вспышки\". Кроме того, \"Мощь тайной магии\" мгновенно восстанавливает \"Массовую регенерацию\".\n(Вероятность срабатывания: 20%)"},
[1226414] = {name = "Временной якорь", additional_info = nil},
[1226415] = {name = "S03 - Item - Scarlet Enclave - Mage - Healer 4P Bonus", additional_info = "[q]\"Перемотка времени\" также уменьшает получаемый целью урон на 20% на 8 сек."},
[1226423] = {name = "S03 – предмет – анклав Алого ордена – маг – бонус бойца за 2 предмета", additional_info = "[q]\"Живая бомба\" теперь наносит урон раз в 1 сек. и взрывается, если цель умирает. Кроме того, эффект \"Вымораживание\" от руны \"Ледяное копье\" теперь суммируется до 10 раз, а \"Стрела чар льда\" дает 2 эффекта:эффектов при попадании."},
[1226432] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 6P Bonus", additional_info = "[q]Время восстановления \"Ледяного шара\" сокращается на 25 сек. При поглощении эффектов \"Вымораживания\" время восстановления \"Глубокой заморозки\" сокращается на 1.0 сек. за каждый поглощенный эффект. Время восстановления \"Огненного взрыва\" сокращается на 5 сек. Кроме того, \"Огненный взрыв\" обновляет время действия \"Живой бомбы\" на цели."},
[1226446] = {name = "S03 - Item - Scarlet Enclave - Mage - Damage 4P Bonus", additional_info = "[q]\"Глубокая заморозка\" продлевает время действия \"Стылой крови\" на 10 сек. \"Огненная глыба\" снимает 2 эффекта:эффектов \"Стрелы гибельного огня\"."},
[1226451] = {name = "Чрезвычайная ситуация", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Modifies Global Cooldown -499:\nБожественный свет , Возложение рук , Возложение рук , Возложение рук , Вспышка Света , Вспышка Света , Вспышка Света , Вспышка Света , Вспышка Света , Вспышка Света , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Свет небес , Шок небес , Шок небес , Шок небес"},
[1226452] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Света\" за 2 предмета", additional_info = "[q]\"Возложение рук\" повышает скорость применения заклинаний на 20% на 30 сек. и на 0.5 сек. сокращает общее время восстановления для 5 следующих заклинаний:следующих заклинаний \"Божественный свет\", \"Свет небес\", \"Вспышка Света\" и \"Шок небес\"."},
[1226454] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Света\" за 4 предмета", additional_info = "[q]\"Частица Света\" теперь также срабатывает, когда вы исцеляете цель этого заклинания, но с эффективностью, сниженной на 50%."},
[1226455] = {name = "Милосердие", additional_info = nil},
[1226459] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Света\" за 6 предметов", additional_info = "[q]Цель \"Частицы Света\" получает еще 25% вашего исцеления."},
[1226460] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Воздаяния\" за 2 предмета", additional_info = "[q]Пока вы используете двуручное оружие, \"Удар воина Света\" и \"Экзорцизм\" дают эффект \"Священная сила\", увеличивающий наносимый урон от светлой магии на 10%. Суммируется до 3 раз.\n(Восстановление: 100мс)"},
[1226461] = {name = "Священная сила", additional_info = nil},
[1226462] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Воздаяния\" за 4 предмета", additional_info = "[q]\"Божественная буря\", \"Шок небес\" и \"Гнев небес\" поглощают все эффекты \"Энергия Света\" и наносят на 100% больше урона за каждый эффект (или на 50% больше, если цель находится под контролем игрока)."},
[1226463] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Воздаяния\" за 6 предметов", additional_info = "[q]За каждый поглощенный эффект \"Энергия Света\" ваша сила атаки повышается на 15% на 10 сек."},
[1226464] = {name = "Храмовник", additional_info = nil},
[1226466] = {name = "Праведный щит", additional_info = nil},
[1226467] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Защиты\" за 2 предмета", additional_info = "[q]\"Щит праведности\" также увеличивает показатель блокирования на 30% на 6 сек."},
[1226477] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Защиты\" за 4 предмета", additional_info = "[q]\"Щит праведности\" получает процентный бонус к урону, равный вероятности блокирования."},
[1226479] = {name = "S03 – предмет – анклав Алого ордена – паладин – бонус \"Защиты\" за 6 предметов", additional_info = "[q]\"Гнев карателя\" больше не вызывает срабатывание \"Воздержанности\", действует на 15 сек. дольше и увеличивает показатель блокирования на 30%."},
[1226480] = {name = "Праведный блок", additional_info = nil},
[1226499] = {name = "S03 – предмет – анклав Алого ордена – жрец – бонус лекаря за 2 предмета", additional_info = "[q]Время восстановления \"Слова силы: Барьер\" сокращается на 30 сек., а \"Пробуждение света\" теперь также позволяет мгновенно произносить заклинания \"Молитва исцеления\" и \"Большее исцеление\"."},
[1226500] = {name = "Отпущение", additional_info = "Мгновенное действие\n[q]Modifies Cast Time -99%:\nБольшее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Большее исцеление , Быстрое исцеление , Быстрое исцеление , Быстрое исцеление , Быстрое исцеление , Быстрое исцеление , Быстрое исцеление , Быстрое исцеление , Исцеление , Исцеление , Исцеление , Исцеление , Малое исцеление , Малое исцеление , Малое исцеление , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления , Молитва исцеления , Связующее исцеление"},
[1226501] = {name = "S03 - Item - Scarlet Enclave - Priest - Healer 6P Bonus", additional_info = "[q]Увеличивает силу исцеления \"Круга исцеления\" и \"Исповеди\" на 25%. Кроме того, время восстановления \"Духа воздаяния\" сокращается на 30 сек., и, пока он действует, ваша сила исцеления увеличивается на 20%."},
[1226502] = {name = "Преданность", additional_info = nil},
[1226503] = {name = "Перегрузка", additional_info = nil},
[1226504] = {name = "Преданность", additional_info = nil},
[1226529] = {name = "Бочка с рыбой", additional_info = "Мгновенное действие\n(Восстановление: 2с)"},
[1226534] = {name = "Бросок рыбы", additional_info = nil},
[1226537] = {name = "Призыв рыбы", additional_info = nil},
[1226565] = {name = "S03 - Item - Scarlet Enclave - Priest - Healer 4P Bonus", additional_info = "[q]\"Слово силы: Щит\" мгновенно восполняет цели здоровье в объеме 60% прочности щита, а сила исцеления заклинаний, на которые действует \"Прозорливость\", увеличивается на 10% за эффект."},
[1226566] = {name = "Слово силы: Щит", additional_info = nil},
[1226585] = {name = "S03 – предмет – анклав Алого ордена – жрец – бонус \"Тьмы\" за 2 предмета", additional_info = "[q]Время действия \"Пытки разума\" и \"Иссушения разума\" больше не сокращается при получении урона во время их поддержания. Кроме того, эти заклинания наносят на 10% больше урона за каждый другой эффект периодического урона от темной магии, действующий на цель. Максимальная прибавка – 30%."},
[1226589] = {name = "Слово Тьмы: Боль", additional_info = nil},
[1226591] = {name = "S03 – предмет – анклав Алого ордена – жрец – бонус \"Тьмы\" за 4 предмета", additional_info = "[q]\"Взрыв разума\" создает на 50% меньше угрозы и наносит на 20% больше урона за каждый эффект \"Пронзание разума\" на цели."},
[1226595] = {name = "S03 – предмет – анклав Алого ордена – жрец – бонус \"Тьмы\" за 6 предметов", additional_info = "[q]Урон от \"Пытки разума\" теперь увеличивается по мере ее поддержания. Каждый раз, когда она наносит урон, наносимый урон увеличивается на 70%. Эффект сбрасывается при повторном поддержании этого заклинания."},
[1226689] = {name = "[q4]Алый колчан", additional_info = "Применение: 3 сек\nИнгредиенты:\nСфера Праведности , Грубая кожа (24), Обработанная грубая шкура (2)\n[q4]Алый колчан\n(2)\nСтановится персональным при надевании\nКолчан (ячеек: 30)\nТребуется\n[q2]Если на персонаже: Увеличение скорости дальней атаки на 15%."},
[1226690] = {name = "[q4]Алый подсумок", additional_info = "Применение: 3 сек\nИнгредиенты:\nСфера Праведности , Толстая чешуя скорпида (24), Обработанная грубая шкура (2)\n[q4]Алый подсумок\n(2)\nСтановится персональным при надевании\nПодсумок (ячеек: 30)\nТребуется\n[q2]Если на персонаже: Увеличение скорости дальней атаки на 15%."},
[1226739] = {name = "Убийство нежити", additional_info = nil},
[1226800] = {name = "Положить в ящик", additional_info = "Применение: 5 сек\nТребуется: Грудь, Наплечники, Наручи, Обувь, Перчатки, Пояс, Шлемы, Штаны\nИнгредиенты:\nЯщик интенданта\n[q]Положить изготовленный предмет снаряжения Алого ордена в ящик. При этом предмет будет навсегда утерян."},
[1226808] = {name = "Пища", additional_info = "{Мгновенное действие} {Восстановление: 1 сек}\nИнгредиенты:\nВитаминизированное печенье из манны\n[q]Восполняет 5% здоровья и маны в сек. в течение 20 сек. Действие прерывается, если встать с места."},
[1226810] = {name = "Камень на плечах", additional_info = "[q]Скорость передвижения снижена на 10%."},
[1226814] = {name = "Витаминизированное печенье из манны", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Восстанавливает 2148 ед. здоровья и 4410 ед. маны за 30 сек. Действие прерывается, если встать с места."},
[1226843] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус бойца за 2 предмета", additional_info = "[q]Пока эффект \"Просто царапина\" не действует, \"Удар в спину\", \"Коварный удар\", \"Удар саблей\" и \"Расправа\" наносят на 20% больше урона за каждый ваш эффект яда или кровотечения, действующий на цель. Максимальный бонус – 60%."},
[1226868] = {name = "Серия ударов!", additional_info = nil},
[1226869] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус бойца за 4 предмета", additional_info = "[q]Критические удары ядов и автоатак с вероятностью 10% продлевают серию приемов на 1.\n(Вероятность срабатывания: 10%)"},
[1226871] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус бойца за 6 предметов", additional_info = "[q]Урон от \"Внезапного удара\", \"Потрошения\", \"Кровавого вихря\" и \"Отравления\" увеличивается на 50%."},
[1226874] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус танка за 2 предмета", additional_info = "[q]Эффекты \"Держать удар\" также увеличивают наносимый урон на 1%."},
[1226882] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус танка за 4 предмета", additional_info = "[q]\"Шквал клинков\" теперь поражает три цели и повышает скорость атаки еще на 10%. Кроме того, время восстановления \"Шквала клинков\" сокращается на 0.5 сек. за каждый израсходованный прием серии."},
[1226883] = {name = "Шквал клинков", additional_info = nil},
[1226956] = {name = "S03 – предмет – анклав Алого ордена – разбойник – бонус танка за 6 предметов", additional_info = "[q]\"Держать удар\" теперь увеличивает запас здоровья еще на 2%, а наносимый урон – на 1%, за каждый эффект. Пока у вас 5 эффекта:эффектов, вы получаете 10 ед. энергии при каждом уклонении или парировании.\n(Восстановление: 1с)"},
[1226957] = {name = "Порхай как бабочка, жаль как пчела", additional_info = nil},
[1226961] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Стихий\" за 2 предмета", additional_info = "[q]Когда \"Выброс лавы\", \"Цепная молния\" или \"Молния\" поражают цель, на которую действует ваш \"Огненный шок\" 5-го или 6-го уровня, цель также получает дополнительный такт урона \"Огненного шока\"."},
[1226963] = {name = "Огненный шок", additional_info = nil},
[1226972] = {name = "Огненный шок", additional_info = nil},
[1226977] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Стихий\" за 4 предмета", additional_info = "[q]Вероятность срабатывания \"Перегрузки\" повышается еще на 10%, а урон от \"Выброса лавы\" увеличивается на вероятность критического удара заклинаний. Когда \"Молния\" или \"Цепная молния\" наносят урон, следующий \"Выброс лавы\", примененный в течение 15 сек., нанесет на 10% больше урона. Последний эффект суммируется до 5 раз."},
[1226978] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Стихий\" за 6 предметов", additional_info = "[q]Если \"Цепная молния\" наносит урон менее чем 3 целям:целям, она наносит на 35% больше урона за каждую недостающую цель."},
[1226981] = {name = "Гримуар уз", additional_info = "Радиус действия: 100 м\n[q]Когда вы или ваш демон наносите урон, вы можете с вероятностью 10% увеличить урон друг друга на 10% на 15 сек."},
[1226984] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Совершенствования\" за 2 предмета", additional_info = "[q]Пока действует \"Статический шок\", \"Вскипание лавы\", \"Выброс лавы\" и \"Удар бури\" с вероятностью 100% увеличивают количество зарядов \"Щита молний\". Если количество зарядов превышает 9, \"Щит молний\" мгновенно наносит урон вашей цели вместо того, чтобы накапливать заряды."},
[1226986] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Совершенствования\" за 4 предмета", additional_info = "[q]Время восстановления \"Тотема кольца огня\" сокращается на 60%, его урон увеличивается на 200%, а затраты маны на применение снижаются на 60%. Теперь \"Тотем кольца огня\" срабатывает сразу же после применения."},
[1226997] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Совершенствования\" за 6 предметов", additional_info = "[q]\"Оружие Водоворота\" теперь накапливает до 10 зарядов:зарядов. Когда вы держите двуручное оружие, то получаете 2 заряда:зарядов за раз. Когда вы применяете заклинание, накопив 5 заряда:зарядов, наносимый урон и эффективность исцеления этого заклинания увеличиваются на 20% за каждый заряд сверх этого порога. Когда вы применяете заклинание, накопив 10 заряда:зарядов, все заряды поглощаются, а заклинание срабатывает дважды."},
[1227080] = {name = "Чтение поваренной книги", additional_info = "Применение: 5 сек\n[q]Обучает готовить вкуснейшие пиры Кэрри Хартфайр."},
[1227088] = {name = "Стремительность земли", additional_info = "Мгновенное действие\n[q]Сокращает время применения следующего заклинания \"Малая волна исцеления\", \"Волна исцеления\" или \"Цепное исцеление\" на 100%."},
[1227093] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Исцеления\" за 2 предмета", additional_info = "[q]Когда \"Щит земли\" восполняет здоровье цели, вы с вероятностью 25% можете мгновенно применить следующее исцеляющее заклинание, требующее время на применение."},
[1227099] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Исцеления\" за 4 предмета", additional_info = "[q]\"Волна исцеления\" и \"Малая волна исцеления\" также восполняют здоровье цели \"Щита земли\" с эффективностью 50%, если вы применяете их к другой цели."},
[1227108] = {name = "Волны исцеления", additional_info = nil},
[1227111] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус \"Исцеления\" за 6 предметов", additional_info = "[q]\"Цепное исцеление\" переходит еще на 1 цель, а показатель снижения эффективности с каждым переходом уменьшается на 20%."},
[1227153] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус танка за 2 предмета", additional_info = "[q]Заклинания категории \"Шок\" активируют руническую способность \"Мастерское владение щитом\". Эффект этой способности теперь суммируется до 7 раз:раз."},
[1227155] = {name = "Мастерское владение щитом", additional_info = nil},
[1227159] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус танка за 4 предмета", additional_info = "[q]\"Щит молний\" восполняет вам здоровье в объеме 100% наносимого урона. Срабатывает не чаще раза в 3 сек.\n(Восстановление: 3с)"},
[1227160] = {name = "Искра жизни", additional_info = nil},
[1227164] = {name = "S03 – предмет – анклав Алого ордена – шаман – бонус танка за 6 предметов", additional_info = "[q]Эффекты \"Мастерского владения щитом\" также сокращают время применения \"Выброса лавы\" на 20% за каждый эффект. \"Выброс лавы\" больше не поглощает заряды \"Оружия Водоворота\"."},
[1227175] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус бойца за 2 предмета", additional_info = "[q]Критические удары непериодических эффектов огня или темной магии поджигают цель, нанося еще 25% урона за 4 сек."},
[1227177] = {name = "Горение", additional_info = nil},
[1227180] = {name = "Горение", additional_info = nil},
[1227186] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус бойца за 4 предмета", additional_info = "[q]\"Стрела Тьмы\", \"Блуждающий дух\", \"Стрела Хаоса\", \"Теневой рассекающий удар\" и \"Ожог души\" наносят на 30% больше урона целям, на которые действует ваша \"Порча\"."},
[1227196] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус бойца за 6 предметов", additional_info = "[q]Критические удары периодических эффектов повышают скорость применения заклинаний на 20% на 15 сек., а \"Обратный поток\" повышает ее еще на 12%."},
[1227200] = {name = "Злобность", additional_info = nil},
[1227204] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус танка за 4 предмета", additional_info = "[q]Вы восстанавливаете здоровье в объеме 10% урона от \"Порчи\". Этот эффект восполняет на 100% больше здоровья, если на цель действует ваше \"Похищение жизни\"."},
[1227207] = {name = "Грязная нажива", additional_info = nil},
[1227214] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус танка за 2 предмета", additional_info = "[q]Теперь \"Теневой рассекающий удар\" применяет ко всем пораженным целям \"Порчу\" 7-го уровня, но только на 12 сек."},
[1227228] = {name = "S03 – предмет – анклав Алого ордена – чернокнижник – бонус танка за 6 предметов", additional_info = "[q]\"Инфернальная броня\" теперь также повышает наносимый магический урон на 20% и действует еще 10 сек."},
[1227231] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус бойца за 2 предмета", additional_info = "[q]Пока вы находитесь в боевой стойке или стойке берсерка, урон от \"Удара героя\", \"Быстрого удара\" и \"Рассекающего удара\" повышается на 20%. \"Рассекающий удар\" поражает еще 1 цель и может вызвать \"Всплеск крови\"."},
[1227232] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус бойца за 4 предмета", additional_info = "[q]Каждый раз, когда ваш \"Вихрь\", \"Удар героя\", \"Быстрый удар\" или \"Рассекающий удар\" поражают цель, ваш следующий \"Мощный удар\" наносит на 20% больше урона. Эффект суммируется до 5 раз:раз."},
[1227234] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус бойца за 6 предметов", additional_info = "[q]Когда \"Глубокие раны\" наносят урон, оставшееся время восстановления \"Вихря\" сокращается на 3 сек. \"Вихрь\" наносит на 100% больше урона целям, на которые действуют ваши \"Глубокие раны\"."},
[1227237] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус \"Защиты\" за 2 предмета", additional_info = "[q]Каждый раз, когда вы поражаете цель \"Ударом героя\" или \"Рассекающим ударом\", урон от \"Ударной волны\" увеличивается на 60%, а время ее восстановления сокращается на 2.0 сек."},
[1227242] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус \"Защиты\" за 4 предмета", additional_info = "[q]\"Безрассудство\", \"Возмездие\" и \"Глухая оборона\" больше не имеют общего времени восстановления. Кроме того, время действия \"Безрассудства\" продлевается на 15 сек. Пока действует \"Безрассудство\", ваша сила повышается на 50% навыка защиты свыше 300."},
[1227245] = {name = "S03 – предмет – анклав Алого ордена – воин – бонус \"Защиты\" за 6 предметов", additional_info = "[q]Вы можете применять любую способность вне зависимости от стойки. Кроме того, когда \"Реванш\", \"Сокрушение\" или \"Сокрушение щитом\" поражают цель, урон от следующего \"Вихря\" или \"Казни\" увеличивается на 20%. Суммируется до 5 раз."},
