[1231258] = {name = "Гниль", additional_info = "Требуется: Облик кошки, Облик медведя, Облик лютого медведя\n[q]Атаки ближнего боя с некоторой вероятностью поражают цель гнилью, наносящей противникам в радиусе 8 м 100 ед. урона от сил природы раз в 2 сек. в течение 12 сек. Также снижает скорость атаки пораженных целей на 15%."},
[1231261] = {name = "Гниль", additional_info = nil},
[1231264] = {name = "Клинки Света", additional_info = "Дистанция ближнего боя\nПрименение: 1.5 сек\n[q]Кружась в вихре, атакует ближайших противников, нанося обычный урон и еще 300 ед. урона. Время действия – 6 сек."},
