[1231280] = {name = "Гражданский арест", additional_info = "Радиус действия: 20 м\n{Применение: 2 сек} {Восстановление: 15 сек}\n[q]Обездвиживает цель и наносит урон в объеме 8% максимального запаса здоровья раз в 2 сек. в течение 6 сек."},
[1231281] = {name = "Уничтожение", additional_info = nil},
[1231282] = {name = "Раскаленное озеро", additional_info = "Применение: 3 сек\n[q]Призывает озеро лавы, заливающее нижний уровень Зала обновления."},
[1231284] = {name = "Удар фруктом", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Бьет цель гнилым фруктом, прерывая применение заклинаний."},
[1231289] = {name = "Аватара горы", additional_info = "Мгновенное действие\n[q]Взывает к воле горы, укрепляя броню на 500 ед., а также увеличивая наносимый физический урон на 5% и размер – на 20%. Время действия – 15 сек."},
[1231292] = {name = "Детонация", additional_info = nil},
[1231293] = {name = "Взмах факелом", additional_info = "Радиус действия: 8 м\nСледующая атака\n[q]Взмахивает факелом перед собой, нанося 80 ед. урона от огня максимум 5 целям:целям.\n\n Поджигает пораженных противников."},
[1231297] = {name = "Бросок факела", additional_info = "Радиус действия: 10 - 30 м\nПрименение: 2.5 сек\n[q]Бросает факел в противника, нанося 120 ед. урона от огня.\n\n Поджигает цель."},
[1231301] = {name = "В огне", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Наносит урон от огня в объеме 2% максимального запаса здоровья раз в 2 сек. в течение 12 сек. Суммируется до 20 раз.\n\n Этот эффект применяют способности дозорных из Нового Авалона, когда те используют факелы."},
[1231310] = {name = "Метка дозорного", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Отмечает цель как нарушителя, не позволяя перейти в состояние незаметности или невидимости, а также пользоваться маскировкой в течение 45 сек."},
[1231312] = {name = "Вихрь", additional_info = nil},
[1231313] = {name = "Детонация", additional_info = nil},
[1231314] = {name = "Сияющее разделение", additional_info = "Радиус действия: 45 м\nПрименение: 2 сек\nТребуется: Оружие ближнего боя\n[q]Наносит цели 35000% урона от оружия и оставляет рану, снижающую эффективность исцеления на 50% на 5 сек."},
[1231317] = {name = "Бешеный укус", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Наносит физический урон в объеме 12% максимального запаса здоровья сразу и еще 2% максимального запаса здоровья раз в 3 сек. в течение 9 сек.\n\n По окончании времени действия цель заболевает водобоязнью с вероятностью, зависящей от текущего запаса здоровья."},
[1231324] = {name = "Водобоязнь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Снижает скорость передвижения на 10%. Наносит физический урон в объеме 1% максимального запаса здоровья раз в 3 сек. в течение 2 мин.\n\n Если эффект не будет снят, вы погибнете."},
[1231330] = {name = "Поглощение", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 0.1 сек}\n[q]Похищает 475 в 525 ед. здоровья максимум у 5 противников:противников, а также повышает силу или ловкость на 30 за каждую пораженную цель. Суммируется до 5 раз."},
