[1234870] = {name = "Священный удар", additional_info = "Дистанция ближнего боя\nСледующая атака\nТребуется: Оружие ближнего боя\n[q]Освящает оружие, позволяя ему нанести 100 ед. дополнительного урона при следующей атаке. Весь наносимый урон становится уроном от светлой магии."},
[1234893] = {name = "Удар воина Света", additional_info = "Дистанция ближнего боя\nМгновенное действие\nТребуется: Оружие ближнего боя\n[q]Наносит противнику 50 ед. урона и увеличивает получаемый им урон от светлой магии на 20 ед. за каждый эффект \"Удар воина Света\". Можно применить до 5 раз. Время действия – 30 сек."},
[1234894] = {name = "Священное расщепление", additional_info = "Дистанция ближнего боя\nСледующая атака Восстановление: 6 сек\nТребуется: Оружие ближнего боя\n[q]Наносит противнику и его находящимся рядом союзникам урон от оружия, увеличенный на 20 ед. Поражает до 3 целей."},
